/// `MouseEvent.prototype.getModifierState(keyArg)`: the modifier
/// state the event carries for `"Alt"`, `"Control"`, `"Shift"`, and
/// `"Meta"` (the four flags [`dom::PointerData`] stores). Every other
/// key (`"AltGraph"`, `"CapsLock"`, unknown strings, ...) and every
/// event without pointer/modifier data reads as `false`.
fn n_mouse_get_modifier_state(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let Some(arg) = args.first().copied() else {
        return Err(err_type("getModifierState: argument required"));
    };
    let key = arg_to_string(heap, arg)?;
    let data = pointer_data_of(heap, &rc, this)?;
    Ok(Value::Bool(match key.as_str() {
        "Alt" => data.alt_key,
        "Control" => data.ctrl_key,
        "Shift" => data.shift_key,
        "Meta" => data.meta_key,
        _ => false,
    }))
}

fn n_pointer_is_primary_get(
    heap: &mut Heap,
    this: Value,
    _a: &[Value],
) -> Result<Value, NativeError> {
    pointer_bool_get(heap, this, |p| p.is_primary)
}
fn n_pointer_width_get(heap: &mut Heap, this: Value, _a: &[Value]) -> Result<Value, NativeError> {
    pointer_f64_get(heap, this, |p| p.width)
}
fn n_pointer_height_get(heap: &mut Heap, this: Value, _a: &[Value]) -> Result<Value, NativeError> {
    pointer_f64_get(heap, this, |p| p.height)
}
fn n_pointer_pressure_get(
    heap: &mut Heap,
    this: Value,
    _a: &[Value],
) -> Result<Value, NativeError> {
    pointer_f64_get(heap, this, |p| p.pressure)
}
fn n_pointer_tilt_x_get(heap: &mut Heap, this: Value, _a: &[Value]) -> Result<Value, NativeError> {
    pointer_f64_get(heap, this, |p| p.tilt_x)
}
fn n_pointer_tilt_y_get(heap: &mut Heap, this: Value, _a: &[Value]) -> Result<Value, NativeError> {
    pointer_f64_get(heap, this, |p| p.tilt_y)
}
fn n_pointer_twist_get(heap: &mut Heap, this: Value, _a: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    // The stored value is already a WebIDL `long` for constructor-built
    // events (converted at init-read time); host values truncate
    // toward zero, matching the `long` conversion — never round.
    Ok(Value::Int(pointer_data_of(heap, &rc, this)?.twist as i32))
}

/// Read a `MouseEventInit`/`PointerEventInit` dictionary into a
/// [`dom::PointerData`]: the coordinate members (unrestricted doubles),
/// `button` (short, default 0), `buttons` (unsigned short bitmask,
/// default 0), the four modifier flags, and the `PointerEventInit`
/// members (`pointerId`, `width`/`height` defaulting to 1, `pressure`,
/// `tiltX`/`tiltY`, `twist`, `pointerType`, `isPrimary`). The base is
/// the union of both inits' defaults, so one reader serves both
/// constructors. Per WebIDL only `undefined`/`null` (and an absent
/// argument) mean "empty dictionary": any other non-object value
/// throws a `TypeError`. `relatedTarget` is not read (v1 gap: it would
/// need a second node-wrapper slot on the event).
fn read_pointer_data_init(
    heap: &mut Heap,
    init: Option<Value>,
) -> Result<dom::PointerData, NativeError> {
    let mut data = dom::PointerData {
        width: 1.0,
        height: 1.0,
        ..dom::PointerData::default()
    };
    let obj = match init {
        None | Some(Value::Undefined) | Some(Value::Null) => return Ok(data),
        Some(Value::Object(obj)) => obj,
        Some(_) => return Err(err_type("MouseEventInit must be an object")),
    };
    data.client_x = dict_num(heap, obj, "clientX")?;
    data.client_y = dict_num(heap, obj, "clientY")?;
    data.screen_x = dict_num(heap, obj, "screenX")?;
    data.screen_y = dict_num(heap, obj, "screenY")?;
    data.page_x = dict_num(heap, obj, "pageX")?;
    data.page_y = dict_num(heap, obj, "pageY")?;
    data.offset_x = dict_num(heap, obj, "offsetX")?;
    data.offset_y = dict_num(heap, obj, "offsetY")?;
    data.movement_x = dict_num(heap, obj, "movementX")?;
    data.movement_y = dict_num(heap, obj, "movementY")?;
    // WebIDL: `button` is a `short`, `buttons` an `unsigned short`
    // (MouseEventInit) — convert with the 16-bit modulo algorithms,
    // not a widening `as` cast / 32-bit conversion.
    data.button = match dict_get(heap, obj, "button")? {
        Some(v) => to_i16_webidl(v)? as i32,
        None => 0,
    };
    data.buttons = match dict_get(heap, obj, "buttons")? {
        Some(v) => to_u16_webidl(v)? as u32,
        None => 0,
    };
    data.pointer_id = match dict_get(heap, obj, "pointerId")? {
        Some(v) => to_u32_webidl(v)? as i32,
        None => 0,
    };
    if let Some(v) = dict_get(heap, obj, "width")? {
        data.width = to_number(v)?;
    }
    if let Some(v) = dict_get(heap, obj, "height")? {
        data.height = to_number(v)?;
    }
    data.pressure = dict_num(heap, obj, "pressure")?;
    // WebIDL: `tiltX`/`tiltY`/`twist` are `long` in PointerEventInit.
    // Convert at init-read time (truncate + modulo 2^32) and store the
    // resulting integer value in the `f64` fields `PointerData`
    // provides, so the getters return it verbatim instead of
    // re-converting (the twist getter previously rounded at read
    // time, which is neither truncation nor the init-time conversion).
    data.tilt_x = match dict_get(heap, obj, "tiltX")? {
        Some(v) => to_i32_webidl(v)? as f64,
        None => 0.0,
    };
    data.tilt_y = match dict_get(heap, obj, "tiltY")? {
        Some(v) => to_i32_webidl(v)? as f64,
        None => 0.0,
    };
    data.twist = match dict_get(heap, obj, "twist")? {
        Some(v) => to_i32_webidl(v)? as f64,
        None => 0.0,
    };
    if let Some(v) = dict_get(heap, obj, "pointerType")? {
        data.pointer_type = dom::PointerType::parse(&arg_to_string(heap, v)?);
    }
    let mut flag = |name: &str| -> Result<bool, NativeError> {
        Ok(dict_get(heap, obj, name)?
            .map(|v| v.is_truthy())
            .unwrap_or(false))
    };
    data.alt_key = flag("altKey")?;
    data.ctrl_key = flag("ctrlKey")?;
    data.meta_key = flag("metaKey")?;
    data.shift_key = flag("shiftKey")?;
    data.is_primary = flag("isPrimary")?;
    Ok(data)
}

/// Build a mouse/pointer event wrapper: the [`wrap_event`] shape
/// linked to `proto` (`MouseEvent.prototype` or
/// `PointerEvent.prototype`, or a subclass prototype). The attribute
/// values are not copied onto the wrapper — the prototype accessors
/// read the stored [`dom::PointerData`] (see the section docs). Shared
/// by the `MouseEvent`/`PointerEvent` constructors and host
/// dispatches ([`Vm::dispatch_pointer_mouse`]).
fn wrap_pointer_mouse_event(
    heap: &mut Heap,
    apis: &mut WebApis,
    event: dom::Event,
    trusted: bool,
    proto: Option<Gc<Object>>,
) -> Result<(Value, u32), AllocError> {
    wrap_event_with_proto(heap, apis, event, trusted, proto)
}

/// `new MouseEvent(type, init?)`: the `Event` shape plus the
/// `MouseEventInit` dictionary, linked to `MouseEvent.prototype`
/// (whose prototype is `Event.prototype`).
fn n_mouse_event_ctor(heap: &mut Heap, _this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = ctor_apis(heap, "MouseEvent")?;
    let etype = match args.first() {
        Some(v) if !v.is_undefined() => arg_to_string(heap, *v)?,
        _ => return Err(err_type("MouseEvent: type argument required")),
    };
    let (bubbles, cancelable) = read_event_init(heap, args.get(1).copied())?;
    let data = read_pointer_data_init(heap, args.get(1).copied())?;
    let mut g = rc.borrow_mut();
    let proto = {
        let fallback = g.gc_roots.borrow().mouse_event_proto;
        ctor_proto(heap, fallback)
    };
    let (v, _) = wrap_pointer_mouse_event(
        heap,
        &mut g,
        dom::Event::new(etype, bubbles, cancelable).with_pointer(data),
        false,
        proto,
    )
    .map_err(|_| NativeError::OutOfMemory)?;
    Ok(v)
}

/// `new PointerEvent(type, init?)`: the `MouseEvent` shape plus the
/// `PointerEventInit` dictionary, linked to `PointerEvent.prototype`
/// (whose prototype is `MouseEvent.prototype`).
fn n_pointer_event_ctor(
    heap: &mut Heap,
    _this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = ctor_apis(heap, "PointerEvent")?;
    let etype = match args.first() {
        Some(v) if !v.is_undefined() => arg_to_string(heap, *v)?,
        _ => return Err(err_type("PointerEvent: type argument required")),
    };
    let (bubbles, cancelable) = read_event_init(heap, args.get(1).copied())?;
    let data = read_pointer_data_init(heap, args.get(1).copied())?;
    let mut g = rc.borrow_mut();
    let proto = {
        let fallback = g.gc_roots.borrow().pointer_event_proto;
        ctor_proto(heap, fallback)
    };
    let (v, _) = wrap_pointer_mouse_event(
        heap,
        &mut g,
        dom::Event::new(etype, bubbles, cancelable).with_pointer(data),
        false,
        proto,
    )
    .map_err(|_| NativeError::OutOfMemory)?;
    Ok(v)
}

// ---------------------------------------------------------------------------
// Snap events (`SnapEvent`)
// ---------------------------------------------------------------------------
//
// The `scrollsnapchange` / `scrollsnapchanging` payload (CSS Scroll
// Snap 2 §5) follows the mouse/pointer pattern: the target pair lives
// on the stored [`dom::Event`] (see `dom::Event::snap_targets`) and
// surfaces through accessors on `SnapEvent.prototype`, so constructor-
// built, host-dispatched, and re-dispatched wrappers all read the same
// fields, and [`event_of`]'s stored-clone path preserves them.

/// Read a `SnapEventInit` dictionary: the `snapTargetBlock` /
/// `snapTargetInline` members (`Node?`, default `null`). Per WebIDL
/// only `undefined`/`null` (and an absent argument) mean "empty
/// dictionary": any other non-object value throws a `TypeError`, as
/// does a present member that is not a node.
fn read_snap_init(
    heap: &mut Heap,
    apis: &WebApis,
    init: Option<Value>,
) -> Result<(Option<NodeId>, Option<NodeId>), NativeError> {
    let obj = match init {
        None | Some(Value::Undefined) | Some(Value::Null) => return Ok((None, None)),
        Some(Value::Object(obj)) => obj,
        Some(_) => return Err(err_type("SnapEventInit must be an object")),
    };
    let block = match dict_get(heap, obj, "snapTargetBlock")? {
        Some(v) => snap_node_of(heap, apis, v)?,
        None => None,
    };
    let inline = match dict_get(heap, obj, "snapTargetInline")? {
        Some(v) => snap_node_of(heap, apis, v)?,
        None => None,
    };
    Ok((block, inline))
}

/// The snap target pair behind a snap-event wrapper (`this`), or the
/// all-null pair when the stored event carries none.
fn snap_targets_of(
    heap: &Heap,
    rc: &Rc<RefCell<WebApis>>,
    this: Value,
) -> Result<(Option<NodeId>, Option<NodeId>), NativeError> {
    let handle = event_handle_of(heap, this)?;
    Ok(rc
        .borrow()
        .events
        .get(&handle)
        .and_then(|e| e.snap_targets)
        .unwrap_or((None, None)))
}

/// Shared body of the `snapTargetBlock`/`snapTargetInline` getters:
/// resolve the stored node id to its canonical wrapper (`None` axis
/// reads as `null`; the document node resolves to the document
/// wrapper through [`wrap_node`]).
fn snap_target_get(heap: &mut Heap, this: Value, block: bool) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let (b, i) = snap_targets_of(heap, &rc, this)?;
    match if block { b } else { i } {
        Some(n) => {
            let mut g = rc.borrow_mut();
            wrap_node(heap, &mut g, n).map_err(|_| NativeError::OutOfMemory)
        }
        None => Ok(Value::Null),
    }
}

/// `SnapEvent.prototype.snapTargetBlock` getter.
fn n_snap_target_block_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    snap_target_get(heap, this, true)
}

/// `SnapEvent.prototype.snapTargetInline` getter.
fn n_snap_target_inline_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    snap_target_get(heap, this, false)
}

/// Build a snap event wrapper: the [`wrap_event`] shape linked to
/// `proto` (`SnapEvent.prototype`, or a subclass prototype). The
/// targets are not copied onto the wrapper — the prototype accessors
/// read the stored [`dom::Event`]. Shared by the `SnapEvent`
/// constructor and host dispatches ([`Vm::dispatch_snap_event`]).
fn wrap_snap_event(
    heap: &mut Heap,
    apis: &mut WebApis,
    event: dom::Event,
    trusted: bool,
    proto: Option<Gc<Object>>,
) -> Result<(Value, u32), AllocError> {
    wrap_event_with_proto(heap, apis, event, trusted, proto)
}

/// `new SnapEvent(type, init?)`: the `Event` shape plus the
/// `SnapEventInit` target pair, linked to `SnapEvent.prototype`
/// (whose prototype is `Event.prototype`).
fn n_snap_event_ctor(heap: &mut Heap, _this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = ctor_apis(heap, "SnapEvent")?;
    let etype = match args.first() {
        Some(v) if !v.is_undefined() => arg_to_string(heap, *v)?,
        _ => return Err(err_type("SnapEvent: type argument required")),
    };
    let (bubbles, cancelable) = read_event_init(heap, args.get(1).copied())?;
    let (block, inline) = {
        let g = rc.borrow();
        read_snap_init(heap, &g, args.get(1).copied())?
    };
    let mut g = rc.borrow_mut();
    let proto = {
        let fallback = g.gc_roots.borrow().snap_event_proto;
        ctor_proto(heap, fallback)
    };
    let (v, _) = wrap_snap_event(
        heap,
        &mut g,
        dom::Event::new(etype, bubbles, cancelable).with_snap_targets(block, inline),
        false,
        proto,
    )
    .map_err(|_| NativeError::OutOfMemory)?;
    Ok(v)
}

/// The `(bubbles, cancelable)` pair the UI Events / Pointer Events
/// tables assign to a host-dispatched pointer/mouse `event_type`:
/// every type bubbles and is cancelable except the ones listed —
/// `mouseenter`/`mouseleave`/`pointerenter`/`pointerleave` neither
/// bubble nor are cancelable, and `pointercancel`,
/// `pointerrawupdate`, `gotpointercapture`, and `lostpointercapture`
/// bubble but are not cancelable. In particular `mousemove` and
/// `pointermove` are both `(true, true)` per the UI Events and
/// Pointer Events tables. Unknown types default to `(true, true)`,
/// the common case for the action-API types.
fn pointer_mouse_bubbles_cancelable(event_type: &str) -> (bool, bool) {
    match event_type {
        "mouseenter" | "mouseleave" | "pointerenter" | "pointerleave" => (false, false),
        "pointercancel" | "pointerrawupdate" | "gotpointercapture" | "lostpointercapture" => {
            (true, false)
        }
        _ => (true, true),
    }
}

/// Install the `Event`, `WheelEvent`, `TouchEvent`, `Touch`,
/// `TouchList`, `MouseEvent`, and `PointerEvent` constructors on the
/// global object: `Event.prototype` carries the shared `constructor`
/// link and backs every event wrapper's prototype chain;
/// `WheelEvent.prototype`'s, `TouchEvent.prototype`'s, and
/// `MouseEvent.prototype`'s prototype is `Event.prototype`, while
/// `PointerEvent.prototype`'s prototype is `MouseEvent.prototype`. The
/// context id is baked onto each constructor (hidden [`CTX_KEY`]) so
/// the constructors can resolve their [`WebApis`] through
/// `new.target`.
fn install_event_classes(
    heap: &mut Heap,
    global: Gc<Object>,
    gc_roots: &Rc<RefCell<GcRoots>>,
    ctx_id: u32,
) -> Result<(), AllocError> {
    // `Event.prototype`: the prototype every event wrapper links to.
    let event_ctor = heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_event_ctor)))?;
    // `Event` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_event_ctor);
    let event_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    // Per WebIDL, `Event.prototype`'s prototype is `Object.prototype`
    // (mirrors `NodeList.prototype` in `build_node_list`): without this
    // the chain is `wrapper → event_proto → null` and any
    // ToPrimitive/ToString on an event wrapper throws.
    if let Some(op) = heap.object_prototype {
        heap.set_prototype(event_proto, Value::Object(op));
    }
    with_temp_root(heap, Value::Object(event_ctor), |heap| {
        with_temp_root(heap, Value::Object(event_proto), |heap| {
            def(heap, event_proto, "constructor", Value::Object(event_ctor))?;
            Ok(())
        })?;
        def(heap, event_ctor, "prototype", Value::Object(event_proto))?;
        def(heap, event_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "Event", Value::Object(event_ctor))?;
        Ok(())
    })?;
    // `WheelEvent.prototype` extends `Event.prototype`.
    let wheel_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_wheel_event_ctor)))?;
    // `WheelEvent` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_wheel_event_ctor);
    let wheel_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(wheel_ctor), |heap| {
        with_temp_root(heap, Value::Object(wheel_proto), |heap| {
            heap.set_prototype(wheel_proto, Value::Object(event_proto));
            def(heap, wheel_proto, "constructor", Value::Object(wheel_ctor))?;
            Ok(())
        })?;
        def(heap, wheel_ctor, "prototype", Value::Object(wheel_proto))?;
        def(heap, wheel_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "WheelEvent", Value::Object(wheel_ctor))?;
        Ok(())
    })?;
    // `TouchEvent.prototype` extends `Event.prototype`.
    let touch_event_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_touch_event_ctor)))?;
    // `TouchEvent` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_touch_event_ctor);
    let touch_event_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(touch_event_ctor), |heap| {
        with_temp_root(heap, Value::Object(touch_event_proto), |heap| {
            heap.set_prototype(touch_event_proto, Value::Object(event_proto));
            def(
                heap,
                touch_event_proto,
                "constructor",
                Value::Object(touch_event_ctor),
            )?;
            Ok(())
        })?;
        def(
            heap,
            touch_event_ctor,
            "prototype",
            Value::Object(touch_event_proto),
        )?;
        def(heap, touch_event_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "TouchEvent", Value::Object(touch_event_ctor))?;
        Ok(())
    })?;
    // `Touch.prototype`: the touch attribute accessors live here so every
    // `Touch` wrapper sees them through the chain.
    let touch_ctor = heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_touch_ctor)))?;
    // `Touch` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_touch_ctor);
    let touch_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(touch_ctor), |heap| {
        with_temp_root(heap, Value::Object(touch_proto), |heap| {
            def(heap, touch_proto, "constructor", Value::Object(touch_ctor))?;
            def_accessor(
                heap,
                touch_proto,
                "identifier",
                n_touch_identifier_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "target",
                n_touch_target_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "clientX",
                n_touch_client_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "clientY",
                n_touch_client_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "screenX",
                n_touch_screen_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "screenY",
                n_touch_screen_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "pageX",
                n_touch_page_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                touch_proto,
                "pageY",
                n_touch_page_y_get,
                n_readonly_set,
            )?;
            Ok(())
        })?;
        def(heap, touch_ctor, "prototype", Value::Object(touch_proto))?;
        def(heap, touch_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "Touch", Value::Object(touch_ctor))?;
        Ok(())
    })?;
    // `TouchList.prototype`: `item()` plus the `constructor` link. The
    // wrappers themselves are real JS arrays (see [`wrap_touch_list`).
    let touch_list_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_touch_list_ctor)))?;
    // `TouchList` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_touch_list_ctor);
    let touch_list_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(touch_list_ctor), |heap| {
        with_temp_root(heap, Value::Object(touch_list_proto), |heap| {
            def(
                heap,
                touch_list_proto,
                "constructor",
                Value::Object(touch_list_ctor),
            )?;
            def_native(heap, touch_list_proto, "item", n_touch_list_item)?;
            Ok(())
        })?;
        def(
            heap,
            touch_list_ctor,
            "prototype",
            Value::Object(touch_list_proto),
        )?;
        def(heap, touch_list_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "TouchList", Value::Object(touch_list_ctor))?;
        Ok(())
    })?;
    // `MouseEvent.prototype` extends `Event.prototype` and carries the
    // mouse attribute accessors (the values live on the stored
    // [`dom::PointerData`]; see the mouse/pointer section docs).
    let mouse_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_mouse_event_ctor)))?;
    // `MouseEvent` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_mouse_event_ctor);
    let mouse_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(mouse_ctor), |heap| {
        with_temp_root(heap, Value::Object(mouse_proto), |heap| {
            heap.set_prototype(mouse_proto, Value::Object(event_proto));
            def(heap, mouse_proto, "constructor", Value::Object(mouse_ctor))?;
            def_accessor(
                heap,
                mouse_proto,
                "screenX",
                n_mouse_screen_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "screenY",
                n_mouse_screen_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "clientX",
                n_mouse_client_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "clientY",
                n_mouse_client_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "pageX",
                n_mouse_page_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "pageY",
                n_mouse_page_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "offsetX",
                n_mouse_offset_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "offsetY",
                n_mouse_offset_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "button",
                n_mouse_button_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "buttons",
                n_mouse_buttons_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "movementX",
                n_mouse_movement_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "movementY",
                n_mouse_movement_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "altKey",
                n_mouse_alt_key_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "ctrlKey",
                n_mouse_ctrl_key_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "metaKey",
                n_mouse_meta_key_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                mouse_proto,
                "shiftKey",
                n_mouse_shift_key_get,
                n_readonly_set,
            )?;
            // `x`/`y` are spec aliases for `clientX`/`clientY`
            // (UI Events), sharing the same getters.
            def_accessor(heap, mouse_proto, "x", n_mouse_client_x_get, n_readonly_set)?;
            def_accessor(heap, mouse_proto, "y", n_mouse_client_y_get, n_readonly_set)?;
            def_native(
                heap,
                mouse_proto,
                "getModifierState",
                n_mouse_get_modifier_state,
            )?;
            Ok(())
        })?;
        def(heap, mouse_ctor, "prototype", Value::Object(mouse_proto))?;
        def(heap, mouse_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "MouseEvent", Value::Object(mouse_ctor))?;
        Ok(())
    })?;
    // `PointerEvent.prototype` extends `MouseEvent.prototype` and adds
    // the pointer-only accessors.
    let pointer_ctor = heap.alloc_object(Object::new(ObjectKind::NativeFunction(
        n_pointer_event_ctor,
    )))?;
    // `PointerEvent` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_pointer_event_ctor);
    let pointer_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(pointer_ctor), |heap| {
        with_temp_root(heap, Value::Object(pointer_proto), |heap| {
            heap.set_prototype(pointer_proto, Value::Object(mouse_proto));
            def(
                heap,
                pointer_proto,
                "constructor",
                Value::Object(pointer_ctor),
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "pointerId",
                n_pointer_id_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "pointerType",
                n_pointer_type_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "isPrimary",
                n_pointer_is_primary_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "width",
                n_pointer_width_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "height",
                n_pointer_height_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "pressure",
                n_pointer_pressure_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "tiltX",
                n_pointer_tilt_x_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "tiltY",
                n_pointer_tilt_y_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                pointer_proto,
                "twist",
                n_pointer_twist_get,
                n_readonly_set,
            )?;
            Ok(())
        })?;
        def(
            heap,
            pointer_ctor,
            "prototype",
            Value::Object(pointer_proto),
        )?;
        def(heap, pointer_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "PointerEvent", Value::Object(pointer_ctor))?;
        Ok(())
    })?;
    // `SnapEvent.prototype` extends `Event.prototype` and carries the
    // snap-target accessors (the values live on the stored
    // [`dom::Event`]; see the snap-event section docs).
    let snap_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_snap_event_ctor)))?;
    // `SnapEvent` is a constructor (WebIDL `IsConstructor`).
    heap.mark_native_constructor(n_snap_event_ctor);
    let snap_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(snap_ctor), |heap| {
        with_temp_root(heap, Value::Object(snap_proto), |heap| {
            heap.set_prototype(snap_proto, Value::Object(event_proto));
            def(heap, snap_proto, "constructor", Value::Object(snap_ctor))?;
            def_accessor(
                heap,
                snap_proto,
                "snapTargetBlock",
                n_snap_target_block_get,
                n_readonly_set,
            )?;
            def_accessor(
                heap,
                snap_proto,
                "snapTargetInline",
                n_snap_target_inline_get,
                n_readonly_set,
            )?;
            Ok(())
        })?;
        def(heap, snap_ctor, "prototype", Value::Object(snap_proto))?;
        def(heap, snap_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
        def(heap, global, "SnapEvent", Value::Object(snap_ctor))?;
        Ok(())
    })?;
    // Stash the prototypes where `wrap_event`/`wrap_wheel_event` read
    // them; the `Trace` impl keeps them alive (see `GcRoots`).
    let mut roots = gc_roots.borrow_mut();
    roots.event_proto = Some(event_proto);
    roots.wheel_event_proto = Some(wheel_proto);
    roots.touch_event_proto = Some(touch_event_proto);
    roots.touch_proto = Some(touch_proto);
    roots.touch_list_proto = Some(touch_list_proto);
    roots.mouse_event_proto = Some(mouse_proto);
    roots.pointer_event_proto = Some(pointer_proto);
    roots.snap_event_proto = Some(snap_proto);
    Ok(())
}

// ---------------------------------------------------------------------------
// `NodeList`
// ---------------------------------------------------------------------------
//
// `childNodes`, `children`, `querySelectorAll` (and friends) are
// Array-kind objects with indexed properties and `length`, linked to a
// shared `NodeList.prototype` that carries the DOM `NodeList` surface:
// `forEach`, `item`, `entries`/`keys`/`values`, and `@@iterator` (so
// `for`-`of`, spread, and destructuring work). This mirrors the
// `TouchList` pattern above: the wrappers stay real arrays (indexed
// access and `length` keep working exactly as before) while the
// prototype supplies the methods and the `instanceof` target.
//
// Deliberate deviations from the DOM spec, pinned here:
// - `children` (an `HTMLCollection` per spec) and the
//   `getElementsBy*` results share `NodeList.prototype`, so they also
//   grow `forEach` (which `HTMLCollection` lacks per spec). One list
//   shape keeps the shim uniform; the task explicitly requires `forEach`
//   on `children`.
// - The lists are snapshots, not live: each access builds a fresh array.
// - `Array.isArray(list)` is `true` (the objects are `ObjectKind::Array`).

/// Install the `NodeList` constructor and `NodeList.prototype` on
/// `global`, and stash the prototype in `gc_roots` for the list
/// builders. `ctx_id` authenticates the constructor like the event
/// constructors above.
fn install_node_list(
    heap: &mut Heap,
    global: Gc<Object>,
    gc_roots: &RefCell<GcRoots>,
    ctx_id: u32,
) -> Result<(), AllocError> {
    // The pair is unrooted until the roots below: no allocation happens
    // between `build_node_list`'s return and the `with_temp_root`
    // calls, so no collection can fire in the gap.
    let (node_list_ctor, node_list_proto) = build_node_list(heap)?;
    with_temp_root(heap, Value::Object(node_list_ctor), |heap| {
        with_temp_root(heap, Value::Object(node_list_proto), |heap| {
            def(heap, node_list_ctor, CTX_KEY, Value::Int(ctx_id as i32))?;
            def(heap, global, "NodeList", Value::Object(node_list_ctor))?;
            Ok(())
        })
    })?;
    gc_roots.borrow_mut().node_list_proto = Some(node_list_proto);
    Ok(())
}

/// Build the `NodeList` constructor + prototype pair, without any
/// global install or root stash: shared by the production install
/// ([`install_node_list`]) and the parse shim, which stash the
/// prototype in different roots.
fn build_node_list(heap: &mut Heap) -> Result<(Gc<Object>, Gc<Object>), AllocError> {
    let node_list_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_node_list_ctor)))?;
    // `NodeList` is a constructor per WebIDL (its body throws "Illegal
    // constructor"); without this the VM `new` gate rejects it as a
    // non-constructor first and the native body never runs.
    heap.mark_native_constructor(n_node_list_ctor);
    let node_list_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(node_list_ctor), |heap| {
        with_temp_root(heap, Value::Object(node_list_proto), |heap| {
            // Per WebIDL, `NodeList.prototype`'s prototype is
            // `Object.prototype`.
            if let Some(op) = heap.object_prototype {
                heap.set_prototype(node_list_proto, Value::Object(op));
            }
            def(
                heap,
                node_list_proto,
                "constructor",
                Value::Object(node_list_ctor),
            )?;
            // The brand the `NodeList.prototype.*` natives check (see
            // [`node_list_this`]): non-enumerable so it never leaks into
            // `for`-`in`/`Object.keys`.
            heap.define_property_str(
                node_list_proto,
                NODE_LIST_KEY,
                Property {
                    value: Value::Bool(true),
                    writable: false,
                    enumerable: false,
                    configurable: false,
                },
            )?;
            def_native(heap, node_list_proto, "forEach", n_node_list_for_each)?;
            def_native(heap, node_list_proto, "item", n_node_list_item)?;
            def_native(heap, node_list_proto, "keys", n_node_list_keys)?;
            def_native(heap, node_list_proto, "entries", n_node_list_entries)?;
            // `values` and `Symbol.iterator` are the same function object,
            // per spec (`NodeList.prototype[Symbol.iterator] ===
            // NodeList.prototype.values`). The symbol key is the real
            // well-known symbol (the `"@@iterator"` string alias is
            // gone), installed with the same attributes the builtins
            // use for `Symbol.iterator` methods.
            let values_fn = native_val(heap, n_node_list_values)?;
            def(heap, node_list_proto, "values", values_fn)?;
            with_temp_root(heap, values_fn, |heap| {
                let iterator_sym = heap.well_known_symbol(WellKnown::Iterator)?;
                heap.define_property_key(
                    node_list_proto,
                    PropKey::Symbol(iterator_sym),
                    Property {
                        value: values_fn,
                        writable: true,
                        enumerable: false,
                        configurable: true,
                    },
                )
            })?;
            Ok(())
        })?;
        def(
            heap,
            node_list_ctor,
            "prototype",
            Value::Object(node_list_proto),
        )?;
        Ok(())
    })?;
    Ok((node_list_ctor, node_list_proto))
}

/// `new NodeList()`: WebIDL gives `NodeList` no constructor.
fn n_node_list_ctor(_heap: &mut Heap, _this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    Err(NativeError::TypeError("Illegal constructor".into()))
}

/// `new Element()`: WebIDL gives `Element` no constructor either.
fn n_element_ctor(_heap: &mut Heap, _this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    Err(NativeError::TypeError("Illegal constructor".into()))
}

/// Build a minimal `Element` constructor + prototype pair, without any
/// global install: the parse shim's `Element` global (feature-detection
/// degradation — `'animate' in Element.prototype` is `false` instead of
/// throwing `ReferenceError`). The production install links its
/// constructor to the real shared element prototype instead.
fn build_element_ctor(heap: &mut Heap) -> Result<(Gc<Object>, Gc<Object>), AllocError> {
    let element_ctor =
        heap.alloc_object(Object::new(ObjectKind::NativeFunction(n_element_ctor)))?;
    // `Element` is a constructor per WebIDL (its body throws "Illegal
    // constructor"); without this the VM `new` gate rejects it as a
    // non-constructor first and the native body never runs.
    heap.mark_native_constructor(n_element_ctor);
    let element_proto = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    with_temp_root(heap, Value::Object(element_ctor), |heap| {
        with_temp_root(heap, Value::Object(element_proto), |heap| {
            // Per WebIDL, `Element.prototype`'s prototype is
            // `Object.prototype`.
            if let Some(op) = heap.object_prototype {
                heap.set_prototype(element_proto, Value::Object(op));
            }
            def(
                heap,
                element_proto,
                "constructor",
                Value::Object(element_ctor),
            )?;
            Ok(())
        })?;
        def(
            heap,
            element_ctor,
            "prototype",
            Value::Object(element_proto),
        )?;
        Ok(())
    })?;
    Ok((element_ctor, element_proto))
}

/// The `NodeList` behind `this`: the receiver itself when its prototype
/// chain carries the [`NODE_LIST_KEY`] brand, else a `TypeError` naming
/// the method (WebIDL's incompatible-receiver throw).
fn node_list_this(heap: &Heap, this: Value, method: &str) -> Result<Gc<Object>, NativeError> {
    let incompatible = || {
        NativeError::TypeError(format!(
            "NodeList.prototype.{method} called on incompatible receiver"
        ))
    };
    let Value::Object(o) = this else {
        return Err(incompatible());
    };
    let branded = walk_proto_chain(heap, o, |p| {
        heap.get_property(p, Wtf8::from_str(NODE_LIST_KEY))
            .map(|_| p)
    })
    .is_some();
    if branded { Ok(o) } else { Err(incompatible()) }
}

/// Own `length` of a NodeList-like as `usize` (0 when missing or
/// negative — the builders always define a non-negative `Int`).
fn node_list_len(heap: &Heap, list: Gc<Object>) -> usize {
    match get_own(heap, list, Wtf8::from_str("length")) {
        Some(Value::Int(n)) if n >= 0 => n as usize,
        Some(Value::Float(f)) if f >= 0.0 => f as usize,
        _ => 0,
    }
}

/// Own indexed element of a NodeList-like (`undefined` when absent, like
/// a hole in `Array.prototype.forEach`'s walk).
fn node_list_get(heap: &Heap, list: Gc<Object>, index: usize) -> Value {
    get_own(heap, list, Wtf8::from_str(&index.to_string())).unwrap_or(Value::Undefined)
}

/// `NodeList.prototype.forEach(callback, thisArg?)`: `callback(value,
/// index, list)` for each index in `[0, length)`. Throws when the
/// callback is not callable, per WebIDL.
fn n_node_list_for_each(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let list = node_list_this(heap, this, "forEach")?;
    let callback = args.first().copied().unwrap_or(Value::Undefined);
    if !is_callable(heap, callback) {
        return Err(NativeError::TypeError(
            "NodeList.prototype.forEach: callback is not callable".into(),
        ));
    }
    let this_arg = args.get(1).copied().unwrap_or(Value::Undefined);
    let len = node_list_len(heap, list);
    let list_val = Value::Object(list);
    for k in 0..len {
        let v = node_list_get(heap, list, k);
        call_function(heap, callback, this_arg, &[v, num(k as f64), list_val])?;
    }
    Ok(Value::Undefined)
}

/// `NodeList.prototype.item(index)`: the indexed node, or `null` when
/// out of range.
fn n_node_list_item(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let list = node_list_this(heap, this, "item")?;
    let index = args.first().copied().unwrap_or(Value::Undefined);
    let i = match to_number(index) {
        Ok(n) if n >= 0.0 && n < node_list_len(heap, list) as f64 => n as usize,
        _ => return Ok(Value::Null),
    };
    Ok(node_list_get(heap, list, i))
}

/// Iteration kinds for [`new_node_list_iterator`]: 0 = keys, 1 = values,
/// 2 = entries.
fn new_node_list_iterator(
    heap: &mut Heap,
    list: Gc<Object>,
    kind: u8,
) -> Result<Value, NativeError> {
    let oom = |_: AllocError| NativeError::OutOfMemory;
    let iter = heap
        .alloc_object(Object::new(ObjectKind::Ordinary))
        .map_err(oom)?;
    with_temp_root(
        heap,
        Value::Object(iter),
        |heap| -> Result<(), NativeError> {
            for (slot, value) in [
                (NODE_ITER_LIST, Value::Object(list)),
                (NODE_ITER_INDEX, Value::Int(0)),
                (NODE_ITER_KIND, Value::Int(kind as i32)),
            ] {
                heap.define_property_str(
                    iter,
                    slot,
                    Property {
                        value,
                        writable: false,
                        enumerable: false,
                        configurable: false,
                    },
                )
                .map_err(oom)?;
            }
            def_native(heap, iter, "next", n_node_list_iter_next)?;
            // Iterators are iterable: `for (x of list.values())`. The
            // real well-known symbol key (the `"@@iterator"` string
            // alias is gone), same pattern as the Map/Set iterators.
            let iterator_sym = heap
                .well_known_symbol(WellKnown::Iterator)
                .map_err(|_| NativeError::OutOfMemory)?;
            define_native_key(
                heap,
                iter,
                PropKey::Symbol(iterator_sym),
                "[Symbol.iterator]",
                n_node_list_iter_self,
                0,
            )?;
            Ok(())
        },
    )?;
    Ok(Value::Object(iter))
}

/// Shared backing for `values()` and `@@iterator` (same function object
/// on the prototype, per spec).
fn n_node_list_values(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let list = node_list_this(heap, this, "values")?;
    new_node_list_iterator(heap, list, 1)
}

fn n_node_list_keys(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let list = node_list_this(heap, this, "keys")?;
    new_node_list_iterator(heap, list, 0)
}

fn n_node_list_entries(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let list = node_list_this(heap, this, "entries")?;
    new_node_list_iterator(heap, list, 2)
}

/// `NodeList` iterator `next()`: `{value, done}` per spec
/// `CreateIterResultObject` (writable/enumerable/configurable).
fn n_node_list_iter_next(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let incompatible =
        || NativeError::TypeError("NodeList iterator next called on incompatible receiver".into());
    let Value::Object(iter) = this else {
        return Err(incompatible());
    };
    let slot = |name: &str| get_own(heap, iter, Wtf8::from_str(name));
    let (list, mut index, kind) = match (
        slot(NODE_ITER_LIST),
        slot(NODE_ITER_INDEX),
        slot(NODE_ITER_KIND),
    ) {
        (Some(Value::Object(list)), Some(Value::Int(index)), Some(Value::Int(kind))) => {
            (list, index, kind)
        }
        _ => return Err(incompatible()),
    };
    let oom = |_: AllocError| NativeError::OutOfMemory;
    let done_result = |heap: &mut Heap| -> Result<Value, NativeError> {
        let obj = heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .map_err(oom)?;
        with_temp_root(
            heap,
            Value::Object(obj),
            |heap| -> Result<(), NativeError> {
                heap.define_property_str(
                    obj,
                    "value",
                    Property {
                        value: Value::Undefined,
                        writable: true,
                        enumerable: true,
                        configurable: true,
                    },
                )
                .map_err(oom)?;
                heap.define_property_str(
                    obj,
                    "done",
                    Property {
                        value: Value::Bool(true),
                        writable: true,
                        enumerable: true,
                        configurable: true,
                    },
                )
                .map_err(oom)?;
                Ok(())
            },
        )?;
        Ok(Value::Object(obj))
    };
    if index < 0 || index as usize >= node_list_len(heap, list) {
        return done_result(heap);
    }
    let value = match kind {
        // keys()
        0 => num(index as f64),
        // entries(): a fresh `[index, node]` array.
        2 => {
            let pair = heap
                .alloc_object(Object::new(ObjectKind::Array))
                .map_err(oom)?;
            with_temp_root(
                heap,
                Value::Object(pair),
                |heap| -> Result<(), NativeError> {
                    if let Some(ap) = heap.array_prototype {
                        heap.set_prototype(pair, Value::Object(ap));
                    }
                    def(heap, pair, "0", num(index as f64)).map_err(oom)?;
                    def(heap, pair, "1", node_list_get(heap, list, index as usize)).map_err(oom)?;
                    def(heap, pair, "length", Value::Int(2)).map_err(oom)?;
                    Ok(())
                },
            )?;
            Value::Object(pair)
        }
        // values()
        _ => node_list_get(heap, list, index as usize),
    };
    index += 1;
    heap.define_property_str(
        iter,
        NODE_ITER_INDEX,
        Property {
            value: Value::Int(index),
            writable: false,
            enumerable: false,
            configurable: false,
        },
    )
    .map_err(oom)?;
    let obj = heap
        .alloc_object(Object::new(ObjectKind::Ordinary))
        .map_err(oom)?;
    with_temp_root(
        heap,
        Value::Object(obj),
        |heap| -> Result<(), NativeError> {
            heap.define_property_str(
                obj,
                "value",
                Property {
                    value,
                    writable: true,
                    enumerable: true,
                    configurable: true,
                },
            )
            .map_err(oom)?;
            heap.define_property_str(
                obj,
                "done",
                Property {
                    value: Value::Bool(false),
                    writable: true,
                    enumerable: true,
                    configurable: true,
                },
            )
            .map_err(oom)?;
            Ok(())
        },
    )?;
    Ok(Value::Object(obj))
}

/// A `NodeList` iterator's `@@iterator`: returns itself.
fn n_node_list_iter_self(
    _heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    match this {
        Value::Object(_) => Ok(this),
        _ => Err(NativeError::TypeError(
            "@@iterator called on incompatible receiver".into(),
        )),
    }
}

/// Link a fresh NodeList-shaped array to `NodeList.prototype` (brand +
/// `forEach`/`item`/iteration through the chain). `None` — the
/// prototype was never installed for this context — degrades to the old
/// prototype-less array: fail-open, never a throw.
fn link_node_list_proto(heap: &mut Heap, arr: Gc<Object>, proto: Option<Gc<Object>>) {
    if let Some(p) = proto {
        heap.set_prototype(arr, Value::Object(p));
    }
}

/// The event handle behind an event wrapper (`this`), for the accessors
/// and propagation natives below.
fn event_handle_of(heap: &Heap, this: Value) -> Result<u32, NativeError> {
    let Value::Object(o) = this else {
        return Err(err_type("event method called with invalid receiver"));
    };
    match heap.get_property(o, Wtf8::from_str(EVENT_KEY)) {
        Some(p) => match p.value {
            Value::Int(h) => Ok(h as u32),
            _ => Err(err_type("event method called with invalid receiver")),
        },
        None => Err(err_type("event method called with invalid receiver")),
    }
}

/// Wrap the dispatch-state node behind `get`, or `null` when there is
/// none (outside dispatch).
fn event_node_prop(
    heap: &mut Heap,
    this: Value,
    get: impl FnOnce(&EventDispatchState) -> Option<NodeId>,
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let node = rc.borrow().event_states.get(&handle).and_then(get);
    match node {
        Some(n) => {
            let mut g = rc.borrow_mut();
            wrap_node(heap, &mut g, n).map_err(|_| NativeError::OutOfMemory)
        }
        None => Ok(Value::Null),
    }
}

fn n_event_target_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    event_node_prop(heap, this, |s| s.target)
}

fn n_event_current_target_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    event_node_prop(heap, this, |s| s.current_target)
}

fn n_event_phase_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let phase = rc
        .borrow()
        .event_states
        .get(&handle)
        .map(|s| s.phase)
        .unwrap_or(PHASE_NONE);
    Ok(Value::Int(phase as i32))
}

fn n_event_is_trusted_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let trusted = rc
        .borrow()
        .event_states
        .get(&handle)
        .map(|s| s.trusted)
        .unwrap_or(false);
    Ok(Value::Bool(trusted))
}

fn n_event_time_stamp_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let time_stamp = rc
        .borrow()
        .event_states
        .get(&handle)
        .map(|s| s.time_stamp)
        .unwrap_or(0.0);
    Ok(Value::Float(time_stamp))
}

fn n_event_default_prevented_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let prevented = rc
        .borrow()
        .events
        .get(&handle)
        .map(|e| e.default_prevented)
        .unwrap_or(false);
    Ok(Value::Bool(prevented))
}

/// `Event.prototype.composedPath()`: the dispatch-time propagation path
/// (target first, then ancestors to the document root) as a fresh
/// array of node wrappers; `[]` outside dispatch (DOM).
fn n_event_composed_path(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let path = rc
        .borrow()
        .event_states
        .get(&handle)
        .map(|s| s.path.clone())
        .unwrap_or_default();
    let arr = heap
        .alloc_object(Object::new(ObjectKind::Array))
        .map_err(|_| NativeError::OutOfMemory)?;
    // `arr` is unreachable until returned; `wrap_node` allocates, so
    // hold a temporary root across the fill.
    with_temp_root(
        heap,
        Value::Object(arr),
        |heap| -> Result<(), NativeError> {
            let mut g = rc.borrow_mut();
            for (i, n) in path.iter().enumerate() {
                let w = wrap_node(heap, &mut g, *n)?;
                // `w` may be a weak-cache wrapper invisible to the
                // collector: root it across the allocating `def` (its
                // key interning can trigger a threshold collection)
                // until the array links it in, like `n_child_nodes_get`.
                with_temp_root(heap, w, |heap| {
                    def(heap, arr, &i.to_string(), w).map_err(|_| NativeError::OutOfMemory)
                })?;
            }
            def(heap, arr, "length", Value::Int(path.len() as i32))
                .map_err(|_| NativeError::OutOfMemory)?;
            Ok(())
        },
    )?;
    Ok(Value::Object(arr))
}

/// `Event.prototype.cancelBubble` getter: the stop-propagation flag.
fn n_event_cancel_bubble_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let cancel = rc
        .borrow()
        .event_states
        .get(&handle)
        .map(|s| s.stop_propagation)
        .unwrap_or(false);
    Ok(Value::Bool(cancel))
}

/// `Event.prototype.cancelBubble` setter: setting `true` sets the stop-
/// propagation flag (DOM); setting `false` is a no-op.
fn n_event_cancel_bubble_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let v = args.first().copied().unwrap_or(Value::Undefined);
    if v.is_truthy()
        && let Some(s) = rc.borrow_mut().event_states.get_mut(&handle)
    {
        s.stop_propagation = true;
    }
    Ok(Value::Undefined)
}

/// `Event.prototype.returnValue` getter (legacy): `false` when the
/// event's canceled flag is set, `true` otherwise.
fn n_event_return_value_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    let prevented = rc
        .borrow()
        .events
        .get(&handle)
        .map(|e| e.default_prevented)
        .unwrap_or(false);
    Ok(Value::Bool(!prevented))
}

/// `Event.prototype.returnValue` setter (legacy): setting `false`
/// cancels the event, exactly like `preventDefault()` (passive-listener
/// and cancelability rules included, via [`n_prevent_default`]); any
/// other value is a no-op.
fn n_event_return_value_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let v = args.first().copied().unwrap_or(Value::Undefined);
    if !v.is_truthy() {
        return n_prevent_default(heap, this, &[]);
    }
    Ok(Value::Undefined)
}

fn n_stop_propagation(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    if let Some(s) = rc.borrow_mut().event_states.get_mut(&handle) {
        s.stop_propagation = true;
    }
    Ok(Value::Undefined)
}

fn n_stop_immediate_propagation(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let handle = event_handle_of(heap, this)?;
    if let Some(s) = rc.borrow_mut().event_states.get_mut(&handle) {
        s.stop_immediate = true;
    }
    Ok(Value::Undefined)
}

/// Read the [`dom::Event`] out of a dispatch argument: either a wrapper
/// made by [`wrap_event`] (including `new Event(...)`/`new WheelEvent(...)`
/// instances) or a plain `{type, bubbles?, cancelable?}` object.
fn event_of(heap: &mut Heap, apis: &WebApis, v: Value) -> Result<dom::Event, NativeError> {
    let Value::Object(o) = v else {
        return Err(err_type("dispatchEvent: argument is not an object"));
    };
    if let Some(p) = heap.get_property(o, Wtf8::from_str(EVENT_KEY))
        && let Value::Int(h) = p.value
        && let Some(e) = apis.events.get(&(h as u32))
    {
        return Ok(e.clone());
    }
    let etype = match heap.get_property(o, Wtf8::from_str("type")) {
        Some(p) => arg_to_string(&mut *heap, p.value)?,
        None => return Err(err_type("dispatchEvent: event object has no type")),
    };
    let flag = |name: &str| {
        heap.get_property(o, Wtf8::from_str(name))
            .map(|p| p.value.is_truthy())
            .unwrap_or(false)
    };
    let mut event = dom::Event::new(etype, flag("bubbles"), flag("cancelable"));
    // Keyboard `key` (UI Events `key` value): read from the init dict so
    // `dispatchEvent({type: "keydown", key: "a"})` — the shape the
    // testdriver key dispatch uses — surfaces `event.key` to listeners.
    // `undefined`/`null` mean "no key", like WebIDL optional members.
    match heap.get_property(o, Wtf8::from_str("key")) {
        Some(p) if !p.value.is_undefined() && !p.value.is_null() => {
            event = event.with_key(arg_to_string(&mut *heap, p.value)?);
        }
        _ => {}
    }
    // Snap targets (CSS Scroll Snap 2 §5): a plain-object dispatch
    // argument may carry `snapTargetBlock` / `snapTargetInline` node
    // members (the `SnapEventInit` shape), resolved like the
    // constructor's dictionary read. Absent members leave the event
    // without a snap payload.
    let block_prop = heap.get_property(o, Wtf8::from_str("snapTargetBlock"));
    let inline_prop = heap.get_property(o, Wtf8::from_str("snapTargetInline"));
    if block_prop.is_some() || inline_prop.is_some() {
        let block = match block_prop {
            Some(p) => snap_node_of(heap, apis, p.value)?,
            None => None,
        };
        let inline = match inline_prop {
            Some(p) => snap_node_of(heap, apis, p.value)?,
            None => None,
        };
        event = event.with_snap_targets(block, inline);
    }
    Ok(event)
}

/// Resolve a `Node?` WebIDL value (a `SnapEventInit` member or a
/// plain-object dispatch member) to a [`NodeId`]: `null`/`undefined`
/// mean no target; an element wrapper resolves through the wrapper
/// cache; the document wrapper (and `window`, which carry no node
/// handle) resolve to the document root node — so
/// `snapTargetBlock: document` round-trips to `=== document`; anything
/// else is a `TypeError`, per the WebIDL `Node?` conversion.
fn snap_node_of(heap: &Heap, apis: &WebApis, v: Value) -> Result<Option<NodeId>, NativeError> {
    match v {
        Value::Null | Value::Undefined => Ok(None),
        Value::Object(o) => match node_id_of_wrapper(heap, o, apis) {
            Some(n) => Ok(Some(n)),
            // No node handle: the document wrapper and the global
            // (`window`) are the node-less wrappers that still name a
            // node — the document root. Both carry the context id;
            // a random plain object does not and is a `TypeError`.
            None if heap.get_property(o, Wtf8::from_str(CTX_KEY)).is_some() => {
                Ok(Some(apis.live_document()?.borrow().root()))
            }
            None => Err(err_type("snap target must be a Node or null")),
        },
        _ => Err(err_type("snap target must be a Node or null")),
    }
}

/// Wrap a pending promise. The object exposes `then`; settling happens in
/// the fetch completion microtask.
fn wrap_promise(heap: &mut Heap, apis: &mut WebApis, handle: u32) -> Result<Value, AllocError> {
    let obj = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    // Unreachable until the caller links the returned value into a rooted
    // graph; `def_native` allocates, so hold a temporary root across the
    // build.
    with_temp_root(heap, Value::Object(obj), |heap| {
        def(heap, obj, CTX_KEY, Value::Int(apis.id as i32))?;
        def(heap, obj, PROMISE_KEY, Value::Int(handle as i32))?;
        def_native(heap, obj, "then", n_then)?;
        Ok(())
    })?;
    Ok(Value::Object(obj))
}

fn promise_handle_of(heap: &Heap, this: Value) -> Result<u32, NativeError> {
    let Value::Object(o) = this else {
        return Err(err_type("then: invalid receiver"));
    };
    match heap.get_property(o, Wtf8::from_str(PROMISE_KEY)) {
        Some(p) => match p.value {
            Value::Int(h) => Ok(h as u32),
            _ => Err(err_type("then: invalid receiver")),
        },
        None => Err(err_type("then: invalid receiver")),
    }
}

/// Build the JS `Response` object for a fetched response.
#[allow(dead_code)]
fn build_response_object(
    heap: &mut Heap,
    apis: &mut WebApis,
    handle: u32,
    resp: &net_fetch::Response,
) -> Result<Value, AllocError> {
    let obj = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    // Unreachable until the caller links the returned value into a rooted
    // graph; the `alloc_str` for the URL and `def_native` can collect, so
    // hold a temporary root across the build.
    with_temp_root(heap, Value::Object(obj), |heap| {
        def(heap, obj, CTX_KEY, Value::Int(apis.id as i32))?;
        def(heap, obj, RESPONSE_KEY, Value::Int(handle as i32))?;
        def(heap, obj, "status", Value::Int(resp.status as i32))?;
        def(
            heap,
            obj,
            "ok",
            Value::Bool(resp.status >= 200 && resp.status < 300),
        )?;
        let url = Value::Str(heap.alloc_str(&resp.url.serialize())?);
        def(heap, obj, "url", url)?;
        def_native(heap, obj, "text", n_resp_text)?;
        Ok(())
    })?;
    Ok(Value::Object(obj))
}

/// Wrap a computed-style snapshot as a declaration object exposing
/// `getPropertyValue`.
fn wrap_style(
    heap: &mut Heap,
    apis: &mut WebApis,
    props: HashMap<String, String>,
) -> Result<Value, AllocError> {
    let handle = apis.next_handle();
    let obj = heap.alloc_object(Object::new(ObjectKind::Ordinary))?;
    // Unreachable until the caller links the returned value into a rooted
    // graph; `def_native` allocates, so hold a temporary root across the
    // build.
    with_temp_root(heap, Value::Object(obj), |heap| {
        def(heap, obj, CTX_KEY, Value::Int(apis.id as i32))?;
        def(heap, obj, STYLE_KEY, Value::Int(handle as i32))?;
        def_native(heap, obj, "getPropertyValue", n_style_get_property_value)?;
        // CSSOM: computed-style longhands are readable as named data
        // properties, both dashed (`style["margin-left"]`) and camelCase
        // (`style.marginLeft`), per CSSOM §5.4.2. The snapshot is
        // read-only, so the named properties are non-writable: writes
        // are ignored instead of sticking.
        for (name, value) in &props {
            let v = Value::Str(heap.alloc_str(value)?);
            // `float` is a reserved word in Rust, so the bindings' Rust
            // identifiers use `cssFloat` — but on the JS object both
            // names work, matching browsers: `cssFloat` is the IDL
            // attribute name and `float` the named-property form
            // (WPT css/CSS2/floats/computed-float-position-absolute.html
            // reads `getComputedStyle(el)['float']`).
            if name == "float" {
                def_readonly(heap, obj, "cssFloat", v)?;
                def_readonly(heap, obj, "float", v)?;
                continue;
            }
            def_readonly(heap, obj, name, v)?;
            let camel = css_camel(name);
            if camel != *name {
                def_readonly(heap, obj, &camel, v)?;
            }
        }
        Ok(())
    })?;
    apis.styles.insert(handle, props);
    Ok(Value::Object(obj))
}

