fn n_create_element(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let tag = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    if tag.is_empty() {
        return Err(err_type("createElement: tag name is empty"));
    }
    let node = rc
        .borrow_mut()
        .live_document()?
        .borrow_mut()
        .create_element(&tag);
    let mut g = rc.borrow_mut();
    wrap_node(heap, &mut g, node).map_err(|_| NativeError::OutOfMemory)
}

/// Well-known element namespace URIs for `document.createElementNS`.
const XHTML_NAMESPACE_URI: &str = "http://www.w3.org/1999/xhtml";
const MATHML_NAMESPACE_URI: &str = "http://www.w3.org/1998/Math/MathML";
const SVG_NAMESPACE_URI: &str = "http://www.w3.org/2000/svg";

/// Resolve the `namespace` argument of `createElementNS` to a
/// [`Namespace`]: `null`/`undefined`/`""` mean no namespace, which for an
/// HTML document is the HTML namespace. Per the DOM "validate and extract"
/// algorithm only the prefix rules are validated — any other namespace URI
/// is legal and carried as [`Namespace::Other`], never silently
/// mis-namespaced as HTML/SVG/MathML.
fn resolve_namespace_arg(heap: &mut Heap, v: Value) -> Result<Namespace, NativeError> {
    match v {
        Value::Null | Value::Undefined => Ok(Namespace::Html),
        _ => {
            let s = arg_to_string(heap, v)?;
            match s.as_str() {
                "" | XHTML_NAMESPACE_URI => Ok(Namespace::Html),
                MATHML_NAMESPACE_URI => Ok(Namespace::MathMl),
                SVG_NAMESPACE_URI => Ok(Namespace::Svg),
                _ => Ok(Namespace::Other(s.into())),
            }
        }
    }
}

/// `document.createElementNS`: like `createElement` but in an explicit
/// namespace; the tag name is kept as-is (no ASCII lowercasing).
fn n_create_element_ns(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let ns = resolve_namespace_arg(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let tag = arg_to_string(&mut *heap, args.get(1).copied().unwrap_or(Value::Undefined))?;
    if tag.is_empty() {
        // No `DOMException` in the engine yet: like `atob`/`btoa`, the
        // spec's `InvalidCharacterError` surfaces as a `TypeError` with
        // the DOM name in the message (see `bindings_url.rs`).
        return Err(err_type(
            "createElementNS: InvalidCharacterError: qualified name is empty",
        ));
    }
    let node = rc
        .borrow_mut()
        .live_document()?
        .borrow_mut()
        .create_element_ns(ns, &tag);
    let mut g = rc.borrow_mut();
    wrap_node(heap, &mut g, node).map_err(|_| NativeError::OutOfMemory)
}

