/// Whether `node` is an HTML `<img>` element: the only element the
/// `HTMLImageElement` `src`/`complete` accessors below apply to.
fn is_img_element(doc: &Document, node: NodeId) -> bool {
    matches!(
        doc.kind(node),
        NodeKind::Element(d) if d.namespace == Namespace::Html && d.tag_name.as_str() == "img"
    )
}

/// `HTMLImageElement.src` getter/setter and `HTMLImageElement.complete`
/// getter (WHATWG HTML §4.8.3). Installed as own accessors on `<img>`
/// wrappers by [`create_wrapper`].
///
/// The `src` setter reflects to the content attribute; the embedder's
/// image pipeline observes the attribute change and (re)fetches.
/// `complete` reads the embedder-shared completed-load set (see
/// [`share_completed_image_loads`]).
fn n_img_src_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let src = {
        let g = rc.borrow();
        let doc = g.live_document()?;
        doc.borrow()
            .get_attribute(node, "src")
            .unwrap_or("")
            .to_string()
    };
    str_of(&src, heap)
}

fn n_img_src_set(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let src = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    {
        let g = rc.borrow();
        let doc = g.live_document()?;
        doc.borrow_mut().set_attribute(node, "src", &src);
    }
    Ok(Value::Undefined)
}

fn n_img_complete_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    // No `src` content attribute: never complete (the load never
    // started). Otherwise complete iff the embedder recorded a
    // completed load for this node.
    let complete = {
        let g = rc.borrow();
        let doc = g.live_document()?;
        let has_src = doc.borrow().get_attribute(node, "src").is_some();
        has_src && g.completed_image_loads.borrow().contains(&node)
    };
    Ok(Value::Bool(complete))
}

/// `HTMLImageElement.complete` is readonly (WebIDL): setting it is a
/// silent no-op.
fn n_img_complete_set_noop(
    _heap: &mut Heap,
    _this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    Ok(Value::Undefined)
}

/// `HTMLAnchorElement.href` getter/setter and `HTMLAnchorElement.search`
/// getter/setter (WHATWG HTML `HTMLHyperlinkElementUtils`; logic in
/// [`dom::anchor`]). Installed as own accessors on `<a>` wrappers by
/// [`create_wrapper`].
///
/// The document base URL comes from the realm's API base URL. The
/// document-encoding override for query percent-encoding is not plumbed
fn n_anchor_href_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let (node, base) = {
        let g = rc.borrow();
        (target_node(heap, this, &g)?, g.base_url.clone())
    };
    let s = {
        let g = rc.borrow();
        let doc = g.live_document()?;
        dom::anchor::anchor_href_serialized(&doc.borrow(), node, &base, doc.borrow().encoding())
    };
    str_of(&s, heap)
}

