fn n_get_attribute(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let name = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    // No intermediate `String`: the document borrow is held across
    // `alloc_str` (it touches neither the document nor the API registry),
    // so the attribute `&str` is copied exactly once, into the heap.
    let g = rc.borrow();
    let doc_rc = g.live_document()?;
    let doc = doc_rc.borrow();
    match doc.get_attribute(node, &name) {
        Some(v) => heap
            .alloc_str(v)
            .map(Value::Str)
            .map_err(|_| NativeError::OutOfMemory),
        None => Ok(Value::Null),
    }
}

/// `Element.hasAttribute`: true when the receiver carries the named
/// attribute. Mirrors [`n_get_attribute`] (same name resolution and
/// receiver handling); the presence test is `get_attribute(...).is_some()`.
///
/// Known deviation, shared with the document API and left unchanged
/// so the element API does not diverge from it: a missing argument
/// stringifies to `"undefined"`, and an invalid attribute name
/// returns `false` instead of throwing `InvalidCharacterError`.
fn n_has_attribute(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let name = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let g = rc.borrow();
    let doc_rc = g.live_document()?;
    let doc = doc_rc.borrow();
    Ok(Value::Bool(doc.get_attribute(node, &name).is_some()))
}

fn n_set_attribute(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let name = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let value = arg_to_string(&mut *heap, args.get(1).copied().unwrap_or(Value::Undefined))?;
    // `Document::set_attribute` is a silent no-op on non-elements, matching
    // the DOM API's contract as bound here.
    rc.borrow_mut()
        .live_document()?
        .borrow_mut()
        .set_attribute(node, &name, &value);
    Ok(Value::Undefined)
}

fn n_remove_attribute(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let name = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    rc.borrow_mut()
        .live_document()?
        .borrow_mut()
        .remove_attribute(node, &name);
    Ok(Value::Undefined)
}

// ---------------------------------------------------------------------------
// Production `classList` (the live DOMTokenList view)
// ---------------------------------------------------------------------------
//
// The w51 in-place upgrade strips the parse shim's own `style`,
// `className`, and `classList` properties (see
// [`SHIM_ELEMENT_OWN_NAMES`]): shim-only state must not shadow or
// outlive the parse. The production `classList` accessor lives on the
// shared `element_proto`, backed by the live document's `class`
// attribute — the same single source of truth the parse shim used,
// so values written mid-parse survive the upgrade and production
// writes are visible to `getAttribute`/`getComputedStyle`.
// (`className` and `style` live in the completer's CSSOM section
// below; the install order there overwrites the earlier twins.)

/// Read the live document's `class` attribute token list.
fn prod_class_tokens(rc: &Rc<RefCell<WebApis>>, node: NodeId) -> Result<Vec<String>, NativeError> {
    let g = rc.borrow();
    Ok(g.live_document()?
        .borrow()
        .get_attribute(node, "class")
        .map(|v| v.split_whitespace().map(str::to_string).collect())
        .unwrap_or_default())
}

/// Hidden key caching the live `classList` view on a production
/// element wrapper (`el.classList === el.classList`).
const EL_CLASS_LIST_KEY: &str = "\u{0}bowser:el-class-list";

/// Wrap a minimal `DOMTokenList` view for the production element's
/// `class` attribute. Every method reads/writes the attribute, so views
/// never disagree; the view itself is cached on the element wrapper
/// under [`EL_CLASS_LIST_KEY`] (`el.classList === el.classList` per
/// WebIDL `[SameObject]`). The view carries the element's context/node
/// handles so the token methods resolve through `apis_rc` /
/// `target_node` directly.
fn wrap_prod_class_list(heap: &mut Heap, this: Value) -> Result<Value, NativeError> {
    let Value::Object(el) = this else {
        return Err(err_type("classList accessed on a non-element"));
    };
    let obj = heap
        .alloc_object(Object::new(ObjectKind::Ordinary))
        .map_err(|_| NativeError::OutOfMemory)?;
    with_temp_root(
        heap,
        Value::Object(obj),
        |heap| -> Result<(), NativeError> {
            let oom = |_: AllocError| NativeError::OutOfMemory;
            for key in [CTX_KEY, NODE_KEY] {
                if let Some(p) = heap.get_property(el, Wtf8::from_str(key)) {
                    def(heap, obj, key, p.value).map_err(oom)?;
                }
            }
            def_native(heap, obj, "add", n_prod_class_list_add).map_err(oom)?;
            def_native(heap, obj, "remove", n_prod_class_list_remove).map_err(oom)?;
            def_native(heap, obj, "toggle", n_prod_class_list_toggle).map_err(oom)?;
            def_native(heap, obj, "contains", n_prod_class_list_contains).map_err(oom)?;
            Ok(())
        },
    )?;
    Ok(Value::Object(obj))
}

fn n_class_list_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let Value::Object(obj) = this else {
        return Err(err_type("classList accessed on a non-element"));
    };
    // `[SameObject]`: return the cached live view when present. The
    // view's methods resolve the element and read/write the `class`
    // attribute on every call, so the cached view cannot go stale.
    if let Some(p) = heap.get_property(obj, Wtf8::from_str(EL_CLASS_LIST_KEY))
        && let Value::Object(o) = p.value
    {
        return Ok(Value::Object(o));
    }
    let view = wrap_prod_class_list(heap, this)?;
    if let Value::Object(o) = view {
        def(heap, obj, EL_CLASS_LIST_KEY, Value::Object(o))
            .map_err(|_| NativeError::OutOfMemory)?;
    }
    Ok(view)
}

fn n_prod_class_list_add(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let tokens = parse_class_list_args(&mut *heap, args)?;
    let mut cur = prod_class_tokens(&rc, node)?;
    for t in tokens {
        if !cur.contains(&t) {
            cur.push(t);
        }
    }
    rc.borrow_mut()
        .live_document()?
        .borrow_mut()
        .set_attribute(node, "class", &cur.join(" "));
    Ok(Value::Undefined)
}

fn n_prod_class_list_remove(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let tokens = parse_class_list_args(&mut *heap, args)?;
    let mut cur = prod_class_tokens(&rc, node)?;
    cur.retain(|c| !tokens.contains(c));
    rc.borrow_mut()
        .live_document()?
        .borrow_mut()
        .set_attribute(node, "class", &cur.join(" "));
    Ok(Value::Undefined)
}

fn n_prod_class_list_toggle(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let mut rest = args.iter().copied();
    let token = {
        let s = arg_to_string(&mut *heap, rest.next().unwrap_or(Value::Undefined))?;
        if s.is_empty() || s.split_whitespace().count() != 1 {
            return Err(err_type("classList token must be a single non-empty token"));
        }
        s
    };
    let force = rest.next();
    let mut cur = prod_class_tokens(&rc, node)?;
    let has = cur.contains(&token);
    let want = match force {
        Some(v) => parse_truthy(v),
        None => !has,
    };
    if want && !has {
        cur.push(token);
    } else if !want && has {
        cur.retain(|c| c != &token);
    }
    rc.borrow_mut()
        .live_document()?
        .borrow_mut()
        .set_attribute(node, "class", &cur.join(" "));
    Ok(Value::Bool(want))
}

fn n_prod_class_list_contains(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let token = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    Ok(Value::Bool(prod_class_tokens(&rc, node)?.contains(&token)))
}

/// The DOM `HierarchyRequestError` analogue: `bowser_dom` panics on
/// childless parents, so the bindings pre-check and throw a `TypeError`.
fn check_can_parent(doc: &Document, parent: NodeId, op: &str) -> Result<(), NativeError> {
    match doc.kind(parent) {
        NodeKind::Document | NodeKind::Element(_) | NodeKind::DocumentFragment => Ok(()),
        NodeKind::DocumentType(_) => {
            Err(err_type(format!("{op}: DocumentType cannot have children")))
        }
        NodeKind::Text(_) => Err(err_type(format!("{op}: Text cannot have children"))),
        NodeKind::Comment(_) => Err(err_type(format!("{op}: Comment cannot have children"))),
        NodeKind::ProcessingInstruction { .. } => {
            Err(err_type(format!("{op}: node cannot have children")))
        }
    }
}

fn n_append_child(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let child_arg = args.first().copied().unwrap_or(Value::Undefined);
    let (parent, child) = {
        let g = rc.borrow();
        (
            target_node(heap, this, &g)?,
            target_node(heap, child_arg, &g)?,
        )
    };
    {
        let g = rc.borrow();
        let doc_rc = g.live_document()?;
        let doc = doc_rc.borrow();
        check_can_parent(&doc, parent, "appendChild")?;
        if matches!(doc.kind(child), NodeKind::Document) {
            return Err(err_type("appendChild: cannot append the document node"));
        }
        // A shadow root is not insertable: `Document` insertion would
        // splice the fragment and empty the shadow tree (the DOM
        // `HierarchyRequestError` analogue).
        if doc.is_shadow_root(child) {
            return Err(err_type("appendChild: cannot insert a shadow root"));
        }
    }
    let old_parent = rc.borrow().live_document()?.borrow().parent(child);
    {
        let g = rc.borrow_mut();
        g.live_document()?.borrow_mut().append_child(parent, child);
    }
    // The child's wrapper is the identity wrapper (cache hit); ancestor
    // chains and document props are re-synced for the live properties.
    let mut g = rc.borrow_mut();
    after_dom_mutation(heap, &mut g, &[child])?;
    if let Some(op) = old_parent
        && op != parent
    {
        after_dom_mutation(heap, &mut g, &[op])?;
    }
    wrap_node(heap, &mut g, child).map_err(|_| NativeError::OutOfMemory)
}

/// `Element.attachShadow(init)` (DOM §4.6.2 — minimal viable).
/// Creates the host's shadow root and returns its wrapper. `mode:
/// "open"` exposes the root through the `shadowRoot` getter;
/// `"closed"` keeps it reachable only through the DOM's internal
/// fragment→host map, so layout and snap-target retargeting still see
/// the shadow content while the page cannot name it.
///
/// Throws `TypeError` when the receiver is not an element, `init` is
/// missing or not an object, `mode` is absent or not `"open"` /
/// `"closed"`, or the host already has a shadow root (the spec's
/// `NotSupportedError` / `InvalidStateError` analogues).
///
/// Deliberately not implemented (documented follow-ups):
/// `delegatesFocus` / `clonable` init members, slotting (`<slot>`),
/// `:host` selectors, style scoping, and event retargeting.
fn n_attach_shadow(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let host = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    // The init dictionary: `mode` is required. A getter runs script,
    // so no `WebApis` borrow is held while reading it.
    let mode = match args.first().copied().unwrap_or(Value::Undefined) {
        Value::Object(obj) => match dict_get(heap, obj, "mode")? {
            Some(v) => {
                let s = arg_to_string(&mut *heap, v)?;
                match s.as_str() {
                    "open" => dom::ShadowRootMode::Open,
                    "closed" => dom::ShadowRootMode::Closed,
                    _ => {
                        return Err(err_type(
                            "attachShadow: mode must be \"open\" or \"closed\"",
                        ));
                    }
                }
            }
            None => return Err(err_type("attachShadow: init.mode is required")),
        },
        _ => return Err(err_type("attachShadow: init argument is required")),
    };
    let fragment = {
        let g = rc.borrow();
        let doc_rc = g.live_document()?;
        let mut doc = doc_rc.borrow_mut();
        // The spec throws `NotSupportedError` for elements that cannot
        // be shadow hosts; this engine only distinguishes element vs
        // non-element (every element name is a valid host here).
        if !matches!(doc.kind(host), dom::NodeKind::Element(_)) {
            return Err(err_type("attachShadow: receiver is not an element"));
        }
        match doc.attach_shadow_root(host, mode) {
            Some(f) => f,
            None => {
                return Err(err_type(
                    "attachShadow: element already hosts a shadow root",
                ));
            }
        }
    };
    // The host's rendered children changed (its boxes now render the
    // shadow tree): re-sync the live wrapper properties.
    let mut g = rc.borrow_mut();
    after_dom_mutation(heap, &mut g, &[host])?;
    wrap_node(heap, &mut g, fragment).map_err(|_| NativeError::OutOfMemory)
}

/// `Element.shadowRoot` (DOM §4.6.2): the open shadow root's wrapper,
/// or `null` for a closed root / no root. Read-only per WebIDL.
fn n_shadow_root_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let host = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let fragment = {
        let g = rc.borrow();
        let doc_rc = g.live_document()?;
        let doc = doc_rc.borrow();
        match doc.shadow_root(host) {
            Some(data) if data.mode == dom::ShadowRootMode::Open => Some(data.root),
            _ => None,
        }
    };
    match fragment {
        Some(f) => {
            let mut g = rc.borrow_mut();
            wrap_node(heap, &mut g, f).map_err(|_| NativeError::OutOfMemory)
        }
        None => Ok(Value::Null),
    }
}

fn n_insert_before(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let child_arg = args.first().copied().unwrap_or(Value::Undefined);
    let before_arg = args.get(1).copied();
    let (parent, child) = {
        let g = rc.borrow();
        (
            target_node(heap, this, &g)?,
            target_node(heap, child_arg, &g)?,
        )
    };
    let before = match before_arg {
        None | Some(Value::Null) | Some(Value::Undefined) => None,
        Some(v) => {
            let g = rc.borrow();
            Some(target_node(heap, v, &g)?)
        }
    };
    {
        let g = rc.borrow();
        let doc_rc = g.live_document()?;
        let doc = doc_rc.borrow();
        check_can_parent(&doc, parent, "insertBefore")?;
        if matches!(doc.kind(child), NodeKind::Document) {
            return Err(err_type("insertBefore: cannot insert the document node"));
        }
        // A shadow root is not insertable (see `n_append_child`).
        if doc.is_shadow_root(child) {
            return Err(err_type("insertBefore: cannot insert a shadow root"));
        }
        if let Some(b) = before
            && doc.parent(b) != Some(parent)
        {
            return Err(err_type("insertBefore: reference node is not a child"));
        }
    }
    let old_parent = rc.borrow().live_document()?.borrow().parent(child);
    {
        let g = rc.borrow_mut();
        g.live_document()?
            .borrow_mut()
            .insert_before(parent, child, before);
    }
    let mut g = rc.borrow_mut();
    after_dom_mutation(heap, &mut g, &[child])?;
    if let Some(op) = old_parent
        && op != parent
    {
        after_dom_mutation(heap, &mut g, &[op])?;
    }
    wrap_node(heap, &mut g, child).map_err(|_| NativeError::OutOfMemory)
}

fn n_remove_child(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let child_arg = args.first().copied().unwrap_or(Value::Undefined);
    let (parent, child) = {
        let g = rc.borrow();
        (
            target_node(heap, this, &g)?,
            target_node(heap, child_arg, &g)?,
        )
    };
    {
        let g = rc.borrow();
        let doc_rc = g.live_document()?;
        let doc = doc_rc.borrow();
        // `Document::remove_child` silently no-ops on a non-child; the DOM
        // `NotFoundError` analogue throws instead.
        if doc.parent(child) != Some(parent) {
            return Err(err_type("removeChild: node is not a child"));
        }
    }
    {
        let g = rc.borrow_mut();
        g.live_document()?.borrow_mut().remove_child(parent, child);
    }
    // The detached child keeps its wrapper (wrapper identity survives
    // removal); ancestors re-sync so `children`/`textContent` stay live.
    let mut g = rc.borrow_mut();
    after_dom_mutation(heap, &mut g, &[parent, child])?;
    wrap_node(heap, &mut g, child).map_err(|_| NativeError::OutOfMemory)
}

// ---------------------------------------------------------------------------
// Element matching and serialization natives
// ---------------------------------------------------------------------------

fn n_matches(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let sel = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let hit = rc
        .borrow()
        .live_document()?
        .borrow()
        .matches(node, &sel)
        .map_err(|e| NativeError::SyntaxError(e.message().to_string()))?;
    Ok(Value::Bool(hit))
}

fn n_closest(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let sel = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let found = rc
        .borrow()
        .live_document()?
        .borrow()
        .closest(node, &sel)
        .map_err(|e| NativeError::SyntaxError(e.message().to_string()))?;
    match found {
        Some(n) => {
            let mut g = rc.borrow_mut();
            wrap_node(heap, &mut g, n).map_err(|_| NativeError::OutOfMemory)
        }
        None => Ok(Value::Null),
    }
}

/// Scope-relative selector support for `Element.querySelector` /
/// `querySelectorAll` (w79fix). The shared document parser rejects a
/// leading combinator and rejects `:` in a type selector, so
/// `el.querySelector("> p")`, `el.querySelector(":scope > p")`, and
/// `el.querySelector(":scope")` all threw `SyntaxError` even though
/// the DOM spec allows them on an element (`:scope` denotes the
/// receiver). The document path is deliberately untouched, so
/// `document.querySelector` still rejects those same strings: only
/// the element path below routes scope-relative groups through this
/// evaluator, and every other group still goes through the shared
/// `Document::query_selector_all_in` unchanged.
///
/// A scope-relative group is evaluated left to right from the
/// receiver: `:scope` (plus any trailing simple selectors on the same
/// compound, e.g. `:scope.a`) is the start set, a leading combinator
/// starts from the receiver, and each step expands through children
/// (`>`), descendants (whitespace), the next element sibling (`+`),
/// or following element siblings (`~`), testing each candidate with
/// `Document::matches` on the single compound. That makes
/// `:scope`-anchored sibling steps able to return nodes outside the
/// receiver's subtree, as in browsers, while plain groups stay
/// descendant-only. Every compound is validated up front with a probe
/// `matches` call, so a bad compound throws even when the receiver
/// has no candidates to test it against (the shared path's
/// fail-before-parse contract).
fn split_selector_groups(sel: &str) -> Vec<&str> {
    let bytes = sel.as_bytes();
    let mut groups = Vec::new();
    let mut start = 0usize;
    let mut depth = 0u32;
    let mut quote: Option<u8> = None;
    let mut i = 0usize;
    while i < bytes.len() {
        let c = bytes[i];
        if let Some(q) = quote {
            if c == q {
                quote = None;
            }
        } else {
            match c {
                b'\'' | b'"' => quote = Some(c),
                b'[' => depth += 1,
                b']' => depth = depth.saturating_sub(1),
                b',' if depth == 0 => {
                    groups.push(sel[start..i].trim());
                    start = i + 1;
                }
                _ => {}
            }
        }
        i += 1;
    }
    groups.push(sel[start..].trim());
    groups
}

fn is_scope_relative_group(group: &str) -> bool {
    let g = group.trim_start();
    if g.starts_with('>') || g.starts_with('+') || g.starts_with('~') {
        return true;
    }
    if let Some(rest) = g.strip_prefix(":scope") {
        return rest.is_empty()
            || rest.starts_with(|c: char| {
                matches!(
                    c,
                    ' ' | '\t' | '\n' | '\r' | '>' | '+' | '~' | '.' | '#' | '[' | ':' | '*'
                )
            });
    }
    false
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScopeCombinator {
    Child,
    NextSibling,
    SubsequentSibling,
    Descendant,
}

#[derive(Debug, Clone, Copy)]
enum ScopeToken<'a> {
    Comb(ScopeCombinator),
    Compound(&'a str),
}

/// Split one scope-relative group into combinator / compound tokens.
/// Whitespace between compounds is the implicit descendant combinator
/// (recorded at evaluation, not here); `>`/`+`/`~` and whitespace
/// inside `[...]` or quotes never split.
fn tokenize_scope_group(group: &str) -> Result<Vec<ScopeToken<'_>>, NativeError> {
    let err = || NativeError::SyntaxError("invalid scope-relative selector".to_string());
    let bytes = group.as_bytes();
    let mut tokens = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if b.is_ascii_whitespace() {
            i += 1;
            continue;
        }
        if b == b'>' || b == b'+' || b == b'~' {
            tokens.push(ScopeToken::Comb(match b {
                b'>' => ScopeCombinator::Child,
                b'+' => ScopeCombinator::NextSibling,
                _ => ScopeCombinator::SubsequentSibling,
            }));
            i += 1;
            continue;
        }
        let start = i;
        let mut quote: Option<u8> = None;
        let mut depth = 0u32;
        while i < bytes.len() {
            let c = bytes[i];
            if let Some(q) = quote {
                if c == q {
                    quote = None;
                }
                i += 1;
                continue;
            }
            match c {
                b'\'' | b'"' => {
                    quote = Some(c);
                    i += 1;
                }
                b'[' => {
                    depth += 1;
                    i += 1;
                }
                b']' => {
                    depth = depth.saturating_sub(1);
                    i += 1;
                }
                b'>' | b'+' | b'~' if depth == 0 => break,
                _ if c.is_ascii_whitespace() && depth == 0 => break,
                _ => i += 1,
            }
        }
        if start == i {
            return Err(err());
        }
        tokens.push(ScopeToken::Compound(&group[start..i]));
    }
    if tokens.is_empty() {
        return Err(err());
    }
    Ok(tokens)
}

fn syntax_err(e: impl std::fmt::Display) -> NativeError {
    NativeError::SyntaxError(e.to_string())
}

/// Byte index of a genuine `:scope` pseudo in `s`, i.e. one outside
/// `[...]`/`(...)`/quotes and followed by the end of the compound or
/// a simple-selector delimiter (`.`, `#`, `[`, `:`, `*`). A trailing
/// name character (as in `:scopefoo`) is not a `:scope` pseudo, so
/// such a compound falls through to the shared parser and throws.
fn scope_pseudo_index(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut i = 0usize;
    let mut bracket = 0u32;
    let mut paren = 0u32;
    let mut quote: Option<u8> = None;
    while i < bytes.len() {
        let b = bytes[i];
        if let Some(q) = quote {
            if b == q {
                quote = None;
            }
            i += 1;
            continue;
        }
        match b {
            b'\'' | b'"' => quote = Some(b),
            b'[' => bracket += 1,
            b']' => bracket = bracket.saturating_sub(1),
            b'(' => paren += 1,
            b')' => paren = paren.saturating_sub(1),
            b':' if bracket == 0 && paren == 0 && s[i..].starts_with(":scope") => {
                let after = &s[i + ":scope".len()..];
                if after.is_empty()
                    || after.starts_with(|c: char| ['.', '#', '[', ':', '*'].contains(&c))
                {
                    return Some(i);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

/// Match a compound that may contain `:scope` against `candidate`:
/// the `:scope` part means "is the receiver", the remainder matches
/// via the shared parser. Compounds without a genuine `:scope`
/// pseudo go straight to the shared parser (so they still throw).
fn matches_scope_compound(
    doc: &Document,
    candidate: NodeId,
    scope: NodeId,
    s: &str,
) -> Result<bool, NativeError> {
    let Some(idx) = scope_pseudo_index(s) else {
        return doc.matches(candidate, s).map_err(syntax_err);
    };
    let stripped = format!("{}{}", &s[..idx], &s[idx + ":scope".len()..]);
    let rest_ok = if scope_pseudo_index(&stripped).is_some() {
        matches_scope_compound(doc, candidate, scope, &stripped)?
    } else if stripped.is_empty() {
        true
    } else {
        doc.matches(candidate, &stripped).map_err(syntax_err)?
    };
    Ok(candidate == scope && rest_ok)
}

/// Validate a compound that may contain `:scope`: validate the
/// remainder after removing the `:scope` pseudo, so `div:scope` and
/// bare `:scope` in a later position do not throw in the probe while
/// a genuinely bad remainder (`:scope > :bad`) still does.
fn validate_scope_compound(doc: &Document, scope: NodeId, s: &str) -> Result<(), NativeError> {
    let Some(idx) = scope_pseudo_index(s) else {
        return doc.matches(scope, s).map_err(syntax_err).map(|_| ());
    };
    let stripped = format!("{}{}", &s[..idx], &s[idx + ":scope".len()..]);
    if scope_pseudo_index(&stripped).is_some() {
        return validate_scope_compound(doc, scope, &stripped);
    }
    if stripped.is_empty() {
        return Ok(());
    }
    doc.matches(scope, &stripped)
        .map_err(syntax_err)
        .map(|_| ())
}

/// Evaluate one scope-relative group against `scope` (see the header
/// comment above [`split_selector_groups`]).
fn eval_scope_group(
    doc: &Document,
    scope: NodeId,
    group: &str,
) -> Result<Vec<NodeId>, NativeError> {
    let err = || NativeError::SyntaxError("invalid scope-relative selector".to_string());
    let tokens = tokenize_scope_group(group)?;
    // Validate every compound up front (probe `matches` on the scope
    // itself: parsing happens before any element test, so this throws
    // on a bad compound even with zero candidates).
    for tok in &tokens {
        if let ScopeToken::Compound(s) = tok {
            validate_scope_compound(doc, scope, s)?;
        }
    }
    let mut current: Vec<NodeId> = Vec::new();
    let mut idx = 0usize;
    match tokens.first() {
        Some(ScopeToken::Compound(s)) if s.starts_with(":scope") => {
            // The leading compound is the receiver filtered by its
            // trailing simple selectors (`.a`, `#x`, `[attr]`,
            // `:pseudo`, `*`); a non-`:scope` rest such as
            // `:scopefoo` was already rejected by the probe above.
            if !matches_scope_compound(doc, scope, scope, s)? {
                return Ok(Vec::new());
            }
            current.push(scope);
            idx = 1;
        }
        Some(ScopeToken::Comb(_)) => {
            current.push(scope);
        }
        _ => return Err(err()),
    }
    let mut comb: Option<ScopeCombinator> = None;
    for tok in tokens.iter().skip(idx) {
        match tok {
            ScopeToken::Comb(c) => {
                if comb.is_some() {
                    return Err(err());
                }
                comb = Some(*c);
            }
            ScopeToken::Compound(s) => {
                let c = comb.take().unwrap_or(ScopeCombinator::Descendant);
                let mut next: Vec<NodeId> = Vec::new();
                let mut seen: HashSet<NodeId> = HashSet::new();
                for &n in &current {
                    match c {
                        ScopeCombinator::Child => {
                            for kid in doc.children(n) {
                                if matches!(doc.kind(kid), NodeKind::Element(_))
                                    && matches_scope_compound(doc, kid, scope, s)?
                                {
                                    next.push(kid);
                                }
                            }
                        }
                        ScopeCombinator::Descendant => {
                            for d in doc.descendants(n) {
                                if matches!(doc.kind(d), NodeKind::Element(_))
                                    && seen.insert(d)
                                    && matches_scope_compound(doc, d, scope, s)?
                                {
                                    next.push(d);
                                }
                            }
                        }
                        ScopeCombinator::NextSibling => {
                            let mut cursor = doc.next_sibling(n);
                            while let Some(sib) = cursor {
                                if matches!(doc.kind(sib), NodeKind::Element(_)) {
                                    if matches_scope_compound(doc, sib, scope, s)? {
                                        next.push(sib);
                                    }
                                    break;
                                }
                                cursor = doc.next_sibling(sib);
                            }
                        }
                        ScopeCombinator::SubsequentSibling => {
                            let mut cursor = doc.next_sibling(n);
                            while let Some(sib) = cursor {
                                if matches!(doc.kind(sib), NodeKind::Element(_))
                                    && matches_scope_compound(doc, sib, scope, s)?
                                {
                                    next.push(sib);
                                }
                                cursor = doc.next_sibling(sib);
                            }
                        }
                    }
                }
                current = next;
                if current.is_empty() {
                    break;
                }
            }
        }
    }
    if comb.is_some() {
        return Err(err());
    }
    Ok(current)
}

/// Element-scoped `querySelectorAll`: the shared
/// `Document::query_selector_all_in` when no group is scope-relative
/// (zero behavior change there), otherwise each group evaluated
/// separately — scope-relative groups by [`eval_scope_group`], the
/// rest by the shared path — unioned in document order. One bad group
/// fails the whole call, as in the shared path.
fn element_query_all_in(
    doc: &Document,
    scope: NodeId,
    sel: &str,
) -> Result<Vec<NodeId>, NativeError> {
    let groups = split_selector_groups(sel);
    if groups.iter().all(|g| !is_scope_relative_group(g)) {
        return doc.query_selector_all_in(scope, sel).map_err(syntax_err);
    }
    let mut out: Vec<NodeId> = Vec::new();
    let mut seen: HashSet<NodeId> = HashSet::new();
    for g in &groups {
        let nodes = if is_scope_relative_group(g) {
            eval_scope_group(doc, scope, g)?
        } else {
            doc.query_selector_all_in(scope, g).map_err(syntax_err)?
        };
        for n in nodes {
            if seen.insert(n) {
                out.push(n);
            }
        }
    }
    // Document order: position in the root preorder walk. Nodes
    // outside that walk (a detached subtree) order by their own
    // subtree's preorder walk instead of evaluation (group) order,
    // so `qsa("p, :scope")` on a detached subtree yields the scope
    // before its `p` child. Attached nodes sort before detached
    // ones; the stable sort keeps any remaining ties in order.
    let preorder = doc.descendants(doc.root());
    let mut pos: HashMap<NodeId, usize> = HashMap::with_capacity(preorder.len());
    for (i, n) in preorder.iter().enumerate() {
        pos.insert(*n, i);
    }
    let mut detached_root = scope;
    while let Some(parent) = doc.parent(detached_root) {
        detached_root = parent;
    }
    let mut detached_pos: HashMap<NodeId, usize> = HashMap::new();
    if detached_root != doc.root() {
        detached_pos.insert(detached_root, 0);
        for (i, n) in doc.descendants(detached_root).iter().enumerate() {
            detached_pos.insert(*n, i + 1);
        }
    }
    out.sort_by(|a, b| match (pos.get(a), pos.get(b)) {
        (Some(x), Some(y)) => x.cmp(y),
        (None, None) => detached_pos
            .get(a)
            .copied()
            .unwrap_or(usize::MAX)
            .cmp(&detached_pos.get(b).copied().unwrap_or(usize::MAX)),
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
    });
    Ok(out)
}

/// `Element.querySelector`: first descendant of the receiver (never
/// the receiver itself) matching the selector, in document order, or
/// `null`. Mirrors [`n_closest`]: the receiver resolves via
/// [`target_node`] against the live document, and a bad selector raises
/// `SyntaxError` like [`n_query_selector`] does. The document wrapper
/// keeps its own document-wide `querySelector` (installed on `doc_obj`,
/// shadowing this prototype method), so this scoped form only ever
/// serves element receivers.
///
/// Scope-relative selectors (`:scope`, a leading combinator) are
/// handled by [`element_query_all_in`]: `:scope` alone matches the
/// receiver itself, and `:scope`-anchored sibling steps may match
/// outside the receiver's subtree, per the DOM spec. Argument
/// handling is deliberately the same as the document API — a missing
/// argument stringifies to `"undefined"` — a known deviation shared
/// with [`n_query_selector`], not diverged here.
fn n_element_query_selector(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let sel = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let found = {
        let doc_rc = rc.borrow().live_document()?;
        let doc = doc_rc.borrow();
        element_query_all_in(&doc, node, &sel)?.into_iter().next()
    };
    match found {
        Some(n) => {
            let mut g = rc.borrow_mut();
            wrap_node(heap, &mut g, n).map_err(|_| NativeError::OutOfMemory)
        }
        None => Ok(Value::Null),
    }
}

/// `Element.querySelectorAll`: every descendant of the receiver (never
/// the receiver itself) matching the selector, in document order.
/// Same Array-shaped, `node_list_proto`-linked result as the document
/// [`n_query_selector_all`] (mirrored, not shared: the document form
/// queries whole-document, this one queries the receiver's subtree).
/// Scope-relative groups are evaluated by [`element_query_all_in`]
/// (see [`split_selector_groups`]); a `:scope`-only selector yields
/// the receiver itself, the one exception to "never the receiver".
fn n_element_query_selector_all(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let sel = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let nodes = {
        let doc_rc = rc.borrow().live_document()?;
        let doc = doc_rc.borrow();
        element_query_all_in(&doc, node, &sel)?
    };
    // Array-kind object with indexed properties, per builtin_object_array.
    let arr = heap
        .alloc_object(Object::new(ObjectKind::Array))
        .map_err(|_| NativeError::OutOfMemory)?;
    let proto = rc.borrow().gc_roots.borrow().node_list_proto;
    // `arr` is unreachable from any GC root until the caller roots the
    // returned value; `wrap_node` allocates, so hold a temporary root
    // across the fill.
    with_temp_root(
        heap,
        Value::Object(arr),
        |heap| -> Result<(), NativeError> {
            link_node_list_proto(heap, arr, proto);
            let mut g = rc.borrow_mut();
            for (i, n) in nodes.iter().enumerate() {
                let w = wrap_node(heap, &mut g, *n).map_err(|_| NativeError::OutOfMemory)?;
                // `w` may be a weak-cache wrapper invisible to the
                // collector: root it across the allocating `def` (its
                // key interning can trigger a threshold collection)
                // until the array links it in, like `n_child_nodes_get`.
                with_temp_root(heap, w, |heap| {
                    def(heap, arr, &i.to_string(), w).map_err(|_| NativeError::OutOfMemory)
                })?;
            }
            def(heap, arr, "length", Value::Int(nodes.len() as i32))
                .map_err(|_| NativeError::OutOfMemory)?;
            Ok(())
        },
    )?;
    Ok(Value::Object(arr))
}

fn str_of(html: &str, heap: &mut Heap) -> Result<Value, NativeError> {
    let s = heap.alloc_str(html).map_err(|_| NativeError::OutOfMemory)?;
    Ok(Value::Str(s))
}

fn n_inner_html_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let html = rc.borrow().live_document()?.borrow().inner_html(node);
    str_of(&html, heap)
}

fn n_inner_html_set(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let html = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    {
        let g = rc.borrow_mut();
        g.live_document()?.borrow_mut().set_inner_html(node, &html);
    }
    // Children changed wholesale: re-sync the live wrapper properties.
    let mut g = rc.borrow_mut();
    after_dom_mutation(heap, &mut g, &[node])?;
    Ok(Value::Undefined)
}

fn n_outer_html_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let html = rc.borrow().live_document()?.borrow().outer_html(node);
    str_of(&html, heap)
}

fn n_outer_html_set(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let html = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let parent = rc.borrow().live_document()?.borrow().parent(node);
    {
        let g = rc.borrow_mut();
        g.live_document()?.borrow_mut().set_outer_html(node, &html);
    }
    // The parent's children changed and the node itself was detached; the
    // node's wrapper keeps pointing at the (live, detached) node, and new
    // sibling wrappers wrap lazily on access.
    let mut g = rc.borrow_mut();
    match parent {
        Some(p) => after_dom_mutation(heap, &mut g, &[p, node])?,
        None => after_dom_mutation(heap, &mut g, &[node])?,
    }
    Ok(Value::Undefined)
}

// ---------------------------------------------------------------------------
// EventTarget natives (shared by elements and the document wrapper)
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// EventTarget natives (shared by elements and the document wrapper)
// ---------------------------------------------------------------------------

/// The `AddEventListenerOptions` dictionary: `capture` keeps its boolean
/// shorthand (`addEventListener(t, f, true)`).
struct ListenerOptions {
    capture: bool,
    once: bool,
    passive: bool,
    signal: Value,
}

impl ListenerOptions {
    fn none() -> Self {
        ListenerOptions {
            capture: false,
            once: false,
            passive: false,
            signal: Value::Undefined,
        }
    }
}

/// Read the listener options argument with ordinary `[[Get]]` semantics:
/// inherited members count and accessor getters run (via [`dict_get`], the
/// same reader the scroll API uses), matching WebIDL dictionary behavior.
/// A boolean argument is the `capture` shorthand; anything else
/// non-object is ignored.
fn read_listener_options(heap: &mut Heap, v: Value) -> Result<ListenerOptions, NativeError> {
    let mut opts = ListenerOptions::none();
    let Value::Object(obj) = v else {
        if v == Value::Bool(true) {
            opts.capture = true;
        }
        return Ok(opts);
    };
    // The getters below run script and may collect: hold the options
    // object as a temporary root across the whole read (each `dict_get`
    // only roots it across its own getter call).
    let base = heap.protect(Value::Object(obj));
    let r = (|| -> Result<(), NativeError> {
        if let Some(c) = dict_get(heap, obj, "capture")? {
            opts.capture = c.is_truthy();
        }
        if let Some(o) = dict_get(heap, obj, "once")? {
            opts.once = o.is_truthy();
        }
        if let Some(p) = dict_get(heap, obj, "passive")? {
            opts.passive = p.is_truthy();
        }
        if let Some(s) = dict_get(heap, obj, "signal")? {
            opts.signal = s;
        }
        Ok(())
    })();
    heap.release_temp(base);
    r?;
    Ok(opts)
}

/// Whether the `signal` option is already aborted: an object-valued
/// `signal` whose `aborted` member (ordinary `[[Get]]`, so inherited or
/// getter-provided) is truthy. WHATWG DOM `addEventListener`: an
/// already-aborted signal skips registration.
fn signal_aborted(heap: &mut Heap, signal: Value) -> Result<bool, NativeError> {
    let Value::Object(obj) = signal else {
        return Ok(false);
    };
    Ok(dict_get(heap, obj, "aborted")?
        .map(|v| v.is_truthy())
        .unwrap_or(false))
}

fn n_add_event_listener(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let etype = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let listener = args.get(1).copied().unwrap_or(Value::Undefined);
    // WHATWG DOM `addEventListener` step 1: a null callback terminates the
    // steps (no-op, no throw).
    if matches!(listener, Value::Null | Value::Undefined) {
        return Ok(Value::Undefined);
    }
    require_callable(listener)?;
    let opts = read_listener_options(heap, args.get(2).copied().unwrap_or(Value::Undefined))?;
    // WHATWG DOM `addEventListener`: an already-aborted `signal` skips
    // registration.
    if signal_aborted(heap, opts.signal)? {
        return Ok(Value::Undefined);
    }
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    {
        let mut g = rc.borrow_mut();
        let seq = g.next_seq;
        g.next_seq = seq.wrapping_add(1);
        // Rust-heap-only: no GC allocation inside this borrow (see
        // [`GcRoots`]).
        let mut roots = g.gc_roots.borrow_mut();
        let (_, entry) = roots.listener_bucket(node, &etype);
        // Duplicate registrations (same type, callback, capture) are
        // ignored; the other options do not participate (per spec).
        if !entry
            .iter()
            .any(|l| l.capture == opts.capture && l.callback == listener)
        {
            entry.push(Listener {
                capture: opts.capture,
                callback: listener,
                seq,
                once: opts.once,
                passive: opts.passive,
                signal: opts.signal,
            });
        }
    }
    Ok(Value::Undefined)
}

/// Remove one production listener registration. Shared by
/// [`n_remove_event_listener`] and the dispatch loop's `once` handling.
fn remove_listener(
    rc: &Rc<RefCell<WebApis>>,
    node: NodeId,
    etype: &str,
    capture: bool,
    callback: Value,
) {
    let g = rc.borrow_mut();
    // Rust-heap-only: no GC allocation inside this borrow (see
    // [`GcRoots`]).
    let mut roots = g.gc_roots.borrow_mut();
    // Non-inserting lookup: a type that was never registered (or whose
    // registrations were all removed and its intern entry evicted) has
    // no bucket to prune.
    if let Some(eid) = roots.event_type_id(etype) {
        let emptied = match roots.listeners.get_mut(&(node, eid)) {
            Some(entry) => {
                entry.retain(|l| !(l.capture == capture && l.callback == callback));
                entry.is_empty()
            }
            None => false,
        };
        if emptied {
            // The last registration for this (node, id) is gone: drop
            // the bucket and release the type's claim on it, evicting
            // the intern entry with its last bucket so the table stays
            // bounded by the live listener population.
            roots.listeners.remove(&(node, eid));
            let evict = match roots.event_type_ids.get_mut(etype) {
                Some(t) => {
                    t.buckets = t.buckets.saturating_sub(1);
                    t.buckets == 0
                }
                None => false,
            };
            if evict {
                roots.event_type_ids.remove(etype);
            }
        }
    }
}

fn n_remove_event_listener(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let etype = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let listener = args.get(1).copied().unwrap_or(Value::Undefined);
    // A null callback never registered (see `n_add_event_listener`), so
    // this is already a no-op; keep it throw-free per spec.
    if matches!(listener, Value::Null | Value::Undefined) {
        return Ok(Value::Undefined);
    }
    let capture =
        read_listener_options(heap, args.get(2).copied().unwrap_or(Value::Undefined))?.capture;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    remove_listener(&rc, node, &etype, capture, listener);
    Ok(Value::Undefined)
}

// ---------------------------------------------------------------------------
// `onscrollsnapchange` / `onscrollsnapchanging` IDL attributes
// ---------------------------------------------------------------------------
//
// There is no general `GlobalEventHandlers` machinery in this
// codebase (no `onclick`, no `onscroll`): these two attributes are the
// minimal dedicated form. The callback is registered as a normal
// bubble-phase listener for (target node, type) — sharing the
// listener table's dedup and dispatch — and remembered in
// [`GcRoots::event_handlers`] so a reassignment removes exactly the
// previous `on*` registration (a callback also registered via
// `addEventListener` is a separate registration and stays). The
// attributes live on the shared element prototype (which the document
// wrapper also links, giving `document.on*`) and on the global
// (`window.on*` — `target_node` maps the global to the document root,
// the same bucket document handlers use).

/// Shared `on*` getter: the stored callback for (receiver node,
/// `etype`), or `null` when none is assigned (the IDL default — the
/// WPT support check is `window.onscrollsnapchange !== undefined`).
fn snap_on_handler_get(heap: &mut Heap, this: Value, etype: &str) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    snap_on_handler_get_node(&rc, node, etype)
}

/// [`snap_on_handler_get`] with an explicit target node.
fn snap_on_handler_get_node(
    rc: &Rc<RefCell<WebApis>>,
    node: NodeId,
    etype: &str,
) -> Result<Value, NativeError> {
    let g = rc.borrow();
    let roots = g.gc_roots.borrow();
    Ok(match roots.event_type_id(etype) {
        Some(id) => roots
            .event_handlers
            .get(&(node, id))
            .copied()
            .unwrap_or(Value::Null),
        None => Value::Null,
    })
}

/// Shared `on*` setter: a callable value replaces any previous `on*`
/// handler for (receiver node, `etype`); `null`/`undefined`/a
/// non-callable value just removes it (WebIDL `EventHandler`
/// conversion treats a non-callable as null).
fn snap_on_handler_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
    etype: &str,
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let v = args.first().copied().unwrap_or(Value::Undefined);
    snap_on_handler_set_node(&rc, node, v, etype, None)
}

/// [`snap_on_handler_set`] with an explicit target node, pre-extracted
/// value, and optional registration sequence: `None` mints a fresh
/// sequence number; `Some` replays a parse-order sequence when adopting
/// a mid-parse assignment (see [`install_page_web_apis`]).
fn snap_on_handler_set_node(
    rc: &Rc<RefCell<WebApis>>,
    node: NodeId,
    v: Value,
    etype: &str,
    seq: Option<u64>,
) -> Result<Value, NativeError> {
    // Remove the previous `on*` registration, if any.
    let old = {
        let g = rc.borrow();
        let mut roots = g.gc_roots.borrow_mut();
        match roots.event_type_id(etype) {
            Some(id) => roots.event_handlers.remove(&(node, id)),
            None => None,
        }
    };
    if let Some(old_cb) = old {
        remove_listener(rc, node, etype, false, old_cb);
    }
    if require_callable(v).is_ok() {
        let mut g = rc.borrow_mut();
        let s = match seq {
            Some(s) => {
                // Adopted mid-parse assignment: keep its parse-order
                // position so the `load` dispatch interleaves it with
                // adopted `addEventListener` registrations correctly.
                g.next_seq = g.next_seq.max(s.wrapping_add(1));
                s
            }
            None => {
                let s = g.next_seq;
                g.next_seq = s.wrapping_add(1);
                s
            }
        };
        // Rust-heap-only: no GC allocation inside this borrow (see
        // [`GcRoots`]).
        let mut roots = g.gc_roots.borrow_mut();
        let (eid, bucket) = roots.listener_bucket(node, etype);
        if !bucket.iter().any(|l| !l.capture && l.callback == v) {
            bucket.push(Listener {
                capture: false,
                callback: v,
                seq: s,
                once: false,
                passive: false,
                signal: Value::Undefined,
            });
        }
        roots.event_handlers.insert((node, eid), v);
    }
    Ok(Value::Undefined)
}

fn n_onscrollsnapchange_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    snap_on_handler_get(heap, this, "scrollsnapchange")
}

fn n_onscrollsnapchange_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    snap_on_handler_set(heap, this, args, "scrollsnapchange")
}

fn n_onscrollsnapchanging_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    snap_on_handler_get(heap, this, "scrollsnapchanging")
}

fn n_onscrollsnapchanging_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    snap_on_handler_set(heap, this, args, "scrollsnapchanging")
}

// ---------------------------------------------------------------------------
// `onload` IDL attribute
// ---------------------------------------------------------------------------
//
// Same minimal dedicated form as `onscrollsnapchange` above: no general
// `GlobalEventHandlers` machinery exists in this codebase, so `onload`
// rides the shared `snap_on_handler_*` helpers with event type
// `"load"`. The setter registers the callback as a normal bubble-phase
// listener on the receiver's node (the document root for `window` /
// `document`), so the window `load` dispatch
// ([`Vm::dispatch_window_load`]) invokes it through the regular
// `dispatchEvent` path — no separate stored-handler invocation needed.

fn n_onload_get(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let (rc, node) = onload_receiver_node(heap, this)?;
    snap_on_handler_get_node(&rc, node, "load")
}

fn n_onload_set(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    let (rc, node) = onload_receiver_node(heap, this)?;
    let v = args.first().copied().unwrap_or(Value::Undefined);
    snap_on_handler_set_node(&rc, node, v, "load", None)
}

/// The node whose `load` bucket the `onload` IDL attribute reads and
/// writes for `this`: per HTML, `body`/`frameset` `onload` forwards to
/// the Window event handler, so those receivers use the document root
/// (the window's bucket — the one [`Vm::dispatch_window_load`]
/// dispatches to) instead of their own node. Without the remap a
/// `document.body.onload = f` handler would sit on the body node,
/// outside the window `load` propagation path, and never fire. Every
/// other receiver keeps its own node.
fn onload_receiver_node(
    heap: &Heap,
    this: Value,
) -> Result<(Rc<RefCell<WebApis>>, NodeId), NativeError> {
    let rc = apis_rc(heap, this)?;
    let node = {
        let g = rc.borrow();
        target_node(heap, this, &g)?
    };
    let forwarded = {
        let g = rc.borrow();
        let doc = g.live_document()?;
        let doc = doc.borrow();
        matches!(doc.kind(node), NodeKind::Element(e) if {
            let tag = e.tag_name.as_str();
            tag == "body" || tag == "frameset"
        })
    };
    if forwarded {
        let root = {
            let g = rc.borrow();
            let doc = g.live_document()?;
            doc.borrow().root()
        };
        Ok((rc, root))
    } else {
        Ok((rc, node))
    }
}

/// The document's `<body>` or `<frameset>` element (first in tree
/// order), if the document has one: per HTML only these elements'
/// `onload` content attribute forwards to the Window event handler —
/// an `onload` attribute on any other element (including `<html>`)
/// never becomes the window handler.
fn document_body_or_frameset(document: &Document) -> Option<NodeId> {
    let root = document.root();
    document.descendants(root).into_iter().find(|&n| {
        matches!(document.kind(n), NodeKind::Element(e) if {
            let tag = e.tag_name.as_str();
            tag == "body" || tag == "frameset"
        })
    })
}

/// One step of a precomputed dispatch plan: the listener to invoke, the
/// node it was registered on (the `currentTarget` for this step, the
/// `once`-removal key, and the `stopPropagation` phase test), and the
/// `eventPhase` for this step.
struct PlanEntry {
    /// Wrapper of the node whose listeners these are (the invocation
    /// receiver: `currentTarget`).
    target: Value,
    callback: Value,
    node: NodeId,
    capture: bool,
    once: bool,
    passive: bool,
    phase: u8,
}

/// Append [`PlanEntry`]s for one dispatch step. `etype` is the interned
/// event-type id ([`GcRoots::event_type_id`]); `None` means no listener
/// was ever registered for this type, so the step is skipped outright.
fn collect_listeners(
    heap: &mut Heap,
    apis: &mut WebApis,
    plan: &mut Vec<PlanEntry>,
    node: NodeId,
    etype: Option<u32>,
    capture: Option<bool>,
) -> Result<(), NativeError> {
    let phase = match capture {
        Some(true) => PHASE_CAPTURING,
        None => PHASE_AT_TARGET,
        Some(false) => PHASE_BUBBLING,
    };
    let mut cbs: Vec<(Value, bool, bool, bool)> = Vec::new();
    {
        // Shared borrow only: ends before `wrap_node` below takes its
        // own `GcRoots` borrows.
        let Some(eid) = etype else {
            return Ok(());
        };
        let roots = apis.gc_roots.borrow();
        if let Some(entries) = roots.listeners.get(&(node, eid)) {
            let mut ordered: Vec<&Listener> = entries
                .iter()
                .filter(|l| capture.map(|c| l.capture == c).unwrap_or(true))
                .collect();
            ordered.sort_by_key(|l| l.seq);
            cbs.extend(
                ordered
                    .iter()
                    .map(|l| (l.callback, l.capture, l.once, l.passive)),
            );
        }
    }
    if !cbs.is_empty() {
        let tgt = wrap_node(heap, apis, node)?;
        plan.extend(
            cbs.into_iter()
                .map(|(callback, capture, once, passive)| PlanEntry {
                    target: tgt,
                    callback,
                    node,
                    capture,
                    once,
                    passive,
                    phase,
                }),
        );
    }
    Ok(())
}

/// Shared implementation for the public `dispatchEvent` (untrusted) and
/// the stashed trusted variant (see [`NATIVE_DISPATCH_EVENT_KEY`]).
fn dispatch_event_inner(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
    trusted: bool,
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let arg = args.first().copied().unwrap_or(Value::Undefined);
    // `arg` is a caller-held value with no documented root guarantee: a
    // plain-object argument runs `event_of` → `arg_to_string` → script
    // `toString` on its `type` member, which can trigger a collection
    // that sweeps the argument mid-read. Hold it as a temporary root
    // across the dispatch (same hazard class as the stashed wheel
    // dispatch in [`n_dispatch_wheel_stashed`]).
    with_temp_root(heap, arg, |heap| {
        let target = {
            let g = rc.borrow();
            target_node(heap, this, &g)?
        };
        // Every script-initiated dispatch delivers a fresh wrapper: a plain
        // `{type, bubbles?, cancelable?}` argument gains the full event shape
        // here.
        let (event_val, event_handle) = {
            let mut g = rc.borrow_mut();
            let event = event_of(heap, &g, arg)?;
            // An event carrying a snap payload (a constructed
            // `SnapEvent` re-dispatched through its stored clone, or a
            // plain object with `snapTarget*` members) wraps with
            // `SnapEvent.prototype` so the target accessors are on the
            // delivered wrapper's chain.
            let (event_val, event_handle) = if event.snap_targets.is_some() {
                let proto = g.gc_roots.borrow().snap_event_proto;
                wrap_event_with_proto(heap, &mut g, event.clone(), trusted, proto)
                    .map_err(|_| NativeError::OutOfMemory)?
            } else {
                wrap_event(heap, &mut g, event.clone(), trusted)
                    .map_err(|_| NativeError::OutOfMemory)?
            };
            // A re-dispatched wrapper keeps the `trusted` flag and `timeStamp`
            // it was created with: DOM dispatch never resets them.
            if let Value::Object(o) = arg
                && let Some(p) = heap.get_property(o, Wtf8::from_str(EVENT_KEY))
                && let Value::Int(h) = p.value
                && let Some(old) = g
                    .event_states
                    .get(&(h as u32))
                    .map(|s| (s.trusted, s.time_stamp))
                && let Some(new) = g.event_states.get_mut(&event_handle)
            {
                new.trusted = old.0;
                new.time_stamp = old.1;
            }
            (event_val, event_handle)
        };
        let prevented = run_event_dispatch(heap, &rc, target, event_val, event_handle)?;
        Ok(Value::Bool(!prevented))
    })
}

/// Dispatch core shared by [`dispatch_event_inner`] and host-initiated
/// dispatches ([`n_dispatch_wheel_stashed`]): delivers the already-built
/// `event_val` wrapper (freshly wrapped or host-built, so host-attached
/// properties such as wheel deltas survive to the listeners) at `target`.
/// Returns true when a non-passive listener prevented the default
/// (`preventDefault` inside a passive listener no-ops via
/// [`n_prevent_default`]).
fn run_event_dispatch(
    heap: &mut Heap,
    rc: &Rc<RefCell<WebApis>>,
    target: NodeId,
    event_val: Value,
    event_handle: u32,
) -> Result<bool, NativeError> {
    // Build the full invocation plan under the apis borrow, then drop it
    // before invoking JS (reentrancy discipline).
    let (plan, event, root_base) = {
        let mut g = rc.borrow_mut();
        let event = event_of(heap, &g, event_val)?;
        // (Re)set the per-dispatch state: a reused wrapper starts every
        // dispatch with fresh stop flags and no passive listener running.
        if let Some(s) = g.event_states.get_mut(&event_handle) {
            s.target = Some(target);
            s.current_target = None;
            s.phase = PHASE_NONE;
            s.stop_propagation = false;
            s.stop_immediate = false;
            s.in_passive_listener = false;
        }
        // The wrapper may sit in no traced root yet (a host-built event),
        // and both the plan build below and the listener invocations
        // after it allocate: hold it as a temporary root across all of
        // them.
        let root_base = heap.protect(event_val);
        let plan = (|| -> Result<Vec<PlanEntry>, NativeError> {
            // A dead document Weak surfaces as `TypeError("document is
            // gone")` here, never as out-of-memory.
            let path = g.live_document()?.borrow().propagation_path(target);
            // Back `composedPath()`: the dispatch-time path, target
            // first. Cleared when dispatch ends (see below), so the
            // accessor reads `[]` outside dispatch.
            if let Some(s) = g.event_states.get_mut(&event_handle) {
                s.path = path.clone();
            }
            // The interned type id resolves once per dispatch (not per
            // node per phase): a type nobody listens for skips every
            // phase with no allocation.
            let etype = g.gc_roots.borrow().event_type_id(&event.event_type);
            let mut plan: Vec<PlanEntry> = Vec::new();
            // Capture phase: root down to the target's parent.
            for &n in path[1..].iter().rev() {
                collect_listeners(heap, &mut g, &mut plan, n, etype, Some(true))?;
            }
            // Target phase: both capture values, registration order.
            collect_listeners(heap, &mut g, &mut plan, target, etype, None)?;
            // Bubble phase, only when the event bubbles.
            if event.bubbles {
                for &n in path[1..].iter() {
                    collect_listeners(heap, &mut g, &mut plan, n, etype, Some(false))?;
                }
            }
            Ok(plan)
        })();
        let plan = match plan {
            Ok(plan) => plan,
            Err(e) => {
                heap.release_temp(root_base);
                return Err(e);
            }
        };
        (plan, event, root_base)
    };
    let invoker = rc.borrow().invoker.clone();
    for entry in plan {
        let (stop_immediate, stop_propagation) = rc
            .borrow()
            .event_states
            .get(&event_handle)
            .map(|s| (s.stop_immediate, s.stop_propagation))
            .unwrap_or((false, false));
        // `stopImmediatePropagation()`: halt the dispatch outright.
        if stop_immediate {
            break;
        }
        // `stopPropagation()`: skip every phase except the target phase.
        if stop_propagation && entry.node != target {
            continue;
        }
        if entry.once {
            // WHATWG DOM "inner invoke": a `once` listener is removed
            // *before* it runs, so a synchronous re-dispatch from inside
            // the listener cannot re-enter it.
            remove_listener(
                rc,
                entry.node,
                &event.event_type,
                entry.capture,
                entry.callback,
            );
        }
        // Publish this step's `currentTarget`/`eventPhase`, and flag a
        // passive listener so `preventDefault()` no-ops while it runs. The
        // previous passive flag is restored afterwards: a nested dispatch
        // from inside the listener gets its own save/restore.
        let prev_passive = rc
            .borrow_mut()
            .event_states
            .get_mut(&event_handle)
            .map(|s| {
                s.current_target = Some(entry.node);
                s.phase = entry.phase;
                std::mem::replace(&mut s.in_passive_listener, entry.passive)
            })
            .unwrap_or(false);
        // Listener exceptions are swallowed: DOM report-and-continue.
        // `borrow()`, not `borrow_mut()`: a listener that synchronously
        // dispatches another event re-enters the invoker, and a held
        // `borrow_mut` guard would panic on the nested borrow.
        let _ = invoker
            .borrow()
            .call(heap, entry.callback, entry.target, &[event_val]);
        if let Some(s) = rc.borrow_mut().event_states.get_mut(&event_handle) {
            s.in_passive_listener = prev_passive;
        }
    }
    // The dispatch is over: `currentTarget`/`eventPhase` go back to
    // null/`NONE`, and the `composedPath()` backing path is cleared
    // (DOM).
    if let Some(s) = rc.borrow_mut().event_states.get_mut(&event_handle) {
        s.current_target = None;
        s.phase = PHASE_NONE;
        s.path.clear();
        s.in_passive_listener = false;
    }
    let prevented = rc
        .borrow()
        .events
        .get(&event_handle)
        .map(|e| e.default_prevented)
        .unwrap_or(false);
    heap.release_temp(root_base);
    Ok(prevented)
}

/// `EventTarget.prototype.dispatchEvent`: script-initiated, untrusted.
fn n_dispatch_event(heap: &mut Heap, this: Value, args: &[Value]) -> Result<Value, NativeError> {
    dispatch_event_inner(heap, this, args, false)
}

/// The stashed window `dispatchEvent` (see [`NATIVE_DISPATCH_EVENT_KEY`]):
/// the engine's own dispatches (the window `load` event) are trusted.
fn n_dispatch_event_trusted(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    dispatch_event_inner(heap, this, args, true)
}

/// Host wheel dispatch (see [`Vm::dispatch_wheel`]): runs inside the VM —
/// the eval keeps the interpreter active so listener invocation works —
/// unstashes the target wrapper and prebuilt wheel event the host parked
/// on the global, and runs the shared dispatch core as a trusted event.
/// Returns true when a non-passive listener prevented the default
/// (`preventDefault` inside a passive listener no-ops, per
/// [`n_prevent_default`]).
fn n_dispatch_wheel_stashed(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let rc = apis_rc(heap, this)?;
    let Value::Object(global) = this else {
        return Err(err_type("wheel dispatch: invalid receiver"));
    };
    let target_val = heap
        .get_property(global, Wtf8::from_str(WHEEL_TARGET_KEY))
        .map(|p| p.value);
    let event_val = heap
        .get_property(global, Wtf8::from_str(WHEEL_EVENT_KEY))
        .map(|p| p.value);
    // Unstash first: a re-entrant dispatch from inside a listener must
    // not observe (or reuse) these slots.
    heap.delete_property(global, Wtf8::from_str(WHEEL_TARGET_KEY));
    heap.delete_property(global, Wtf8::from_str(WHEEL_EVENT_KEY));
    let (Some(t), Some(e)) = (target_val, event_val) else {
        return Ok(Value::Bool(false));
    };
    // The stash slots are deleted above, so from here on the target and
    // the event are reachable only through these Rust locals — and this
    // hidden native is script-reachable
    // (`window["\0bowser:dispatchWheel"]()`), so a forged direct call has
    // no other roots for them at all. Every call below can allocate and
    // collect (`run_event_dispatch` runs `event_of` → `arg_to_string` →
    // script `toString` before it roots the wrapper), which would sweep
    // the unrooted values mid-dispatch (use-after-free). Hold both as
    // temporary roots until the dispatch completes, released on every
    // exit path.
    let base = heap.protect(t);
    heap.protect(e);
    let r = (|| -> Result<bool, NativeError> {
        let target = {
            let g = rc.borrow();
            target_node(heap, t, &g)?
        };
        let handle = event_handle_of(heap, e)?;
        run_event_dispatch(heap, &rc, target, e, handle)
    })();
    heap.release_temp(base);
    Ok(Value::Bool(r?))
}

