/// The parse's shared `NodeList.prototype` for parse slot `id`
/// ([`install_parse_document_shim`] stashes it in the shim roots):
/// `None` when the shim never installed it — fail-open, the list keeps
/// its old prototype-less shape.
fn parse_node_list_proto(id: u64) -> Option<Gc<Object>> {
    PARSE_HOSTS.with(|hosts| {
        hosts
            .borrow()
            .get(&id)
            .and_then(|entry| entry.listeners.borrow().node_list_proto)
    })
}

/// The shim realm's `DOMRect.prototype`, stashed by
/// [`install_parse_document_shim`]. `None` when the shim never
/// installed it — fail-open, the rect keeps its old prototype-less
/// shape.
fn parse_dom_rect_proto(id: u64) -> Option<Gc<Object>> {
    PARSE_HOSTS.with(|hosts| {
        hosts
            .borrow()
            .get(&id)
            .and_then(|entry| entry.listeners.borrow().dom_rect_proto)
    })
}

/// Build an Array-kind object from `len` wrapped children.
fn parse_child_array(
    heap: &mut Heap,
    id: u64,
    kids: &[ScriptChild],
    elements_only: bool,
) -> Result<Value, NativeError> {
    let arr = heap
        .alloc_object(Object::new(ObjectKind::Array))
        .map_err(|_| NativeError::OutOfMemory)?;
    let proto = parse_node_list_proto(id);
    with_temp_root(
        heap,
        Value::Object(arr),
        |heap| -> Result<(), NativeError> {
            let oom = |_: AllocError| NativeError::OutOfMemory;
            link_node_list_proto(heap, arr, proto);
            let mut i = 0usize;
            for kid in kids {
                let w = match kid {
                    ScriptChild::Element(e) => {
                        Some(wrap_parse_element(heap, id, *e).map(Value::Object)?)
                    }
                    ScriptChild::Text(t) if !elements_only => {
                        Some(wrap_parse_text(heap, id, t).map(Value::Object)?)
                    }
                    ScriptChild::Text(_) => None,
                };
                if let Some(w) = w {
                    def(heap, arr, &i.to_string(), w).map_err(oom)?;
                    i += 1;
                }
            }
            def(heap, arr, "length", Value::Int(i as i32)).map_err(oom)?;
            Ok(())
        },
    )?;
    Ok(Value::Object(arr))
}

fn n_parse_el_child_nodes_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "childNodes")?;
    let kids = deref_parse_host(host).child_nodes(el);
    parse_child_array(heap, id, &kids, false)
}

fn n_parse_el_children_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "children")?;
    let kids = deref_parse_host(host).child_nodes(el);
    parse_child_array(heap, id, &kids, true)
}

fn parse_wrap_child(heap: &mut Heap, id: u64, kid: &ScriptChild) -> Result<Value, NativeError> {
    match kid {
        ScriptChild::Element(e) => wrap_parse_element(heap, id, *e).map(Value::Object),
        ScriptChild::Text(t) => wrap_parse_text(heap, id, t).map(Value::Object),
    }
}

fn n_parse_el_first_child_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "firstChild")?;
    match deref_parse_host(host).first_child(el) {
        Some(kid) => parse_wrap_child(heap, id, &kid),
        None => Ok(Value::Null),
    }
}

fn n_parse_el_last_child_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "lastChild")?;
    match deref_parse_host(host).last_child(el) {
        Some(kid) => parse_wrap_child(heap, id, &kid),
        None => Ok(Value::Null),
    }
}

/// Read-only shim properties silently ignore sets (sloppy-mode behavior).
fn n_parse_el_readonly_set(
    _heap: &mut Heap,
    _this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    Ok(Value::Undefined)
}

// -- Parse-phase on-demand layout -------------------------------------------
//
// Mid-parse scripts can force layout (`el.style.width = "200px";
// `el.offsetWidth`) before any real layout pass exists. `ParseLayoutHook`
// answers those reads with computed values: it snapshots the tree built
// so far (the chunk-1 `ScriptHost::snapshot_document` / `mutation_count`
// / `ScriptElement::arena_index` primitives), rebuilds only the subtree
// rooted at the element's containing block as a fresh document, lays
// *that* out, and measures with the same `table_box_geometry` /
// `table_offset_parent` API the production getters use. The pass is
// cached against the tree's `mutation_count`: any DOM mutation (parser
// or script) bumps it, so repeated reads between mutations are map
// lookups and never re-layout. Never more than the parsed-so-far tree:
// layout input is bounded to the rebuilt subtree (measuring `body`
// roots at `html`, which is the entire parsed-so-far document).
//
// Honest approximations (mid-parse, best effort):
// - Viewport defaults to 800x600; the production install threads the
//   embedder's viewport through [`install_parse_document_shim`].
// - Only UA, inline `style=""`, `<style>` element rules, and
//   `<link rel="stylesheet">` sheets apply (w51: link hrefs are
//   resolved against the effective base — the seeded document
//   URL, overridden by the first `<base href>` — and loaded at
//   harvest time under a hard per-sheet time budget; an unseeded
//   URL or a failed load leaves the sheet out).
// - `getBoundingClientRect` x/y are relative to the partial-layout root
//   (the containing block), not the viewport: the ancestors above the
//   root are never laid out. Width/height are exact.
// - `offsetLeft`/`offsetTop` are exact when the partial root coincides
//   with the offset parent (a positioned ancestor, or `body`); for a
//   static element nested under static blocks they come out relative to
//   the nearest block-container ancestor instead.
// - `position: fixed` roots the partial layout at the element itself,
//   so its gBCR x/y come out ~0 and percentage widths resolve against
//   the element-as-root.
// - `<template>` contents and declarative shadow roots are skipped in
//   the partial rebuild: neither renders.
// - Font metrics are the real font backend's (`FontCache`, shared
//   parse-wide with the WPT test fonts installed): the partial
//   layout measures text exactly like the post-parse pipeline, so
//   mid-parse geometry agrees with post-parse geometry.
// - Custom elements (`x-table`, …) no visible rule gives a display to
//   are measured as honest zeros, not numbers: their used `display`
//   would come from a stylesheet no harvested rule supplies (a
//   `<link>` sheet that failed to load, or none at all), so the
//   pass would size them as inline fragments instead of the tables /
//   blocks the sheet makes them. Table-internal reads (`tr`, `td`, …)
//   widen the partial root to the enclosing `<table>`: the full
//   row/column/span grid and the table-level rules (`table {
//   border-collapse: … }`) must sit inside the rebuilt subtree for
//   table geometry (e.g. `visibility: collapse` redistribution) to
//   agree with the full layout.
// - When a harvested `<style>` rule uses a combinator (`main table`),
//   the pass is rooted at the document element instead of the
//   containing block: the narrower subtree could not match the rule
//   at all. (`position: fixed` keeps its element root.)
// - A table combining `visibility: collapse`, a `rowspan > 1` cell,
//   and text is measured as honest zeros document-wide: its
//   redistribution runs on real font metrics now, but the partial
//   pass's fractional line heights still differ by `f32` ULPs from
//   the full layout's, so rounded cross-checks lose to rounding even
//   when the pass matches the full layout exactly. Text-free grids
//   keep measured values (fixed-size content is exact).

/// Fallback viewport for mid-parse partial layouts when the embedder
/// provides none: 800x600 matches the `geometry_vm` test harness.
/// The production install threads the embedder's viewport through
/// [`install_parse_document_shim`].
const PARSE_LAYOUT_VIEWPORT_W: f32 = 800.0;
const PARSE_LAYOUT_VIEWPORT_H: f32 = 600.0;

/// How many `(mutation_count, root)` entries the [`ParseLayoutHook`]
/// keeps: enough that ping-ponging reads across a few subtrees stay
/// cache hits instead of re-laying out (finding 1), small enough that
/// the linear scan in `ensure_layout` stays trivial.
const PARSE_LAYOUT_CACHE_ENTRIES: usize = 4;

/// On-demand partial layout for parse-phase geometry reads.
///
/// Lives on [`ParseHostEntry`] (one per script installation).
/// `entries` is a small MRU cache of measured subtrees keyed by
/// `(mutation_count, root arena index)`: any DOM mutation (parser or
/// script) bumps the count, so repeated reads between mutations are
/// map lookups and never re-layout. The measured subtree root is part
/// of the key (finding 1): one pass only ever measures one subtree,
/// so a read outside the last-measured subtree must re-run rather
/// than return another subtree's zeros. An entry with an empty map is
/// a cached miss (finding 7): a failed pass is not retried until the
/// tree actually changes. `widened` remaps a provisional root to the
/// widened root the finding-2 post-pass actually laid out, so later
/// reads reuse the widened entry directly. `passes` counts partial
/// layout passes: test instrumentation for the cache (see
/// [`ParseShimGuard::layout_passes`]). `boxes` is scratch space for
/// `measure_subtree`, moved into `entries` after each pass.
pub(crate) struct ParseLayoutHook {
    passes: u64,
    boxes: HashMap<usize, ParseMeasuredBox>,
    entries: Vec<((u64, usize), HashMap<usize, ParseMeasuredBox>)>,
    widened: Vec<((u64, usize), usize)>,
    /// Whether a pass has seen a table combining `visibility:
    /// collapse`, a `rowspan > 1` cell, and real text
    /// ([`snapshot_has_collapse_rowspan_text`]). Collapse
    /// redistribution across spanning rows over text-driven fractional
    /// heights defeats the rounded-integer cross-checks those tests
    /// assert, and the double-precision cross-table comparisons are
    /// ULP-unstable in any full-context layout, so once such a grid
    /// exists every geometry read in this script answers the honest
    /// zero. Sticky rather than per-count: the dynamic tests toggle
    /// the row back to `visible` and compare the two tables against
    /// each other with exact equality, which real numbers from a
    /// shared pass cannot satisfy either (the two grids differ by a
    /// few ULPs of `f32` accumulation).
    collapse_rowspan_seen: bool,
    /// Scroll-snap data per `mutation_count` (see
    /// [`Self::snap_scroll`]): the snap containers, areas, and ranges
    /// of the tree at that count, shared across scroll targets. Kept
    /// tiny like `entries`; a tree mutation invalidates by count.
    snap_cache: Vec<(u64, Rc<ParseSnapData>)>,
    /// Computed-style data per `mutation_count` (see
    /// [`Self::computed_props`]): the whole-tree rebuild the
    /// parse-shim `getComputedStyle` cascades against. Kept tiny like
    /// `snap_cache`; a tree mutation invalidates by count.
    style_cache: Vec<(u64, Rc<ParseStyleData>)>,
    /// Embedder viewport in CSS px for mid-parse partial layouts: the
    /// `(800, 600)` fallback when the embedder provided none.
    viewport: (u32, u32),
    /// Document URL seeded for this parse (w51), copied from the
    /// shim roots at install: `<link rel="stylesheet">` hrefs are
    /// resolved against it at harvest time. `None` (never seeded)
    /// leaves link sheets unloaded, degrading to the old
    /// `<style>`-only harvest.
    document_url: Option<String>,
    /// `<link>` sheet cache for the whole parse (w51 fix A6),
    /// shared with every other installation through
    /// [`ParseShimRoots::link_sheets`]: the layout, snap, and style
    /// harvests of *all* scripts of the parse share it, so one
    /// sheet is fetched at most once per parse. A standalone hook
    /// (unit tests) gets a private cache until install replaces it
    /// with the roots' handle.
    link_sheets: Rc<RefCell<ParseLinkSheetCache>>,
    /// Font cache for mid-parse partial layouts, shared with every
    /// other installation through [`ParseShimRoots::fonts`]: the
    /// partial layout measures text with the same real font metrics
    /// the post-parse pipeline uses (including the installed WPT
    /// test fonts), so mid-parse geometry agrees with post-parse
    /// geometry. A standalone hook (unit tests) gets a private
    /// slot until install replaces it with the roots' handle.
    /// `None` until the first partial layout needs it.
    fonts: Rc<RefCell<Option<FontCache>>>,
    /// Recorded nested-scroller offsets, as `(host arena index,
    /// offset)` pairs, refreshed on every shim scroll write (see
    /// [`parse_el_scroll_set`]). [`Self::rebuild_tree`] maps these
    /// onto the rebuilt document's nodes so sticky constraints bake
    /// at the script-written offsets: without it a mid-parse
    /// `scrollTop` write is invisible to the next geometry read.
    /// Empty until the first scroll write; the viewport scroll is
    /// deliberately excluded (callers keep applying it to the point,
    /// see `n_parse_doc_element_from_point`).
    scroll_bake: Vec<(usize, (f32, f32))>,
}

/// `<link>` sheet texts fetched for one parse (w51), shared by
/// every shim installation of the parse through
/// [`ParseShimRoots`] (w51 fix A6: the cache used to live on
/// [`ParseLayoutHook`], so it started empty for every
/// parser-inserted script and a page with N scripts refetched
/// every sheet N times — including one-shot/nonce sheet URLs the
/// shim then consumed before the production loader could fetch
/// them).
///
/// Keyed by resolved sheet URL. `None` values are failed or
/// timed-out loads: failures are cached too, so a failing sheet is
/// paid once per parse, not once per script. (Divergence left by
/// design: the fetched texts are *not* handed to the production
/// loader — it lives in `bowser_app`, which depends on this crate —
/// so it refetches each sheet once after the parse.)
#[derive(Default)]
pub(crate) struct ParseLinkSheetCache {
    texts: HashMap<String, Option<String>>,
    /// Network fetches actually performed (test instrumentation:
    /// the sharing tests assert one fetch per URL per parse).
    fetches: u64,
}

/// Measured geometry for one element of a partial layout: the
/// `table_box_geometry` result, the border box (relative to the
/// partial-layout root), scroll extents, used borders, and the offset
/// parent's arena index (resolved to a handle per read).
#[derive(Clone, Copy)]
struct ParseMeasuredBox {
    geom: TableBoxGeometry,
    rect: Rect,
    scroll_w: f32,
    scroll_h: f32,
    /// Used border widths `[top, right, bottom, left]`.
    borders: [f32; 4],
    is_body: bool,
    offset_parent_arena: Option<usize>,
    /// Custom element (`x-table`, …) the pass left at the initial
    /// `display: inline`: no harvested rule assigns it a display,
    /// so geometry measured through it is fiction and reads answer
    /// the honest zero instead (see `ensure_layout`).
    custom_inline: bool,
    /// Per-dimension phantom flags for a cell-less `<table>`: the table
    /// engine's [`LayoutBox::phantom_w`]/[`LayoutBox::phantom_h`] stamp,
    /// read directly — the engine computed both with full context, so
    /// the shim no longer re-derives per-dimension residuals from the
    /// old single-bool OR (that re-derivation bled: caption, min-width,
    /// redistributed-height, and rows==0 cases). Only an `auto`
    /// dimension with no used borders can be the phantom — a specified
    /// size, or used borders making the engine's number real, keeps its
    /// laid-out number (a `<caption>` never stamps the width).
    ///
    /// A truly childless table never reaches the engine (it takes
    /// `layout_block`'s empty-block early return), so it carries no
    /// stamp: `phantom_w` ORs in the minimal [`childless_table_phantom`]
    /// fallback for those (auto width, no used borders, width inside
    /// one border-spacing).
    phantom_w: bool,
    phantom_h: bool,
}

/// Minimal phantom-width fallback for a truly childless `<table>`: it
/// never reaches the table engine (`layout_block`'s empty-block early
/// return), so it carries no [`LayoutBox::phantom_w`] stamp. Mirrors
/// the deleted `table_zero_dims`' width arm only: auto width, no used
/// horizontal borders, and the laid-out width inside one border-spacing
/// (a vertical table's physical-width phantom is the vertical spacing).
/// The height arm never applied to childless tables (it needed rows),
/// so the height keeps its laid-out number. `h_borders` is the call
/// site's `box_used_borders` left+right, used (not specified) so
/// collapsed-table winners agree with the geometry the reads use.
fn childless_table_phantom(bx: &LayoutBox, h_borders: f32) -> bool {
    // Note: no `InlineTable` variant — inline tables share
    // `BoxType::Table` (their `display` lives in `data.display`).
    if !matches!(bx.box_type, BoxType::Table) || !bx.children.is_empty() {
        return false;
    }
    let style = bx.style.as_ref();
    let width_auto = match style.and_then(|s| s.get("width")) {
        None => true,
        Some(CssValue::Keyword(k)) => k.eq_ignore_ascii_case("auto"),
        _ => false,
    };
    if !width_auto || h_borders > 0.001 {
        return false;
    }
    let collapse = style
        .and_then(|s| s.get("border-collapse"))
        .is_some_and(|v| matches!(v, CssValue::Keyword(k) if k.eq_ignore_ascii_case("collapse")));
    // `border-spacing` computes to absolute px (see
    // `adjust_computed_props`), so the components parse directly.
    let spacing = if collapse {
        0.0
    } else {
        let serialized = style
            .and_then(|s| s.get("border-spacing"))
            .map_or_else(|| "0".to_owned(), css_value_to_string);
        let mut parts = serialized
            .split_whitespace()
            .filter_map(|p| p.strip_suffix("px")?.parse::<f32>().ok());
        let h = parts.next().unwrap_or(0.0);
        let v = parts.next().unwrap_or(h);
        let vertical = style.and_then(|s| s.get("writing-mode")).is_some_and(|v| {
            matches!(v, CssValue::Keyword(k) if k.eq_ignore_ascii_case("vertical-lr") || k.eq_ignore_ascii_case("vertical-rl"))
        });
        if vertical { v } else { h }
    };
    bx.rect.w <= spacing + 0.001
}

/// What the parse-phase geometry getters read: a [`ParseMeasuredBox`]
/// plus the resolved offset-parent handle. All px values unrounded
/// (the JS binding rounds IDL `long`s on the way out).
#[derive(Clone, Copy)]
pub(crate) struct ParseElementGeometry {
    pub geom: TableBoxGeometry,
    pub rect: Rect,
    pub scroll_w: f32,
    pub scroll_h: f32,
    pub borders: [f32; 4],
    pub is_body: bool,
    pub offset_parent: Option<ScriptElement>,
}

impl Default for ParseElementGeometry {
    /// The honest zero: stale handle, detached element, or no box
    /// (`display: none`, `display: contents`) — never `undefined`.
    fn default() -> Self {
        Self {
            geom: TableBoxGeometry {
                offset_width: 0.0,
                offset_height: 0.0,
                client_width: 0.0,
                client_height: 0.0,
                offset_left: 0.0,
                offset_top: 0.0,
            },
            rect: Rect {
                x: 0.0,
                y: 0.0,
                w: 0.0,
                h: 0.0,
            },
            scroll_w: 0.0,
            scroll_h: 0.0,
            borders: [0.0; 4],
            is_body: false,
            offset_parent: None,
        }
    }
}

/// Outputs of one [`ParseLayoutHook::rebuild_and_layout`] pass that the
/// finding-2 post-pass inspects: the rebuilt document, its node→arena
/// map, the harvested author stylesheets, and the layout viewport.
struct PartialRebuild<'a> {
    doc: &'a Document,
    node_arena: &'a HashMap<NodeId, usize>,
    sheets: &'a [Stylesheet],
    viewport: (f32, f32),
}

// ---------------------------------------------------------------------------
// Mid-parse scroll snapping
//
// Script scrolls (`element.scrollTo`, `window.scrollTo`, …) run before
// the production `ScrollTree` exists, so the shim evaluates scroll-snap
// itself against the on-demand partial layout. The selection math
// mirrors `bowser_app::scroll`'s `eval_snap` / `snap_target_on_axis`
// exactly (same formulas, same epsilon); the app crate cannot be
// depended on from here, so the small pure core is duplicated. Every
// other production behavior with no mid-parse equivalent (smooth
// animation, `scrollend`, chaining) is simply absent: a script scroll
// resolves synchronously, which is exactly what testharness-era tests
// observe.
// ---------------------------------------------------------------------------

/// Candidate-count epsilon for scroll-snap comparisons (mirrors the
/// production `SNAP_EPS`).
const PARSE_SNAP_EPS: f32 = 1.0 / 4096.0;

/// One snap target of a parse-phase container: the query's area plus
/// the per-target `scroll-snap-stop` and x-reversal flag (mirrors the
/// production `SnapAreaInfo`).
struct ParseSnapArea {
    rect: Rect,
    align_x: SnapAlign,
    align_y: SnapAlign,
    stop: SnapStop,
    rev_x: bool,
}

/// One parse-phase scroll container's snap inputs: range, snapport,
/// snap type, padding, areas (mirrors the production container's
/// `snap` + geometry, minus everything only layout frames need).
struct ParseSnapContainer {
    scrollport: Rect,
    origin: (f32, f32),
    max: (f32, f32),
    snap_type: SnapType,
    /// `scroll-padding` as (top, right, bottom, left).
    padding: (f32, f32, f32, f32),
    areas: Vec<ParseSnapArea>,
    /// The container's initial scroll position from a
    /// `scroll-initial-target: nearest` descendant (CSS Scroll
    /// Snap 2 §3.1.2): the selected target's aligned offset,
    /// clamped into `[origin, max]`; `None` when no descendant
    /// opts in. Read paths report it for a container script has
    /// never scrolled (see `parse_el_scroll_get`).
    initial_target: Option<(f32, f32)>,
}

/// Snap data for one tree state (one `mutation_count`): the element
/// containers by rebuilt-document node, the viewport container, and the
/// node lookups the scroll natives need to route a target.
struct ParseSnapData {
    by_node: HashMap<NodeId, ParseSnapContainer>,
    viewport: Option<ParseSnapContainer>,
    root_node: Option<NodeId>,
    body_node: Option<NodeId>,
    /// Original parse-arena index → rebuilt-document node.
    arena_node: HashMap<usize, NodeId>,
}

/// Style data for one tree state (one `mutation_count`): the whole
/// parsed-so-far tree rebuilt as a fresh [`Document`] (rooted at the
/// document element, so ancestor-dependent selectors and inheritance
/// resolve exactly as in the full document), the author stylesheets
/// harvested from its `<style>` elements, and the arena→node lookup
/// `getComputedStyle` needs to route a target. Mirrors
/// [`ParseSnapData`]'s whole-tree rebuild, minus the layout pass:
/// computed style needs the cascade, not boxes.
struct ParseStyleData {
    doc: Document,
    sheets: Vec<Stylesheet>,
    /// Original parse-arena index → rebuilt-document node.
    arena_node: HashMap<usize, NodeId>,
}

/// The UA stylesheet for parse-shim computed style, parsed once (the
/// production install keeps its own copy on `WebApis`).
fn parse_ua_stylesheet() -> &'static Stylesheet {
    static UA: OnceLock<Stylesheet> = OnceLock::new();
    UA.get_or_init(default_ua_stylesheet)
}

/// One axis's snap candidate: a snap position, whether its area is
/// `scroll-snap-stop: always`, and the valid resting range when the
/// area covers the snapport (mirrors the production `SnapCandidate`).
struct ParseSnapCandidate {
    pos: f32,
    always: bool,
    cover_lo: f32,
    cover_hi: f32,
}

fn parse_snap_is_mandatory(t: SnapType) -> bool {
    matches!(
        t,
        SnapType::MandatoryX | SnapType::MandatoryY | SnapType::MandatoryBoth
    )
}

fn parse_snap_snaps_x(t: SnapType) -> bool {
    matches!(
        t,
        SnapType::ProximityX
            | SnapType::MandatoryX
            | SnapType::ProximityBoth
            | SnapType::MandatoryBoth
    )
}

fn parse_snap_snaps_y(t: SnapType) -> bool {
    matches!(
        t,
        SnapType::ProximityY
            | SnapType::MandatoryY
            | SnapType::ProximityBoth
            | SnapType::MandatoryBoth
    )
}

/// The proximity snap reach for one axis (mirror of the production
/// `proximity_threshold` in bowser_app's scroll.rs): one third of the
/// snapport extent. CSS Scroll Snap 1 §5.2 leaves the reach UA-defined;
/// the full snapport extent this mirror originally received snapped
/// nearly every proximity rest (the wave-50 `not-resnap-outside-
/// proximity-threshold` regression: a rest 250px from the nearest snap
/// position in a 600px snapport was dragged onto it).
fn parse_proximity_threshold(snapport_extent: f32) -> f32 {
    snapport_extent / 3.0
}

/// Pick the snapped resting offset on one axis (mirror of the
/// production `snap_target_on_axis`): `scroll-snap-stop: always` traps
/// a relative scroll at the first `always` position it passes over, a
/// resting offset inside a covering area's valid range stays, and
/// otherwise the nearest position wins — unconditionally under
/// `mandatory`, within `threshold` of the natural offset under
/// `proximity`.
fn parse_snap_select_axis(
    candidates: &[ParseSnapCandidate],
    natural: f32,
    pre: f32,
    mandatory: bool,
    threshold: f32,
    relative: bool,
) -> Option<f32> {
    use std::cmp::Ordering;
    if candidates.is_empty() {
        return None;
    }
    let nearer = |a: &f32, b: &f32, to: f32| {
        (*a - to)
            .abs()
            .partial_cmp(&(*b - to).abs())
            .unwrap_or(Ordering::Equal)
    };
    if relative {
        let (lo, hi) = if pre <= natural {
            (pre, natural)
        } else {
            (natural, pre)
        };
        // The starting point itself does not count as passed over —
        // otherwise a scroll starting exactly on a snap position could
        // never leave it.
        let first = candidates.iter().filter(|c| {
            c.always && (c.pos - pre).abs() > PARSE_SNAP_EPS && c.pos >= lo && c.pos <= hi
        });
        if let Some(c) = first.min_by(|a, b| nearer(&a.pos, &b.pos, pre)) {
            return Some(c.pos);
        }
    }
    // A resting offset the snapport covers entirely inside an area is a
    // valid snap position in its own right (snap overflow): the scroll
    // stays there instead of being dragged to a position.
    if candidates
        .iter()
        .any(|c| natural >= c.cover_lo - PARSE_SNAP_EPS && natural <= c.cover_hi + PARSE_SNAP_EPS)
    {
        return Some(natural);
    }
    candidates
        .iter()
        .map(|c| c.pos)
        .min_by(|a, b| nearer(a, b, natural))
        .filter(|&p| mandatory || (p - natural).abs() <= threshold)
}

/// One snap candidate for one area on one axis (mirror of the
/// production `eval_snap` candidate math): the position that aligns
/// the area with the snapport, plus the covering range when the area
/// is larger than the snapport.
#[allow(clippy::too_many_arguments)]
fn parse_snap_candidate(
    align: SnapAlign,
    start: f32,
    size: f32,
    port: f32,
    sp: f32,
    pad_start: f32,
    pad_end: f32,
    always: bool,
    rev: bool,
) -> Option<ParseSnapCandidate> {
    let align = if rev {
        match align {
            SnapAlign::Start => SnapAlign::End,
            SnapAlign::End => SnapAlign::Start,
            a => a,
        }
    } else {
        align
    };
    let pos = match align {
        SnapAlign::Start => start - pad_start,
        SnapAlign::End => start + size - port + pad_end,
        SnapAlign::Center => start + size * 0.5 - pad_start - sp * 0.5,
        SnapAlign::None => return None,
    };
    let (cover_lo, cover_hi) = if size > sp {
        (start - pad_start, start + size - sp - pad_start)
    } else {
        (pos, pos)
    };
    Some(ParseSnapCandidate {
        pos,
        always,
        cover_lo,
        cover_hi,
    })
}

/// Snap-adjust one scroll of one container (mirror of the production
/// `eval_snap` selection plus the `[origin, max]` clamp): the natural
/// offset returns unchanged when the container has no snap type, the
/// scroll is dust, or no candidate applies; a chosen target is clamped
/// into the container's scrollable range.
fn parse_snap_apply(
    cont: &ParseSnapContainer,
    pre: (f32, f32),
    natural: (f32, f32),
    relative: bool,
) -> (f32, f32) {
    let clamp_axis = |v: f32, lo: f32, hi: f32| {
        let lo = lo.min(hi);
        if v.is_nan() { lo } else { v.clamp(lo, hi) }
    };
    let clamp = |p: (f32, f32)| {
        (
            clamp_axis(p.0, cont.origin.0, cont.max.0),
            clamp_axis(p.1, cont.origin.1, cont.max.1),
        )
    };
    let natural = clamp(natural);
    if cont.snap_type == SnapType::None {
        return natural;
    }
    if (natural.0 - pre.0).abs() < PARSE_SNAP_EPS && (natural.1 - pre.1).abs() < PARSE_SNAP_EPS {
        return natural;
    }
    let (pad_t, pad_r, pad_b, pad_l) = cont.padding;
    let spw = (cont.scrollport.w - pad_l - pad_r).max(0.0);
    let sph = (cont.scrollport.h - pad_t - pad_b).max(0.0);
    let mut px = Vec::new();
    let mut py = Vec::new();
    for a in &cont.areas {
        let always = a.stop == SnapStop::Always;
        if let Some(cd) = parse_snap_candidate(
            a.align_x,
            a.rect.x,
            a.rect.w,
            cont.scrollport.w,
            spw,
            pad_l,
            pad_r,
            always,
            a.rev_x,
        ) {
            px.push(cd);
        }
        if let Some(cd) = parse_snap_candidate(
            a.align_y,
            a.rect.y,
            a.rect.h,
            cont.scrollport.h,
            sph,
            pad_t,
            pad_b,
            always,
            false,
        ) {
            py.push(cd);
        }
    }
    let st = cont.snap_type;
    let mut out = natural;
    // Axis gating (production `eval_snap`, commit 2992973): an axis
    // the snap type does not cover has NO valid snap positions (CSS
    // Scroll Snap §5.2) — it is not evaluated at all, not even under
    // proximity. The previous shim passed
    // `mandatory && snaps_<axis>` as the strictness flag, so an
    // uncovered axis degraded to a proximity evaluation and a
    // diagonal scroll could be dragged sideways onto a snap point of
    // the axis the snap type ignores.
    if parse_snap_snaps_x(st)
        && let Some(x) = parse_snap_select_axis(
            &px,
            natural.0,
            pre.0,
            parse_snap_is_mandatory(st),
            parse_proximity_threshold(spw),
            relative,
        )
    {
        out.0 = x;
    }
    if parse_snap_snaps_y(st)
        && let Some(y) = parse_snap_select_axis(
            &py,
            natural.1,
            pre.1,
            parse_snap_is_mandatory(st),
            parse_proximity_threshold(sph),
            relative,
        )
    {
        out.1 = y;
    }
    clamp(out)
}

/// Resolve one computed padding side against `pct_base`:
/// percentages against the base, `em` against the element's own
/// computed font size, `rem`/viewport units against `ctx`, absolute
/// lengths directly, deferred calc as `pct * base + px`, unitless
/// zero as zero. Anything else (keywords, `ex` beyond the 0.5em
/// fallback, unknown units) is 0 — the same fail-closed shape as
/// [`parse_abs_len_px`], but with the relative units resolved
/// instead of dropped.
fn resolve_pad_css_value(
    value: Option<&CssValue>,
    pct_base: f32,
    font_px: f32,
    ctx: &ComputedAdjustCtx,
) -> f32 {
    use bowser_css::LengthUnit;
    match value {
        Some(CssValue::Percentage(p)) => p / 100.0 * pct_base,
        Some(CssValue::MathDeferred { pct, px, .. }) => pct / 100.0 * pct_base + px,
        Some(CssValue::Length(n, unit)) => match unit {
            LengthUnit::Px => *n,
            LengthUnit::Cm => *n * 96.0 / 2.54,
            LengthUnit::Mm => *n * 96.0 / 25.4,
            LengthUnit::In => *n * 96.0,
            LengthUnit::Pt => *n * 96.0 / 72.0,
            LengthUnit::Pc => *n * 16.0,
            LengthUnit::Q => *n * 96.0 / 101.6,
            LengthUnit::Em => *n * font_px,
            LengthUnit::Rem => *n * ctx.root_px,
            LengthUnit::Vw => *n * ctx.vw / 100.0,
            LengthUnit::Vh => *n * ctx.vh / 100.0,
            LengthUnit::Vmin => *n * ctx.vw.min(ctx.vh) / 100.0,
            LengthUnit::Vmax => *n * ctx.vw.max(ctx.vh) / 100.0,
            LengthUnit::Ex => *n * font_px * 0.5,
        },
        Some(CssValue::Number(n)) if *n == 0.0 => 0.0,
        _ => 0.0,
    }
}

/// An absolute CSS length in px (mirror of the production
/// `abs_len_px`): absolute units convert, everything else (relative
/// units, keywords, missing) is 0 — the mid-parse resolver has no
/// font/viewport context for a target's ancestors.
fn parse_abs_len_px(value: Option<&CssValue>) -> f32 {
    use bowser_css::LengthUnit;
    match value {
        Some(CssValue::Length(v, unit)) => match unit {
            LengthUnit::Px => *v,
            LengthUnit::Cm => *v * 96.0 / 2.54,
            LengthUnit::Mm => *v * 96.0 / 25.4,
            LengthUnit::In => *v * 96.0,
            LengthUnit::Pt => *v * 96.0 / 72.0,
            LengthUnit::Pc => *v * 16.0,
            LengthUnit::Q => *v * 96.0 / 101.6,
            _ => 0.0,
        },
        _ => 0.0,
    }
}

/// The `(left, top, right, bottom)` border+padding insets of a
/// split-inline wrapper's border box past its content box (mirror of
/// layout's `split_inline_spill_insets`, via the mid-parse
/// [`parse_abs_len_px`]): absolute lengths only; a border width counts
/// only when the side's border style is set and not `none`/`hidden`.
fn parse_split_inline_spill_insets(style: &bowser_css::ComputedStyle) -> (f32, f32, f32, f32) {
    use bowser_css::props;
    let side = |pad: u8, bw: u8, bs: u8| {
        let padding = parse_abs_len_px(style.get_by_index(pad));
        let border = match style.get_str_by_index(bs) {
            Some(v) if !v.eq_ignore_ascii_case("none") && !v.eq_ignore_ascii_case("hidden") => {
                parse_abs_len_px(style.get_by_index(bw))
            }
            _ => 0.0,
        };
        padding + border
    };
    (
        side(
            props::PADDING_LEFT,
            props::BORDER_LEFT_WIDTH,
            props::BORDER_LEFT_STYLE,
        ),
        side(
            props::PADDING_TOP,
            props::BORDER_TOP_WIDTH,
            props::BORDER_TOP_STYLE,
        ),
        side(
            props::PADDING_RIGHT,
            props::BORDER_RIGHT_WIDTH,
            props::BORDER_RIGHT_STYLE,
        ),
        side(
            props::PADDING_BOTTOM,
            props::BORDER_BOTTOM_WIDTH,
            props::BORDER_BOTTOM_STYLE,
        ),
    )
}

/// A `scroll-padding` side: absolute lengths in px, plus percentages
/// against the scrollport extent (the one relative form with a local
/// base); other units resolve to 0 mid-parse.
fn parse_snap_len(value: Option<&CssValue>, pct_base: f32) -> f32 {
    match value {
        Some(CssValue::Percentage(p)) => p / 100.0 * pct_base,
        Some(CssValue::Number(n)) => *n,
        other => parse_abs_len_px(other),
    }
}

/// Resolve `scroll-padding` as (top, right, bottom, left) from the
/// computed style's longhands (the cascade has already expanded the
/// shorthand onto them).
fn parse_scroll_padding_abs(
    style: Option<&bowser_css::ComputedStyle>,
    scrollport_w: f32,
    scrollport_h: f32,
) -> (f32, f32, f32, f32) {
    let Some(style) = style else {
        return (0.0, 0.0, 0.0, 0.0);
    };
    (
        parse_snap_len(style.get("scroll-padding-top"), scrollport_h),
        parse_snap_len(style.get("scroll-padding-right"), scrollport_w),
        parse_snap_len(style.get("scroll-padding-bottom"), scrollport_h),
        parse_snap_len(style.get("scroll-padding-left"), scrollport_w),
    )
}

/// The layout box for `node`, iterative preorder (the box tree is
/// never recursed, mirroring the layout crate's own walks).
fn parse_find_box(root: &LayoutTree, node: NodeId) -> Option<&LayoutBox> {
    let mut stack: Vec<&LayoutBox> = vec![root];
    while let Some(b) = stack.pop() {
        if b.node == Some(node) {
            return Some(b);
        }
        stack.extend(b.children.iter());
    }
    None
}

/// Loose float equality for page-frame rect origins, which round-trip
/// through content-origin arithmetic (mirror of the production
/// `approx_eq`).
fn parse_approx_eq(a: f32, b: f32) -> bool {
    (a - b).abs() <= 0.01
}

/// Prune the areas a nested container claims (`owned`, in the page
/// frame) from a container's own `areas` (in container content
/// coordinates; `origin` is the container's content origin in the
/// page frame). One-for-one (production `snap_areas_for_engine`,
/// commit b6efe53): each owned area removes AT MOST ONE of this
/// container's areas. A nested container's own box can share a rect
/// and alignment with the first area inside it (a child that exactly
/// fills it), and the previous any-match filter removed BOTH twins —
/// losing the container's own box as an area of this container
/// entirely. With one-for-one removal one twin survives, which is
/// all the snap engine needs: their snap positions agree.
fn parse_snap_prune_owned(
    mut areas: Vec<bowser_layout::SnapArea>,
    owned: &[(Rect, SnapAlign, SnapAlign)],
    origin: (f32, f32),
) -> Vec<bowser_layout::SnapArea> {
    let (ox, oy) = origin;
    for (r, ax, ay) in owned {
        if let Some(i) = areas.iter().position(|a| {
            *ax == a.align_x
                && *ay == a.align_y
                && r.w == a.rect.w
                && r.h == a.rect.h
                && parse_approx_eq(r.x, a.rect.x + ox)
                && parse_approx_eq(r.y, a.rect.y + oy)
        }) {
            areas.remove(i);
        }
    }
    areas
}

/// A snap target's physical alignment (shared by the snap-area
/// walk and the initial-target walk): the `(block, inline)` pair
/// from `scroll_snap_align` mapped onto physical axes per the
/// target's own writing mode, plus the x-reversal flag. The layout
/// query maps the pair the same way; anything vertical swaps it,
/// and the physical start/end edges swap when the x progression
/// runs right-to-left (`vertical-rl`/`sideways-rl`, or
/// `direction: rtl` in a horizontal writing mode).
fn parse_align_axes(style: &bowser_css::ComputedStyle) -> (SnapAlign, SnapAlign, bool) {
    let (block, inline) = style.scroll_snap_align();
    let wm = style.get_str("writing-mode");
    // Mirror the query's `HorizontalTb` vs not split: anything
    // vertical swaps the (block, inline) pair.
    let vertical = wm.is_some_and(|w| {
        w.eq_ignore_ascii_case("vertical-lr")
            || w.eq_ignore_ascii_case("vertical-rl")
            || w.eq_ignore_ascii_case("sideways-lr")
            || w.eq_ignore_ascii_case("sideways-rl")
    });
    let (align_x, align_y) = if vertical {
        (block, inline)
    } else {
        (inline, block)
    };
    let rev_x = match wm {
        Some(w)
            if w.eq_ignore_ascii_case("vertical-rl") || w.eq_ignore_ascii_case("sideways-rl") =>
        {
            true
        }
        Some(w)
            if w.eq_ignore_ascii_case("vertical-lr") || w.eq_ignore_ascii_case("sideways-lr") =>
        {
            false
        }
        _ => style
            .get_str("direction")
            .is_some_and(|d| d.eq_ignore_ascii_case("rtl")),
    };
    (align_x, align_y, rev_x)
}

/// A container's `scroll-initial-target` position (CSS Scroll
/// Snap 2 §3.1.2): among the container's descendants with
/// `scroll-initial-target: nearest` — skipping `position: fixed`
/// subtrees and nested containers' interiors, like the snap-area
/// walk — the target whose aligned offset is nearest the
/// container's initial offset (`origin`) wins, ties keep document
/// order, and the winning offset, clamped into `[origin, max]`,
/// is the container's initial scroll position. Alignment follows
/// the target's `scroll-snap-align`, defaulting to `start` on an
/// axis that names none (the spec's default initial alignment).
/// Rects convert to container content coordinates through the
/// container's content origin (the same border+padding recovery
/// `parse_snap_areas` performs), so the candidate math is the
/// snap candidate math verbatim.
fn parse_initial_target(
    tree: &LayoutTree,
    container_node: NodeId,
    containers: &HashSet<NodeId>,
    scrollport: Rect,
    padding: (f32, f32, f32, f32),
    origin: (f32, f32),
    max: (f32, f32),
) -> Option<(f32, f32)> {
    let cbox = parse_find_box(tree, container_node)?;
    let (pad_t, pad_r, pad_b, pad_l) = padding;
    let spw = (scrollport.w - pad_l - pad_r).max(0.0);
    let sph = (scrollport.h - pad_t - pad_b).max(0.0);
    let (ox, oy) = {
        let style = cbox.style.as_deref();
        let get = |prop: &str| style.and_then(|s| s.get(prop));
        (
            cbox.rect.x
                + parse_abs_len_px(get("border-left-width"))
                + parse_abs_len_px(get("padding-left")),
            cbox.rect.y
                + parse_abs_len_px(get("border-top-width"))
                + parse_abs_len_px(get("padding-top")),
        )
    };
    let clamp = |v: f32, lo: f32, hi: f32| {
        let lo = lo.min(hi);
        if v.is_nan() { lo } else { v.clamp(lo, hi) }
    };
    let mut cands: Vec<(f32, f32)> = Vec::new();
    let mut walk: Vec<&LayoutBox> = cbox.children.iter().collect();
    while let Some(box_) = walk.pop() {
        if box_
            .style
            .as_ref()
            .is_some_and(|s| position_of(s) == Position::Fixed)
        {
            continue;
        }
        if box_
            .node
            .is_some_and(|n| n != container_node && containers.contains(&n))
        {
            continue; // a nested container's subtree is its own
        }
        if let Some(style) = box_.style.as_deref()
            && style
                .get_str("scroll-initial-target")
                .is_some_and(|v| v.eq_ignore_ascii_case("nearest"))
        {
            let (ax, ay, rev_x) = parse_align_axes(style);
            let ax = if ax == SnapAlign::None {
                SnapAlign::Start
            } else {
                ax
            };
            let ay = if ay == SnapAlign::None {
                SnapAlign::Start
            } else {
                ay
            };
            let px = parse_snap_candidate(
                ax,
                box_.rect.x - ox,
                box_.rect.w,
                scrollport.w,
                spw,
                pad_l,
                pad_r,
                false,
                rev_x,
            )
            .map(|c| c.pos);
            let py = parse_snap_candidate(
                ay,
                box_.rect.y - oy,
                box_.rect.h,
                scrollport.h,
                sph,
                pad_t,
                pad_b,
                false,
                false,
            )
            .map(|c| c.pos);
            if let (Some(px), Some(py)) = (px, py) {
                cands.push((clamp(px, origin.0, max.0), clamp(py, origin.1, max.1)));
            }
        }
        walk.extend(box_.children.iter());
    }
    // The walk is stack order (reverse document order): iterate it
    // backwards so ties keep the earliest target in document order.
    let mut best: Option<((f32, f32), f32)> = None;
    for pos in cands.into_iter().rev() {
        let d2 = (pos.0 - origin.0).powi(2) + (pos.1 - origin.1).powi(2);
        if best.is_none_or(|(_, bd)| d2 < bd) {
            best = Some((pos, d2));
        }
    }
    best.map(|(pos, _)| pos)
}

/// A container's snap areas with per-target `scroll-snap-stop` and the
/// x-reversal flag attached (mirror of the production
/// `snap_areas_for_engine`): the layout query reports each area's
/// retargeted target node, and stop/reversal are recovered by matching
/// each area against the subtree's target boxes in the shared page
/// frame; areas a nested container claims are pruned from this list.
fn parse_snap_areas(
    root: &LayoutTree,
    container_node: NodeId,
    containers: &HashSet<NodeId>,
    doc: &Document,
) -> Vec<ParseSnapArea> {
    let Some(cbox) = parse_find_box(root, container_node) else {
        return Vec::new();
    };
    let areas = snap_areas_for_container(root, container_node, doc);
    if areas.is_empty() {
        return Vec::new();
    }
    // The query reports rects in container content coordinates (border
    // box minus border and padding): recover a container's content
    // origin to compare areas in the shared page frame.
    let origin_of = |b: &LayoutBox| -> (f32, f32) {
        let style = b.style.as_deref();
        let get = |prop: &str| style.and_then(|s| s.get(prop));
        (
            b.rect.x
                + parse_abs_len_px(get("border-left-width"))
                + parse_abs_len_px(get("padding-left")),
            b.rect.y
                + parse_abs_len_px(get("border-top-width"))
                + parse_abs_len_px(get("padding-top")),
        )
    };
    // Outermost nested container boxes (`position: fixed` subtrees are
    // skipped — the query emits no areas from them).
    let mut nested: Vec<&LayoutBox> = Vec::new();
    let mut stack: Vec<&LayoutBox> = cbox.children.iter().collect();
    while let Some(box_) = stack.pop() {
        if box_
            .style
            .as_ref()
            .is_some_and(|s| position_of(s) == Position::Fixed)
        {
            continue;
        }
        if box_
            .node
            .is_some_and(|n| n != container_node && containers.contains(&n))
        {
            nested.push(box_);
            continue;
        }
        stack.extend(box_.children.iter());
    }
    // The targets' stops: (page-frame rect expanded by `scroll-margin`,
    // physical alignment) -> `scroll-snap-stop`, plus the reversal
    // flag. The query maps `scroll_snap_align()`'s `(block, inline)`
    // pair onto physical axes per the target's own writing mode; the
    // same mapping is reproduced here off the serialized
    // `writing-mode` (vertical-* swaps the pair). An absolutely
    // positioned box only produces an area when its containing block is
    // inside the container (the query's rule); the walk below is
    // deliberately looser — a non-participating box's rect never
    // matches a surviving area, so the extra entries are inert.
    let mut stops: Vec<(Rect, SnapAlign, SnapAlign, SnapStop, bool)> = Vec::new();
    let mut walk: Vec<&LayoutBox> = cbox.children.iter().collect();
    while let Some(box_) = walk.pop() {
        if box_
            .style
            .as_ref()
            .is_some_and(|s| position_of(s) == Position::Fixed)
        {
            continue;
        }
        if let Some(style) = box_.style.as_deref() {
            let (block, inline) = style.scroll_snap_align();
            if block != SnapAlign::None || inline != SnapAlign::None {
                let (align_x, align_y, rev_x) = parse_align_axes(style);
                let get = |prop: &str| style.get(prop);
                // `sane_len` mirrors the query's own sanitization so
                // the rect compares exactly against the query's areas.
                stops.push((
                    Rect {
                        x: sane_len(box_.rect.x - parse_abs_len_px(get("scroll-margin-left"))),
                        y: sane_len(box_.rect.y - parse_abs_len_px(get("scroll-margin-top"))),
                        w: sane_len(
                            box_.rect.w
                                + parse_abs_len_px(get("scroll-margin-left"))
                                + parse_abs_len_px(get("scroll-margin-right")),
                        ),
                        h: sane_len(
                            box_.rect.h
                                + parse_abs_len_px(get("scroll-margin-top"))
                                + parse_abs_len_px(get("scroll-margin-bottom")),
                        ),
                    },
                    align_x,
                    align_y,
                    style.scroll_snap_stop(),
                    rev_x,
                ));
            }
        }
        walk.extend(box_.children.iter());
    }
    let (ox, oy) = origin_of(cbox);
    // Every area the nested containers claim for themselves, in the
    // page frame: an area of this container matching one of these
    // (rect and alignment) belongs to the nested subtree, not here.
    // The pruning itself is one-for-one (see
    // [`parse_snap_prune_owned`]).
    let mut owned: Vec<(Rect, SnapAlign, SnapAlign)> = Vec::new();
    for n in &nested {
        let Some(nn) = n.node else { continue };
        let (nox, noy) = origin_of(n);
        owned.extend(
            snap_areas_for_container(root, nn, doc)
                .into_iter()
                .map(|a| {
                    (
                        Rect {
                            x: a.rect.x + nox,
                            y: a.rect.y + noy,
                            w: a.rect.w,
                            h: a.rect.h,
                        },
                        a.align_x,
                        a.align_y,
                    )
                }),
        );
    }
    parse_snap_prune_owned(areas, &owned, (ox, oy))
        .into_iter()
        .map(|a| {
            let (px, py) = (a.rect.x + ox, a.rect.y + oy);
            // Prefer `Always` on conflicting matches (identical rect
            // and alignment from two targets): the trap then errs
            // toward stopping, the spec-faithful direction. The
            // reversal flag rides the same match.
            let matched = stops
                .iter()
                .filter(|(r, ax, ay, _, _)| {
                    *ax == a.align_x
                        && *ay == a.align_y
                        && r.w == a.rect.w
                        && r.h == a.rect.h
                        && parse_approx_eq(r.x, px)
                        && parse_approx_eq(r.y, py)
                })
                .max_by(|x, y| (x.3 == SnapStop::Always).cmp(&(y.3 == SnapStop::Always)));
            let (stop, rev_x) = match matched {
                Some((_, _, _, s, r)) => (*s, *r),
                None => (SnapStop::Normal, false),
            };
            ParseSnapArea {
                rect: a.rect,
                align_x: a.align_x,
                align_y: a.align_y,
                stop,
                rev_x,
            }
        })
        .collect()
}

/// The viewport's scroll origin and maximum from the document's
/// scrollable overflow (mirror of the production
/// `document_max_scroll`): the whole box tree minus `position: fixed`
/// subtrees and nested containers' interiors.
fn parse_document_extents(
    tree: &LayoutTree,
    containers: &HashSet<NodeId>,
    viewport: (f32, f32),
) -> ((f32, f32), (f32, f32)) {
    let (mut nx, mut ny) = (0.0f32, 0.0f32);
    let (mut ex, mut ey) = (0.0f32, 0.0f32);
    let mut stack: Vec<(&LayoutBox, bool)> = vec![(tree, false)];
    while let Some((b, fixed_above)) = stack.pop() {
        let fixed = fixed_above
            || b.style
                .as_ref()
                .is_some_and(|s| position_of(s) == Position::Fixed);
        if !fixed {
            nx = nx.min(b.rect.x);
            ny = ny.min(b.rect.y);
            ex = ex.max(b.rect.x + b.rect.w);
            ey = ey.max(b.rect.y + b.rect.h);
        }
        let is_nested = b.node.is_some_and(|n| containers.contains(&n));
        if !is_nested {
            stack.extend(b.children.iter().map(|c| (c, fixed)));
        }
    }
    (
        (nx.min(0.0), ny.min(0.0)),
        ((ex - viewport.0).max(0.0), (ey - viewport.1).max(0.0)),
    )
}

/// Env-gated trace for the `<link>` sheet harvest (w52): with
/// `BOWSER_PARSE_LINK_DEBUG=1` in the environment, the recorder's link
/// branch and [`ParseLayoutHook::linked_sheet_text`] log the document
/// URL, the resolved sheet URL, cache hit/miss, and the fetch outcome
/// to stderr. Off by default; zero cost when unset.
macro_rules! parse_link_debug {
    ($($t:tt)*) => {
        if std::env::var_os("BOWSER_PARSE_LINK_DEBUG").is_some() {
            eprintln!("[parse-link] {}", format_args!($($t)*));
        }
    };
}

/// Hard wall-clock budget for one harvested `<link>` fetch (w51
/// fix A5), in total — not per redirect hop. `bowser_net`'s public
/// fetch entry points take no timeout configuration (their
/// internal `Timeouts` are fixed at a 30s connect / 60s socket /
/// 600s-per-redirect-hop total, up to 20 hops), so an unbounded
/// synchronous fetch on the parser/JS thread would let a
/// slow-drip or blackholed sheet server block a mid-parse
/// `offsetWidth` / `getComputedStyle` read for many minutes. The
/// harvest therefore runs the fetch on a detached worker thread
/// and waits with this budget; on expiry the sheet is treated as
/// missing (and the failure is cached, see
/// [`ParseLinkSheetCache`]). The abandoned worker is left to
/// `bowser_net`'s own timeouts: it holds no locks the shim needs
/// and its result is simply never received. Deterministic for the
/// WPT harness: the local test server answers in milliseconds, so
/// the budget never trips there.
const LINK_SHEET_FETCH_BUDGET: Duration = Duration::from_secs(10);

/// Load one linked stylesheet's text (w51), bounded by
/// [`LINK_SHEET_FETCH_BUDGET`] (w51 fix A5).
///
/// Honest divergence from the production loader (w51 fix A10):
/// this fetch is *unauthenticated* — it sends no cookies, no
/// `User-Agent`, and no subresource context (`headers` is empty),
/// unlike `bowser_app`'s loader, which fetches with the page's
/// cookie jar and headers. Cookie-gated sheets therefore come
/// back missing mid-parse (exactly the pre-w51 behavior for those
/// sheets) and only apply once the production loader fetches them
/// after the parse. The production loader's status rule does
/// apply (loader.rs `fetch_stylesheet`): only a 2xx response is
/// parsed; any failure — including a budget timeout — skips the
/// sheet and the page load continues. (The app loader's own
/// fetcher cannot be called from here: `bowser_app` depends on
/// this crate, not the other way round.)
fn fetch_linked_sheet_text(url: &Url) -> Option<String> {
    fetch_linked_sheet_text_with_budget(url, LINK_SHEET_FETCH_BUDGET)
}

/// [`fetch_linked_sheet_text`] with an explicit budget: the seam
/// the timeout test drives with a sub-second budget so it never
/// waits out the production one.
fn fetch_linked_sheet_text_with_budget(url: &Url, budget: Duration) -> Option<String> {
    let request = net_fetch::Request {
        method: "GET".to_string(),
        url: url.clone(),
        headers: Vec::new(),
        body: None,
    };
    let (tx, rx) = mpsc::channel();
    // Detached on purpose: on timeout the caller walks away and
    // the worker's late send just fails into the dropped receiver.
    thread::spawn(move || {
        let _ = tx.send(fetch_linked_sheet_blocking(&request));
    });
    rx.recv_timeout(budget).ok().flatten()
}

/// The unbounded fetch itself, run on the worker thread spawned
/// by [`fetch_linked_sheet_text_with_budget`].
fn fetch_linked_sheet_blocking(request: &net_fetch::Request) -> Option<String> {
    let response = net_fetch::fetch(request).ok()?;
    if !(200..300).contains(&response.status) {
        return None;
    }
    Some(response.text())
}

/// Resolve one harvested `<link>` href to its sheet URL (w51 fix
/// A8), mirroring the production loader's `effective_base_url`
/// semantics (bowser_app loader.rs): the base starts as the
/// document URL and is overridden by the snapshot's first
/// `<base href>` when the recorder captured one — the base href
/// itself resolved against the document URL, an invalid base
/// ignored (the document URL stays the base). The href is then
/// resolved against that effective base.
fn resolve_linked_sheet_url(
    document_url: &str,
    base_href: Option<&str>,
    href: &str,
) -> Option<Url> {
    let doc = bowser_url::parse(document_url, None).ok()?;
    let base = match base_href {
        Some(b) if !b.trim().is_empty() => {
            bowser_url::parse(b, Some(&doc)).unwrap_or_else(|_| doc.clone())
        }
        _ => doc.clone(),
    };
    bowser_url::parse(href, Some(&base)).ok()
}

impl ParseLayoutHook {
    /// The author stylesheets harvested from one snapshot (w51), in
    /// document order: `<style>` texts parsed directly, `<link
    /// rel="stylesheet">` hrefs resolved against the snapshot's
    /// effective base (the seeded document URL, overridden by its
    /// first `<base href>` — w51 fix A8), loaded (once per parse,
    /// cached across installations — w51 fix A6), and parsed with
    /// `bowser_css` — link and style interleaved by document
    /// position, matching the production cascade order (loader.rs
    /// `collect_style_sources`). Unresolvable or failed links are
    /// skipped, mirroring the production loader.
    fn harvested_sheets(&mut self, rec: &SnapshotRecorder) -> Vec<Stylesheet> {
        let mut out = Vec::with_capacity(rec.sheets.len());
        for sheet in &rec.sheets {
            match sheet {
                HarvestedSheet::Inline(text) => out.push(bowser_css::parse_stylesheet(text)),
                HarvestedSheet::Link(href) => {
                    if let Some(text) = self.linked_sheet_text(rec.base_href.as_deref(), href) {
                        out.push(bowser_css::parse_stylesheet(&text));
                    }
                }
            }
        }
        out
    }

    /// The text of one `<link>` sheet, resolved against the
    /// snapshot's effective base (w51 fix A8) and fetched at most
    /// once per parse through the shared cache (w51 fix A6) —
    /// failures are cached too. `None` when no document URL was
    /// seeded, the href does not resolve, or the load failed.
    fn linked_sheet_text(&mut self, base_href: Option<&str>, href: &str) -> Option<String> {
        let document_url = self.document_url.as_deref()?;
        parse_link_debug!("document_url={document_url} base_href={base_href:?} href={href}");
        let url = resolve_linked_sheet_url(document_url, base_href, href)?;
        parse_link_debug!("resolved href={href} -> {}", url.serialize());
        let key = url.serialize();
        if let Some(cached) = self.link_sheets.borrow().texts.get(&key) {
            parse_link_debug!(
                "cache hit {key} -> {}",
                cached.as_deref().map(str::len).map_or(-1, |n| n as i64)
            );
            return cached.clone();
        }
        parse_link_debug!("cache miss {key}; fetching");
        let text = fetch_linked_sheet_text(&url);
        parse_link_debug!(
            "fetch {key} -> {}",
            text.as_deref().map(str::len).map_or(-1, |n| n as i64)
        );
        let mut cache = self.link_sheets.borrow_mut();
        cache.fetches += 1;
        cache.texts.insert(key, text.clone());
        text
    }

    /// `viewport` is the embedder's viewport in CSS px as `(u32, u32)`,
    /// matching the app's `BrowserConfig::viewport` convention; `None`
    /// keeps the 800x600 fallback.
    pub(crate) fn new(viewport: Option<(u32, u32)>) -> Self {
        Self {
            passes: 0,
            boxes: HashMap::new(),
            entries: Vec::new(),
            widened: Vec::new(),
            collapse_rowspan_seen: false,
            snap_cache: Vec::new(),
            style_cache: Vec::new(),
            document_url: None,
            link_sheets: Rc::new(RefCell::new(ParseLinkSheetCache::default())),
            fonts: Rc::new(RefCell::new(None)),
            scroll_bake: Vec::new(),
            viewport: viewport.unwrap_or((
                PARSE_LAYOUT_VIEWPORT_W as u32,
                PARSE_LAYOUT_VIEWPORT_H as u32,
            )),
        }
    }

    /// Partial layout passes run so far (test instrumentation).
    pub(crate) fn layout_passes(&self) -> u64 {
        self.passes
    }

    /// A shim scroll write landed: refresh the scroll bake and drop
    /// the mutation-count-keyed geometry caches. Scroll writes do not
    /// bump the mutation count, so without this the next geometry read
    /// would reuse the pre-scroll bake and sticky constraints would
    /// never see the written offset. The snap/style caches are
    /// scroll-independent and stay.
    pub(crate) fn note_scroll_write(&mut self, bake: Vec<(usize, (f32, f32))>) {
        self.scroll_bake = bake;
        self.entries.clear();
        self.widened.clear();
    }

    /// Measure `el`, running one partial layout pass over its
    /// containing-block subtree when the tree mutated — or the measured
    /// subtree changed — since the last pass. Returns `None` when the
    /// handle is stale or the element has no box: the getters answer 0
    /// then.
    pub(crate) fn ensure_layout(
        &mut self,
        host: &mut ScriptHost<'_, '_, '_>,
        el: ScriptElement,
    ) -> Option<ParseElementGeometry> {
        // The ancestor chain selects the partial-layout root and later
        // resolves the offset-parent handle. Stale handles fail closed
        // here, before any layout work.
        let chain = ancestor_chain(host, el)?;
        // Snapshot-free root guess for the cache key (finding 1): the
        // finding-2 post-pass may widen it once the stylesheets are
        // known; `widened` remaps the guess to the root actually laid
        // out so the widened entry is reused directly.
        let provisional = Self::select_partial_root(host, &chain);
        let count = host.mutation_count();
        let mut key = (count, provisional.arena_index());
        if let Some(&(_, actual)) = self.widened.iter().find(|(k, _)| *k == key) {
            key.1 = actual;
        }
        // A previous pass at this count already laid out the whole
        // document (a widened root): `measure_subtree` measures every
        // box in that tree, so its entry serves this element too —
        // reuse it instead of re-running a subtree pass (and, for a
        // static element, a second widened pass) per parent subtree.
        let doc_root = chain[chain.len() - 1].arena_index();
        if key.1 != doc_root && self.entries.iter().any(|(k, _)| *k == (count, doc_root)) {
            key.1 = doc_root;
        }
        if self.entries.iter().all(|(k, _)| *k != key) {
            match self.run_partial_layout(host, &chain, provisional) {
                Some((laid_out_count, actual_root)) => {
                    // The count is re-read after the snapshot inside
                    // `run_partial_layout` (flushing buffered text can
                    // bump it); the entry is keyed by that post-flush
                    // count so the cache stays exact.
                    key.0 = laid_out_count;
                    if actual_root != key.1 {
                        self.widened.push((key, actual_root));
                        if self.widened.len() > PARSE_LAYOUT_CACHE_ENTRIES {
                            self.widened.remove(0);
                        }
                        key.1 = actual_root;
                    }
                    let boxes = std::mem::take(&mut self.boxes);
                    self.push_entry(key, boxes);
                }
                None => {
                    // Finding 7: cache the miss as an empty entry.
                    // Every later read at this count hits it instead of
                    // re-running a doomed snapshot+rebuild; the next
                    // real mutation changes the count and retries.
                    self.push_entry(key, HashMap::new());
                }
            }
        }
        // Collapse+rowspan bail: a pass found a table combining
        // `visibility: collapse`, a `rowspan > 1` cell, and text
        // ([`snapshot_has_collapse_rowspan_text`]). Its redistribution
        // runs on real font metrics, but the partial pass's fractional
        // line heights still differ by `f32` ULPs from the full
        // layout's, so rounded cross-checks (`cell == Σ rows`) lose to
        // rounding even when the pass matches the full layout exactly,
        // and the visible-phase cross-table comparisons lose to `f32`
        // ULP differences between the two grids. Every read answers the
        // honest zero instead; the bail is document-wide and sticky
        // so a collapsed table, its reference table, and later
        // visibility phases stay consistent.
        if self.collapse_rowspan_seen {
            return None;
        }
        let pos = self.entries.iter().position(|(k, _)| *k == key)?;
        // A cached miss (empty entry) fails here: the getters answer 0,
        // and the entry stays cached until the tree mutates.
        let bx = self.entries[pos].1.get(&el.arena_index())?;
        // Missing-sheet bail: when the measured element — or any
        // ancestor up to the root actually laid out — is a custom
        // element the pass left at the initial `display: inline`
        // ([`is_unresolved_custom_element`]), no harvested rule
        // gave it a display, so every number derived through it is
        // fiction (the css-tables `visibility-*` tests measure
        // `x-table` & friends exactly this way, against a `<link>`
        // sheet whose rules now resolve this bail when they load).
        // The read answers the honest zero instead; the entry
        // stays cached, so unrelated elements of the same pass are
        // still served.
        let boxes = &self.entries[pos].1;
        for &h in chain.iter() {
            let arena = h.arena_index();
            if boxes.get(&arena).is_some_and(|b| b.custom_inline) {
                return None;
            }
            if arena == key.1 {
                break;
            }
        }
        // Cell-less table phantom: a `<table>` with no cells sizes by
        // border-spacing rather than content (see
        // `table_sized_by_phantom`). The auto dimension is reported as
        // the honest zero; the other keeps its laid-out number (e.g. a
        // specified 50px size, or a container-redistributed height).
        let mut geom = ParseElementGeometry {
            geom: bx.geom,
            rect: bx.rect,
            scroll_w: bx.scroll_w,
            scroll_h: bx.scroll_h,
            borders: bx.borders,
            is_body: bx.is_body,
            offset_parent: bx
                .offset_parent_arena
                .and_then(|ap| chain.iter().find(|h| h.arena_index() == ap).copied()),
        };
        if bx.phantom_w {
            geom.geom.offset_width = 0.0;
            geom.geom.client_width = 0.0;
            geom.rect.w = 0.0;
        }
        if bx.phantom_h {
            geom.geom.offset_height = 0.0;
            geom.geom.client_height = 0.0;
            geom.rect.h = 0.0;
        }
        // MRU rotation: the hit moves to the back so ping-ponging
        // subtrees keep their entries while cold ones age out.
        if pos + 1 != self.entries.len() {
            let entry = self.entries.remove(pos);
            self.entries.push(entry);
        }
        Some(geom)
    }

    /// The whole parsed-so-far tree's measured boxes at the current
    /// mutation count, for mid-parse `document.elementFromPoint`
    /// hit-testing: runs one partial layout pass rooted at the document
    /// element when the tree mutated since the last one, then hands back
    /// the pass's box map (`arena index -> measured box`). `None` when
    /// the pass cannot run (cached miss, collapse bail — the same
    /// failures [`ensure_layout`] reports for a single element).
    ///
    /// The box `rect`s are in the partial-layout root's frame (the
    /// document element, laid out at the unshifted document origin);
    /// callers shift the viewport-space point by the recorded window
    /// scroll, mirroring the production `n_element_from_point`.
    fn whole_tree_boxes(
        &mut self,
        host: &mut ScriptHost<'_, '_, '_>,
        doc_el: ScriptElement,
    ) -> Option<&HashMap<usize, ParseMeasuredBox>> {
        // `ensure_layout` rotates the hit entry to the back on success,
        // so the last entry is this pass's whole-tree box map.
        self.ensure_layout(host, doc_el)?;
        self.entries.last().map(|(_, boxes)| boxes)
    }

    /// Insert or replace a cache entry, evicting the least-recently-used
    /// entry past `PARSE_LAYOUT_CACHE_ENTRIES`.
    fn push_entry(&mut self, key: (u64, usize), boxes: HashMap<usize, ParseMeasuredBox>) {
        if let Some(pos) = self.entries.iter().position(|(k, _)| *k == key) {
            self.entries.remove(pos);
        }
        self.entries.push((key, boxes));
        if self.entries.len() > PARSE_LAYOUT_CACHE_ENTRIES {
            self.entries.remove(0);
        }
    }

    /// One partial layout pass: snapshot, rebuild the containing-block
    /// subtree, lay it out, measure every element box. Never more than
    /// the parsed-so-far tree: layout input is bounded to the rebuilt
    /// subtree (which is the entire parsed-so-far tree when the root is
    /// `html`/`body`). Each pass pays an O(parsed-so-far) snapshot cost.
    /// Returns the post-snapshot `mutation_count` the boxes were laid
    /// out against and the arena index of the root actually laid out
    /// (the finding-2 post-pass may widen it past `provisional`).
    /// `None` means the pass could not run at all (e.g. the root has no
    /// snapshot ordinal): the caller caches the miss (finding 7)
    /// instead of retrying it on every read.
    fn run_partial_layout(
        &mut self,
        host: &mut ScriptHost<'_, '_, '_>,
        chain: &[ScriptElement],
        provisional: ScriptElement,
    ) -> Option<(u64, usize)> {
        // Snapshot the tree built so far, borrowing the arena: the
        // parse continues afterwards, undisturbed. `<style>` text is
        // harvested for author rules on the side.
        let mut rec = SnapshotRecorder::new();
        let order = host.snapshot_document(&mut rec);
        // The count is read after the snapshot: flushing buffered text
        // can bump it, and the layout below reflects the post-flush
        // tree, so caching against the post-flush count is exact.
        let count = host.mutation_count();

        // Arm the collapse+rowspan bail when the whole snapshot —
        // not just the rebuilt subtree — shows the combination: reads
        // against the collapsed table's reference table must bail too,
        // and their passes cannot see the collapsed one. Sticky: the
        // dynamic tests toggle back to `visible` and compare exact
        // doubles across the two tables, which no full-context pass
        // satisfies.
        if snapshot_has_collapse_rowspan_text(&rec) {
            self.collapse_rowspan_seen = true;
        }

        // Arena index -> `start_element` emission ordinal.
        let mut arena_ord: HashMap<usize, usize> = HashMap::with_capacity(order.len());
        for (ord, arena) in order.iter().enumerate() {
            arena_ord.insert(*arena, ord);
        }

        // Author rules from `<style>` elements apply document-wide, so
        // they are harvested from the whole snapshot, not the subtree.
        // `<link>` sheets ride the same harvest, in document order.
        let sheets: Vec<Stylesheet> = self.harvested_sheets(&rec);
        let sheet_refs: Vec<&Stylesheet> = sheets.iter().collect();

        let viewport = (self.viewport.0 as f32, self.viewport.1 as f32);
        // The live parser quirks mode: the doctype token sets it
        // before any body script runs, so it is already final when
        // this mid-parse pass runs. The rebuilt documents below
        // default to `NoQuirks`; without this stamp every quirks
        // rule (table-cell height, font-style at the table boundary,
        // cell width) would be invisible to mid-parse reads.
        let quirks = host.quirks_mode();
        let mut root = provisional;
        // Selector-context widening: a pass rooted below an ancestor a
        // harvested rule's combinator needs (e.g. `main table` with the
        // pass rooted at a `div`) cannot apply that rule at all. When
        // any harvested rule uses a combinator, root the pass at the
        // document element instead, so every ancestor-dependent
        // selector can match; the `widened` key remap keeps later reads
        // on the widened entry. `position: fixed` keeps its element
        // root (its containing block is the viewport).
        if root.arena_index() != chain[0].arena_index() && sheets_have_combinator(&sheets) {
            root = chain.last().copied().unwrap_or(root);
        }
        let (doc, node_arena) = self.rebuild_and_layout(
            &rec,
            &order,
            &arena_ord,
            &sheet_refs,
            viewport,
            root,
            quirks,
        )?;
        // Finding-2 post-pass: the provisional root only sees inline
        // `position`. When the measured element's true containing block
        // sits above it (a stylesheet-positioned ancestor, or `body`
        // for an abspos element with no positioned ancestor at all),
        // re-run once from the wider root so percentage insets and
        // `offsetParent` resolve against the right box.
        let rebuilt = PartialRebuild {
            doc: &doc,
            node_arena: &node_arena,
            sheets: &sheets,
            viewport,
        };
        if let Some(wide) = self.stylesheet_widened_root(host, &rebuilt, chain, root)
            && self
                .rebuild_and_layout(
                    &rec,
                    &order,
                    &arena_ord,
                    &sheet_refs,
                    viewport,
                    wide,
                    quirks,
                )
                .is_some()
        {
            root = wide;
        }
        Some((count, root.arena_index()))
    }

    /// Rebuild the subtree rooted at `root` as a fresh document, lay it
    /// out, and measure every element box into `self.boxes`. Returns the
    /// rebuilt document and its node→arena map for the finding-2
    /// post-pass. `None` when the root has no snapshot ordinal.
    ///
    /// The argument count mirrors the established shape for this
    /// hook's rebuild entries (see [`Self::rebuild_tree`]).
    #[allow(clippy::too_many_arguments)]
    fn rebuild_and_layout(
        &mut self,
        rec: &SnapshotRecorder,
        order: &[usize],
        arena_ord: &HashMap<usize, usize>,
        sheet_refs: &[&Stylesheet],
        viewport: (f32, f32),
        root: ScriptElement,
        quirks_mode: QuirksMode,
    ) -> Option<(Document, HashMap<NodeId, usize>)> {
        let (doc, tree, node_arena) = self.rebuild_tree(
            rec,
            order,
            arena_ord,
            sheet_refs,
            viewport,
            root,
            true,
            quirks_mode,
        )?;
        self.boxes.clear();
        self.measure_subtree(&doc, &tree, &node_arena);
        self.passes += 1;
        Some((doc, node_arena))
    }

    /// Rebuild the subtree rooted at `root` as a fresh document and
    /// lay it out, without measuring. `None` when the root has no
    /// snapshot ordinal. Shared by [`Self::rebuild_and_layout`] and the
    /// scroll-snap pass ([`Self::snap_data`]), which needs the layout
    /// tree itself rather than measured boxes.
    ///
    /// `bake_scroll` maps the hook's recorded shim scroll offsets onto
    /// the rebuilt document so sticky constraints bake at the
    /// script-written positions (geometry reads). The snap pass passes
    /// `false`: snap areas live in unshifted content coordinates.
    ///
    /// `quirks_mode` is the live parser mode, stamped onto the
    /// rebuilt document before layout: `PartialDocBuilder` documents
    /// default to `NoQuirks`, and layout (`Forest`) plus style
    /// (`Styler`) both read the mode from the document, so the stamp
    /// is what makes quirks rules visible to mid-parse reads.
    ///
    /// The argument count mirrors the established shape for this
    /// hook's rebuild entries.
    #[allow(clippy::too_many_arguments)]
    fn rebuild_tree(
        &mut self,
        rec: &SnapshotRecorder,
        order: &[usize],
        arena_ord: &HashMap<usize, usize>,
        sheet_refs: &[&Stylesheet],
        viewport: (f32, f32),
        root: ScriptElement,
        bake_scroll: bool,
        quirks_mode: QuirksMode,
    ) -> Option<(Document, LayoutTree, HashMap<NodeId, usize>)> {
        let root_ord = *arena_ord.get(&root.arena_index())?;
        let (start, end) = rec.subtree_range(root_ord)?;

        // Rebuild only the root's subtree as a fresh document: this is
        // the partial bound.
        let mut build = PartialDocBuilder::new();
        build.replay(&rec.events[start..=end], root_ord);
        let (mut doc, node_arena) = build.finish(order);
        doc.set_quirks_mode(quirks_mode);

        let viewport = Size {
            w: viewport.0,
            h: viewport.1,
        };
        // Measure with real font metrics (not `FixedFontMetrics`): the
        // partial layout must agree with the post-parse pipeline,
        // which measures with the embedder's font cache — including
        // the installed WPT test fonts, so `font: 20px Ahem` text
        // measures 1em/char mid-parse too. The cache is shared
        // parse-wide and created lazily: parses with no mid-parse
        // geometry read never pay the system-font walk.
        let mut slot = self.fonts.borrow_mut();
        if slot.is_none() {
            let mut cache = FontCache::new();
            cache.install_test_fonts();
            *slot = Some(cache);
        }
        let tree = {
            let fonts: &FontCache = slot.as_ref().expect("just initialized");
            if bake_scroll && !self.scroll_bake.is_empty() {
                // Sticky constraints bake at layout time: map the
                // recorded shim scroll offsets (host arena -> offset)
                // onto the rebuilt document's nodes so a mid-parse
                // `scrollTop` write is visible to the geometry read
                // that follows it.
                let arena_node: HashMap<usize, NodeId> =
                    node_arena.iter().map(|(&n, &a)| (a, n)).collect();
                let mut nested_offsets: HashMap<NodeId, (f32, f32)> =
                    HashMap::with_capacity(self.scroll_bake.len());
                for (arena, offset) in &self.scroll_bake {
                    if let Some(&node) = arena_node.get(arena) {
                        nested_offsets.insert(node, *offset);
                    }
                }
                layout_with_intrinsics_and_scroll_and_offsets(
                    &doc,
                    sheet_refs,
                    viewport,
                    fonts,
                    &HashMap::new(),
                    (0.0, 0.0),
                    &nested_offsets,
                )
            } else {
                layout(&doc, sheet_refs, viewport, fonts)
            }
        };
        Some((doc, tree, node_arena))
    }

    /// Snap-adjust a script scroll: `(pre, natural)` offsets against
    /// the partial layout's snap data. `el` is `None` for window
    /// scrolls (the viewport container), otherwise the element
    /// wrapper's handle.
    ///
    /// Returns the adjusted offset, or `None` when there is no snap
    /// data to adjust against (no document element, no container for
    /// the target, a failed rebuild): the caller then records the
    /// offsets verbatim, preserving the old set-then-read contract.
    /// Script scrolls are absolute writes, so `relative` is always
    /// `false` from the natives today — the parameter keeps the mirror
    /// signature so the selection semantics stay shared.
    pub(crate) fn snap_scroll(
        &mut self,
        host: &mut ScriptHost<'_, '_, '_>,
        el: Option<ScriptElement>,
        pre: (f32, f32),
        natural: (f32, f32),
        relative: bool,
    ) -> Option<(f32, f32)> {
        let data = self.snap_data(host)?;
        let node = el.and_then(|e| data.arena_node.get(&e.arena_index()).copied());
        let cont = match node {
            None => data.viewport.as_ref()?,
            Some(n) if Some(n) == data.root_node || Some(n) == data.body_node => {
                data.viewport.as_ref()?
            }
            Some(n) => data.by_node.get(&n)?,
        };
        Some(parse_snap_apply(cont, pre, natural, relative))
    }

    /// The initial scroll position of `el`'s container (or the
    /// viewport for `None`/root/body) from its
    /// `scroll-initial-target` descendant, against the same snap
    /// data [`snap_scroll`](Self::snap_scroll) evaluates. `None`
    /// when the container has no initial target (or no snap data):
    /// the caller then reports the recorded offset, `(0, 0)` for a
    /// never-written slot.
    pub(crate) fn initial_target_scroll(
        &mut self,
        host: &mut ScriptHost<'_, '_, '_>,
        el: Option<ScriptElement>,
    ) -> Option<(f32, f32)> {
        let data = self.snap_data(host)?;
        let node = el.and_then(|e| data.arena_node.get(&e.arena_index()).copied());
        let cont = match node {
            None => data.viewport.as_ref()?,
            Some(n) if Some(n) == data.root_node || Some(n) == data.body_node => {
                data.viewport.as_ref()?
            }
            Some(n) => data.by_node.get(&n)?,
        };
        // The initial position is a rest position: the container's
        // own snap selection applies to it exactly as it would to a
        // scroll landing there (a mandatory container can only rest
        // on a snap position — the production tree composes the same
        // way, seating before its resnap). Identity for non-snapping
        // containers.
        cont.initial_target
            .map(|t| parse_snap_apply(cont, cont.origin, t, false))
    }

    /// The snap data for the current tree state, cached per
    /// `mutation_count`. The data covers the whole tree, so every
    /// scroll target reuses the same entry.
    fn snap_data(&mut self, host: &mut ScriptHost<'_, '_, '_>) -> Option<Rc<ParseSnapData>> {
        let count = host.mutation_count();
        if let Some((_, data)) = self.snap_cache.iter().find(|(c, _)| *c == count) {
            return Some(Rc::clone(data));
        }
        let data = Rc::new(self.build_snap_data(host)?);
        if self.snap_cache.len() >= PARSE_LAYOUT_CACHE_ENTRIES {
            self.snap_cache.remove(0);
        }
        self.snap_cache.push((count, Rc::clone(&data)));
        Some(data)
    }

    /// One document-element-rooted rebuild and the per-container snap
    /// inputs: containers from the layout query (the document element
    /// and `<body>` propagate to the viewport, mirroring production
    /// `discover`), each container's snap areas with stop/reversal
    /// attached, and the viewport's scroll range from the document's
    /// scrollable overflow. Never more than the parsed-so-far tree.
    fn build_snap_data(&mut self, host: &mut ScriptHost<'_, '_, '_>) -> Option<ParseSnapData> {
        let root_el = host.document_element()?;
        let mut rec = SnapshotRecorder::new();
        let order = host.snapshot_document(&mut rec);
        let mut arena_ord: HashMap<usize, usize> = HashMap::with_capacity(order.len());
        for (ord, arena) in order.iter().enumerate() {
            arena_ord.insert(*arena, ord);
        }
        let sheets: Vec<Stylesheet> = self.harvested_sheets(&rec);
        let sheet_refs: Vec<&Stylesheet> = sheets.iter().collect();
        let viewport = (self.viewport.0 as f32, self.viewport.1 as f32);
        let quirks = host.quirks_mode();
        let (doc, tree, node_arena) = self.rebuild_tree(
            &rec,
            &order,
            &arena_ord,
            &sheet_refs,
            viewport,
            root_el,
            false,
            quirks,
        )?;
        self.passes += 1;
        let arena_node: HashMap<usize, NodeId> = node_arena.iter().map(|(&n, &a)| (a, n)).collect();
        let root_node = doc.document_element();
        let body_node = doc.get_elements_by_tag_name("body").item(0);
        let infos = scroll_containers_with_offset(&tree, (0.0, 0.0));
        // The document element and `<body>` propagate to the viewport
        // (their `overflow` becomes the viewport's): they are not
        // nested containers.
        let container_nodes: HashSet<NodeId> = infos
            .iter()
            .filter_map(|c| c.node)
            .filter(|n| Some(*n) != root_node && Some(*n) != body_node)
            .collect();
        let mut by_node = HashMap::new();
        for c in &infos {
            let Some(node) = c.node else { continue };
            if !container_nodes.contains(&node) {
                continue;
            }
            let style = parse_find_box(&tree, node).and_then(|b| b.style.as_deref());
            let padding = parse_scroll_padding_abs(style, c.scrollport.w, c.scrollport.h);
            by_node.insert(
                node,
                ParseSnapContainer {
                    scrollport: c.scrollport,
                    origin: c.scroll_origin,
                    max: c.max,
                    snap_type: style
                        .map(|s| s.scroll_snap_type())
                        .unwrap_or(SnapType::None),
                    padding,
                    areas: parse_snap_areas(&tree, node, &container_nodes, &doc),
                    initial_target: parse_initial_target(
                        &tree,
                        node,
                        &container_nodes,
                        c.scrollport,
                        padding,
                        c.scroll_origin,
                        c.max,
                    ),
                },
            );
        }
        let viewport_cont = root_node.map(|rn| {
            let rstyle = parse_find_box(&tree, rn).and_then(|b| b.style.as_deref());
            let bstyle = body_node
                .and_then(|bn| parse_find_box(&tree, bn))
                .and_then(|b| b.style.as_deref());
            let mut st = rstyle
                .map(|s| s.scroll_snap_type())
                .unwrap_or(SnapType::None);
            if st == SnapType::None {
                st = bstyle
                    .map(|s| s.scroll_snap_type())
                    .unwrap_or(SnapType::None);
            }
            let (origin, max) = parse_document_extents(&tree, &container_nodes, viewport);
            let padding = parse_scroll_padding_abs(rstyle, viewport.0, viewport.1);
            let scrollport = Rect {
                x: 0.0,
                y: 0.0,
                w: viewport.0,
                h: viewport.1,
            };
            ParseSnapContainer {
                scrollport,
                origin,
                max,
                snap_type: st,
                padding,
                areas: parse_snap_areas(&tree, rn, &container_nodes, &doc),
                initial_target: parse_initial_target(
                    &tree,
                    rn,
                    &container_nodes,
                    scrollport,
                    padding,
                    origin,
                    max,
                ),
            }
        });
        Some(ParseSnapData {
            by_node,
            viewport: viewport_cont,
            root_node,
            body_node,
            arena_node,
        })
    }

    /// The computed style of `el` as serialized property strings (the
    /// parse shim's `getComputedStyle`): the element is located in the
    /// whole-tree rebuild for the current `mutation_count` and styled
    /// with the real cascade (`compute_style` over the harvested
    /// author sheets plus the UA sheet), so stylesheet rules,
    /// inheritance, and the table presentational hints all reach the
    /// result — the old inline-style-only shim could serve none of
    /// them. `None` when the element is not in the rebuilt tree
    /// (detached, inside `<template>` contents, or no document
    /// element yet): the caller falls back to the inline-only path.
    pub(crate) fn computed_props(
        &mut self,
        host: &mut ScriptHost<'_, '_, '_>,
        el: ScriptElement,
    ) -> Option<HashMap<String, String>> {
        let data = self.style_data(host)?;
        let node = *data.arena_node.get(&el.arena_index())?;
        let sheet_refs: Vec<&Stylesheet> = data.sheets.iter().collect();
        let viewport = Viewport {
            w: self.viewport.0 as f32,
            h: self.viewport.1 as f32,
        };
        let computed = compute_style(
            &data.doc,
            node,
            &sheet_refs,
            parse_ua_stylesheet(),
            &viewport,
        );
        let font_px = computed_font_px_of(&computed);
        let root_px = match data.doc.document_element() {
            Some(r) if r != node => computed_font_px_of(&compute_style(
                &data.doc,
                r,
                &sheet_refs,
                parse_ua_stylesheet(),
                &viewport,
            )),
            _ => font_px,
        };
        let mut props: HashMap<String, String> = HashMap::new();
        for (prop, initial, _inherited) in PARSE_COMPUTED_PROPS {
            if computed_shorthand_longhands(prop).is_some() {
                continue; // synthesized from the longhands below
            }
            let val = match computed.get(prop) {
                Some(v) => cssom_computed_value(prop, v),
                None => initial.to_string(),
            };
            props.insert(prop.to_string(), val);
        }
        // `overflow` serializes from its axes, like the production
        // surface (the slot itself holds only a bare keyword).
        if let (Some(x), Some(y)) = (computed.get("overflow-x"), computed.get("overflow-y")) {
            let xs = css_value_to_string(x);
            let ys = css_value_to_string(y);
            props.insert(
                "overflow".to_string(),
                if xs == ys { xs } else { format!("{xs} {ys}") },
            );
        }
        let ctx = ComputedAdjustCtx {
            font_px,
            root_px,
            vw: viewport.w,
            vh: viewport.h,
        };
        adjust_computed_props(&mut props, &ctx);
        // The specified inline `border-spacing` (the rebuilt doc
        // carries the element's `style` attribute) feeds the math
        // re-resolution: see `reresolve_math_border_spacing`.
        // `data.doc` is owned by `data` (alive past this call), so the
        // attribute `&str` needs no intermediate `String`.
        let style_attr = data.doc.get_attribute(node, "style");
        reresolve_math_border_spacing(&mut props, style_attr, &ctx);
        synthesize_border_shorthands(&mut props);
        // Every other computed shorthand serializes from its
        // (adjusted) longhands through the shared helper (w78fix
        // H1): the scroll family, the box family, `gap`, `border`,
        // `font`, and `flex`. The helper runs again at the end of
        // this function, after the percentage/auto margin resolution
        // below mutates the `margin-*` longhands.
        synthesize_computed_shorthands(&mut props);
        // Used-value resolution for `height`/`width`: a computed `auto`
        // resolves to the used content-box dimension (CSSOM resolved
        // values). `ensure_layout` flushes the partial layout after any
        // dynamic style change — the pass cache is keyed by mutation
        // count, so the measured border box is current — and fails
        // closed (`None`) when the element has no box (`display: none` /
        // `display: contents`), leaving the computed `auto` in place.
        // The partial layout runs no JS, so nothing re-enters
        // `PARSE_HOSTS` while the entry borrow is held (the same shape
        // as the geometry getters). Percentage padding has no
        // containing-block width on this path and resolves to 0, like
        // the shim's other relative units.
        let auto_h = props.get("height").is_some_and(|h| h == "auto");
        let auto_w = props.get("width").is_some_and(|w| w == "auto");
        if (auto_h || auto_w)
            && display_takes_box_dims(computed.get("display"))
            && let Some(geom) = self.ensure_layout(host, el)
        {
            // Padding sides, resolved before the inserts below borrow
            // `props` mutably.
            let pad = |prop: &str| {
                used_padding_px(
                    props.get(prop).map(String::as_str).unwrap_or("0px"),
                    &ctx,
                    0.0,
                )
            };
            let (pad_top, pad_bottom) = (pad("padding-top"), pad("padding-bottom"));
            let (pad_left, pad_right) = (pad("padding-left"), pad("padding-right"));
            if auto_h {
                let used_h =
                    (geom.rect.h - geom.borders[0] - geom.borders[2] - pad_top - pad_bottom)
                        .max(0.0);
                props.insert("height".to_string(), format!("{used_h}px"));
            }
            if auto_w {
                let used_w =
                    (geom.rect.w - geom.borders[1] - geom.borders[3] - pad_left - pad_right)
                        .max(0.0);
                props.insert("width".to_string(), format!("{used_w}px"));
            }
        }
        // Used-value resolution for `margin-*`: percentage margins
        // resolve against a base, and `auto` block margins of an
        // orthogonal caption distribute like the production
        // `used_auto_block_margins_orthogonal_caption` — the shim
        // has no `LayoutBox`/ancestor chain, so both are driven by
        // `ensure_layout` geometry instead (the task's (a)): the
        // table's box gives the span, the caption's box the extent.
        // The percentage base is the table's inline size for an
        // orthogonal caption (the table content box along physical
        // y, mirroring layout's `pct_base`), the containing-block
        // width for an ordinary box (the parent content width).
        // Parent padding resolves fully here (see the block below):
        // percentages against the parent's containing-block width
        // (the grandparent content width when it is computable, the
        // parent padding-box width otherwise), `em` against the
        // parent's computed font size, `rem`/viewport units against
        // `ctx` — so a non-px parent padding no longer reads as 0
        // and overstates the base. The one approximation left: when
        // the grandparent itself carries percentage padding, its
        // content width uses its padding-box width as the base
        // (production's approximation), so the error in this base is
        // at most the parent's percentage times the grandparent's
        // percentage-padding error; with no percentage padding
        // anywhere above, the base is exact. Ordinary `auto`
        // margins are left alone: their production resolution needs
        // the parent content-box offsets, which the partial pass's
        // per-subtree frames do not share. Any missing piece (no
        // parent, no parent computed style, no geometry) fails
        // closed, leaving the serialized `auto`/`%` value in place.
        let margin_sides = ["margin-top", "margin-right", "margin-bottom", "margin-left"];
        let margin_needs = margin_sides.iter().any(|p| {
            props.get(*p).is_some_and(|v| {
                v == "auto" || v.trim_end().ends_with('%') || v.trim_start().starts_with("calc(")
            })
        });
        if margin_needs
            && let Some(chain) = ancestor_chain(host, el)
            && let Some(parent_el) = chain.get(1).copied()
            && let Some(parent_node) = data.arena_node.get(&parent_el.arena_index()).copied()
        {
            let parent_computed = compute_style(
                &data.doc,
                parent_node,
                &sheet_refs,
                parse_ua_stylesheet(),
                &viewport,
            );
            let kw = |s: &bowser_css::ComputedStyle, prop: &str, kw: &str| matches!(s.get(prop), Some(CssValue::Keyword(k)) if k.eq_ignore_ascii_case(kw));
            let is_orth = kw(&computed, "display", "table-caption")
                && kw(&computed, "writing-mode", "horizontal-tb")
                && (kw(&parent_computed, "display", "table")
                    || kw(&parent_computed, "display", "inline-table"))
                && (kw(&parent_computed, "writing-mode", "vertical-lr")
                    || kw(&parent_computed, "writing-mode", "vertical-rl"));
            if let (Some(geom), Some(parent_geom)) = (
                self.ensure_layout(&mut *host, el),
                self.ensure_layout(&mut *host, parent_el),
            ) {
                // Parent padding, resolved (see the margin comment
                // above): percentages against the parent's
                // containing-block width — the grandparent content
                // width when the grandparent's geometry and style
                // are available, else the parent padding-box width
                // (production's approximation). An abspos parent's
                // true containing block may sit further up the
                // tree; that case keeps the padding-box fallback
                // and its bounded error rather than a silent zero.
                let parent_pad_box =
                    (parent_geom.rect.w - parent_geom.borders[1] - parent_geom.borders[3]).max(0.0);
                let parent_font_px = computed_font_px_of(&parent_computed);
                let parent_pct_base = chain
                    .get(2)
                    .and_then(|&gp_el| {
                        let gp_node = data.arena_node.get(&gp_el.arena_index()).copied()?;
                        let gp_computed = compute_style(
                            &data.doc,
                            gp_node,
                            &sheet_refs,
                            parse_ua_stylesheet(),
                            &viewport,
                        );
                        let gp_geom = self.ensure_layout(&mut *host, gp_el)?;
                        let gp_pad_box =
                            (gp_geom.rect.w - gp_geom.borders[1] - gp_geom.borders[3]).max(0.0);
                        let gp_font_px = computed_font_px_of(&gp_computed);
                        let gp_pad = |prop: &str| {
                            resolve_pad_css_value(
                                gp_computed.get(prop),
                                gp_pad_box,
                                gp_font_px,
                                &ctx,
                            )
                        };
                        Some(
                            (gp_geom.rect.w
                                - gp_geom.borders[1]
                                - gp_geom.borders[3]
                                - gp_pad("padding-left")
                                - gp_pad("padding-right"))
                            .max(0.0),
                        )
                    })
                    .unwrap_or(parent_pad_box);
                let parent_pad = |prop: &str| {
                    resolve_pad_css_value(
                        parent_computed.get(prop),
                        parent_pct_base,
                        parent_font_px,
                        &ctx,
                    )
                };
                // Abspos orthogonal captions resolve against their
                // own containing block, not the table span — the
                // production `abspos_caption_cb_width` rule, adapted
                // to the shim's ancestor chain. The branch is on the
                // caption's OWN position (CSS 2.1 §10.1): a fixed
                // caption's block is the viewport, whatever
                // positioned ancestors intervene; an absolute
                // caption's is its nearest positioned ancestor's
                // content width, fixed ancestors included. An
                // ancestor without geometry is skipped outward: the
                // pass that produced this element's geometry
                // normally covers its ancestors too.
                let is_abspos =
                    kw(&computed, "position", "absolute") || kw(&computed, "position", "fixed");
                let abspos_base = if is_orth && is_abspos {
                    if kw(&computed, "position", "fixed") {
                        Some(self.viewport.0 as f32)
                    } else {
                        let mut found: Option<f32> = None;
                        for &anc_el in chain.iter().skip(1) {
                            let Some(anc_node) =
                                data.arena_node.get(&anc_el.arena_index()).copied()
                            else {
                                continue;
                            };
                            let anc_computed = compute_style(
                                &data.doc,
                                anc_node,
                                &sheet_refs,
                                parse_ua_stylesheet(),
                                &viewport,
                            );
                            if kw(&anc_computed, "position", "static") {
                                continue;
                            }
                            if let Some(anc_geom) = self.ensure_layout(&mut *host, anc_el) {
                                let pad_base =
                                    (anc_geom.rect.w - anc_geom.borders[1] - anc_geom.borders[3])
                                        .max(0.0);
                                let anc_font_px = computed_font_px_of(&anc_computed);
                                let pad = |prop: &str| {
                                    resolve_pad_css_value(
                                        anc_computed.get(prop),
                                        pad_base,
                                        anc_font_px,
                                        &ctx,
                                    )
                                };
                                found = Some(
                                    (anc_geom.rect.w
                                        - anc_geom.borders[1]
                                        - anc_geom.borders[3]
                                        - pad("padding-left")
                                        - pad("padding-right"))
                                    .max(0.0),
                                );
                                break;
                            }
                        }
                        Some(found.unwrap_or(self.viewport.0 as f32))
                    }
                } else {
                    None
                };
                let base = if let Some(b) = abspos_base {
                    b
                } else if is_orth {
                    (parent_geom.rect.h
                        - parent_geom.borders[0]
                        - parent_geom.borders[2]
                        - parent_pad("padding-top")
                        - parent_pad("padding-bottom"))
                    .max(0.0)
                } else {
                    (parent_geom.rect.w
                        - parent_geom.borders[1]
                        - parent_geom.borders[3]
                        - parent_pad("padding-left")
                        - parent_pad("padding-right"))
                    .max(0.0)
                };
                // Percentages first: the auto distribution below
                // reads the fixed side in px.
                for side in margin_sides {
                    if let Some(v) = props.get(side).cloned()
                        && let Some(px) = resolve_serialized_margin_px(&v, base, &ctx)
                    {
                        props.insert(side.to_string(), format!("{px}px"));
                    }
                }
                // Orthogonal-caption auto block margins: the
                // production gate, adapted — floated and out-of-flow
                // captions never reach the caption list, so their
                // `auto` stands.
                let in_flow = kw(&computed, "float", "none")
                    && (kw(&computed, "position", "static")
                        || kw(&computed, "position", "relative")
                        || kw(&computed, "position", "sticky"));
                if is_orth && in_flow {
                    let mt_auto = props.get("margin-top").is_some_and(|v| v == "auto");
                    let mb_auto = props.get("margin-bottom").is_some_and(|v| v == "auto");
                    if mt_auto || mb_auto {
                        let fixed_px = |side: &str| {
                            props
                                .get(side)
                                .and_then(|v| serialized_length_px(v, &ctx))
                                .unwrap_or(0.0)
                                .max(0.0)
                        };
                        let fixed = if mt_auto && mb_auto {
                            0.0
                        } else if mt_auto {
                            fixed_px("margin-bottom")
                        } else {
                            fixed_px("margin-top")
                        };
                        let free = (base - geom.rect.h - fixed).max(0.0);
                        if mt_auto && mb_auto {
                            props.insert("margin-top".to_string(), format!("{}px", free / 2.0));
                            props.insert("margin-bottom".to_string(), format!("{}px", free / 2.0));
                        } else if mt_auto {
                            props.insert("margin-top".to_string(), format!("{free}px"));
                        } else {
                            props.insert("margin-bottom".to_string(), format!("{free}px"));
                        }
                    }
                }
            }
        }
        // Re-synthesize after the margin resolution above: it
        // rewrote the `margin-*` longhands, so the `margin`
        // shorthand synthesized earlier would otherwise read stale.
        synthesize_computed_shorthands(&mut props);
        Some(props)
    }

    /// The style data for the current tree state, cached per
    /// `mutation_count` (see [`Self::snap_data`]'s caching shape).
    fn style_data(&mut self, host: &mut ScriptHost<'_, '_, '_>) -> Option<Rc<ParseStyleData>> {
        let count = host.mutation_count();
        if let Some((_, data)) = self.style_cache.iter().find(|(c, _)| *c == count) {
            return Some(Rc::clone(data));
        }
        let data = Rc::new(self.build_style_data(host)?);
        // `build_style_data`'s snapshot may have flushed buffered
        // text (bumping the count); key the entry by the post-build
        // count, exactly like the layout entries.
        let count = host.mutation_count();
        if self.style_cache.len() >= PARSE_LAYOUT_CACHE_ENTRIES {
            self.style_cache.remove(0);
        }
        self.style_cache.push((count, Rc::clone(&data)));
        Some(data)
    }

    /// One whole-tree rebuild for computed style: snapshot, replay
    /// the document element's subtree into a fresh [`Document`], and
    /// harvest the author stylesheets from the snapshot's `<style>`
    /// texts. No layout pass runs (computed style does not need
    /// boxes), so `passes` is untouched. The rebuilt document is
    /// stamped with the live parser quirks mode (see
    /// [`Self::rebuild_tree`]): without it `compute_style` would
    /// always see `NoQuirks` and quirks inheritance rules (e.g.
    /// §3.11 font-style at the table boundary) would never apply
    /// to mid-parse `getComputedStyle` reads.
    fn build_style_data(&mut self, host: &mut ScriptHost<'_, '_, '_>) -> Option<ParseStyleData> {
        let root_el = host.document_element()?;
        let mut rec = SnapshotRecorder::new();
        let order = host.snapshot_document(&mut rec);
        let mut arena_ord: HashMap<usize, usize> = HashMap::with_capacity(order.len());
        for (ord, arena) in order.iter().enumerate() {
            arena_ord.insert(*arena, ord);
        }
        let root_ord = *arena_ord.get(&root_el.arena_index())?;
        let (start, end) = rec.subtree_range(root_ord)?;
        let mut build = PartialDocBuilder::new();
        build.replay(&rec.events[start..=end], root_ord);
        let (mut doc, node_arena) = build.finish(&order);
        doc.set_quirks_mode(host.quirks_mode());
        let arena_node: HashMap<usize, NodeId> = node_arena.iter().map(|(&n, &a)| (a, n)).collect();
        let sheets: Vec<Stylesheet> = self.harvested_sheets(&rec);
        Some(ParseStyleData {
            doc,
            sheets,
            arena_node,
        })
    }

    /// The partial-layout root for `chain` from inline style alone: the
    /// element's containing block. The nearest ancestor with a
    /// non-static inline `position` (the classic
    /// `el.style.position = "relative"` forced-layout setup), else the
    /// parent element — the CSS containing block for the static case —
    /// else the element itself. `position: fixed` roots at the element:
    /// its containing block is the viewport.
    ///
    /// Stylesheet `position` is deliberately invisible here: this feeds
    /// the cache key, so it must stay snapshot-free. The
    /// stylesheet-aware post-pass ([`Self::stylesheet_widened_root`])
    /// widens the root after the snapshot, when the rules are known.
    ///
    /// Table widening: a `tr`/`td` read would otherwise rebuild only the
    /// row/row-group subtree, dropping the table element — and with it
    /// the table-level rules (`table { border-collapse: … }`) and the
    /// full grid `visibility: collapse` redistribution needs. When the
    /// nearest enclosing `<table>` sits above the provisional root, the
    /// pass is rooted at the table instead: tables are bounded, and the
    /// pass then agrees with the full layout for the whole grid.
    fn select_partial_root(
        host: &ScriptHost<'_, '_, '_>,
        chain: &[ScriptElement],
    ) -> ScriptElement {
        let el = chain[0];
        // Fixed: the containing block is the viewport, which only a
        // document-rooted pass has. An element-rooted pass lays the
        // element out as the rebuilt document's root at (0, 0),
        // discarding its left/top (and right/bottom) offsets entirely
        // — static and dynamic fixed alike read (0, 0) (WPT
        // `position-absolute-dynamic-formatting-context`: the fixed
        // box "stays in-flow"). Root at the document element so the
        // fixed box lays out against the real initial containing
        // block.
        if inline_position(host, el).as_deref() == Some("fixed") {
            return chain.last().copied().unwrap_or(el);
        }
        let mut root_idx = if chain.len() > 1 { 1 } else { 0 };
        for (i, &h) in chain.iter().enumerate().skip(1) {
            if let Some(pos) = inline_position(host, h)
                && pos != "static"
            {
                root_idx = i;
                break;
            }
        }
        // Sticky widening: the sticky constraint bakes against the
        // nearest scroll container's box and its recorded offset. A
        // pass rooted below that container has neither — the
        // container's node is not in the rebuilt subtree, so its
        // recorded offset has no node to attach to and the constraint
        // falls back to the viewport. When the measured element or
        // any ancestor up to the provisional root is sticky, root the
        // pass at the document element so every scroll container is
        // present and the bake matches the full-document layout.
        let last = root_idx.min(chain.len().saturating_sub(1));
        if chain[..=last]
            .iter()
            .any(|&h| inline_position(host, h).as_deref() == Some("sticky"))
        {
            return chain.last().copied().unwrap_or(el);
        }
        if root_idx > 0 {
            for &h in chain.iter().skip(root_idx + 1) {
                if host.tag_name(h).as_deref() == Some("table") {
                    return h;
                }
            }
        }
        chain[root_idx]
    }

    /// Finding-2 post-pass: the root to re-run the partial layout with,
    /// or `None` when the provisional root already covers the true
    /// containing block.
    ///
    /// The provisional root only sees inline `position`. When the
    /// measured element is out-of-flow (absolute/fixed, from inline or
    /// author style) yet the partial tree produced no offset parent for
    /// it — no positioned ancestor and no `body` in the subtree — the
    /// true containing block sits above the provisional root: re-run
    /// from the document element so percentage insets and
    /// `offsetParent` resolve against the right box. Stylesheet
    /// `position: fixed` on the element itself re-roots at the element
    /// (viewport containing block), mirroring the inline-`fixed` rule
    /// in [`Self::select_partial_root`].
    ///
    /// The same widening applies to in-flow elements (static, relative,
    /// sticky, or no `position` declared at all): CSSOM View gives such
    /// an element the nearest positioned ancestor as its offset parent,
    /// falling back to `body` — never `null` — but a pass rooted at a
    /// static parent subtree contains neither, so `offsetParent` came
    /// back `null` and `offsetLeft`/`offsetTop` froze at the subtree's
    /// local coordinates (WPT `css-overflow/scrollbar-gutter-*`: a
    /// plain static `.content` child read `offsetLeft` 10 in every
    /// container). Re-running from the document element puts the real
    /// ancestor chain — positioned ancestors and the `body` fallback —
    /// inside the tree.
    fn stylesheet_widened_root(
        &self,
        host: &ScriptHost<'_, '_, '_>,
        rebuilt: &PartialRebuild<'_>,
        chain: &[ScriptElement],
        root: ScriptElement,
    ) -> Option<ScriptElement> {
        let el = chain[0];
        // No entry means `display: none` (nothing to widen); `body`
        // already reports a null offsetParent correctly; any offset
        // parent found inside the subtree is exactly right (a
        // positioned ancestor nearer than the true containing block is
        // impossible), so only the missing-parent case can widen.
        let bx = self.boxes.get(&el.arena_index())?;
        if bx.is_body || bx.offset_parent_arena.is_some() {
            return None;
        }
        // Effective `position`: inline style beats normal author rules,
        // author `!important` beats inline. Stylesheet matching needs
        // the rebuilt document, so it only runs when inline style left
        // the question open and some rule actually declares `position`.
        // `None` means no `position` is declared anywhere: the element
        // is static, which the widening below treats like any other
        // in-flow value.
        let inline = inline_position(host, el);
        let eff: Option<String> = match inline {
            Some(pos) if pos == "fixed" => return None, // already rooted at the element
            Some(pos) => match Self::author_position(rebuilt, el) {
                Some((v, true)) => Some(v),
                _ => Some(pos),
            },
            None => {
                let any_position_rule = rebuilt.sheets.iter().any(|s| {
                    s.rules()
                        .iter()
                        .flat_map(|r| r.declarations.iter())
                        .any(|d| d.property.as_str() == "position")
                });
                if !any_position_rule {
                    None
                } else {
                    Self::author_position(rebuilt, el).map(|(v, _)| v)
                }
            }
        };
        match eff.as_deref() {
            // Fixed: only a document-rooted pass lays the box against
            // the viewport containing block (see `select_partial_root`).
            // Widen to the document element, never back to the element
            // itself: an element-rooted pass discards its offsets.
            Some("fixed") => {
                let wide = chain.last().copied().unwrap_or(el);
                (wide.arena_index() != root.arena_index()).then_some(wide)
            }
            Some("absolute") => {
                let wide = chain.last().copied().unwrap_or(el);
                (wide.arena_index() != root.arena_index()).then_some(wide)
            }
            // In-flow (static / relative / sticky / undeclared): the
            // offset parent — a positioned ancestor above the pass
            // root, or the `body` fallback — is only visible in a
            // document-wide pass.
            _ => {
                let wide = chain.last().copied().unwrap_or(el);
                (wide.arena_index() != root.arena_index()).then_some(wide)
            }
        }
    }

    /// Specified `position` for `el` from harvested author rules only
    /// (inline style and UA are the caller's business): the winning
    /// declaration's value and whether it is `!important`. Rules apply
    /// in source order across stylesheets; a rule applies when one of
    /// its selectors matches the element's rebuilt node
    /// ([`bowser_css::matches`]) and its `@media` (if any) matches the
    /// partial-layout viewport. `!important` declarations beat normal
    /// ones; within a level the last declaration wins.
    fn author_position(rebuilt: &PartialRebuild<'_>, el: ScriptElement) -> Option<(String, bool)> {
        let nid = rebuilt
            .node_arena
            .iter()
            .find(|&(_, &arena)| arena == el.arena_index())
            .map(|(&nid, _)| nid)?;
        let mut win: Option<(String, bool)> = None;
        for sheet in rebuilt.sheets {
            for rule in sheet.rules() {
                if let Some(mq) = &rule.media
                    && !mq.matches(rebuilt.viewport.0, rebuilt.viewport.1)
                {
                    continue;
                }
                if !rule
                    .selectors
                    .iter()
                    .any(|s| bowser_css::matches(s, rebuilt.doc, nid))
                {
                    continue;
                }
                for decl in &rule.declarations {
                    if decl.property.as_str() != "position" {
                        continue;
                    }
                    let CssValue::Keyword(k) = &decl.value else {
                        continue;
                    };
                    let v = k.to_ascii_lowercase();
                    if !matches!(
                        v.as_str(),
                        "static" | "relative" | "absolute" | "fixed" | "sticky"
                    ) {
                        continue;
                    }
                    // A normal declaration cannot displace an
                    // `!important` winner; otherwise last wins.
                    let dominated = matches!(win, Some((_, true))) && !decl.important;
                    if !dominated {
                        win = Some((v, decl.important));
                    }
                }
            }
        }
        win
    }

    /// Walk the partial layout tree, measuring every element box with
    /// `table_box_geometry` and recording scroll extents for the
    /// `scrollWidth`/`scrollHeight` getters. Iterative: layout trees
    /// can be arbitrarily deep.
    ///
    /// The scroll extents are transform-aware, mirroring the layout
    /// crate's `scrollable_extent` (CSS Overflow 3 §3: the scrollable
    /// overflow region is built from descendants' border boxes *after*
    /// applying their transforms). Like that query, each element's
    /// extent is measured in the element's OWN frame: the accumulated
    /// transform for a descendant starts at the scroller element's
    /// border-box origin (`translate(rect.x, rect.y)`) WITHOUT the
    /// scroller's own local transform, and descendant transforms
    /// compose relative to the scroller from there (see
    /// [`subtree_child_accumulated_transform`]). The scroller's own
    /// transform and every ancestor's transform therefore never enter
    /// its `scrollWidth`/`scrollHeight`: a scroller translated by its
    /// own `transform: translateX(100px)` reports the same extents as
    /// untransformed, and an ancestor's `scale(2)` does not double
    /// them. (The previous single global accumulation was rooted at
    /// the partial tree's root and included the element's own and its
    /// ancestors' transforms, while the padding-box origin subtracted
    /// below stayed untransformed — inflating exactly those cases.)
    /// With no transforms anywhere the accumulated matrices are pure
    /// translations and the walk reduces to exactly the untransformed
    /// rect union, the identity case keeping the direct-rect fast
    /// path.
    ///
    /// Cost: the per-scroller walk is O(subtree) per measured element,
    /// so a whole pass is O(N * subtree) worst case (a deep chain).
    /// That mirrors the layout crate, which also walks each scroll
    /// container's subtree separately; the partial trees measured
    /// here are the parsed-so-far tree, bounded in practice.
    fn measure_subtree<'t>(
        &mut self,
        doc: &Document,
        tree: &'t LayoutBox,
        node_arena: &HashMap<NodeId, usize>,
    ) {
        /// One measured box: its layout box and parent frame, for the
        /// per-scroller extent walks after the measuring pass.
        struct Frame<'t> {
            bx: &'t LayoutBox,
            rect: Rect,
        }
        let mut frames: Vec<Frame<'t>> = Vec::new();
        let mut arena_frame: HashMap<usize, usize> = HashMap::new();
        let mut ancestors: Vec<&LayoutBox> = Vec::new();
        // `(box, exiting)`: the marker pops the ancestor the matching
        // enter pushed, keeping `ancestors` exactly the current chain.
        let mut stack: Vec<(&LayoutBox, bool)> = vec![(tree, false)];
        // Tag-name predicates for the layout geometry API (see
        // `measure_node_geometry`): `table_box_geometry` takes them by
        // value and closures are not `Copy`, so each measured element
        // builds a fresh pair.
        let preds = || {
            (
                |bx: &LayoutBox| is_body_box(doc, bx),
                |bx: &LayoutBox| is_table_part_box(doc, bx),
            )
        };
        while let Some((bx, exiting)) = stack.pop() {
            if exiting {
                ancestors.pop();
                continue;
            }
            let fi = frames.len();
            frames.push(Frame { bx, rect: bx.rect });
            if let Some(nid) = bx.node
                && let Some(&arena) = node_arena.get(&nid)
            {
                // First box wins: an element's principal box carries
                // its node; split inline fragments share it.
                if let Entry::Vacant(vac) = self.boxes.entry(arena) {
                    let (is_body, is_table_part) = preds();
                    let geom = table_box_geometry(bx, &ancestors, is_body, is_table_part);
                    let (is_body, is_table_part) = preds();
                    let offset_parent_arena =
                        table_offset_parent(bx, &ancestors, is_body, is_table_part)
                            .and_then(|op| op.node)
                            .and_then(|op_nid| node_arena.get(&op_nid).copied());
                    let (is_body, _) = preds();
                    // Same used borders layout subtracts for clientWidth/
                    // clientHeight above: one shared computation, so the
                    // two geometry families cannot disagree.
                    let borders = box_used_borders(bx, &ancestors);
                    // Cell-less table phantom: the table engine stamps
                    // per-dimension flags (`LayoutBox::phantom_w` /
                    // `phantom_h`, see `table_sized_by_phantom`); the
                    // shim reads them directly. A truly childless table
                    // never reaches the engine, so the minimal fallback
                    // covers its width (see `childless_table_phantom`).
                    let phantom_w =
                        bx.phantom_w || childless_table_phantom(bx, borders[1] + borders[3]);
                    vac.insert(ParseMeasuredBox {
                        geom,
                        rect: bx.rect,
                        // Filled by the per-scroller extent walks below.
                        scroll_w: 0.0,
                        scroll_h: 0.0,
                        borders,
                        is_body: is_body(bx),
                        offset_parent_arena,
                        custom_inline: is_unresolved_custom_element(doc, bx),
                        phantom_w,
                        phantom_h: bx.phantom_h,
                    });
                    arena_frame.insert(arena, fi);
                }
            }
            stack.push((bx, true));
            ancestors.push(bx);
            for child in bx.children.iter().rev() {
                stack.push((child, false));
            }
        }
        // Nested scroll containers (layout's `scroll_containers`
        // candidates, same `node` + `overflow_axes` gate): an extent
        // walk folds a nested scroller's own box into the union but
        // never descends into its subtree — its overflowing content is
        // clipped by its own scrollport and cannot extend an outer
        // scroller's range. The set is complete before any walk runs,
        // mirroring `scroll_containers`' deepest-first confirmation, so
        // every walk sees every deeper container exactly as layout's
        // `scrollable_extent` `skip` set does.
        let scroll_skip: HashSet<*const LayoutBox> = frames
            .iter()
            .filter_map(|f| {
                let style = f.bx.style.as_ref()?;
                f.bx.node?;
                let (axes, _) = overflow_axes(style);
                (axes.0 || axes.1).then_some(f.bx as *const LayoutBox)
            })
            .collect();
        // Scroll extents: one walk per measured element, in that
        // element's own frame (see the method docs). The walk seeds
        // from the element's own untransformed border box and folds in
        // every descendant's transformed border box: a descendant's
        // accumulated transform is its chain of layout offsets and
        // local transforms composed starting at the scroller's
        // border-box origin — the scroller's own local transform is
        // never composed in, and no ancestor above the scroller is
        // visited at all.
        //
        // Three containing-block/edge filters mirror the layout crate's
        // `scrollable_extent` (pinned there by
        // `scrollable_extent_still_skips_viewport_anchored_fixed` and
        // `scrollable_extent_fixed_under_scroller_itself_does_not_extend`):
        // a `position: fixed` descendant whose containing block is the
        // initial containing block — or the scroller itself — is
        // anchored to a frame that never scrolls with this element, so
        // neither it nor its subtree extends the extent. Only a
        // fixed-CB trigger (transform/filter/…) strictly *below* the
        // scroller turns a fixed descendant into scrolling content.
        // Likewise, an absolutely positioned descendant whose
        // containing block lies outside the scroller does not scroll
        // with it: the walk tracks whether the containing block is
        // inside (seeded from the scroller's own positioned-ness), and
        // a positioned box — or a fixed-CB trigger — below the scroller
        // starts a new containing block inside it.
        // The walk skips the *self* contribution of a split-inline
        // wrapper (a `BoxType::Block` box whose element's computed
        // `display` is `inline`): layout generates that box as the
        // flow container for a block-level child of an inline element,
        // and its rect is the child's *unshifted* flow footprint — the
        // element's real (fragmented) boxes carry no such border box,
        // so folding it in would report the unshifted extent of a
        // relatively positioned child instead of its shifted content
        // (WPT `scrollable-overflow-relative-positioned-block-in-inline`:
        // 704 instead of 404). Its children still walk and contribute.
        // The wrapper's own border/padding spill is real, though: the
        // wrapper lays out with its full style, so its border-box edges
        // spill past the child's unshifted footprint (its content box)
        // by the border+padding insets on each side, and that ring
        // paints and must be reachable by scrolling. Only the wrapper
        // edges on sides with a nonzero inset contribute — with no
        // border/padding on a side, the wrapper's edge on that side
        // *is* the unshifted footprint edge and stays skipped,
        // preserving the 704-vs-404 behavior above (mirror of layout's
        // `split_inline_spill_insets` + the spill arm of
        // `scrollable_extent`).
        // The walk skips the *subtrees* of nested scroll containers
        // (`scroll_skip`): a nested scroller's own box contributes, but
        // its overflowing content is clipped by its own scrollport and
        // never extends an outer scroller's range (mirror of layout's
        // `scrollable_extent` `skip` set, populated deepest-first).
        for (&arena, &fi) in &arena_frame {
            let f = &frames[fi];
            // Shared with the production `scrollWidth`/`scrollHeight`
            // getters: the same fold over the same nested-scroller skip
            // set, so shim and production agree by construction.
            let (min_l, _min_t, max_r, max_b) = scrollable_extent_in_frame(f.bx, &scroll_skip);
            if let Some(bx) = self.boxes.get_mut(&arena) {
                // Scroll sizes are padding-box relative: the farthest
                // content edge minus the padding-box origin, at least
                // the client size. The frame's own border box
                // contributes exactly the client size (its far edge
                // minus both borders on the axis). Both the far edges
                // above and this origin are in the scroller's own
                // frame, so they cancel exactly. In RTL the range runs
                // leftward instead: the padding-box's right edge back
                // to the nearest content edge (mirrors the production
                // finalize in `node_scroll_size`).
                let pad_l = f.rect.x + bx.borders[3];
                let pad_t = f.rect.y + bx.borders[0];
                let rtl =
                    f.bx.style
                        .as_ref()
                        .and_then(|s| s.get_str("direction"))
                        .is_some_and(|d| d.eq_ignore_ascii_case("rtl"));
                bx.scroll_w = if rtl {
                    let pad_r = f.rect.x + f.rect.w - bx.borders[1];
                    bx.geom.client_width.max((pad_r - min_l).max(0.0))
                } else {
                    bx.geom
                        .client_width
                        .max((max_r - pad_l - bx.borders[1]).max(0.0))
                };
                bx.scroll_h = bx
                    .geom
                    .client_height
                    .max((max_b - pad_t - bx.borders[2]).max(0.0));
            }
        }
    }
}

/// The box's own `transform` evaluated to a 2D matrix in the box's
/// local frame (origin at its border-box top-left), pivoted around
/// `transform-origin` — the same evaluation the layout crate's
/// `scrollable_extent` fold and paint's transform group use, with the
/// border box as the reference box. `None` when the property is
/// absent/`none`, or when it cannot be evaluated with absolute-length
/// resolution (an `em`-based `translate()`, say): such a box counts as
/// untransformed in the scroll-extent union, just like it renders
/// untransformed.
fn subtree_box_local_transform(bx: &LayoutBox) -> Option<bowser_css::TransformMatrix> {
    let style = bx.style.as_ref()?;
    if !has_non_none_transform(style) {
        return None;
    }
    let transform = style.get_by_index(bowser_css::props::TRANSFORM)?;
    let origin = style
        .get_by_index(bowser_css::props::TRANSFORM_ORIGIN)
        .and_then(bowser_css::TransformOrigin::parse)
        .unwrap_or_else(bowser_css::TransformOrigin::initial);
    let ctx = bowser_css::TransformContext {
        reference_width: bx.rect.w.max(0.0),
        reference_height: bx.rect.h.max(0.0),
        resolve_length: &bowser_css::resolve_absolute_length,
    };
    let m = bowser_css::evaluate_transform(transform, &origin, &ctx)?;
    [m.a, m.b, m.c, m.d, m.e, m.f]
        .iter()
        .all(|v| v.is_finite())
        .then_some(m)
}

/// The accumulated transform mapping `child`'s local coordinates
/// (origin at its border-box top-left) into the scroll-extent frame
/// the union measures in, given `parent_acc` (the accumulated
/// transform of `parent` in that same frame). The frame is rooted at
/// whichever scroller the extent walk started from (see
/// `measure_subtree`): when `parent` IS that scroller, `parent_acc`
/// is the bare translation to its border-box origin, so the
/// scroller's own local transform never enters. A point of the child
/// sits in the parent's local frame at the child's layout offset
/// within the parent, transformed by the child's own `transform`
/// first (CSS Transforms 1 §8: the rightmost, innermost transform
/// applies first). Boxes without an evaluable `transform` contribute
/// the identity local matrix, so the accumulation degrades to plain
/// translations — exactly the untransformed fold.
fn subtree_child_accumulated_transform(
    parent_acc: &bowser_css::TransformMatrix,
    parent: &LayoutBox,
    child: &LayoutBox,
) -> bowser_css::TransformMatrix {
    let local =
        subtree_box_local_transform(child).unwrap_or_else(bowser_css::TransformMatrix::identity);
    parent_acc
        .mul(&bowser_css::TransformMatrix::translate(
            child.rect.x - parent.rect.x,
            child.rect.y - parent.rect.y,
        ))
        .mul(&local)
}

/// Scrollable overflow extent of one element's subtree, measured in the
/// element's own frame: the nearest content edges `(min_l, min_t)` and
/// the farthest content edges `(max_r, max_b)`. The caller turns them
/// into `scrollWidth`/`scrollHeight` with the padding-box origin and the
/// scroller's `direction` (see the finalizes at the end of
/// [`measure_subtree`] and in [`node_scroll_size`]): LTR sizes grow from
/// the padding-box origin to the far edges, RTL `scrollWidth` from the
/// padding-box's right edge back to the nearest content edge.
///
/// Shared by the parse shim's mid-parse measurement and the production
/// `Element.scrollWidth`/`scrollHeight` getters, so the two agree by
/// construction. The fold mirrors the layout crate's
/// `scrollable_extent` (CSS Overflow 3 §3: the scrollable overflow
/// region is built from descendants' border boxes *after* applying
/// their transforms): it seeds from the scroller's own untransformed
/// border box — the scroller's own local transform and every
/// ancestor's transform never enter — and composes each descendant's
/// accumulated transform from there (see
/// [`subtree_child_accumulated_transform`]).
///
/// Three containing-block/edge filters mirror the layout crate
/// (pinned there by `scrollable_extent_still_skips_viewport_anchored_fixed`
/// and `scrollable_extent_fixed_under_scroller_itself_does_not_extend`):
/// a `position: fixed` descendant whose containing block is the initial
/// containing block — or the scroller itself — is anchored to a frame
/// that never scrolls with this element, so neither it nor its subtree
/// extends the extent (only a fixed-CB trigger strictly *below* the
/// scroller turns a fixed descendant into scrolling content); an
/// absolutely positioned descendant whose containing block lies outside
/// the scroller does not scroll with it either (the walk tracks whether
/// the containing block is inside, seeded from the scroller's own
/// positioned-ness). The *self* contribution of a split-inline wrapper
/// (a `BoxType::Block` box whose computed `display` is `inline`) is
/// skipped — its rect is the child's unshifted flow footprint — but its
/// border/padding spill edges still contribute (mirror of layout's
/// `split_inline_spill_insets`). Nested scroll containers (`skip`, the
/// same `overflow_axes` gate the shim and `scroll_containers` use)
/// fold their own box in but are never descended into: their
/// overflowing content is clipped by their own scrollport.
///
/// `skip` holds raw box pointers; that is fine in-process — the set is
/// built and consumed within a single call over an immutable tree.
fn scrollable_extent_in_frame(
    scroller: &LayoutBox,
    skip: &HashSet<*const LayoutBox>,
) -> (f32, f32, f32, f32) {
    let scroller_acc = bowser_css::TransformMatrix::translate(scroller.rect.x, scroller.rect.y);
    let mut min_l = scroller.rect.x;
    let mut min_t = scroller.rect.y;
    let mut max_r = scroller.rect.x + scroller.rect.w;
    let mut max_b = scroller.rect.y + scroller.rect.h;
    // `(box, accumulated transform, CB-inside, fixed-CB-inside)`: the
    // fixed flag starts false — a fixed-CB trigger on the scroller
    // itself anchors fixed descendants to the scrollport frame, which
    // does not scroll — and the CB flag starts from the scroller's own
    // positioned-ness: an abspos child of an unpositioned scroller takes
    // its containing block from outside and does not scroll with it.
    let scroller_positioned = scroller
        .style
        .as_ref()
        .map(|s| position_of(s))
        .unwrap_or(Position::Static)
        != Position::Static;
    let mut walk: Vec<(&LayoutBox, bowser_css::TransformMatrix, bool, bool)> = scroller
        .children
        .iter()
        .rev()
        .map(|c| {
            (
                c,
                subtree_child_accumulated_transform(&scroller_acc, scroller, c),
                scroller_positioned,
                false,
            )
        })
        .collect();
    while let Some((cbx, acc, cb_inside, fixed_cb_inside)) = walk.pop() {
        let pos = cbx
            .style
            .as_ref()
            .map(|s| position_of(s))
            .unwrap_or(Position::Static);
        if pos == Position::Fixed && !fixed_cb_inside {
            continue;
        }
        // Absolutely positioned against a containing block outside the
        // scroller: does not scroll with it either.
        if pos == Position::Absolute && !cb_inside {
            continue;
        }
        let split_inline_wrapper = cbx.box_type == BoxType::Block
            && cbx.style.as_ref().is_some_and(|s| {
                matches!(s.get("display"), Some(CssValue::Keyword(k)) if k.eq_ignore_ascii_case("inline"))
            });
        if split_inline_wrapper {
            // Only the border/padding spill edges past the child's
            // unshifted footprint (see `measure_subtree` docs): each
            // side's wrapper edge contributes only when that side has a
            // nonzero inset. This walk folds the near edges too (they
            // feed RTL `scrollWidth` via `min_l`/`min_t`), so all four
            // spill edges can move the union on their nonzero sides.
            let (spill_l, spill_t, spill_r, spill_b) = cbx
                .style
                .as_deref()
                .map(parse_split_inline_spill_insets)
                .unwrap_or((0.0, 0.0, 0.0, 0.0));
            if spill_l > 0.0 {
                if acc.is_identity() {
                    min_l = min_l.min(cbx.rect.x - spill_l);
                } else {
                    for (px, py) in [(-spill_l, 0.0), (-spill_l, cbx.rect.h)] {
                        let (tx, _) = acc.apply(px, py);
                        min_l = min_l.min(tx);
                    }
                }
            }
            if spill_t > 0.0 {
                if acc.is_identity() {
                    min_t = min_t.min(cbx.rect.y - spill_t);
                } else {
                    for (px, py) in [(0.0, -spill_t), (cbx.rect.w, -spill_t)] {
                        let (_, ty) = acc.apply(px, py);
                        min_t = min_t.min(ty);
                    }
                }
            }
            if spill_r > 0.0 {
                if acc.is_identity() {
                    max_r = max_r.max(cbx.rect.x + cbx.rect.w);
                } else {
                    for (px, py) in [(cbx.rect.w, 0.0), (cbx.rect.w, cbx.rect.h)] {
                        let (tx, _) = acc.apply(px, py);
                        max_r = max_r.max(tx);
                    }
                }
            }
            if spill_b > 0.0 {
                if acc.is_identity() {
                    max_b = max_b.max(cbx.rect.y + cbx.rect.h);
                } else {
                    for (px, py) in [(0.0, cbx.rect.h), (cbx.rect.w, cbx.rect.h)] {
                        let (_, ty) = acc.apply(px, py);
                        max_b = max_b.max(ty);
                    }
                }
            }
        } else if acc.is_identity() {
            min_l = min_l.min(cbx.rect.x);
            min_t = min_t.min(cbx.rect.y);
            max_r = max_r.max(cbx.rect.x + cbx.rect.w);
            max_b = max_b.max(cbx.rect.y + cbx.rect.h);
        } else {
            // The transformed border box is a parallelogram; its
            // bounding box is the bounding box of its four transformed
            // corners — this is where a `translate()`/`scale()`/`rotate()`
            // on the box or on an intermediate descendant of the scroller
            // moves the union.
            for (px, py) in [
                (0.0, 0.0),
                (cbx.rect.w, 0.0),
                (0.0, cbx.rect.h),
                (cbx.rect.w, cbx.rect.h),
            ] {
                let (tx, ty) = acc.apply(px, py);
                min_l = min_l.min(tx);
                min_t = min_t.min(ty);
                max_r = max_r.max(tx);
                max_b = max_b.max(ty);
            }
        }
        // A positioned box that scrolls with the scroller is itself a
        // containing block inside it; so is a box establishing a fixed
        // containing block (transform/filter/…), since absolute
        // descendants take their containing block from it; otherwise the
        // nearest such ancestor above is unchanged.
        let child_cb_inside = pos != Position::Static
            || cb_inside
            || cbx.style.as_ref().is_some_and(|s| establishes_fixed_cb(s));
        let child_fixed_cb_inside =
            fixed_cb_inside || cbx.style.as_ref().is_some_and(|s| establishes_fixed_cb(s));
        // A nested scroll container's subtree is clipped by its own
        // scrollport: its own box already contributed above, but its
        // children walk nothing into this scroller's extent (mirror of
        // `scrollable_extent`'s `skip` gate).
        if !skip.contains(&(cbx as *const LayoutBox)) {
            for child in cbx.children.iter().rev() {
                let gacc = subtree_child_accumulated_transform(&acc, cbx, child);
                walk.push((child, gacc, child_cb_inside, child_fixed_cb_inside));
            }
        }
    }
    (min_l, min_t, max_r, max_b)
}

/// `el` plus its ancestors, outermost last. `None` when the handle is
/// stale (wrong parse generation or out of range).
fn ancestor_chain(host: &ScriptHost<'_, '_, '_>, el: ScriptElement) -> Option<Vec<ScriptElement>> {
    // Validates the handle: `tag_name` fails closed on stale ones.
    host.tag_name(el)?;
    let mut chain = vec![el];
    while let Some(p) = host.parent_element(chain[chain.len() - 1]) {
        chain.push(p);
    }
    Some(chain)
}

/// Specified `position` from an element's inline `style` attribute.
/// Stylesheet rules are not consulted: the partial-layout root choice
/// only needs the script-set cases (the classic forced-layout pattern
/// sets `el.style.position` before reading).
fn inline_position(host: &ScriptHost<'_, '_, '_>, el: ScriptElement) -> Option<String> {
    for (name, value) in host.get_attributes(el) {
        if !name.eq_ignore_ascii_case("style") {
            continue;
        }
        for decl in value.split(';') {
            let (prop, val) = match decl.split_once(':') {
                Some(p) => p,
                None => continue,
            };
            if prop.trim().eq_ignore_ascii_case("position") {
                let v = val.trim().to_ascii_lowercase();
                let v = v.strip_suffix("!important").map(str::trim).unwrap_or(&v);
                return match v {
                    "static" | "relative" | "absolute" | "fixed" | "sticky" => Some(v.to_string()),
                    _ => None,
                };
            }
        }
    }
    None
}

/// Whether `bx` is the HTML `body` element's box.
fn is_body_box(doc: &Document, bx: &LayoutBox) -> bool {
    bx.node
        .is_some_and(|n| matches!(doc.kind(n), NodeKind::Element(e) if e.tag_name == "body"))
}

/// Whether `bx` is an HTML `td`/`th`/`table` part's box (CSSOM View's
/// retained static-element-inside-table rule).
fn is_table_part_box(doc: &Document, bx: &LayoutBox) -> bool {
    bx.node.is_some_and(|n| {
        matches!(doc.kind(n), NodeKind::Element(e) if ["td", "th", "table"].contains(&e.tag_name.as_str()))
    })
}

/// Whether `bx` is a custom element (hyphenated tag: `x-table`,
/// `my-widget`) the partial pass left at the initial `display: inline`:
/// no UA rule, harvested author rule, or inline style assigns it a
/// display, so its used display would be decided by a stylesheet
/// the pass could not harvest (a `<link>` sheet that failed to
/// load, or none) and any geometry derived through it is fiction.
/// Real elements never trip this: the UA sheet gives every known
/// tag a display, and an author rule the pass can see (`<style>`,
/// `<link>`, inline) assigns a real display.
fn is_unresolved_custom_element(doc: &Document, bx: &LayoutBox) -> bool {
    let Some(nid) = bx.node else {
        return false;
    };
    let NodeKind::Element(e) = doc.kind(nid) else {
        return false;
    };
    if !e.tag_name.contains('-') {
        return false;
    }
    match bx.style.as_deref().and_then(|s| s.get("display")) {
        None => true,
        Some(CssValue::Keyword(k)) => k.eq_ignore_ascii_case("inline"),
        _ => false,
    }
}

/// Whether any rule in the harvested author stylesheets uses a
/// combinator: such rules need ancestor/sibling context the partial
/// subtree may not contain (see the selector-context widening in
/// [`ParseLayoutHook::run_partial_layout`]).
fn sheets_have_combinator(sheets: &[Stylesheet]) -> bool {
    sheets.iter().any(|s| {
        s.rules()
            .iter()
            .flat_map(|r| r.selectors.iter())
            .any(bowser_css::has_combinator)
    })
}

/// Whether an inline `style` value declares `visibility: collapse`
/// (tolerating `!important`).
fn style_has_visibility_collapse(style: &str) -> bool {
    style.split(';').any(|decl| {
        let (prop, val) = match decl.split_once(':') {
            Some(p) => p,
            None => return false,
        };
        if !prop.trim().eq_ignore_ascii_case("visibility") {
            return false;
        }
        let v = val.trim().to_ascii_lowercase();
        let v = v.strip_suffix("!important").map(str::trim).unwrap_or(&v);
        v == "collapse"
    })
}

/// Whether the parsed-so-far snapshot holds a `<table>` whose grid
/// combines `visibility: collapse` (inline style) with a `rowspan > 1`
/// cell and real (non-whitespace) text: collapse redistribution across
/// spanning rows over text-driven fractional line heights defeats the
/// rounded-integer cross-checks such tests assert (`cell == Σ rows`
/// fails at `91 != 30 + 30 + 30` even when the partial pass matches
/// the full layout exactly), and the hook has no font backend to do
/// better mid-parse. The scan walks the whole snapshot — the bail is
/// document-wide, so a collapsed table's reference table bails too.
///
/// Deliberately narrow: class-driven collapse is not scanned (inline
/// style covers the collapse+rowspan test family), and the text gate
/// keeps text-free grids (fixed-size content measures exactly) served.
fn snapshot_has_collapse_rowspan_text(rec: &SnapshotRecorder) -> bool {
    /// One open `<table>` in the event stream, with the depth it was
    /// opened at so non-table end tags do not pop it.
    struct TableFrame {
        depth: usize,
        rowspan: bool,
        collapse: bool,
        text: bool,
    }
    let mut stack: Vec<TableFrame> = Vec::new();
    let mut depth: usize = 0;
    let mut skip: usize = 0; // inside <template> contents / shadow roots: inert
    for ev in &rec.events {
        match ev {
            SnapEvent::StartTemplateContents | SnapEvent::StartShadowRoot => skip += 1,
            SnapEvent::EndTemplateContents | SnapEvent::EndShadowRoot => {
                skip = skip.saturating_sub(1);
            }
            SnapEvent::StartElement { tag, attrs, .. } if skip == 0 => {
                if tag.eq_ignore_ascii_case("table") {
                    stack.push(TableFrame {
                        depth,
                        rowspan: false,
                        collapse: false,
                        text: false,
                    });
                }
                let is_cell = tag.eq_ignore_ascii_case("td") || tag.eq_ignore_ascii_case("th");
                let mut rowspan = false;
                let mut collapse = false;
                for (name, value) in attrs {
                    if is_cell
                        && name.eq_ignore_ascii_case("rowspan")
                        && value.trim().parse::<u32>().unwrap_or(0) > 1
                    {
                        rowspan = true;
                    }
                    if name.eq_ignore_ascii_case("style") && style_has_visibility_collapse(value) {
                        collapse = true;
                    }
                }
                // Mark every enclosing table: the collapsed element may
                // be a `col`/`colgroup`, a row, or a cell.
                for frame in stack.iter_mut() {
                    frame.rowspan |= rowspan;
                    frame.collapse |= collapse;
                }
                depth += 1;
            }
            SnapEvent::EndElement if skip == 0 => {
                depth = depth.saturating_sub(1);
                if stack.last().is_some_and(|frame| frame.depth == depth)
                    && let Some(frame) = stack.pop()
                    && frame.rowspan
                    && frame.collapse
                    && frame.text
                {
                    return true;
                }
            }
            SnapEvent::Text(text) if skip == 0 && !text.trim().is_empty() => {
                for frame in stack.iter_mut() {
                    frame.text = true;
                }
            }
            _ => {}
        }
    }
    false
}

/// One recorded tree-construction event. Only element/text structure is
/// kept: comments, doctypes, and PIs never affect layout.
enum SnapEvent {
    StartElement {
        tag: String,
        ns: Namespace,
        attrs: Vec<(String, String)>,
    },
    EndElement,
    Text(String),
    StartTemplateContents,
    EndTemplateContents,
    StartShadowRoot,
    EndShadowRoot,
}

/// One author stylesheet harvested from a snapshot (w51), in
/// document order: `<style>` text inline, or a `<link
/// rel="stylesheet">` href to resolve and load at harvest time.
/// Keeping one ordered list (instead of a `<style>`-only list)
/// preserves the production cascade order across the two kinds.
enum HarvestedSheet {
    Inline(String),
    Link(String),
}

/// [`TreeSink`] that records the snapshot event stream for later
/// subtree extraction, harvesting `<style>` element text and
/// `<link rel="stylesheet">` hrefs on the side.
///
/// `start_element`/`end_element` are recorded unconditionally — even
/// inside `<template>` contents and shadow roots — so event positions
/// stay aligned with the arena-index emission order
/// [`ScriptHost::snapshot_document`] returns.
struct SnapshotRecorder {
    events: Vec<SnapEvent>,
    depth: usize,
    /// Element depth of the `<style>` element whose text is being
    /// captured (`None` when not inside one).
    style_at: Option<usize>,
    style_buf: String,
    /// Index into `sheets` of the `<style>` placeholder reserved at
    /// its start tag, filled with its text at its end tag: reserving
    /// at the start keeps `sheets` in document order even though
    /// the text only arrives later.
    style_sheet: Option<usize>,
    /// Harvested author sheets (`<style>` and `<link>`), in
    /// document order.
    sheets: Vec<HarvestedSheet>,
    /// The first `<base href>` of the snapshot (w51 fix A8), on
    /// the same outside-inert-subtrees rule as the sheets: the
    /// production loader resolves subresources against it
    /// (`effective_base_url`). Recorded verbatim; an invalid base
    /// falls back to the document URL at resolution time (see
    /// [`resolve_linked_sheet_url`]).
    base_href: Option<String>,
    template_depth: u32,
    shadow_depth: u32,
}

impl SnapshotRecorder {
    fn new() -> Self {
        Self {
            events: Vec::new(),
            depth: 0,
            style_at: None,
            style_buf: String::new(),
            style_sheet: None,
            sheets: Vec::new(),
            base_href: None,
            template_depth: 0,
            shadow_depth: 0,
        }
    }

    /// Event range `(start, end)` (inclusive) of the subtree rooted at
    /// the `root_ord`-th `start_element`. Elements are emitted in
    /// document order, so the subtree is contiguous.
    fn subtree_range(&self, root_ord: usize) -> Option<(usize, usize)> {
        let mut ord = 0usize;
        let mut start: Option<usize> = None;
        let mut depth = 0u32;
        for (i, ev) in self.events.iter().enumerate() {
            match ev {
                SnapEvent::StartElement { .. } => {
                    if ord == root_ord {
                        start = Some(i);
                        depth = 1;
                    } else if start.is_some() {
                        depth += 1;
                    }
                    ord += 1;
                }
                SnapEvent::EndElement if start.is_some() => {
                    depth -= 1;
                    if depth == 0 {
                        return Some((start.unwrap_or(0), i));
                    }
                }
                _ => {}
            }
        }
        None
    }
}

impl TreeSink for SnapshotRecorder {
    fn doctype(&mut self, _doctype: Doctype) {}
    fn text(&mut self, text: String, _loc: Option<SourceLoc>) {
        if self.style_at.is_some() {
            self.style_buf.push_str(&text);
        }
        self.events.push(SnapEvent::Text(text));
    }
    fn comment(&mut self, _data: String, _loc: Option<SourceLoc>) {}
    fn processing_instruction(&mut self, _target: String, _data: String, _loc: Option<SourceLoc>) {}
    fn start_element(
        &mut self,
        tag: String,
        ns: Namespace,
        attrs: Vec<(String, String)>,
        _loc: Option<SourceLoc>,
    ) {
        // Harvest `<style>` text only outside inert subtrees: styles in
        // `<template>` contents do not apply.
        if self.template_depth == 0
            && self.shadow_depth == 0
            && ns == Namespace::Html
            && tag == "style"
            && self.style_at.is_none()
        {
            self.style_at = Some(self.depth);
            self.style_buf.clear();
            self.style_sheet = Some(self.sheets.len());
            self.sheets.push(HarvestedSheet::Inline(String::new()));
        }
        // Harvest `<link rel="stylesheet">` hrefs (w51), on the same
        // outside-inert-subtrees rule: the production loader's
        // `is_stylesheet_link` rel-token rule (the `stylesheet` token,
        // ASCII case-insensitive), plus the brief's exclusion of
        // `alternate stylesheet`. The href is resolved and loaded
        // later, at harvest time (see `ParseLayoutHook::harvested_sheets`).
        if self.template_depth == 0
            && self.shadow_depth == 0
            && ns == Namespace::Html
            && tag == "link"
        {
            let attr = |name: &str| {
                attrs
                    .iter()
                    .find(|(n, _)| n.eq_ignore_ascii_case(name))
                    .map(|(_, v)| v.as_str())
            };
            let is_sheet = attr("rel").is_some_and(|rel| {
                let mut stylesheet = false;
                let mut alternate = false;
                for token in rel.split(|c: char| c.is_ascii_whitespace()) {
                    if token.eq_ignore_ascii_case("stylesheet") {
                        stylesheet = true;
                    } else if token.eq_ignore_ascii_case("alternate") {
                        alternate = true;
                    }
                }
                stylesheet && !alternate
            });
            if is_sheet
                && let Some(href) = attr("href")
                && !href.trim().is_empty()
            {
                parse_link_debug!(
                    "recorded link rel={:?} href={href} (template_depth={} shadow_depth={})",
                    attr("rel"),
                    self.template_depth,
                    self.shadow_depth
                );
                self.sheets.push(HarvestedSheet::Link(href.to_string()));
            } else {
                parse_link_debug!(
                    "skipped link rel={:?} href={:?} is_sheet={is_sheet} (template_depth={} shadow_depth={})",
                    attr("rel"),
                    attr("href"),
                    self.template_depth,
                    self.shadow_depth
                );
            }
        }
        // Record the first `<base href>` (w51 fix A8), on the same
        // outside-inert-subtrees rule as the sheets above: the
        // production loader's `effective_base_url` takes the first
        // base element with a non-empty `href` in document order
        // (an empty one does not count and does not stop the
        // search) and resolves it against the document URL.
        if self.template_depth == 0
            && self.shadow_depth == 0
            && self.base_href.is_none()
            && ns == Namespace::Html
            && tag == "base"
            && let Some(href) = attrs
                .iter()
                .find(|(n, _)| n.eq_ignore_ascii_case("href"))
                .map(|(_, v)| v.as_str())
            && !href.trim().is_empty()
        {
            self.base_href = Some(href.to_string());
        }
        self.events.push(SnapEvent::StartElement { tag, ns, attrs });
        self.depth += 1;
    }
    fn end_element(&mut self) {
        self.depth = self.depth.saturating_sub(1);
        if self.style_at == Some(self.depth) {
            let text = std::mem::take(&mut self.style_buf);
            if let Some(idx) = self.style_sheet.take() {
                self.sheets[idx] = HarvestedSheet::Inline(text);
            }
            self.style_at = None;
        }
        self.events.push(SnapEvent::EndElement);
    }
    fn start_template_contents(&mut self) {
        self.template_depth += 1;
        self.events.push(SnapEvent::StartTemplateContents);
    }
    fn end_template_contents(&mut self) {
        self.template_depth = self.template_depth.saturating_sub(1);
        self.events.push(SnapEvent::EndTemplateContents);
    }
    fn start_shadow_root(
        &mut self,
        _mode: ShadowRootMode,
        _delegates_focus: bool,
        _clonable: bool,
    ) {
        self.shadow_depth += 1;
        self.events.push(SnapEvent::StartShadowRoot);
    }
    fn end_shadow_root(&mut self) {
        self.shadow_depth = self.shadow_depth.saturating_sub(1);
        self.events.push(SnapEvent::EndShadowRoot);
    }
}

/// Rebuilds one recorded subtree as a fresh [`Document`], skipping
/// `<template>` contents and shadow roots (neither renders).
struct PartialDocBuilder {
    doc: Document,
    stack: Vec<NodeId>,
    node_ids: Vec<NodeId>,
    /// Global emission ordinal per replayed element, parallel to
    /// `node_ids`: skipped (template/shadow) elements consume ordinals
    /// without producing nodes.
    ordinals: Vec<usize>,
    skip: u32,
}

impl PartialDocBuilder {
    fn new() -> Self {
        Self {
            doc: Document::new(),
            stack: Vec::new(),
            node_ids: Vec::new(),
            ordinals: Vec::new(),
            skip: 0,
        }
    }

    /// Replay `events`, counting emission ordinals from `first_ord`
    /// (the subtree root's global ordinal).
    fn replay(&mut self, events: &[SnapEvent], first_ord: usize) {
        let mut ord = first_ord;
        for ev in events {
            match ev {
                SnapEvent::StartElement { tag, ns, attrs } => {
                    let this_ord = ord;
                    ord += 1;
                    if self.skip > 0 {
                        continue;
                    }
                    let n = self.doc.create_element_ns(ns.clone(), tag);
                    for (name, value) in attrs {
                        self.doc.set_attribute(n, name, value);
                    }
                    let parent = self
                        .stack
                        .last()
                        .copied()
                        .unwrap_or_else(|| self.doc.root());
                    self.doc.append_child(parent, n);
                    self.stack.push(n);
                    self.node_ids.push(n);
                    self.ordinals.push(this_ord);
                }
                SnapEvent::EndElement => {
                    if self.skip == 0 {
                        self.stack.pop();
                    }
                }
                SnapEvent::Text(text) => {
                    if self.skip > 0 {
                        continue;
                    }
                    let n = self.doc.create_text_node(text);
                    let parent = self
                        .stack
                        .last()
                        .copied()
                        .unwrap_or_else(|| self.doc.root());
                    self.doc.append_child(parent, n);
                }
                SnapEvent::StartTemplateContents | SnapEvent::StartShadowRoot => {
                    self.skip += 1;
                }
                SnapEvent::EndTemplateContents | SnapEvent::EndShadowRoot => {
                    self.skip = self.skip.saturating_sub(1);
                }
            }
        }
    }

    /// The rebuilt document plus dom-node -> arena-index for every
    /// replayed element (`order` is the snapshot's emission order).
    fn finish(self, order: &[usize]) -> (Document, HashMap<NodeId, usize>) {
        let mut node_arena = HashMap::with_capacity(self.node_ids.len());
        for (nid, ord) in self.node_ids.iter().zip(self.ordinals.iter()) {
            if let Some(&arena) = order.get(*ord) {
                node_arena.insert(*nid, arena);
            }
        }
        (self.doc, node_arena)
    }
}

/// Resolve a parse element wrapper and measure it, running a partial
/// layout pass when the tree mutated since the last one. Unmeasurable
/// but valid wrappers (stale handle, detached, `display: none`) get
/// the honest zero from [`ParseElementGeometry::default`].
fn parse_measured_element(
    heap: &mut Heap,
    this: Value,
    fn_name: &str,
) -> Result<(u64, ParseElementGeometry), NativeError> {
    let (id, host_ptr, el) = parse_el_host(heap, this, fn_name)?;
    // SAFETY: `host_ptr` addresses the parser's tree through the
    // `ParseShimGuard` contract documented on `deref_parse_host`, while
    // the hook borrows from the thread-local `PARSE_HOSTS` map: the two
    // are disjoint objects. The partial layout runs no JS, so nothing
    // re-enters `PARSE_HOSTS` while the entry borrow is held.
    let host = deref_parse_host(host_ptr);
    PARSE_HOSTS.with(|hosts| {
        let mut hosts = hosts.borrow_mut();
        let entry = hosts
            .get_mut(&id)
            .ok_or_else(|| err_type("document is not available outside the parser"))?;
        Ok((
            id,
            entry
                .layout_hook
                .ensure_layout(host, el)
                .unwrap_or_default(),
        ))
    })
}

macro_rules! parse_geom_long_getter {
    ($fn_name:ident, $js_name:expr, $extract:expr) => {
        fn $fn_name(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
            let (_, m) = parse_measured_element(heap, this, $js_name)?;
            // CSSOM View defines these as `long`: round to the nearest
            // integer on the way out, like the production getters.
            Ok(Value::Int($extract(&m).round() as i32))
        }
    };
}

parse_geom_long_getter!(
    n_parse_el_offset_width_get,
    "offsetWidth",
    |m: &ParseElementGeometry| m.geom.offset_width
);
parse_geom_long_getter!(
    n_parse_el_offset_height_get,
    "offsetHeight",
    |m: &ParseElementGeometry| m.geom.offset_height
);
parse_geom_long_getter!(
    n_parse_el_offset_left_get,
    "offsetLeft",
    |m: &ParseElementGeometry| if m.is_body { 0.0 } else { m.geom.offset_left }
);
parse_geom_long_getter!(
    n_parse_el_offset_top_get,
    "offsetTop",
    |m: &ParseElementGeometry| if m.is_body { 0.0 } else { m.geom.offset_top }
);
parse_geom_long_getter!(
    n_parse_el_client_width_get,
    "clientWidth",
    |m: &ParseElementGeometry| m.geom.client_width
);
parse_geom_long_getter!(
    n_parse_el_client_height_get,
    "clientHeight",
    |m: &ParseElementGeometry| m.geom.client_height
);
parse_geom_long_getter!(
    n_parse_el_client_left_get,
    "clientLeft",
    |m: &ParseElementGeometry| m.borders[3]
);
parse_geom_long_getter!(
    n_parse_el_client_top_get,
    "clientTop",
    |m: &ParseElementGeometry| m.borders[0]
);
parse_geom_long_getter!(
    n_parse_el_scroll_width_get,
    "scrollWidth",
    |m: &ParseElementGeometry| m.scroll_w
);
parse_geom_long_getter!(
    n_parse_el_scroll_height_get,
    "scrollHeight",
    |m: &ParseElementGeometry| m.scroll_h
);

/// `scrollLeft`/`scrollTop` are writable per DOM; with no scrollable
/// overflow mid-parse the sets are accepted and dropped.
fn n_parse_el_geom_set(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let _ = parse_el_host(heap, this, "geometry")?;
    Ok(Value::Undefined)
}

/// Resolve a shim element wrapper to its `(host id, element key)` for
/// the per-element scroll recording on [`ParseHostEntry`]`scroll`.
fn parse_el_id_key(heap: &Heap, this: Value, fn_name: &str) -> Result<(u64, u64), NativeError> {
    let (obj, id, _host) = parse_host(heap, this)?;
    let key = match heap.get_property(obj, Wtf8::from_str(PARSE_EL_KEY)) {
        Some(p) => match p.value {
            Value::Int(key) => key as u64,
            _ => {
                return Err(err_type(format!(
                    "{fn_name} called on a corrupt element wrapper"
                )));
            }
        },
        None => return Err(err_type(format!("{fn_name} called on a non-element"))),
    };
    // The entry may be gone when the script outlives the parse; fail
    // closed like `parse_el_host` does.
    let live = PARSE_HOSTS.with(|hosts| hosts.borrow().contains_key(&id));
    if !live {
        return Err(err_type("document is not available outside the parser"));
    }
    Ok((id, key))
}

/// Whether the element behind `key` is the document element or
/// `<body>`: their scroll slot IS the window's, because the viewport
/// scroller is described both as an element and as the window.
fn parse_key_is_viewport_scroller(entry: &ParseHostEntry, key: u64) -> bool {
    if entry.host.is_null() {
        return false;
    }
    let Some(&el) = entry.elements.get(&key) else {
        return false;
    };
    // SAFETY: `entry.host` addresses the parser's tree through the
    // `ParseShimGuard` contract on `deref_parse_host` (same call sites
    // as the geometry natives); this is a read-only tag check.
    let host = deref_parse_host(entry.host);
    matches!(
        host.tag_name(el).as_deref(),
        Some(t) if t.eq_ignore_ascii_case("html") || t.eq_ignore_ascii_case("body")
    )
}

/// Mirror a window scroll write into the parse's shared roots (M7):
/// the per-installation [`ParseHostEntry`] is popped with each
/// script's guard, so the position must also live on the
/// [`ParseShimRoots`] the production install drains (see
/// [`adopt_shim_scroll`]).
fn mirror_shim_window_scroll(entry: &ParseHostEntry, offset: (f32, f32)) {
    entry.listeners.borrow_mut().shim_window_scroll = Some(offset);
}

/// Mirror an element scroll write into the parse's shared roots
/// (M7, see [`mirror_shim_window_scroll`]), recording the identities
/// the production install resolves against its document: the
/// element's `id` attribute (when present and non-empty) and its
/// document-order ordinal among all elements, deduped by parse
/// arena index. Best-effort: a null host (a mechanism-test entry) or
/// an element the host no longer enumerates records nothing — there
/// is then nothing the production tree could resolve it to.
fn mirror_shim_element_scroll(entry: &ParseHostEntry, key: u64, offset: (f32, f32)) {
    if entry.host.is_null() {
        return;
    }
    let Some(&el) = entry.elements.get(&key) else {
        return;
    };
    // SAFETY: `entry.host` addresses the parser's tree through the
    // `ParseShimGuard` contract on `deref_parse_host` (same call
    // sites as `parse_key_is_viewport_scroller`, which the caller
    // just ran); these are read-only host queries.
    let host = deref_parse_host(entry.host);
    let id_attr = host
        .get_attributes(el)
        .into_iter()
        .find(|(name, _)| name.eq_ignore_ascii_case("id"))
        .map(|(_, value)| value)
        .filter(|value| !value.is_empty());
    // Unified ordinal (w51 rework): the same all-namespace
    // enumeration the element-wrapper identities use, so the
    // production `adopt_shim_scroll` `"*"`-ordinal resolution
    // agrees by construction (the old host
    // `get_elements_by_tag_name("*")` counts HTML only and
    // shifts after any inline `<svg>`).
    let map = all_element_enum(host, &entry.enum_cache);
    let Some(&(ordinal, _)) = map.get(&el.arena_index()) else {
        return;
    };
    let rec = ParseShimElementScroll {
        arena: el.arena_index(),
        id_attr,
        ordinal,
        offset,
    };
    let mut roots = entry.listeners.borrow_mut();
    if let Some(existing) = roots
        .shim_element_scroll
        .iter_mut()
        .find(|r| r.arena == rec.arena)
    {
        *existing = rec;
    } else {
        roots.shim_element_scroll.push(rec);
    }
}

/// The initial scroll position of the container `key` names (or
/// of the viewport for `None`), from its `scroll-initial-target`
/// descendant (see [`ParseLayoutHook::initial_target_scroll`]).
/// `None` when there is no live host, no snap data, or no target:
/// the read then reports the recorded offset.
fn parse_initial_target_get(id: u64, key: Option<u64>) -> Option<(f32, f32)> {
    PARSE_HOSTS.with(|hosts| {
        let mut hosts = hosts.borrow_mut();
        let entry = hosts.get_mut(&id)?;
        if entry.host.is_null() {
            return None;
        }
        let el = match key {
            Some(k) => match entry.elements.get(&k) {
                Some(&el) => Some(el),
                None => return None,
            },
            None => None,
        };
        // SAFETY: same `ParseShimGuard` contract as `parse_snap_scroll`
        // (see `deref_parse_host`): the host object and the
        // `PARSE_HOSTS` entry are disjoint, and the partial layout runs
        // no JS, so nothing re-enters `PARSE_HOSTS` while the entry
        // borrow is held.
        let host = deref_parse_host(entry.host);
        entry.layout_hook.initial_target_scroll(host, el)
    })
}

/// Read one shim element's recorded scroll offset (see
/// [`ParseHostEntry`]`scroll`): `(0, 0)` until written — except that
/// a never-written slot reports the container's
/// `scroll-initial-target` position when it has one (CSS Scroll
/// Snap 2 §3.1.2: that position IS the container's initial scroll
/// position, so a read before any write observes it). The document
/// element and `<body>` read the window's slot instead.
fn parse_el_scroll_get(id: u64, key: u64) -> (f32, f32) {
    let (value, written) = PARSE_HOSTS.with(|hosts| {
        let hosts = hosts.borrow();
        let Some(entry) = hosts.get(&id) else {
            return ((0.0, 0.0), true);
        };
        if parse_key_is_viewport_scroller(entry, key) {
            (entry.window_scroll, entry.window_scroll_written)
        } else {
            match entry.scroll.get(&key) {
                Some(&v) => (v, true),
                None => ((0.0, 0.0), false),
            }
        }
    });
    if written {
        return value;
    }
    parse_initial_target_get(id, Some(key)).unwrap_or(value)
}

/// Record one shim element's scroll offset. The document element and
/// `<body>` write the window's slot instead, so `window.scrollTo` and
/// `document.documentElement.scrollLeft = …` observe each other.
///
/// Also refreshes the layout hook's scroll bake and drops its cached
/// geometry: sticky constraints bake at layout time, so the next
/// geometry read must re-run the partial layout against the written
/// offsets (see [`ParseLayoutHook::note_scroll_write`]).
fn parse_el_scroll_set(id: u64, key: u64, x: f32, y: f32) {
    PARSE_HOSTS.with(|hosts| {
        if let Some(entry) = hosts.borrow_mut().get_mut(&id) {
            if parse_key_is_viewport_scroller(entry, key) {
                entry.window_scroll = (x, y);
                entry.window_scroll_written = true;
                mirror_shim_window_scroll(entry, (x, y));
            } else {
                entry.scroll.insert(key, (x, y));
                mirror_shim_element_scroll(entry, key, (x, y));
            }
            // Map the recorded per-element offsets onto host arena
            // indices for the hook's bake (see `scroll_bake`).
            let bake: Vec<(usize, (f32, f32))> = entry
                .scroll
                .iter()
                .filter_map(|(k, &offset)| {
                    entry.elements.get(k).map(|el| (el.arena_index(), offset))
                })
                .collect();
            entry.layout_hook.note_scroll_write(bake);
        }
    });
}

/// Snap-adjust a shim scroll through the on-demand partial layout and
/// return the offset to record: `key` is `None` for window scrolls.
/// `natural` comes back unchanged when there is no snap data to
/// evaluate against (null host, stale handle, no container for the
/// target, a failed rebuild) — the caller then records verbatim,
/// preserving the set-then-read contract.
fn parse_snap_scroll(
    id: u64,
    key: Option<u64>,
    pre: (f32, f32),
    natural: (f32, f32),
) -> (f32, f32) {
    PARSE_HOSTS.with(|hosts| {
        let mut hosts = hosts.borrow_mut();
        let Some(entry) = hosts.get_mut(&id) else {
            return natural;
        };
        if entry.host.is_null() {
            return natural;
        }
        let el = match key {
            Some(k) => match entry.elements.get(&k) {
                Some(&el) => Some(el),
                None => return natural,
            },
            None => None,
        };
        // SAFETY: `entry.host` addresses the parser's tree through the
        // `ParseShimGuard` contract documented on `deref_parse_host`
        // (see `parse_measured_element`): the host object and the
        // `PARSE_HOSTS` entry are disjoint, and the partial layout runs
        // no JS, so nothing re-enters `PARSE_HOSTS` while the entry
        // borrow is held.
        let host = deref_parse_host(entry.host);
        entry
            .layout_hook
            .snap_scroll(host, el, pre, natural, false)
            .unwrap_or(natural)
    })
}

fn n_parse_el_scroll_left_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, key) = parse_el_id_key(heap, this, "scrollLeft")?;
    Ok(Value::Float(f64::from(parse_el_scroll_get(id, key).0)))
}

fn n_parse_el_scroll_top_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, key) = parse_el_id_key(heap, this, "scrollTop")?;
    Ok(Value::Float(f64::from(parse_el_scroll_get(id, key).1)))
}

fn n_parse_el_scroll_left_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, key) = parse_el_id_key(heap, this, "scrollLeft")?;
    let x = arg_to_scroll_px(heap, args.first().copied().unwrap_or(Value::Undefined))?;
    let (cx, cy) = parse_el_scroll_get(id, key);
    let out = parse_snap_scroll(id, Some(key), (cx, cy), (x, cy));
    parse_el_scroll_set(id, key, out.0, out.1);
    Ok(Value::Undefined)
}

fn n_parse_el_scroll_top_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, key) = parse_el_id_key(heap, this, "scrollTop")?;
    let y = arg_to_scroll_px(heap, args.first().copied().unwrap_or(Value::Undefined))?;
    let (cx, cy) = parse_el_scroll_get(id, key);
    let out = parse_snap_scroll(id, Some(key), (cx, cy), (cx, y));
    parse_el_scroll_set(id, key, out.0, out.1);
    Ok(Value::Undefined)
}

/// Shim `Element.scrollTo(x, y)` / `scrollTo({left, top, behavior})`
/// (and the `scroll` alias): resolves the target offset, snap-adjusts
/// it against the partial layout when the element is a scroll
/// container with snap areas (see [`parse_snap_scroll`]), and records
/// the result for later `scrollLeft`/`scrollTop` reads.
/// `behavior: "smooth"` records its target immediately (there is no
/// animation clock this early).
fn n_parse_el_scroll_to(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, key) = parse_el_id_key(heap, this, "scrollTo")?;
    // A getter runs script, so no parse-host borrow is held while
    // reading the dictionary.
    let (x, y, _behavior) = parse_scroll_args(heap, args, false)?;
    let (cx, cy) = parse_el_scroll_get(id, key);
    let out = parse_snap_scroll(id, Some(key), (cx, cy), (x.unwrap_or(cx), y.unwrap_or(cy)));
    parse_el_scroll_set(id, key, out.0, out.1);
    Ok(Value::Undefined)
}

/// Resolve the parse-shim id backing a window-family object: the
/// shim installs the window scroll surface on the global object
/// itself, and `window` aliases the global — so this reads the id back
/// through the object's `document`, exactly like
/// `parse_shim_listeners` resolves the listener roots.
fn parse_window_id(heap: &Heap, this: Value) -> Result<u64, NativeError> {
    let not_live = || err_type("document is not available outside the parser");
    let Value::Object(obj) = this else {
        return Err(err_type("window scroll called on a non-window"));
    };
    let doc = match heap.get_property(obj, Wtf8::from_str("document")) {
        Some(p) => match p.value {
            Value::Object(o) => o,
            _ => return Err(not_live()),
        },
        None => return Err(not_live()),
    };
    match heap.get_property(doc, Wtf8::from_str(PARSE_CTX_KEY)) {
        Some(p) => match p.value {
            Value::Float(f) => Ok(f as u64),
            _ => Err(not_live()),
        },
        None => Err(not_live()),
    }
}

/// Read the shim entry's window scroll slot, `(0, 0)` once the
/// installation (or the document) is gone.
fn parse_window_scroll_get(id: u64) -> (f32, f32) {
    let (value, written) = PARSE_HOSTS
        .with(|hosts| {
            hosts
                .borrow()
                .get(&id)
                .map(|entry| (entry.window_scroll, entry.window_scroll_written))
        })
        .unwrap_or(((0.0, 0.0), true));
    if written {
        return value;
    }
    // Never written: the viewport's `scroll-initial-target`
    // position is the window's initial scroll position.
    parse_initial_target_get(id, None).unwrap_or(value)
}

/// Record the shim entry's window scroll slot.
fn parse_window_scroll_set(id: u64, x: f32, y: f32) {
    PARSE_HOSTS.with(|hosts| {
        if let Some(entry) = hosts.borrow_mut().get_mut(&id) {
            entry.window_scroll = (x, y);
            entry.window_scroll_written = true;
            mirror_shim_window_scroll(entry, (x, y));
        }
    });
}

/// Shim `window.scrollTo(x, y)` / `scrollTo({left, top, behavior})`
/// (and the `scroll` alias): the window's viewport scroll, snap-
/// adjusted through the partial layout (see [`parse_snap_scroll`).
/// Called on the global object itself — which is what `window`
/// aliases, so bare `scrollTo(…)` and `window.scrollTo(…)` are the same
/// function; `self` aliases too.
fn n_parse_window_scroll_to(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let id = parse_window_id(heap, this)?;
    // A getter runs script, so no parse-host borrow is held while
    // reading the dictionary.
    let (x, y, _behavior) = parse_scroll_args(heap, args, false)?;
    let (cx, cy) = parse_window_scroll_get(id);
    let out = parse_snap_scroll(id, None, (cx, cy), (x.unwrap_or(cx), y.unwrap_or(cy)));
    parse_window_scroll_set(id, out.0, out.1);
    Ok(Value::Undefined)
}

/// Shim `window.scrollBy(dx, dy)` / `scrollBy({left, top, behavior})`:
/// the relative twin of [`n_parse_window_scroll_to`].
fn n_parse_window_scroll_by(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let id = parse_window_id(heap, this)?;
    // A getter runs script, so no parse-host borrow is held while
    // reading the dictionary.
    let (dx, dy, _behavior) = parse_scroll_args(heap, args, true)?;
    let (cx, cy) = parse_window_scroll_get(id);
    let natural = (cx + dx.unwrap_or(0.0), cy + dy.unwrap_or(0.0));
    let out = parse_snap_scroll(id, None, (cx, cy), natural);
    parse_window_scroll_set(id, out.0, out.1);
    Ok(Value::Undefined)
}

fn n_parse_window_scroll_x_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let id = parse_window_id(heap, this)?;
    Ok(Value::Float(f64::from(parse_window_scroll_get(id).0)))
}

fn n_parse_window_scroll_y_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let id = parse_window_id(heap, this)?;
    Ok(Value::Float(f64::from(parse_window_scroll_get(id).1)))
}

/// Shim `Element.scrollBy(dx, dy)` / `scrollBy({left, top, behavior})`:
/// the relative twin of [`n_parse_el_scroll_to`].
fn n_parse_el_scroll_by(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, key) = parse_el_id_key(heap, this, "scrollBy")?;
    // A getter runs script, so no parse-host borrow is held while
    // reading the dictionary.
    let (dx, dy, _behavior) = parse_scroll_args(heap, args, true)?;
    let (cx, cy) = parse_el_scroll_get(id, key);
    let natural = (cx + dx.unwrap_or(0.0), cy + dy.unwrap_or(0.0));
    let out = parse_snap_scroll(id, Some(key), (cx, cy), natural);
    parse_el_scroll_set(id, key, out.0, out.1);
    Ok(Value::Undefined)
}

/// `el.offsetParent` mid-parse: the wrapper for the layout API's
/// offset-parent element, or `null` when CSSOM View says there is none
/// (root, `body`, `position: fixed`, `display: none`). A static element
/// with no positioned ancestor reports `document.body`, like the
/// production getter.
fn n_parse_el_offset_parent_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, m) = parse_measured_element(heap, this, "offsetParent")?;
    match m.offset_parent {
        Some(p) => wrap_parse_element(heap, id, p).map(Value::Object),
        None => Ok(Value::Null),
    }
}

fn n_parse_el_query_selector(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "querySelector")?;
    let sel = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    match deref_parse_host(host).query_selector_in(el, &sel) {
        Some(e) => wrap_parse_element(heap, id, e).map(Value::Object),
        None => Ok(Value::Null),
    }
}

fn n_parse_el_query_selector_all(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "querySelectorAll")?;
    let sel = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let els: Vec<ScriptChild> = deref_parse_host(host)
        .query_selector_all_in(el, &sel)
        .into_iter()
        .map(ScriptChild::Element)
        .collect();
    parse_child_array(heap, id, &els, true)
}

/// Resolve any element wrapper (possibly from another installation of
/// the same parse) to its handle.
fn parse_el_handle_any_slot(
    heap: &Heap,
    v: Value,
    fn_name: &str,
) -> Result<ScriptElement, NativeError> {
    let (_id, el) = parse_el_handle(heap, v, fn_name)?;
    Ok(el)
}

fn n_parse_el_append_child(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, parent) = parse_el_host(heap, this, "appendChild")?;
    let child_val = args.first().copied().unwrap_or(Value::Undefined);
    let child = parse_el_handle_any_slot(heap, child_val, "appendChild")?;
    let host_ref = deref_parse_host(host);
    // DocumentFragment semantics: splicing a `template.content`
    // fragment appends its children.
    if parse_is_fragment(heap, child_val) {
        let kids = host_ref.child_elements(child);
        for kid in kids {
            if !host_ref.append_child(parent, kid) {
                return Err(err_type("appendChild failed"));
            }
            // Live identity maintenance (w51 rework).
            refresh_shim_record_attachment(id, kid);
        }
        return Ok(child_val);
    }
    if host_ref.append_child(parent, child) {
        // Live identity maintenance (w51 rework): a reinserted
        // element's detached mark clears (see
        // `refresh_shim_record_attachment`).
        refresh_shim_record_attachment(id, child);
        Ok(child_val)
    } else {
        Err(err_type("appendChild failed"))
    }
}

fn n_parse_el_remove_child(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, parent) = parse_el_host(heap, this, "removeChild")?;
    let child_val = args.first().copied().unwrap_or(Value::Undefined);
    let child = parse_el_handle_any_slot(heap, child_val, "removeChild")?;
    if deref_parse_host(host).remove_child(parent, child) {
        // Live identity maintenance (w51 rework): the removed
        // element's record is marked detached, so the upgrade
        // drops it instead of resolving its stale ordinal onto
        // the next same-tag sibling.
        mark_shim_record_detached(id, child, true);
        Ok(child_val)
    } else {
        Err(err_type("removeChild failed"))
    }
}

fn n_parse_el_insert_before(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, parent) = parse_el_host(heap, this, "insertBefore")?;
    let mut rest = args.iter().copied();
    let new_val = rest.next().unwrap_or(Value::Undefined);
    let ref_val = rest.next().unwrap_or(Value::Undefined);
    let new = parse_el_handle_any_slot(heap, new_val, "insertBefore")?;
    let reference = match ref_val {
        Value::Null | Value::Undefined => None,
        v => Some(parse_el_handle_any_slot(heap, v, "insertBefore")?),
    };
    let host_ref = deref_parse_host(host);
    if parse_is_fragment(heap, new_val) {
        let kids = host_ref.child_elements(new);
        for kid in kids {
            if !host_ref.insert_before(parent, kid, reference) {
                return Err(err_type("insertBefore failed"));
            }
            // Live identity maintenance (w51 rework).
            refresh_shim_record_attachment(id, kid);
        }
        return Ok(new_val);
    }
    if host_ref.insert_before(parent, new, reference) {
        // Live identity maintenance (w51 rework).
        refresh_shim_record_attachment(id, new);
        Ok(new_val)
    } else {
        Err(err_type("insertBefore failed"))
    }
}

/// Whether a wrapper is a `template.content` fragment.
fn parse_is_fragment(heap: &Heap, v: Value) -> bool {
    match v {
        Value::Object(o) => heap
            .get_property(o, Wtf8::from_str(PARSE_FRAG_KEY))
            .is_some(),
        _ => false,
    }
}

/// The scroll shift a mid-parse `getBoundingClientRect` must subtract
/// to convert its measured rect into viewport coordinates: the window
/// scroll plus every ancestor scroller's recorded offset.
///
/// The partial layout bakes sticky constraints at the script-written
/// offsets (`scroll_bake`), so a stuck box's measured rect is in
/// scroller-content coordinates (e.g. scroll 100 + `top: 50` measures
/// 150); without this subtraction every post-scroll read lands exactly
/// one scroll offset above the viewport answer (WPT
/// `position-sticky-get-bounding-client-rect`: 150 instead of 50, and
/// a relative box reads 50 instead of -50). The production getter
/// subtracts the same quantity via [`scroll_shift`]; the shim never
/// did, because it returned the raw partial-tree rect.
///
/// Applies in full when the serving pass was rooted at the document
/// element, i.e. the rect is in document coordinates. Subtree-rooted
/// passes report root-relative coordinates by contract (the ancestors
/// above the root were never laid out), and shifting those by
/// document-level scrolls would corrupt them — except when the root
/// itself is a scroller, whose own scroll shifts its content relative
/// to its box. A fixed box is already viewport-anchored in a
/// document-rooted pass, so it never shifts.
/// An absolutely positioned box only scrolls with scrollers at or
/// above its offset parent (its containing block): a scroller between
/// the box and its containing block does not move it. In-flow boxes
/// (static, relative, sticky) scroll with every ancestor scroller.
/// Fail-closed to zero on any resolution failure: a no-box element
/// must keep reading (0, 0), never a shifted zero.
fn parse_gbcr_scroll_shift(heap: &Heap, this: Value, m: &ParseElementGeometry) -> (f32, f32) {
    let Ok((id, host_ptr, el)) = parse_el_host(heap, this, "getBoundingClientRect") else {
        return (0.0, 0.0);
    };
    PARSE_HOSTS.with(|hosts| {
        let mut hosts = hosts.borrow_mut();
        let Some(entry) = hosts.get_mut(&id) else {
            return (0.0, 0.0);
        };
        // SAFETY: `host_ptr` addresses the parser's tree through the
        // `ParseShimGuard` contract documented on `deref_parse_host`,
        // while the hook borrows from the thread-local `PARSE_HOSTS`
        // map: the two are disjoint objects. The partial layout runs
        // no JS, so nothing re-enters `PARSE_HOSTS` while the entry
        // borrow is held (same discipline as
        // `parse_measured_element`).
        let host = deref_parse_host(host_ptr);
        let Some(chain) = ancestor_chain(host, el) else {
            return (0.0, 0.0);
        };
        let Some(doc_el) = chain.last() else {
            return (0.0, 0.0);
        };
        let doc_arena = doc_el.arena_index();
        // The serving entry is the MRU-last one (`ensure_layout`
        // rotates the hit to the back); it must be document-rooted
        // and must actually contain this element's box, otherwise the
        // measurement was a cached miss and the honest zero stands.
        let Some((key, boxes)) = entry.layout_hook.entries.last() else {
            return (0.0, 0.0);
        };
        if !boxes.contains_key(&el.arena_index()) {
            return (0.0, 0.0);
        }
        // Subtree-rooted pass: the rect is relative to the root's
        // border box, and a scroller above the root moves root and
        // element together, so no document-level shift applies — with
        // one exception: when the root IS a scroller, its own scroll
        // shifts its content relative to its box, so the root's
        // recorded offset must come off. In-flow boxes always scroll
        // with the root's content; an absolute box does only when its
        // containing block is inside the subtree (an offset parent
        // was found there) — with its containing block outside, the
        // root's scroll does not move it. A fixed box never shifts.
        if key.1 != doc_arena {
            if inline_position(host, el).as_deref() == Some("fixed") {
                return (0.0, 0.0);
            }
            if inline_position(host, el).as_deref() == Some("absolute") && m.offset_parent.is_none()
            {
                return (0.0, 0.0);
            }
            if let Some(&(_, off)) = entry
                .layout_hook
                .scroll_bake
                .iter()
                .find(|(a, _)| *a == key.1)
            {
                return (off.0, off.1);
            }
            return (0.0, 0.0);
        }
        if inline_position(host, el).as_deref() == Some("fixed") {
            return (0.0, 0.0);
        }
        let mut sx = entry.window_scroll.0;
        let mut sy = entry.window_scroll.1;
        // Chain index of the offset parent (the containing block for
        // absolute boxes): scrollers at or above it move the box,
        // scrollers below it do not. `usize::MAX` when there is no
        // offset parent (viewport containing block): no ancestor
        // scroller moves the box, only the window scroll does.
        // In-flow boxes take every ancestor scroller (gate 0).
        let abs_gate = if inline_position(host, el).as_deref() == Some("absolute") {
            match m.offset_parent {
                Some(op) => chain
                    .iter()
                    .position(|h| h.arena_index() == op.arena_index())
                    .unwrap_or(usize::MAX),
                None => usize::MAX,
            }
        } else {
            0
        };
        for (j, anc) in chain.iter().enumerate().skip(1) {
            if j < abs_gate {
                continue;
            }
            if let Some(&(_, off)) = entry
                .layout_hook
                .scroll_bake
                .iter()
                .find(|(a, _)| *a == anc.arena_index())
            {
                sx += off.0;
                sy += off.1;
            }
        }
        (sx, sy)
    })
}

fn n_parse_el_get_bounding_client_rect(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, m) = parse_measured_element(heap, this, "getBoundingClientRect")?;
    // DOMRect fields are doubles. Document-rooted passes measure in
    // document coordinates: convert to viewport coordinates by
    // subtracting the window scroll and ancestor scroller offsets
    // (see `parse_gbcr_scroll_shift`). Subtree-rooted passes keep
    // their root-relative contract: the ancestors above the root are
    // never laid out mid-parse (see `ParseLayoutHook`).
    let (shx, shy) = parse_gbcr_scroll_shift(heap, this, &m);
    let x = (m.rect.x - shx) as f64;
    let y = (m.rect.y - shy) as f64;
    let w = m.rect.w as f64;
    let h = m.rect.h as f64;
    let rect = alloc_dom_rect(heap, parse_dom_rect_proto(id), x, y, w, h)?;
    Ok(Value::Object(rect))
}

/// `el.tagName`: the uppercase qualified name (`DIV`, `SPAN`, ...).
/// Whether a parse-host element is an `<img>`: gates the shim
/// `src`/`complete` accessors in [`wrap_parse_element`].
fn is_parse_img(host_id: u64, el: ScriptElement) -> bool {
    PARSE_HOSTS.with(|hosts| {
        let hosts = hosts.borrow();
        let entry = match hosts.get(&host_id) {
            Some(e) => e,
            None => return false,
        };
        let host = deref_parse_host(entry.host);
        host.tag_name(el)
            .map(|t| t.eq_ignore_ascii_case("img"))
            .unwrap_or(false)
    })
}

/// `HTMLImageElement.src` on a parse-shim `<img>` wrapper: reflects to
/// the `src` content attribute (upgrades to the production accessor at
/// install).
fn n_parse_el_img_src_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, el) = parse_el_handle(heap, this, "src")?;
    let src = PARSE_HOSTS.with(|hosts| {
        let hosts = hosts.borrow();
        let entry = hosts.get(&id)?;
        let host = deref_parse_host(entry.host);
        Some(
            host.get_attributes(el)
                .into_iter()
                .find(|(name, _)| name.eq_ignore_ascii_case("src"))
                .map(|(_, value)| value)
                .unwrap_or_default(),
        )
    });
    let Some(src) = src else {
        return Err(err_type("document is not available outside the parser"));
    };
    let s = heap.alloc_str(&src).map_err(|_| NativeError::OutOfMemory)?;
    Ok(Value::Str(s))
}

fn n_parse_el_img_src_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "src")?;
    let src = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    // The parse host validates the handle against the parse generation.
    deref_parse_host(host).set_attribute(el, "src", &src);
    // Keep the id-global map consistent if this ever aliases (harmless
    // for src, but matches `setAttribute`'s bookkeeping).
    let _ = id;
    Ok(Value::Undefined)
}

/// `HTMLImageElement.complete` on a parse-shim `<img>` wrapper: always
/// false mid-parse — the embedder's image pipeline has not run yet, so
/// no load could have completed.
fn n_parse_el_img_complete_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let _ = parse_el_handle(heap, this, "complete")?;
    Ok(Value::Bool(false))
}

fn n_parse_el_tag_name_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (_id, host, el) = parse_el_host(heap, this, "tagName")?;
    let name = deref_parse_host(host)
        .tag_name(el)
        .unwrap_or_default()
        .to_uppercase();
    Ok(Value::Str(
        heap.alloc_str(&name)
            .map_err(|_| NativeError::OutOfMemory)?,
    ))
}

/// `el.nextElementSibling` / `el.previousElementSibling`.
fn n_parse_el_next_sibling_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    parse_sibling_get(heap, this, true, "nextElementSibling")
}

fn n_parse_el_prev_sibling_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    parse_sibling_get(heap, this, false, "previousElementSibling")
}

fn parse_sibling_get(
    heap: &mut Heap,
    this: Value,
    next: bool,
    name: &'static str,
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, name)?;
    match deref_parse_host(host).sibling_element(el, next) {
        Some(sib) => wrap_parse_element(heap, id, sib).map(Value::Object),
        None => Ok(Value::Null),
    }
}

/// `el.cloneNode(deep)`.
fn n_parse_el_clone_node(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "cloneNode")?;
    let deep = parse_truthy(args.first().copied().unwrap_or(Value::Undefined));
    // A `template.content` fragment clones to a fragment (DOM:
    // `cloneNode` preserves the node's type): carry the fragment
    // marking onto the new wrapper. Without this, `appendChild` /
    // `insertBefore` see a plain element wrapper and insert the clone
    // itself — a literal `<template>` element, whose children never
    // render — instead of splicing its children (the fixed-layout-2
    // shape: the cloned `x-table` stayed inside the non-rendered
    // `<template>` and every `offsetWidth` read answered zero).
    let is_frag = parse_is_fragment(heap, this);
    match deref_parse_host(host).clone_element(el, deep) {
        Some(cloned) => {
            let obj = wrap_parse_element(heap, id, cloned)?;
            if is_frag {
                with_temp_root(heap, Value::Object(obj), |heap| {
                    def(heap, obj, PARSE_FRAG_KEY, Value::Bool(true))?;
                    Ok::<(), AllocError>(())
                })
                .map_err(|_| NativeError::OutOfMemory)?;
            }
            Ok(Value::Object(obj))
        }
        None => Err(err_type("cloneNode on a detached element")),
    }
}

/// `template.content`: a fragment of the template's contents, or null.
fn n_parse_el_content_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "content")?;
    match deref_parse_host(host).template_content(el) {
        Some(frag) => {
            let obj = wrap_parse_element(heap, id, frag)?;
            // Mark as a fragment: appendChild/insertBefore splice its
            // children instead of the wrapper itself.
            with_temp_root(heap, Value::Object(obj), |heap| {
                def(heap, obj, PARSE_FRAG_KEY, Value::Bool(true))?;
                Ok::<(), AllocError>(())
            })
            .map_err(|_| NativeError::OutOfMemory)?;
            Ok(Value::Object(obj))
        }
        None => Ok(Value::Null),
    }
}

/// `el.remove()`: detach from the parent, if attached.
fn n_parse_el_remove(heap: &mut Heap, this: Value, _args: &[Value]) -> Result<Value, NativeError> {
    let (id, host, el) = parse_el_host(heap, this, "remove")?;
    let host_ref = deref_parse_host(host);
    if let Some(parent) = host_ref.parent_element(el) {
        host_ref.remove_child(parent, el);
    }
    // Live identity maintenance (w51 rework): the removed
    // element's record is marked detached (see
    // `n_parse_el_remove_child`).
    mark_shim_record_detached(id, el, true);
    Ok(Value::Undefined)
}

// -- classList ------------------------------------------------------------

/// Wrap a minimal `DOMTokenList` for the element's `class` attribute.
/// Cached on the element wrapper under [`PARSE_CLASS_LIST_KEY`]
/// (`el.classList === el.classList` per WebIDL `[SameObject]`): every
/// method reads/writes the attribute, so the cached view never goes stale.
fn wrap_parse_class_list(heap: &mut Heap, id: u64, el_key: u64) -> Result<Gc<Object>, NativeError> {
    let obj = heap
        .alloc_object(Object::new(ObjectKind::Ordinary))
        .map_err(|_| NativeError::OutOfMemory)?;
    with_temp_root(
        heap,
        Value::Object(obj),
        |heap| -> Result<(), NativeError> {
            let oom = |_: AllocError| NativeError::OutOfMemory;
            def(heap, obj, PARSE_CTX_KEY, Value::Float(id as f64)).map_err(oom)?;
            def(heap, obj, PARSE_EL_KEY, Value::Int(el_key as i32)).map_err(oom)?;
            def_native(heap, obj, "add", n_parse_class_list_add).map_err(oom)?;
            def_native(heap, obj, "remove", n_parse_class_list_remove).map_err(oom)?;
            def_native(heap, obj, "toggle", n_parse_class_list_toggle).map_err(oom)?;
            def_native(heap, obj, "contains", n_parse_class_list_contains).map_err(oom)?;
            Ok(())
        },
    )?;
    Ok(obj)
}

fn parse_class_tokens(
    host: &ScriptHost<'static, 'static, 'static>,
    el: ScriptElement,
) -> Vec<String> {
    host.get_attributes(el)
        .into_iter()
        .find(|(n, _)| n.eq_ignore_ascii_case("class"))
        .map(|(_, v)| v.split_whitespace().map(str::to_string).collect())
        .unwrap_or_default()
}

/// JS truthiness for the `classList.toggle` force argument.
fn parse_truthy(v: Value) -> bool {
    match v {
        Value::Undefined | Value::Null => false,
        Value::Bool(b) => b,
        Value::Int(i) => i != 0,
        Value::Float(f) => f != 0.0 && !f.is_nan(),
        Value::Str(s) => !s.as_wtf8().is_empty(),
        Value::Object(_) | Value::Symbol(_) | Value::BigInt(_) => true,
    }
}

fn n_parse_el_class_list_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (obj, id, _host) = parse_host(heap, this)?;
    // `[SameObject]`: return the cached live view when present. The
    // view's methods read/write the `class` attribute on every call,
    // so the cached view cannot go stale.
    if let Some(p) = heap.get_property(obj, Wtf8::from_str(PARSE_CLASS_LIST_KEY))
        && let Value::Object(o) = p.value
    {
        return Ok(Value::Object(o));
    }
    let key = match heap.get_property(obj, Wtf8::from_str(PARSE_EL_KEY)) {
        Some(p) => match p.value {
            Value::Int(k) => k as u64,
            _ => return Err(err_type("classList accessed on a corrupt element wrapper")),
        },
        None => return Err(err_type("classList accessed on a non-element")),
    };
    let list = wrap_parse_class_list(heap, id, key)?;
    def(heap, obj, PARSE_CLASS_LIST_KEY, Value::Object(list))
        .map_err(|_| NativeError::OutOfMemory)?;
    Ok(Value::Object(list))
}

fn parse_class_list_args(heap: &mut Heap, args: &[Value]) -> Result<Vec<String>, NativeError> {
    args.iter()
        .copied()
        .map(|v| {
            let s = arg_to_string(&mut *heap, v)?;
            if s.is_empty() || s.split_whitespace().count() != 1 {
                return Err(err_type("classList token must be a single non-empty token"));
            }
            Ok(s)
        })
        .collect()
}

fn n_parse_class_list_add(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (_id, host, el) = parse_el_host(heap, this, "classList.add")?;
    let tokens = parse_class_list_args(&mut *heap, args)?;
    let host_ref = deref_parse_host(host);
    let mut cur = parse_class_tokens(host_ref, el);
    for t in tokens {
        if !cur.contains(&t) {
            cur.push(t);
        }
    }
    host_ref.set_attribute(el, "class", &cur.join(" "));
    Ok(Value::Undefined)
}

fn n_parse_class_list_remove(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (_id, host, el) = parse_el_host(heap, this, "classList.remove")?;
    let tokens = parse_class_list_args(&mut *heap, args)?;
    let host_ref = deref_parse_host(host);
    let mut cur = parse_class_tokens(host_ref, el);
    cur.retain(|c| !tokens.contains(c));
    host_ref.set_attribute(el, "class", &cur.join(" "));
    Ok(Value::Undefined)
}

fn n_parse_class_list_toggle(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (_id, host, el) = parse_el_host(heap, this, "classList.toggle")?;
    let mut rest = args.iter().copied();
    let token = {
        let s = arg_to_string(&mut *heap, rest.next().unwrap_or(Value::Undefined))?;
        if s.is_empty() || s.split_whitespace().count() != 1 {
            return Err(err_type("classList token must be a single non-empty token"));
        }
        s
    };
    let force = rest.next();
    let host_ref = deref_parse_host(host);
    let mut cur = parse_class_tokens(host_ref, el);
    let has = cur.contains(&token);
    let want = match force {
        Some(v) => parse_truthy(v),
        None => !has,
    };
    if want && !has {
        cur.push(token);
    } else if !want && has {
        cur.retain(|c| c != &token);
    }
    host_ref.set_attribute(el, "class", &cur.join(" "));
    Ok(Value::Bool(want))
}

fn n_parse_class_list_contains(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (_id, host, el) = parse_el_host(heap, this, "classList.contains")?;
    let token = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    Ok(Value::Bool(
        parse_class_tokens(deref_parse_host(host), el).contains(&token),
    ))
}

// -- text node wrappers -----------------------------------------------------

/// Wrap raw text as a minimal `Text` node (`nodeType` 3,
/// `textContent`/`nodeValue`/`data`). Detached: sets do not write back
/// into the tree (the parent's `textContent` setter is the mutation
/// path).
fn wrap_parse_text(heap: &mut Heap, id: u64, text: &str) -> Result<Gc<Object>, NativeError> {
    let obj = heap
        .alloc_object(Object::new(ObjectKind::Ordinary))
        .map_err(|_| NativeError::OutOfMemory)?;
    with_temp_root(
        heap,
        Value::Object(obj),
        |heap| -> Result<(), NativeError> {
            let oom = |_: AllocError| NativeError::OutOfMemory;
            def(heap, obj, PARSE_CTX_KEY, Value::Float(id as f64)).map_err(oom)?;
            let s = heap.alloc_str(text).map(Value::Str).map_err(oom)?;
            def(heap, obj, PARSE_TEXT_KEY, s).map_err(oom)?;
            def(heap, obj, "nodeType", Value::Int(3)).map_err(oom)?;
            def_accessor(
                heap,
                obj,
                "textContent",
                n_parse_text_content_get,
                n_parse_text_content_set,
            )
            .map_err(oom)?;
            def_accessor(
                heap,
                obj,
                "nodeValue",
                n_parse_text_content_get,
                n_parse_text_content_set,
            )
            .map_err(oom)?;
            def_accessor(
                heap,
                obj,
                "data",
                n_parse_text_content_get,
                n_parse_text_content_set,
            )
            .map_err(oom)?;
            // `childNodes`: CharacterData has no children, so this is
            // always an empty snapshot `NodeList`. WPT helpers such as
            // `checkSubtreeExpectedValues` recurse through `childNodes` of
            // every node including text, so the accessor must exist and
            // return an Array-kind receiver.
            def_accessor(
                heap,
                obj,
                "childNodes",
                n_parse_text_child_nodes_get,
                n_parse_el_readonly_set,
            )
            .map_err(oom)?;
            Ok(())
        },
    )?;
    Ok(obj)
}

/// `childNodes` getter for a text-node wrapper: always an empty snapshot
/// `NodeList`, since text nodes have no children (mirrors
/// [`n_parse_el_child_nodes_get`] for elements).
fn n_parse_text_child_nodes_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (_obj, id, _host) = parse_host(heap, this)?;
    parse_child_array(heap, id, &[], false)
}

fn n_parse_text_content_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let Value::Object(o) = this else {
        return Err(err_type("textContent accessed on a non-object"));
    };
    match heap.get_property(o, Wtf8::from_str(PARSE_TEXT_KEY)) {
        Some(p) => Ok(p.value),
        None => Err(err_type("textContent accessed on a non-text node")),
    }
}

fn n_parse_text_content_set(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let Value::Object(o) = this else {
        return Err(err_type("textContent set on a non-object"));
    };
    if heap
        .get_property(o, Wtf8::from_str(PARSE_TEXT_KEY))
        .is_none()
    {
        return Err(err_type("textContent set on a non-text node"));
    }
    let t = arg_to_string(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    let s = heap
        .alloc_str(&t)
        .map(Value::Str)
        .map_err(|_| NativeError::OutOfMemory)?;
    def(heap, o, PARSE_TEXT_KEY, s).map_err(|_| NativeError::OutOfMemory)?;
    Ok(Value::Undefined)
}

// -- document structure -----------------------------------------------------

fn n_parse_doc_body_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (_obj, id, host) = parse_host(heap, this)?;
    match deref_parse_host(host).body_element() {
        Some(el) => wrap_parse_element(heap, id, el).map(Value::Object),
        None => Ok(Value::Null),
    }
}

fn n_parse_doc_document_element_get(
    heap: &mut Heap,
    this: Value,
    _args: &[Value],
) -> Result<Value, NativeError> {
    let (_obj, id, host) = parse_host(heap, this)?;
    match deref_parse_host(host).document_element() {
        Some(el) => wrap_parse_element(heap, id, el).map(Value::Object),
        None => Ok(Value::Null),
    }
}

// -- getComputedStyle -------------------------------------------------------

/// (property, initial value, inherited?). `border-collapse`,
/// `border-spacing`, `caption-side`, and `empty-cells` are inherited per
/// css-tables-3 (see `css/css-tables/inheritance.html`).
const PARSE_COMPUTED_PROPS: &[(&str, &str, bool)] = &[
    ("border-collapse", "separate", true),
    ("border-spacing", "0px", true),
    ("caption-side", "top", true),
    ("empty-cells", "show", true),
    ("table-layout", "auto", false),
    ("writing-mode", "horizontal-tb", true),
    ("direction", "ltr", true),
    ("display", "inline", false),
    ("position", "static", false),
    ("float", "none", false),
    ("clear", "none", false),
    ("visibility", "visible", true),
    ("color", "black", true),
    ("background-color", "transparent", false),
    // w79fix: the seven layered `background` longhands (initials
    // matching the cascade's), plus the `background` shorthand
    // row (initial `""`, like `border` below, so a
    // synthesis-failing element does not fall back to a bogus
    // value). Without these rows the shim's computed object never
    // carried the longhands, so `synthesize_computed_shorthands`
    // could not fire for `background` there either.
    ("background-image", "none", false),
    ("background-position", "0% 0%", false),
    ("background-size", "auto auto", false),
    ("background-repeat", "repeat", false),
    ("background-attachment", "scroll", false),
    ("background-origin", "padding-box", false),
    ("background-clip", "border-box", false),
    ("background", "", false),
    ("opacity", "1", false),
    ("width", "auto", false),
    ("height", "auto", false),
    ("min-width", "auto", false),
    ("max-width", "none", false),
    ("min-height", "auto", false),
    ("max-height", "none", false),
    ("margin-top", "0px", false),
    ("margin-right", "0px", false),
    ("margin-bottom", "0px", false),
    ("margin-left", "0px", false),
    // w78fix H1: the box shorthands and their logical pairs (and
    // `gap`/`border`/`font`/`flex` below) are synthesized from the
    // longhands by `synthesize_computed_shorthands`, like
    // `border-width`/`border-style`/`border-color` already were —
    // without a row here the shim's computed object never exposes
    // them (`margin in getComputedStyle` is false, and the value
    // reads as `undefined`/`""`). The initial is the synthesis of
    // the initial longhands, used only when synthesis cannot run.
    ("margin", "0px", false),
    ("margin-inline-start", "0px", false),
    ("margin-inline-end", "0px", false),
    ("margin-block-start", "0px", false),
    ("margin-block-end", "0px", false),
    ("margin-inline", "0px", false),
    ("margin-block", "0px", false),
    ("padding-top", "0px", false),
    ("padding-right", "0px", false),
    ("padding-bottom", "0px", false),
    ("padding-left", "0px", false),
    ("padding", "0px", false),
    ("padding-inline-start", "0px", false),
    ("padding-inline-end", "0px", false),
    ("padding-block-start", "0px", false),
    ("padding-block-end", "0px", false),
    ("padding-inline", "0px", false),
    ("padding-block", "0px", false),
    ("border-top-width", "0px", false),
    ("border-right-width", "0px", false),
    ("border-bottom-width", "0px", false),
    ("border-left-width", "0px", false),
    ("border-top-style", "none", false),
    ("border-right-style", "none", false),
    ("border-bottom-style", "none", false),
    ("border-left-style", "none", false),
    ("border-top-color", "currentcolor", false),
    ("border-right-color", "currentcolor", false),
    ("border-bottom-color", "currentcolor", false),
    ("border-left-color", "currentcolor", false),
    ("border-width", "0px", false),
    ("border-style", "none", false),
    ("border-color", "currentcolor", false),
    // The full `border` shorthand: synthesized in full form; the
    // initial is `""` so a differing-sides element (where synthesis
    // correctly yields nothing) does not fall back to a bogus value.
    ("border", "", false),
    ("font-size", "16px", true),
    ("font-style", "normal", true),
    ("font-variant", "normal", true),
    ("font-weight", "400", true),
    ("line-height", "normal", true),
    ("font-family", "sans-serif", true),
    // `font` synthesis of the initial longhands (weight `400` is
    // kept by the font synthesis, like any non-`normal` weight).
    ("font", "400 16px sans-serif", true),
    // `gap` from `row-gap`/`column-gap` (`normal`/`normal`), and
    // `flex` from its initial longhands.
    ("row-gap", "normal", false),
    ("column-gap", "normal", false),
    ("gap", "normal", false),
    ("flex-grow", "0", false),
    ("flex-shrink", "1", false),
    ("flex-basis", "auto", false),
    ("flex", "0 1 auto", false),
    ("text-align", "start", true),
    ("text-decoration", "none", false),
    ("text-transform", "none", true),
    ("white-space", "normal", true),
    ("vertical-align", "baseline", false),
    ("letter-spacing", "normal", true),
    ("overflow", "visible", false),
    ("overflow-x", "visible", false),
    ("overflow-y", "visible", false),
    ("cursor", "auto", true),
    ("z-index", "auto", false),
    // CSS Position 4 (w79 phase 1): `overlay` (`none | auto`, not
    // inherited). This row is what makes the parse shim's computed
    // style expose it (`in` check) and `CSS.supports` accept it —
    // without it both gates fail before any value is read. The
    // computed value itself comes from the real cascade (UA rule
    // forces `none` for non-top-layer elements); top-layer
    // promotion is phase 2 work.
    ("overlay", "none", false),
    ("top", "auto", false),
    ("right", "auto", false),
    ("bottom", "auto", false),
    ("left", "auto", false),
    // CSS Logical Properties 1: the flow-relative insets sit beside
    // their physical counterparts here, so the parse shim's computed
    // style exposes them (`in` check), resolves their values, and
    // `CSS.supports` accepts them — exactly like `top`/`right`/
    // `bottom`/`left` above. Without these rows every
    // `inset-computed` subtest failed at the testcommon gates
    // (`property in getComputedStyle` / `CSS.supports`) before any
    // value was even read.
    ("inset-block-start", "auto", false),
    ("inset-block-end", "auto", false),
    ("inset-inline-start", "auto", false),
    ("inset-inline-end", "auto", false),
    ("scroll-snap-type", "none", false),
    ("scroll-snap-align", "none", false),
    ("scroll-snap-stop", "normal", false),
    ("scroll-margin", "0px", false),
    ("scroll-margin-top", "0px", false),
    ("scroll-margin-right", "0px", false),
    ("scroll-margin-bottom", "0px", false),
    ("scroll-margin-left", "0px", false),
    ("scroll-margin-block", "0px", false),
    ("scroll-margin-inline", "0px", false),
    ("scroll-margin-block-start", "0px", false),
    ("scroll-margin-block-end", "0px", false),
    ("scroll-margin-inline-start", "0px", false),
    ("scroll-margin-inline-end", "0px", false),
    ("scroll-padding", "auto", false),
    ("scroll-padding-top", "auto", false),
    ("scroll-padding-right", "auto", false),
    ("scroll-padding-bottom", "auto", false),
    ("scroll-padding-left", "auto", false),
    ("scroll-padding-block", "auto", false),
    ("scroll-padding-inline", "auto", false),
    ("scroll-padding-block-start", "auto", false),
    ("scroll-padding-block-end", "auto", false),
    ("scroll-padding-inline-start", "auto", false),
    ("scroll-padding-inline-end", "auto", false),
    ("scroll-initial-target", "none", false),
    ("scrollbar-gutter", "auto", false),
    ("overflow-clip-margin", "0px", false),
];

/// UA `display` defaults for `getComputedStyle` (no stylesheet cascade
/// in the shim, so these stand in for the UA stylesheet).
fn parse_ua_display(tag: &str) -> &'static str {
    match tag {
        "table" => "table",
        "thead" | "tbody" | "tfoot" => "table-row-group",
        "colgroup" => "table-column-group",
        "col" => "table-column",
        "tr" => "table-row",
        "td" | "th" => "table-cell",
        "caption" => "table-caption",
        "div" | "p" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "ul" | "ol" | "dl" | "li"
        | "main" | "section" | "article" | "header" | "footer" | "nav" | "aside" | "figure"
        | "figcaption" | "blockquote" | "pre" | "hr" | "form" | "fieldset" | "address" | "body" => {
            "block"
        }
        _ => "inline",
    }
}

fn parse_computed_info(prop: &str) -> (&'static str, bool) {
    for (p, initial, inherited) in PARSE_COMPUTED_PROPS {
        if *p == prop {
            return (initial, *inherited);
        }
    }
    ("", false)
}

/// Inline value for `prop` on the computed-value path, if any.
/// Deliberately NOT [`parse_style_decls`]: that is the specified
/// style store, which preserves authored color keywords (`red`,
/// `transparent`) per CSSOM, while computed values must serialize
/// colors canonically (rgb()/rgba()). The computed fallback reads
/// through [`computed_style_decls_from_text`] instead (w78fix3).
fn parse_computed_inline_decl(
    host: &ScriptHost<'static, 'static, 'static>,
    el: ScriptElement,
    prop: &str,
) -> Option<String> {
    let style = host
        .get_attributes(el)
        .into_iter()
        .find(|(n, _)| n.eq_ignore_ascii_case("style"))
        .map(|(_, v)| v)
        .unwrap_or_default();
    computed_style_decls_from_text(&style)
        .into_iter()
        .find(|(n, _)| n == prop)
        .map(|(_, v)| v)
}

/// Resolve one computed property: inline value, else `initial`/
/// `inherit`/`unset`/inheritance rules, else the initial (or inherited
/// parent) value. Recursion depth is capped; pathological trees fail
/// closed to the initial value.
fn parse_computed_prop(
    host: &mut ScriptHost<'static, 'static, 'static>,
    el: ScriptElement,
    prop: &str,
    depth: u8,
) -> String {
    let (initial, inherited) = parse_computed_info(prop);
    if depth > 64 {
        return initial.to_string();
    }
    let parent_computed = |host: &mut ScriptHost<'static, 'static, 'static>| -> String {
        match host.parent_element(el) {
            Some(p) => parse_computed_prop(host, p, prop, depth + 1),
            None => initial.to_string(),
        }
    };
    match parse_computed_inline_decl(host, el, prop).as_deref() {
        None | Some("") => {
            if inherited {
                parent_computed(host)
            } else {
                initial.to_string()
            }
        }
        Some("initial") => initial.to_string(),
        Some("inherit") => parent_computed(host),
        Some("unset") => {
            if inherited {
                parent_computed(host)
            } else {
                initial.to_string()
            }
        }
        Some(v) => v.to_string(),
    }
}

/// Resolve the live parse-shim slot from a global-receiver native
/// (`this` is the page global): through `global.document`'s install tag.
fn parse_host_from_global(
    heap: &Heap,
    this: Value,
) -> Result<(u64, *mut ScriptHost<'static, 'static, 'static>), NativeError> {
    let not_live = || err_type("document is not available outside the parser");
    let Value::Object(global) = this else {
        return Err(err_type("called with an invalid receiver"));
    };
    let doc = match heap.get_property(global, Wtf8::from_str("document")) {
        Some(p) => match p.value {
            Value::Object(o) => o,
            _ => return Err(not_live()),
        },
        None => return Err(not_live()),
    };
    let id = match heap.get_property(doc, Wtf8::from_str(PARSE_CTX_KEY)) {
        Some(p) => match p.value {
            Value::Float(f) => f as u64,
            _ => return Err(not_live()),
        },
        None => return Err(not_live()),
    };
    let host = PARSE_HOSTS
        .with(|hosts| hosts.borrow().get(&id).map(|entry| entry.host))
        .ok_or_else(not_live)?;
    if host.is_null() {
        return Err(not_live());
    }
    Ok((id, host))
}

/// The inline-style-only computed map (the pre-cascade shim's
/// resolution): used when the element is not in the layout hook's
/// whole-tree rebuild (detached, or inside `<template>` contents).
/// Inline declarations plus `initial`/`inherit`/`unset`/inheritance
/// resolution, finished with the same shorthand synthesis and CSSOM
/// adjustments the cascade path applies.
fn parse_computed_fallback(
    host: *mut ScriptHost<'static, 'static, 'static>,
    el: ScriptElement,
    viewport: (u32, u32),
) -> HashMap<String, String> {
    let host_ref = deref_parse_host(host);
    let tag = host_ref.tag_name(el).unwrap_or_default();
    let mut props: HashMap<String, String> = HashMap::new();
    for (prop, _initial, _inherited) in PARSE_COMPUTED_PROPS {
        if computed_shorthand_longhands(prop).is_some() {
            continue; // synthesized from the longhands below
        }
        let val = if *prop == "display"
            && parse_computed_inline_decl(host_ref, el, "display").is_none()
        {
            // No cascade on this path: the UA default stands in.
            parse_ua_display(&tag).to_string()
        } else {
            parse_computed_prop(host_ref, el, prop, 0)
        };
        props.insert(prop.to_string(), val);
    }
    let font_px = props
        .get("font-size")
        .and_then(|s| {
            serialized_length_px(
                s,
                &ComputedAdjustCtx {
                    font_px: 16.0,
                    root_px: 16.0,
                    vw: 0.0,
                    vh: 0.0,
                },
            )
        })
        .unwrap_or(16.0);
    let ctx = ComputedAdjustCtx {
        font_px,
        root_px: font_px,
        vw: viewport.0 as f32,
        vh: viewport.1 as f32,
    };
    adjust_computed_props(&mut props, &ctx);
    synthesize_border_shorthands(&mut props);
    // Every other computed shorthand through the shared helper
    // (w78fix H1), like the cascade path above.
    synthesize_computed_shorthands(&mut props);
    props
}

fn n_parse_get_computed_style(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let (id, host) = parse_host_from_global(heap, this)?;
    let el_val = args.first().copied().unwrap_or(Value::Undefined);
    let (_eid, el) = parse_el_handle(heap, el_val, "getComputedStyle")?;
    // The cascade path: the layout hook's whole-tree rebuild styled
    // by the real cascade (see `ParseLayoutHook::computed_props`).
    let cascaded = PARSE_HOSTS.with(|hosts| {
        let mut hosts = hosts.borrow_mut();
        let entry = hosts.get_mut(&id)?;
        // SAFETY: `host` addresses the parser's tree through the
        // `ParseShimGuard` contract documented on `deref_parse_host`
        // (see `parse_measured_element`): the host object and the
        // `PARSE_HOSTS` entry are disjoint, and the cascade runs no
        // JS, so nothing re-enters `PARSE_HOSTS` while the entry
        // borrow is held.
        let host_ref = deref_parse_host(host);
        entry.layout_hook.computed_props(host_ref, el)
    });
    let values = match cascaded {
        Some(v) => v,
        None => {
            let viewport = PARSE_HOSTS
                .with(|hosts| {
                    hosts
                        .borrow()
                        .get(&id)
                        .map(|entry| entry.layout_hook.viewport)
                })
                .unwrap_or((
                    PARSE_LAYOUT_VIEWPORT_W as u32,
                    PARSE_LAYOUT_VIEWPORT_H as u32,
                ));
            parse_computed_fallback(host, el, viewport)
        }
    };
    let obj = heap
        .alloc_object(Object::new(ObjectKind::Ordinary))
        .map_err(|_| NativeError::OutOfMemory)?;
    with_temp_root(
        heap,
        Value::Object(obj),
        |heap| -> Result<(), NativeError> {
            let oom = |_: AllocError| NativeError::OutOfMemory;
            // Every known property is an own data property, so `prop in
            // getComputedStyle(el)` works (WPT's computed-testcommon
            // asserts support this way).
            for (prop, initial, _inherited) in PARSE_COMPUTED_PROPS {
                let val = values
                    .get(*prop)
                    .cloned()
                    .unwrap_or_else(|| initial.to_string());
                let s = heap.alloc_str(&val).map(Value::Str).map_err(oom)?;
                def(heap, obj, prop, s).map_err(oom)?;
                let camel = css_camel(prop);
                if camel != *prop {
                    let cs = heap.alloc_str(&val).map(Value::Str).map_err(oom)?;
                    def(heap, obj, &camel, cs).map_err(oom)?;
                }
            }
            def_native(
                heap,
                obj,
                "getPropertyValue",
                n_parse_computed_get_property_value,
            )
            .map_err(oom)?;
            Ok(())
        },
    )?;
    Ok(Value::Object(obj))
}

fn n_parse_computed_get_property_value(
    heap: &mut Heap,
    this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let Value::Object(o) = this else {
        return Err(err_type("getPropertyValue called on a non-object"));
    };
    let name = parse_style_prop_arg(
        &mut *heap,
        args.first().copied().unwrap_or(Value::Undefined),
    )?;
    match heap.get_property(o, Wtf8::from_str(&name)) {
        Some(p) => Ok(p.value),
        None => heap
            .alloc_str("")
            .map(Value::Str)
            .map_err(|_| NativeError::OutOfMemory),
    }
}

/// `CSS.supports` value validation (w52): the value must parse
/// against the property's real grammar — the same
/// [`parse_valid_style_decls`] check `el.style` assignment uses, so
/// `CSS.supports` and style setting agree. Values `bowser_css`
/// cannot parse (`-moz-available`, `intrinsic`, …) return false
/// instead of the old vacuous true. `calc-size()` parses (w51/w52)
/// and validates as a length, like `calc()`.
///
/// The value must parse as exactly one declaration for the named
/// property: a smuggled second declaration (`supports('width',
/// '10px; color: red')`) no longer validates through the first
/// (browsers: false). Shorthands still validate — the single
/// declaration expands to its longhands after this gate.
fn css_supports_value(prop_dashed: &str, val: &str) -> bool {
    let val = val.trim();
    if val.is_empty() {
        return false;
    }
    // `!important` is not part of a declaration value: `supports()`
    // takes `(property, value)`, so a trailing `!important` never
    // validates (matches browsers).
    let suffix = "!important";
    let t = val.trim_end();
    if t.len() >= suffix.len()
        && t.is_char_boundary(t.len() - suffix.len())
        && t[t.len() - suffix.len()..].eq_ignore_ascii_case(suffix)
    {
        return false;
    }
    // A second declaration smuggled into the value (`supports('width',
    // '10px; color: red')`) must not validate through the first one:
    // the text must hold exactly one declaration (a trailing `;` is
    // fine). This is a syntactic gate, before shorthand expansion —
    // `supports('scroll-margin', '10px')` still validates via the
    // longhands below.
    let text = format!("{prop_dashed}: {val}");
    let chunks = split_top_level_decls(&text);
    if chunks.iter().filter(|c| !c.trim().is_empty()).count() != 1 {
        return false;
    }
    // `var()` references cannot be resolved without context: per CSS
    // Conditional a declaration whose whole value is a single `var()`
    // reference counts as supported (matches browsers), while the
    // grammar check below would reject the unresolvable `Var` node.
    // Only a *leading* `var(` function token qualifies: trailing
    // garbage (`var(--x) garbage garbage`) and idents merely
    // containing the substring (`avar(--x)`) fall through to the
    // grammar check and fail, like browsers.
    if is_single_var_function(val) {
        return true;
    }
    !parse_valid_style_decls(&format!("{prop_dashed}: {val}")).is_empty()
}

/// Whether `val` is exactly one `var()` function call (balanced
/// parens, nothing before or after), e.g. `var(--x)` or
/// `VAR(--x, 10px)`. The leading `var(` must be a real function
/// token — `avar(--x)` does not qualify.
fn is_single_var_function(val: &str) -> bool {
    let lower = val.to_ascii_lowercase();
    let rest = match lower.strip_prefix("var(") {
        Some(rest) => rest,
        None => return false,
    };
    // `rest` is ASCII here (the prefix is), so byte indexing is safe.
    let bytes = rest.as_bytes();
    let mut depth = 1usize;
    let mut i = 0;
    let mut quote = 0u8;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == b'\\' {
                i += 1; // skip the escaped char
            } else if b == quote {
                quote = 0;
            }
        } else if b == b'\'' || b == b'"' {
            quote = b;
        } else if b == b'(' {
            depth += 1;
        } else if b == b')' {
            depth -= 1;
            if depth == 0 {
                // The matching close paren must end the value.
                return rest[i + 1..].trim().is_empty();
            }
        }
        i += 1;
    }
    false
}

/// Split declaration-block text at top-level `;`, ignoring
/// semicolons inside strings and nested `()`/`[]`/`{}` (e.g. the one
/// in `url(data:image/svg+xml;…)`), for [`css_supports_value`]'s
/// single-declaration gate. Byte indices stay on char boundaries:
/// only ASCII bytes are inspected.
fn split_top_level_decls(text: &str) -> Vec<&str> {
    let bytes = text.as_bytes();
    let mut chunks = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    let mut quote = 0u8;
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == b'\\' {
                i += 1;
            } else if b == quote {
                quote = 0;
            }
        } else {
            match b {
                b'\'' | b'"' => quote = b,
                b'(' | b'[' | b'{' => depth += 1,
                b')' | b']' | b'}' => depth -= 1,
                b';' if depth <= 0 => {
                    chunks.push(&text[start..i]);
                    start = i + 1;
                }
                _ => {}
            }
        }
        i += 1;
    }
    chunks.push(&text[start..]);
    chunks
}

/// `CSS.supports`: true for a known property whose value validates
/// against the property's grammar (see [`css_supports_value`]).
fn n_parse_css_supports(
    heap: &mut Heap,
    _this: Value,
    args: &[Value],
) -> Result<Value, NativeError> {
    let mut rest = args.iter().copied();
    let first = rest.next().unwrap_or(Value::Undefined);
    let ok = match rest.next() {
        Some(second) => {
            let prop = arg_to_string(&mut *heap, first).unwrap_or_default();
            let val = arg_to_string(&mut *heap, second).unwrap_or_default();
            let dashed = css_dashed(&prop.to_ascii_lowercase());
            PARSE_COMPUTED_PROPS.iter().any(|(p, _, _)| *p == dashed)
                && css_supports_value(&dashed, &val)
        }
        None => {
            // `CSS.supports("display: block")` form.
            let cond = arg_to_string(&mut *heap, first).unwrap_or_default();
            match cond.split_once(':') {
                Some((prop, val)) => {
                    let dashed = css_dashed(&prop.trim().to_ascii_lowercase());
                    PARSE_COMPUTED_PROPS.iter().any(|(p, _, _)| *p == dashed)
                        && css_supports_value(&dashed, val)
                }
                None => false,
            }
        }
    };
    Ok(Value::Bool(ok))
}

// -- id-named window properties ---------------------------------------------

/// Whether `s` is a valid JS identifier (for id-named globals).
fn is_js_identifier(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c == '_' || c == '$' || c.is_alphabetic() => {}
        _ => return false,
    }
    chars.all(|c| c == '_' || c == '$' || c.is_alphanumeric())
}

/// Expose elements with `id` attributes as window named properties
/// (HTML5 window named properties). Snapshot per installation: ids
/// parsed after this script do not appear until the next script's
/// install. Never shadows an existing global own-or-inherited property
/// (testharness.js's own globals win).
fn parse_install_id_globals(
    heap: &mut Heap,
    global: Gc<Object>,
    id: u64,
    host: *mut ScriptHost<'static, 'static, 'static>,
) -> Result<(), NativeError> {
    if host.is_null() {
        return Ok(());
    }
    // SAFETY: the install path holds the `ParseShimGuard`; the host
    // borrow it was made from is alive (same justification as
    // `deref_parse_host`).
    let host_ref: &mut ScriptHost<'static, 'static, 'static> = unsafe { &mut *host };
    let ids = host_ref.element_ids();
    with_temp_root(
        heap,
        Value::Object(global),
        |heap| -> Result<(), NativeError> {
            let oom = |_: AllocError| NativeError::OutOfMemory;
            for (name, el) in &ids {
                if !is_js_identifier(name) {
                    continue;
                }
                if let Some(existing) = heap.get_property(global, Wtf8::from_str(name)) {
                    // A stale id-named wrapper from an earlier script:
                    // repoint it at this install instead of skipping it
                    // (see `repoint_stale_id_global`).
                    repoint_stale_id_global(heap, existing.value, id, *el).map_err(oom)?;
                    continue;
                }
                let w = wrap_parse_element(heap, id, *el)?;
                def(heap, global, name, Value::Object(w)).map_err(oom)?;
            }
            Ok(())
        },
    )?;
    Ok(())
}

/// Repoint an id-named element wrapper installed by an earlier script
/// at the current installation. Sequential parser-inserted scripts each
/// snapshot id-named window properties tagged with their own slot id,
/// and the slot is popped when the script ends — a wrapper left behind
/// throws `TypeError: document is not available outside the parser` on
/// any DOM API. This mirrors the shared `document` wrapper's repoint:
/// the wrapper keeps its object identity, gains this install's slot id
/// in [`PARSE_CTX_KEY`], and its handle is re-registered under a fresh
/// element key in this install's slot (the old key belonged to the
/// popped slot's map).
///
/// Two cases are deliberately left alone: non-shim globals (page
/// script's own properties win, as before), and wrappers whose slot is
/// still live — a nested `document.write` script: the outer install
/// owns the wrapper and resumes after this script, so it must keep
/// serving the outer slot.
fn repoint_stale_id_global(
    heap: &mut Heap,
    existing: Value,
    id: u64,
    el: ScriptElement,
) -> Result<(), AllocError> {
    let Value::Object(obj) = existing else {
        return Ok(());
    };
    let old_id = match heap.get_property(obj, Wtf8::from_str(PARSE_CTX_KEY)) {
        Some(p) => match p.value {
            Value::Float(f) => f as u64,
            _ => return Ok(()),
        },
        None => return Ok(()),
    };
    // Element wrappers (not the shared document wrapper) carry
    // `PARSE_EL_KEY`.
    if heap
        .get_property(obj, Wtf8::from_str(PARSE_EL_KEY))
        .is_none()
    {
        return Ok(());
    }
    if PARSE_HOSTS.with(|hosts| hosts.borrow().contains_key(&old_id)) {
        return Ok(());
    }
    let key = PARSE_HOSTS.with(|hosts| {
        let mut hosts = hosts.borrow_mut();
        let entry = hosts.get_mut(&id).ok_or(AllocError)?;
        let key = entry.next_element;
        entry.next_element = entry.next_element.wrapping_add(1);
        entry.elements.insert(key, el);
        Ok::<u64, AllocError>(key)
    })?;
    // The wrapper is reachable from the temp-rooted global; the `def`
    // calls below may allocate, but a collection cannot free a
    // reachable object, so no extra root is needed beyond the one here
    // for the wrapper itself.
    with_temp_root(heap, Value::Object(obj), |heap| {
        def(heap, obj, PARSE_CTX_KEY, Value::Float(id as f64))?;
        def(heap, obj, PARSE_EL_KEY, Value::Int(key as i32))?;
        // The repointed wrapper must not keep `[SameObject]` views
        // baked with the popped slot's `(id, el_key)`: a stale view
        // would resolve its methods against a dead slot (`TypeError:
        // document is not available outside the parser`). Drop both
        // cached views so the next access mints fresh ones for the
        // new slot (mirrors `upgrade_shim_element_wrappers`).
        heap.delete_property(obj, Wtf8::from_str(PARSE_CLASS_LIST_KEY));
        heap.delete_property(obj, Wtf8::from_str(PARSE_STYLE_KEY));
        Ok(())
    })
}

