    #[test]
    fn dispatch_event_carries_key() {
        // The testdriver key dispatch shape:
        // `dispatchEvent({type, key, bubbles, cancelable})` surfaces
        // `event.key` to listeners.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"box\">x</div></body></html>",
            "",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "(function(){ \
                   var seen = 'none'; \
                   var el = document.getElementById('box'); \
                   el.addEventListener('keydown', function(e){ seen = e.key; }); \
                   el.dispatchEvent({type:'keydown', key:'Tab', bubbles:true, cancelable:true}); \
                   return seen; \
                 })()"
            ),
            "Tab"
        );
        // No `key` member: the property stays absent (base Event shape).
        assert_eq!(
            node_list_str(
                &mut vm,
                "(function(){ \
                   var seen = 'absent'; \
                   var el = document.getElementById('box'); \
                   el.addEventListener('keydown', function(e){ seen = ('key' in e) ? e.key : 'absent'; }); \
                   el.dispatchEvent({type:'keydown', bubbles:true, cancelable:true}); \
                   return String(seen); \
                 })()"
            ),
            "absent"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn testdriver_bridge_queues_requests_with_tokens() {
        let (mut vm, doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"box\">x</div></body></html>",
            "",
        );
        let out = node_list_str(
            &mut vm,
            "(function(){ \
               var b = window.__bowser_testdriver; \
               if (!b) return 'no-bridge'; \
               var el = document.getElementById('box'); \
               var t1 = b.click(el); \
               var t2 = b.send_keys(el, 'hi'); \
               var t3 = b.bless(); \
               return [typeof t1, typeof t2, typeof t3, t1 < t2, t2 < t3].join(','); \
             })()",
        );
        assert_eq!(out, "number,number,number,true,true");
        let box_node = doc.borrow().get_element_by_id("box").expect("box");
        let reqs = take_testdriver_requests(ctx);
        assert_eq!(reqs.len(), 3);
        assert!(reqs[0].token < reqs[1].token && reqs[1].token < reqs[2].token);
        assert_eq!(reqs[0].action, TestDriverAction::Click { node: box_node });
        assert_eq!(
            reqs[1].action,
            TestDriverAction::SendKeys {
                node: box_node,
                keys: "hi".to_string()
            }
        );
        assert_eq!(reqs[2].action, TestDriverAction::Bless);
        // Drained: the next take is empty.
        assert!(take_testdriver_requests(ctx).is_empty());
        remove_context(ContextId(ctx));
    }

