    #[test]
    fn testdriver_action_sequence_queues_deserialized_payload() {
        let (mut vm, doc, ctx) = production_vm();
        let out = node_list_str(
            &mut vm,
            "(function(){ \
               var b = window.__bowser_testdriver; \
               var el = document.getElementById('inner'); \
               var t = b.action_sequence([ \
                 { type: 'key', id: 'keyboard', actions: [ \
                     { type: 'keyDown', value: 'a' }, \
                     { type: 'pause', duration: 50 }, \
                     { type: 'keyUp', value: 'a' } ] }, \
                 { type: 'pointer', id: 'mouse', parameters: { pointerType: 'pen' }, actions: [ \
                     { type: 'pointerMove', duration: 100, origin: el, x: 10, y: 20 }, \
                     { type: 'pointerDown', button: 0 }, \
                     { type: 'pointerMove', duration: 0, origin: 'pointer', x: 5, y: -5 }, \
                     { type: 'pointerUp' } ] }, \
                 { type: 'wheel', id: 'wheel', actions: [ \
                     { type: 'scroll', x: 0, y: 0, deltaX: 0, deltaY: 100, duration: 200, \
                       origin: 'viewport' } ] }, \
                 { type: 'none', id: 'none', actions: [ { type: 'pause' } ] } \
               ]); \
               return typeof t; \
             })()",
        );
        assert_eq!(out, "number");
        let inner = doc.borrow().get_element_by_id("inner").expect("inner");
        let reqs = take_testdriver_requests(ctx.0);
        assert_eq!(reqs.len(), 1);
        let TestDriverAction::ActionSequence { sequence } = &reqs[0].action else {
            panic!("expected an action_sequence request");
        };
        assert_eq!(sequence.sources.len(), 4);

        // Key source.
        let key = &sequence.sources[0];
        assert_eq!(key.kind, ActionSourceKind::Key);
        assert_eq!(key.id, "keyboard");
        assert_eq!(key.pointer_type, None);
        assert_eq!(key.actions.len(), 3);
        assert_eq!(key.actions[0].kind, ActionItemKind::KeyDown);
        assert_eq!(key.actions[0].value.as_deref(), Some("a"));
        assert_eq!(key.actions[1].kind, ActionItemKind::Pause);
        assert_eq!(key.actions[1].duration, Some(50.0));
        assert_eq!(key.actions[2].kind, ActionItemKind::KeyUp);

        // Pointer source with a resolved element origin.
        let pointer = &sequence.sources[1];
        assert_eq!(pointer.kind, ActionSourceKind::Pointer);
        assert_eq!(pointer.id, "mouse");
        assert_eq!(pointer.pointer_type.as_deref(), Some("pen"));
        assert_eq!(pointer.actions.len(), 4);
        assert_eq!(pointer.actions[0].kind, ActionItemKind::PointerMove);
        assert_eq!(pointer.actions[0].duration, Some(100.0));
        assert_eq!(pointer.actions[0].origin, ActionOrigin::Element(inner));
        assert_eq!(pointer.actions[0].x, Some(10.0));
        assert_eq!(pointer.actions[0].y, Some(20.0));
        assert_eq!(pointer.actions[1].kind, ActionItemKind::PointerDown);
        assert_eq!(pointer.actions[1].button, Some(0));
        assert_eq!(pointer.actions[2].kind, ActionItemKind::PointerMove);
        assert_eq!(pointer.actions[2].origin, ActionOrigin::Pointer);
        assert_eq!(pointer.actions[2].x, Some(5.0));
        assert_eq!(pointer.actions[2].y, Some(-5.0));
        assert_eq!(pointer.actions[3].kind, ActionItemKind::PointerUp);
        // An omitted `button` defaults to the primary button.
        assert_eq!(pointer.actions[3].button, Some(0));

        // Wheel source.
        let wheel = &sequence.sources[2];
        assert_eq!(wheel.kind, ActionSourceKind::Wheel);
        assert_eq!(wheel.actions.len(), 1);
        assert_eq!(wheel.actions[0].kind, ActionItemKind::Scroll);
        assert_eq!(wheel.actions[0].delta_y, Some(100.0));
        assert_eq!(wheel.actions[0].duration, Some(200.0));
        assert_eq!(wheel.actions[0].origin, ActionOrigin::Viewport);

        // None source: a bare pause defaults to a zero duration.
        let none = &sequence.sources[3];
        assert_eq!(none.kind, ActionSourceKind::None);
        assert_eq!(none.actions.len(), 1);
        assert_eq!(none.actions[0].kind, ActionItemKind::Pause);
        assert_eq!(none.actions[0].duration, Some(0.0));

        // Drained: the next take is empty.
        assert!(take_testdriver_requests(ctx.0).is_empty());
        remove_context(ctx);
    }

    #[test]
    fn testdriver_action_sequence_rejects_malformed() {
        let (mut vm, _doc, ctx) = production_vm();
        for src in [
            // Not an array.
            "window.__bowser_testdriver.action_sequence({})",
            // Unknown source type.
            "window.__bowser_testdriver.action_sequence([{type: 'stylus', actions: []}])",
            // Missing source type / actions.
            "window.__bowser_testdriver.action_sequence([{actions: []}])",
            "window.__bowser_testdriver.action_sequence([{type: 'key'}])",
            // Unknown action type.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'key', id: 'k', actions: [{type: 'keySmash'}]}])",
            // Action that is not an object.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'key', id: 'k', actions: [42]}])",
            // Origin that is neither a string nor an element.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: \
                 [{type: 'pointerMove', origin: {}}]}])",
            // Unknown origin string.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: \
                 [{type: 'pointerMove', origin: 'el'}]}])",
            // Absent argument.
            "window.__bowser_testdriver.action_sequence()",
        ] {
            let out = eval_log(
                &mut vm,
                &format!(
                    "(function(){{ try {{ {src}; return 'no-throw'; }} \
                       catch (e) {{ return 'threw:' + (e instanceof TypeError); }} }})()"
                ),
            );
            assert_eq!(out, "threw:true", "payload {src:?} should throw TypeError");
        }
        // A rejected call queues nothing.
        assert!(take_testdriver_requests(ctx.0).is_empty());
        remove_context(ctx);
    }

    #[test]
    fn testdriver_action_sequence_rejects_non_finite_coords_and_bad_buttons() {
        let (mut vm, _doc, ctx) = production_vm();
        for src in [
            // NaN x on a pointerMove.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'pointerMove', x: NaN, y: 0}]}])",
            // Infinite y on a pointerMove.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'pointerMove', x: 0, y: Infinity}]}])",
            // Huge coordinate beyond f32 range.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'pointerMove', x: 1e300, y: 0}]}])",
            // NaN scroll delta.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'wheel', id: 'w', actions: [{type: 'scroll', x: 0, y: 0, deltaX: 0, deltaY: NaN}]}])",
            // Infinite scroll origin coordinate.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'wheel', id: 'w', actions: [{type: 'scroll', x: -Infinity, y: 0, deltaX: 0, deltaY: 1}]}])",
            // button: -1 must reject, not wrap to 4294967295.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'pointerDown', button: -1}]}])",
            // button: 5 is out of the WebDriver 0..=4 range.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'pointerUp', button: 5}]}])",
        ] {
            let out = eval_log(
                &mut vm,
                &format!(
                    "(function(){{ try {{ {src}; return 'no-throw'; }} \
                       catch (e) {{ return 'threw:' + (e instanceof TypeError); }} }})()"
                ),
            );
            assert_eq!(out, "threw:true", "payload {src:?} should throw TypeError");
        }
        // No partial sequence was queued by any rejected call.
        assert!(take_testdriver_requests(ctx.0).is_empty());
        remove_context(ctx);
    }

