    #[test]
    fn testdriver_action_sequence_rejects_source_action_kind_mismatches() {
        let (mut vm, _doc, ctx) = production_vm();
        for src in [
            // Pointer action inside a key sequence.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'key', id: 'k', actions: [{type: 'pointerDown', button: 0}]}])",
            // Key action inside a pointer sequence.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'keyDown', value: 'a'}]}])",
            // Scroll inside a pointer sequence.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'pointer', id: 'm', actions: [{type: 'scroll', x: 0, y: 0, deltaX: 0, deltaY: 1}]}])",
            // PointerMove inside a wheel sequence.
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'wheel', id: 'w', actions: [{type: 'pointerMove', x: 0, y: 0}]}])",
            // Key action inside a none sequence (pauses only).
            "window.__bowser_testdriver.action_sequence(\
               [{type: 'none', id: 'n', actions: [{type: 'keyUp', value: 'a'}]}])",
            // A valid first source does not save a mismatched second
            // source: the whole sequence rejects, nothing is queued.
            "window.__bowser_testdriver.action_sequence([\
               {type: 'key', id: 'k', actions: [{type: 'keyDown', value: 'a'}]}, \
               {type: 'key', id: 'k2', actions: [{type: 'pointerMove', x: 0, y: 0}]}])",
        ] {
            let out = eval_log(
                &mut vm,
                &format!(
                    "(function(){{ try {{ {src}; return 'no-throw'; }} \
                       catch (e) {{ return 'threw:' + (e instanceof TypeError); }} }})()"
                ),
            );
            assert_eq!(out, "threw:true", "payload {src:?} should throw TypeError");
        }
        assert!(take_testdriver_requests(ctx.0).is_empty());
        remove_context(ctx);
    }

    #[test]
    fn geometry_index_agrees_with_dfs_fallback() {
        let (mut vm, doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"outer\"><div id=\"box\">x</div></div></body></html>",
            "#outer { position: relative; width: 400px; height: 300px; } \
             #box { width: 100px; height: 50px; margin-left: 7px; margin-top: 9px; }",
        );
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        // Publishing the tree built the index.
        assert!(apis.borrow().layout_box_index.borrow().is_some());
        // The index lookup lands on the same box (same rect, same
        // ancestor chain) the DFS finds, for a nested node.
        let box_node = doc.borrow().get_element_by_id("box").expect("box");
        {
            let g = apis.borrow();
            let tree = g.layout_tree.borrow().clone().expect("tree");
            let index_guard = g.layout_box_index.borrow();
            let index = index_guard.as_ref().expect("index");
            let (dfs_box, dfs_ancestors) = find_layout_box(&tree, box_node).expect("dfs hit");
            let (idx_box, idx_ancestors) = index.lookup(&tree, box_node).expect("index hit");
            assert_eq!(idx_box.rect, dfs_box.rect);
            assert_eq!(idx_ancestors.len(), dfs_ancestors.len());
            for (a, b) in idx_ancestors.iter().zip(dfs_ancestors.iter()) {
                assert_eq!(a.node, b.node);
                assert_eq!(a.rect, b.rect);
            }
            // A node with no layout box (a detached element) misses
            // the index entirely.
            let detached = doc.borrow_mut().create_element("div");
            assert!(index.lookup(&tree, detached).is_none());
            assert!(find_layout_box(&tree, detached).is_none());
        }
        // Every geometry getter agrees with the DFS fallback: drop the
        // index and the same measurements come out (the fallback now
        // answers them).
        let measure = "(function(){ \
               function m(id){ var e = document.getElementById(id); \
                 var op = e.offsetParent; \
                 return [e.offsetWidth, e.offsetHeight, e.offsetLeft, e.offsetTop, \
                         e.clientWidth, e.clientHeight, op ? op.id : 'null'].join('/'); } \
               return [m('outer'), m('box')].join(';'); })()";
        let with_index = node_list_str(&mut vm, measure);
        apis.borrow().layout_box_index.replace(None);
        let without_index = node_list_str(&mut vm, measure);
        assert_eq!(with_index, without_index);
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_index_lookup_deep_tree_spills_past_inline_buffer() {
        // The lookup's child-index path lives in a 64-entry stack
        // buffer and spills to a heap `Vec` only past 64 levels of
        // depth. A tree deeper than the inline buffer must still
        // resolve exactly like the DFS fallback.
        const DEPTH: usize = 90;
        let mut html = String::from("<html><head></head><body>");
        for i in 0..DEPTH {
            // Vary the nested div's child index per level (`i % 3`
            // leading <p> siblings) so the test exercises path
            // *ordering*, not just path length: a misordered path
            // lands on the wrong box and fails the node check below.
            // (All-zero paths would pass even misordered.)
            html.push_str(&format!("<div id=\"d{i}\">"));
            for _ in 0..i % 3 {
                html.push_str("<p>x</p>");
            }
        }
        html.push_str("<div id=\"deep\">x</div>");
        for _ in 0..DEPTH {
            html.push_str("</div>");
        }
        html.push_str("</body></html>");
        let (_vm, doc, ctx) = geometry_vm(html.as_bytes(), "div { width: 10px; height: 10px; }");
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        {
            let g = apis.borrow();
            let tree = g.layout_tree.borrow().clone().expect("tree");
            let index_guard = g.layout_box_index.borrow();
            let index = index_guard.as_ref().expect("index");
            // The deep node: exercises the spill path.
            let deep = doc.borrow().get_element_by_id("deep").expect("deep");
            let (dfs_box, dfs_ancestors) = find_layout_box(&tree, deep).expect("dfs hit");
            assert!(
                dfs_ancestors.len() > 64,
                "test tree must exceed the inline path buffer, got {}",
                dfs_ancestors.len()
            );
            let (idx_box, idx_ancestors) = index.lookup(&tree, deep).expect("index hit");
            assert_eq!(idx_box.rect, dfs_box.rect);
            assert_eq!(idx_ancestors.len(), dfs_ancestors.len());
            for (a, b) in idx_ancestors.iter().zip(dfs_ancestors.iter()) {
                assert_eq!(a.node, b.node);
                assert_eq!(a.rect, b.rect);
            }
            // A shallow node in the same tree (inline path) agrees too.
            let top = doc.borrow().get_element_by_id("d0").expect("d0");
            let (dfs_box, dfs_ancestors) = find_layout_box(&tree, top).expect("dfs hit");
            let (idx_box, idx_ancestors) = index.lookup(&tree, top).expect("index hit");
            assert_eq!(idx_box.rect, dfs_box.rect);
            assert_eq!(idx_ancestors.len(), dfs_ancestors.len());
        }
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_index_rebuilt_on_swap_and_dropped_on_clear() {
        let (mut vm, doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"box\">x</div></body></html>",
            "#box { width: 100px; height: 50px; }",
        );
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetWidth;"),
            "100"
        );
        assert!(apis.borrow().layout_box_index.borrow().is_some());
        // Re-publishing (a fresh tree from a fresh layout with new
        // CSS) rebuilds the index: the getters measure the new tree,
        // not the stale index paths.
        let sheet = bowser_css::parse_stylesheet("#box { width: 250px; height: 60px; }");
        let tree = bowser_layout::layout(
            &doc.borrow(),
            &[&sheet],
            bowser_layout::Size { w: 800.0, h: 600.0 },
            &bowser_layout::FixedFontMetrics,
        );
        share_layout_tree(ctx, Rc::new(tree));
        assert!(apis.borrow().layout_box_index.borrow().is_some());
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetWidth;"),
            "250"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetHeight;"),
            "60"
        );
        // Clearing drops tree and index together: getters go back to
        // the honest no-layout answer.
        clear_layout_tree(ctx);
        assert!(apis.borrow().layout_box_index.borrow().is_none());
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetWidth;"),
            "0"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_measure_table_internal_elements() {
        // Table-internal boxes (`td`, `tr`, `table`) go through the same
        // getters via `table_box_geometry`'s border-box/padding-box
        // mechanics, including its collapse-model border handling.
        // Standards doctype (not doctype-less): a missing doctype is
        // full quirks mode, where §3.13 makes the cell's `height`
        // border-box (40, not 52) — that quirk is pinned by the
        // dedicated quirks tests, not by this mechanics test.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<!DOCTYPE html><html><head></head><body><table id=\"t\"><tr id=\"r\"><td id=\"c\">x</td></tr></table></body></html>",
            "#t { width: 300px; border-collapse: separate; } \
             #c { width: 120px; height: 40px; border: 5px solid black; }",
        );
        // `td`: auto table layout gives the single column the table's
        // full inner width minus the separated-model border spacing
        // (UA `table { border-spacing: 2px }` puts 2px on each side, so
        // the cell border box is 300 - 2 - 2 = 296); the declared 120px
        // cell width does not constrain it. The 5px borders plus the UA
        // `td { padding: 1px }` make the border box 296x52 (content 40 +
        // padding 2 + border 10) and the padding box 286x42.
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"c\").offsetWidth;"),
            "296"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"c\").offsetHeight;"),
            "52"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"c\").clientWidth;"),
            "286"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"c\").clientHeight;"),
            "42"
        );
        // The table is 300 wide and has no positioned ancestor, so its
        // own offsetParent is document.body (CSSOM View: a static
        // element with no positioned ancestor never reports null) and
        // its offsets are body-relative.
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"t\").offsetWidth;"),
            "300"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"t\").offsetParent === document.body;"
            ),
            "true"
        );
        // The static `td`'s offset parent is the static `table` itself
        // (CSSOM View's retained td/th/table rule), not the body.
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"c\").offsetParent === \
                 document.getElementById(\"t\");"
            ),
            "true"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_offset_parent_static_div_in_td() {
        // A static `div` inside a static `td` reports the `td` as its
        // offsetParent (CSSOM View's retained td/th/table rule) — not
        // `document.body`, even with no positioned ancestor anywhere.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><table><tr><td><div id=\"in\">x</div></td></tr></table></body></html>",
            "td { font-size: 10px; } #in { width: 50px; height: 20px; }",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"in\").offsetParent === \
                 document.getElementById(\"in\").parentNode;"
            ),
            "true"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"in\").offsetParent.tagName;"
            ),
            "TD"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_body_offset_parent_null_with_positioned_html() {
        // CSSOM View step 1: `document.body.offsetParent` is null even
        // when `<html>` is positioned.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"box\">x</div></body></html>",
            "html { position: relative; } #box { width: 100px; height: 50px; }",
        );
        assert_eq!(
            node_list_str(&mut vm, "document.body.offsetParent;"),
            "null"
        );
        // The static #box under the positioned `<html>` still finds
        // `document.body` first — `<html>` never becomes an offset
        // parent here.
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"box\").offsetParent === document.body;"
            ),
            "true"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_offset_relative_to_positioned_parent() {
        // Non-zero `offsetLeft`/`offsetTop`: measured from the element's
        // border edge to the positioned offset parent's padding-box
        // origin. Margins push the border edge out from the parent's
        // content edge, so the offsets read back the margins exactly
        // (the parent's border cancels: it shifts both edges equally).
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"outer\"><div id=\"box\">x</div></div></body></html>",
            "#outer { position: relative; border: 4px solid black; width: 400px; height: 300px; } \
             #box { margin: 20px 0 0 30px; width: 100px; height: 50px; }",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"box\").offsetParent === \
                 document.getElementById(\"outer\");"
            ),
            "true"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetLeft;"),
            "30"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetTop;"),
            "20"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_baseline_td_pct_divs() {
        // w76 bindings task 1: production-path probe for WPT
        // `css-tables/tentative/baseline-td` "%ge children": the
        // 50% div's offsetParent is its td and its offsetTop is 30
        // (row baseline 80 minus its own 50 bottom edge); the 80%
        // div sits at 0. Bare tds (parser fixup supplies tr/tbody),
        // inline-table, position:relative, 8px horizontal
        // border-spacing, td padding 0 — the WPT shape exactly.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div>inline table<table style=\"height:100px;position:relative;display:inline-table;border-spacing:8px 0\"><td style=\"vertical-align:baseline\"><div id=\"d50\" style=\"width:100px;height:50%\"></div></td><td style=\"vertical-align:baseline\"><div id=\"d80\" style=\"width:100px;height:80%\"></div></td></table></div></body></html>",
            "td { padding: 0; }",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "document.getElementById(\"d50\").offsetParent.tagName;"
            ),
            "TD"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d50\").offsetTop;"),
            "30"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d50\").offsetHeight;"),
            "50"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d80\").offsetTop;"),
            "0"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d80\").offsetHeight;"),
            "80"
        );
        remove_context(ContextId(ctx));
    }

