    #[test]
    fn computed_style_calc_pct_margins_resolve() {
        // w77fix: `calc()` percentage margins resolve on the
        // production path. Before the fix the percentage gate
        // (`ends_with('%')`) never fired for a value ending in
        // `')'`, so the serialized `calc()` string was served
        // verbatim instead of a px value.
        let read = |style: &str| -> String {
            let html = format!(
                "<html><head></head><body><div style=\"width:500px\"><div id=\"c\" style=\"{style}\">x</div></div></body></html>"
            );
            let (mut vm, _doc, ctx) = geometry_vm(html.as_bytes(), "");
            let r = node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c\")).marginLeft;",
            );
            remove_context(ContextId(ctx));
            r
        };
        assert_eq!(read("margin-left:calc(50% + 60px)"), "310px");
        assert_eq!(read("margin-left:calc(50% - 60px)"), "190px");
        assert_eq!(read("margin-left:calc(20%)"), "100px");
    }

    #[test]
    fn resolve_serialized_margin_px_forms() {
        // Unit coverage for the resolver's forms, including the
        // whitespace-padded percentage (`"20 %"`) the old
        // `strip_suffix` + parse chain could not be trusted on for
        // every serialization, and the fail-closed forms.
        let ctx = ComputedAdjustCtx {
            font_px: 20.0,
            root_px: 16.0,
            vw: 800.0,
            vh: 600.0,
        };
        assert_eq!(
            resolve_serialized_margin_px("20%", 500.0, &ctx),
            Some(100.0)
        );
        assert_eq!(
            resolve_serialized_margin_px("20 %", 500.0, &ctx),
            Some(100.0)
        );
        assert_eq!(
            resolve_serialized_margin_px("calc(50% + 60px)", 500.0, &ctx),
            Some(310.0)
        );
        assert_eq!(
            resolve_serialized_margin_px("calc(50% - 60px)", 500.0, &ctx),
            Some(190.0)
        );
        assert_eq!(
            resolve_serialized_margin_px("calc(20%)", 500.0, &ctx),
            Some(100.0)
        );
        assert_eq!(
            resolve_serialized_margin_px("calc(10% + 1em)", 500.0, &ctx),
            Some(70.0)
        );
        assert_eq!(resolve_serialized_margin_px("auto", 500.0, &ctx), None);
        assert_eq!(resolve_serialized_margin_px("10px", 500.0, &ctx), None);
        assert_eq!(
            resolve_serialized_margin_px("calc(50% * 2)", 500.0, &ctx),
            None
        );
    }

    #[test]
    fn computed_style_orthogonal_caption_auto_block_margins() {
        // w76 bindings task 3: the computed-style half of the
        // layout worker's orthogonal-caption distribution (w76
        // `orthogonal_caption_inline_shift`). Table vertical-lr
        // 300x200, horizontal caption 50 tall, `margin:auto 0`:
        // 150 free space along the table's inline axis splits 75/75,
        // so the caption's used block margins read 75px/75px — not
        // the computed `auto`. Inline styles drive both layout and
        // computed style here; the geometry_vm sheet is empty.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">caption</caption></table></body></html>",
            "",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c\")).marginTop;"
            ),
            "75px"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c\")).marginBottom;"
            ),
            "75px"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn computed_style_orthogonal_caption_auto_block_margins_variants() {
        // w76fix M7: the caption gate beyond the single happy path.
        // Each case reads `marginTop`/`marginBottom` off one fresh
        // `geometry_vm` (inline styles drive layout and computed
        // style; the sheet is empty). The gate replicates the layout
        // shift arithmetic, so the expected values come from
        // span/extent/fixed, not from the caption's placement.
        let read = |html: &[u8]| -> (String, String) {
            let (mut vm, _doc, ctx) = geometry_vm(html, "");
            let mt = node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c\")).marginTop;",
            );
            let mb = node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c\")).marginBottom;",
            );
            remove_context(ContextId(ctx));
            (mt, mb)
        };
        // vertical-rl: block-start is still the physical top.
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-rl;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">caption</caption></table></body></html>"),
            ("75px".to_string(), "75px".to_string()),
            "vertical-rl"
        );
        // Bottom caption: the shift stamps the same distribution
        // regardless of caption-side.
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0;caption-side:bottom\">caption</caption></table></body></html>"),
            ("75px".to_string(), "75px".to_string()),
            "bottom caption"
        );
        // Single-auto: the fixed side keeps its value, the auto side
        // takes all free space (200 - 50 - 10 = 140).
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin-top:auto;margin-bottom:10px\">caption</caption></table></body></html>"),
            ("140px".to_string(), "10px".to_string()),
            "single-auto"
        );
        // Percentage padding against the CONTAINING BLOCK width, not
        // the table's own: the wrapper is 500px, so `padding-top:
        // 10%` is 50px; the border box is 200, so the span is
        // 200 - 50 = 150 and the margins are 50/50 (cross-checked
        // against layout placement: the caption's offsetTop is 100
        // = 50 padding + 50 used margin). The old table-width base
        // would give 30px padding, span 170, and 60/60.
        assert_eq!(
            read(b"<html><head></head><body><div style=\"width:500px\"><table style=\"writing-mode:vertical-lr;width:300px;height:200px;padding-top:10%\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">caption</caption></table></div></body></html>"),
            ("50px".to_string(), "50px".to_string()),
            "% padding with table width != CB width"
        );
        // Borders do not leak into the margins: the border box is
        // 200, so the span is 200 - 20 = 180 and the margins are
        // 65/65 (ignoring the borders would give span 200, 75/75).
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px;border:10px solid black\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">caption</caption></table></body></html>"),
            ("65px".to_string(), "65px".to_string()),
            "border"
        );
        // Overflowing caption: free space clamps at zero, not a
        // negative trailing margin.
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:250px;margin:auto 0\">caption</caption></table></body></html>"),
            ("0px".to_string(), "0px".to_string()),
            "overflow"
        );
        // Floated / abspos captions never reach the caption list in
        // layout, so their auto margins compute to zero in layout
        // and stay computed `auto` here, not geometric offsets.
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0;float:left\">caption</caption></table></body></html>"),
            ("auto".to_string(), "auto".to_string()),
            "floated caption"
        );
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0;position:absolute\">caption</caption></table></body></html>"),
            ("auto".to_string(), "auto".to_string()),
            "abspos caption"
        );
        // Relative / sticky captions stay in flow: layout routes
        // only absolute/fixed to the abspos list, so they reach the
        // caption list and get the same 75/75 distribution. (A
        // static-only gate regressed this to `auto`.)
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0;position:relative\">caption</caption></table></body></html>"),
            ("75px".to_string(), "75px".to_string()),
            "relative caption"
        );
        assert_eq!(
            read(b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0;position:sticky\">caption</caption></table></body></html>"),
            ("75px".to_string(), "75px".to_string()),
            "sticky caption"
        );
        // Inline-table captions: the parent box is `InlineBlock`,
        // not `Table`, and the gate must still resolve.
        assert_eq!(
            read(b"<html><head></head><body><table style=\"display:inline-table;writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">caption</caption></table></body></html>"),
            ("75px".to_string(), "75px".to_string()),
            "inline-table caption"
        );
        // Second captions: each caption gets its own shift in
        // layout, so the second auto caption reads 75/75 too (the
        // old pure-geometry read would have included the first
        // caption's extent and margins).
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><table style=\"writing-mode:vertical-lr;width:300px;height:200px\"><caption id=\"c\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">one</caption><caption id=\"c2\" style=\"writing-mode:horizontal-tb;height:50px;margin:auto 0\">two</caption></table></body></html>",
            "",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c\")).marginTop;"
            ),
            "75px",
            "first of two captions"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c2\")).marginTop;"
            ),
            "75px",
            "second caption"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"c2\")).marginBottom;"
            ),
            "75px",
            "second caption bottom"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_display_none_reports_zeros() {
        // `display: none`: no CSS layout box -> all zeros, null
        // offsetParent, per the layout API's contract.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"box\">x</div></body></html>",
            "#box { display: none; width: 100px; height: 50px; }",
        );
        for prop in [
            "offsetWidth",
            "offsetHeight",
            "offsetLeft",
            "offsetTop",
            "clientWidth",
            "clientHeight",
        ] {
            assert_eq!(
                node_list_str(
                    &mut vm,
                    &format!("document.getElementById(\"box\").{prop};")
                ),
                "0",
                "{prop} of display:none element"
            );
        }
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetParent;"),
            "null"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn geometry_getters_client_subtracts_borders_and_padding() {
        // General (non-table) element: `clientWidth` is the padding box,
        // `offsetWidth` the border box, under the default content-box
        // sizing: 100x50 content + 10px padding + 5px border per side.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"box\">x</div></body></html>",
            "#box { width: 100px; height: 50px; border: 5px solid black; padding: 10px; }",
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetWidth;"),
            "130"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").offsetHeight;"),
            "80"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").clientWidth;"),
            "120"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"box\").clientHeight;"),
            "70"
        );
        remove_context(ContextId(ctx));
    }

    // -- element matching and serialization -------------------------------

    #[test]
    fn element_matches_and_closest() {
        let mut fx = setup(
            "<html><body><div id=\"a\" class=\"x\"><p id=\"b\" class=\"y\">t</p></div></body></html>",
        );
        let p = call_get_element_by_id(&mut fx, "b");
        let yes = str_val(&mut fx, "p.y");
        assert_eq!(
            n_matches(&mut fx.heap, p, &[yes]).unwrap(),
            Value::Bool(true)
        );
        let no = str_val(&mut fx, "span");
        assert_eq!(
            n_matches(&mut fx.heap, p, &[no]).unwrap(),
            Value::Bool(false)
        );
        let desc = str_val(&mut fx, "div p");
        assert_eq!(
            n_matches(&mut fx.heap, p, &[desc]).unwrap(),
            Value::Bool(true)
        );
        let closest_sel = str_val(&mut fx, "div.x");
        let found = n_closest(&mut fx.heap, p, &[closest_sel]).unwrap();
        assert_eq!(
            node_id_attr(&fx, node_of(&fx, found)),
            Some("a".to_string())
        );
        // closest includes the element itself
        let self_sel = str_val(&mut fx, "p");
        let me = n_closest(&mut fx.heap, p, &[self_sel]).unwrap();
        assert_eq!(node_of(&fx, me), node_of(&fx, p));
        let missing = str_val(&mut fx, "table");
        assert_eq!(n_closest(&mut fx.heap, p, &[missing]).unwrap(), Value::Null);
        // malformed selectors raise SyntaxError
        let bad = str_val(&mut fx, "div >");
        assert!(matches!(
            n_matches(&mut fx.heap, p, &[bad]),
            Err(NativeError::SyntaxError(_))
        ));
        assert!(matches!(
            n_closest(&mut fx.heap, p, &[bad]),
            Err(NativeError::SyntaxError(_))
        ));
    }

    #[test]
    fn query_selector_syntax_error_is_syntax_error() {
        let mut fx = setup("<html><body></body></html>");
        let doc_val = global_prop(&fx, "document");
        let bad = str_val(&mut fx, "div >");
        assert!(matches!(
            n_query_selector(&mut fx.heap, doc_val, &[bad]),
            Err(NativeError::SyntaxError(_))
        ));
        assert!(matches!(
            n_query_selector_all(&mut fx.heap, doc_val, &[bad]),
            Err(NativeError::SyntaxError(_))
        ));
        // valid selectors still work after the error path
        let ok = str_val(&mut fx, "body");
        assert!(matches!(
            n_query_selector(&mut fx.heap, doc_val, &[ok]).unwrap(),
            Value::Object(_)
        ));
    }

    #[test]
    fn document_get_elements_by_class_name() {
        let mut fx = setup(
            "<html><body><p class=\"x\">1</p><p class=\"x y\">2</p><span class=\"y\">3</span></body></html>",
        );
        let doc_val = global_prop(&fx, "document");
        let x = str_val(&mut fx, "x");
        let arr_val = n_get_elements_by_class_name(&mut fx.heap, doc_val, &[x]).unwrap();
        let Value::Object(arr) = arr_val else {
            panic!("not an array")
        };
        assert_eq!(
            fx.heap
                .get_property(arr, Wtf8::from_str("length"))
                .unwrap()
                .value,
            Value::Int(2)
        );
        let xy = str_val(&mut fx, "x y");
        let arr2 = n_get_elements_by_class_name(&mut fx.heap, doc_val, &[xy]).unwrap();
        let Value::Object(arr2) = arr2 else {
            panic!("not an array")
        };
        assert_eq!(
            fx.heap
                .get_property(arr2, Wtf8::from_str("length"))
                .unwrap()
                .value,
            Value::Int(1)
        );
        // empty query matches nothing
        let empty = str_val(&mut fx, "");
        let arr3 = n_get_elements_by_class_name(&mut fx.heap, doc_val, &[empty]).unwrap();
        let Value::Object(arr3) = arr3 else {
            panic!("not an array")
        };
        assert_eq!(
            fx.heap
                .get_property(arr3, Wtf8::from_str("length"))
                .unwrap()
                .value,
            Value::Int(0)
        );
    }

    #[test]
    fn document_get_elements_by_tag_name() {
        let mut fx = setup(
            "<html><head><title>t</title></head><body><p>1</p><p>2</p><span>3</span></body></html>",
        );
        let doc_val = global_prop(&fx, "document");
        let length_of = |fx: &mut Fixture, query: &str| -> i32 {
            let q = str_val(fx, query);
            let v = n_get_elements_by_tag_name(&mut fx.heap, doc_val, &[q]).unwrap();
            let Value::Object(arr) = v else {
                panic!("not an array")
            };
            match fx
                .heap
                .get_property(arr, Wtf8::from_str("length"))
                .unwrap()
                .value
            {
                Value::Int(n) => n,
                _ => panic!("length is not an int"),
            }
        };
        // ASCII case-insensitive for HTML-namespace elements.
        assert_eq!(length_of(&mut fx, "p"), 2);
        assert_eq!(length_of(&mut fx, "P"), 2);
        assert_eq!(length_of(&mut fx, "span"), 1);
        assert_eq!(length_of(&mut fx, "div"), 0);
        // "*" matches every element: html, head, title, body, p, p, span.
        assert_eq!(length_of(&mut fx, "*"), 7);
        // Static snapshot in document order: indexed entries.
        let star = str_val(&mut fx, "*");
        let v = n_get_elements_by_tag_name(&mut fx.heap, doc_val, &[star]).unwrap();
        let Value::Object(arr) = v else {
            panic!("not an array")
        };
        let first = fx
            .heap
            .get_property(arr, Wtf8::from_str("0"))
            .unwrap()
            .value;
        assert_eq!(prop_str(&fx, obj_of(first), "tagName"), "HTML");
        let last = fx
            .heap
            .get_property(arr, Wtf8::from_str("6"))
            .unwrap()
            .value;
        assert_eq!(prop_str(&fx, obj_of(last), "tagName"), "SPAN");
    }

    #[test]
    fn document_create_element_ns() {
        let mut fx = setup("<html><body></body></html>");
        let doc_val = global_prop(&fx, "document");
        let ns_of = |fx: &Fixture, w: Value| -> Namespace {
            match fx.doc.borrow().kind(node_of(fx, w)) {
                NodeKind::Element(e) => e.namespace.clone(),
                _ => panic!("not an element"),
            }
        };
        // SVG namespace: tag case preserved (no ASCII lowercasing).
        let svg_ns = str_val(&mut fx, "http://www.w3.org/2000/svg");
        let svg = str_val(&mut fx, "svg");
        let w = call_method(&mut fx, doc_val, n_create_element_ns, &[svg_ns, svg]);
        assert_eq!(ns_of(&fx, w), Namespace::Svg);
        assert_eq!(prop_str(&fx, obj_of(w), "tagName"), "SVG");
        // MathML namespace.
        let mml_ns = str_val(&mut fx, "http://www.w3.org/1998/Math/MathML");
        let math = str_val(&mut fx, "math");
        let w = call_method(&mut fx, doc_val, n_create_element_ns, &[mml_ns, math]);
        assert_eq!(ns_of(&fx, w), Namespace::MathMl);
        // null / undefined / "" / XHTML URI all mean the HTML namespace.
        let div = str_val(&mut fx, "div");
        let w = call_method(&mut fx, doc_val, n_create_element_ns, &[Value::Null, div]);
        assert_eq!(ns_of(&fx, w), Namespace::Html);
        let w = call_method(
            &mut fx,
            doc_val,
            n_create_element_ns,
            &[Value::Undefined, div],
        );
        assert_eq!(ns_of(&fx, w), Namespace::Html);
        let empty = str_val(&mut fx, "");
        let w = call_method(&mut fx, doc_val, n_create_element_ns, &[empty, div]);
        assert_eq!(ns_of(&fx, w), Namespace::Html);
        let xhtml = str_val(&mut fx, "http://www.w3.org/1999/xhtml");
        let w = call_method(&mut fx, doc_val, n_create_element_ns, &[xhtml, div]);
        assert_eq!(ns_of(&fx, w), Namespace::Html);
        assert_eq!(prop_str(&fx, obj_of(w), "tagName"), "DIV");
        // An arbitrary namespace URI is legal per DOM "validate and
        // extract": it is carried as `Namespace::Other`, never
        // mis-namespaced as HTML/SVG/MathML.
        let bogus = str_val(&mut fx, "http://example.com/ns");
        let w = call_method(&mut fx, doc_val, n_create_element_ns, &[bogus, div]);
        assert_eq!(
            ns_of(&fx, w),
            Namespace::Other("http://example.com/ns".into())
        );
        // An empty tag is still an `InvalidCharacterError` (surfaced as
        // `TypeError`: the engine has no `DOMException` yet).
        let empty_tag = str_val(&mut fx, "");
        let err = n_create_element_ns(&mut fx.heap, doc_val, &[svg_ns, empty_tag]);
        assert!(matches!(err, Err(NativeError::TypeError(_))));
        if let Err(NativeError::TypeError(msg)) = err {
            assert!(
                msg.contains("InvalidCharacterError"),
                "unexpected message: {msg}"
            );
        }
    }

    #[test]
    fn document_create_comment_and_fragment() {
        let mut fx = setup("<html><body></body></html>");
        let doc_val = global_prop(&fx, "document");
        // createComment: detached comment wrapper, data as textContent.
        let data = str_val(&mut fx, "a note");
        let c = call_method(&mut fx, doc_val, n_create_comment, &[data]);
        assert_eq!(prop_str(&fx, obj_of(c), "textContent"), "a note");
        assert_eq!(prop_val(&fx, obj_of(c), "parentNode"), Value::Null);
        assert!(matches!(
            fx.doc.borrow().kind(node_of(&fx, c)),
            NodeKind::Comment(_)
        ));
        // createDocumentFragment: detached empty fragment wrapper.
        let f = call_method(&mut fx, doc_val, n_create_document_fragment, &[]);
        assert_eq!(prop_val(&fx, obj_of(f), "parentNode"), Value::Null);
        assert!(matches!(
            fx.doc.borrow().kind(node_of(&fx, f)),
            NodeKind::DocumentFragment
        ));
        let kids = obj_of(prop_val(&fx, obj_of(f), "children"));
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(0));
    }

    #[test]
    fn element_inner_html_accessor() {
        let mut fx = setup("<html><body><div id=\"a\">hi <b>x</b></div></body></html>");
        // accessors live on the shared element prototype
        let proto = fx.apis.borrow().gc_roots.borrow().element_proto.unwrap();
        let acc = fx
            .heap
            .get_accessor(proto, Wtf8::from_str("innerHTML"))
            .expect("innerHTML accessor");
        assert!(matches!(acc.get, Value::Object(_)));
        assert!(matches!(acc.set, Value::Object(_)));
        let el = call_get_element_by_id(&mut fx, "a");
        let got = n_inner_html_get(&mut fx.heap, el, &[]).unwrap();
        assert_eq!(str_contents(&fx, got), "hi <b>x</b>");
        // setter re-parses the fragment and live props re-sync
        let new_html = str_val(&mut fx, "<p>new</p>");
        n_inner_html_set(&mut fx.heap, el, &[new_html]).unwrap();
        let got2 = n_inner_html_get(&mut fx.heap, el, &[]).unwrap();
        assert_eq!(str_contents(&fx, got2), "<p>new</p>");
        let Value::Object(o) = el else {
            panic!("not an object")
        };
        let text = fx
            .heap
            .get_property(o, Wtf8::from_str("textContent"))
            .unwrap()
            .value;
        assert_eq!(str_contents(&fx, text), "new");
    }

    #[test]
    fn element_outer_html_accessor() {
        let mut fx =
            setup("<html><body><div><p id=\"a\">old</p><span>s</span></div></body></html>");
        let proto = fx.apis.borrow().gc_roots.borrow().element_proto.unwrap();
        assert!(
            fx.heap
                .get_accessor(proto, Wtf8::from_str("outerHTML"))
                .is_some()
        );
        let el = call_get_element_by_id(&mut fx, "a");
        let got = n_outer_html_get(&mut fx.heap, el, &[]).unwrap();
        assert_eq!(str_contents(&fx, got), "<p id=\"a\">old</p>");
        let new_html = str_val(&mut fx, "<b>new</b>");
        n_outer_html_set(&mut fx.heap, el, &[new_html]).unwrap();
        // the old node is detached, its replacement holds its position
        let doc = fx.doc.borrow();
        let div = doc.get_elements_by_tag_name("div").item(0).unwrap();
        assert_eq!(doc.inner_html(div), "<b>new</b><span>s</span>");
        assert_eq!(doc.get_element_by_id("a"), None);
    }

    #[test]
    fn w79k_production_element_query_selector() {
        // w79k: production `Element.querySelector`/`querySelectorAll`,
        // scoped to the receiver's descendants. Fail-before: neither
        // name existed on `element_proto` (the shim versions are
        // stripped at upgrade), so table-model-fixup-2's first
        // step-body statement (`root.querySelector("[target=a]")`)
        // threw `callee is not a function` 40/40.
        let mut fx = setup(
            "<html><body><div id=\"root\" foo=\"\"><p id=\"p1\" class=\"a\">one</p><span id=\"tgt\" target=\"a\">t</span><section id=\"sec\"><p id=\"p2\" class=\"b\">two</p></section></div><p id=\"outside\" class=\"a\">out</p></body></html>",
        );
        let proto = fx.apis.borrow().gc_roots.borrow().element_proto.unwrap();
        assert!(
            fx.heap
                .get_property(proto, Wtf8::from_str("querySelector"))
                .is_some(),
            "element_proto must define querySelector"
        );
        assert!(
            fx.heap
                .get_property(proto, Wtf8::from_str("querySelectorAll"))
                .is_some(),
            "element_proto must define querySelectorAll"
        );
        let root = call_get_element_by_id(&mut fx, "root");
        let p1 = call_get_element_by_id(&mut fx, "p1");
        let tgt = call_get_element_by_id(&mut fx, "tgt");
        let p2 = call_get_element_by_id(&mut fx, "p2");
        let qs = |fx: &mut Fixture, recv: Value, sel: &str| -> Value {
            let s = str_val(fx, sel);
            n_element_query_selector(&mut fx.heap, recv, &[s]).unwrap()
        };
        let qsa = |fx: &mut Fixture, recv: Value, sel: &str| -> Vec<NodeId> {
            let s = str_val(fx, sel);
            let arr = n_element_query_selector_all(&mut fx.heap, recv, &[s]).unwrap();
            let Value::Object(o) = arr else {
                panic!("querySelectorAll must return an object")
            };
            let len = match fx
                .heap
                .get_property(o, Wtf8::from_str("length"))
                .unwrap()
                .value
            {
                Value::Int(n) => n,
                _ => panic!("length must be an int"),
            };
            (0..len)
                .map(|i| {
                    let v = fx
                        .heap
                        .get_property(o, Wtf8::from_str(&i.to_string()))
                        .unwrap()
                        .value;
                    node_of(fx, v)
                })
                .collect()
        };
        // The fixup-2 statement shape: attribute selector on the root.
        // (Each step is bound before the next read: the query closures
        // take `&mut Fixture`, so a result and its expected node cannot
        // be compared inside one expression.)
        let tgt_id = node_of(&fx, tgt);
        let hit = qs(&mut fx, root, "[target=a]");
        assert_eq!(node_of(&fx, hit), tgt_id);
        // First match in document order; the scope element never matches.
        let p1_id = node_of(&fx, p1);
        let first_p = qs(&mut fx, root, "p");
        assert_eq!(node_of(&fx, first_p), p1_id);
        assert_eq!(qs(&mut fx, root, "div"), Value::Null);
        assert_eq!(qs(&mut fx, root, "#root"), Value::Null);
        assert_eq!(qs(&mut fx, root, "em"), Value::Null);
        // Descendants only: the outside `.a` paragraph is invisible.
        let only_a = qsa(&mut fx, root, ".a");
        assert_eq!(only_a, vec![p1_id]);
        // Comma-group union in document order, not group order.
        let tgt_id2 = node_of(&fx, tgt);
        let p2_id = node_of(&fx, p2);
        let both = vec![p1_id, tgt_id2, p2_id];
        assert_eq!(qsa(&mut fx, root, "p, span"), both);
        assert_eq!(qsa(&mut fx, root, "span, p"), both);
        assert_eq!(qsa(&mut fx, root, "em"), Vec::<NodeId>::new());
        // Bad selector raises SyntaxError, like document.querySelector.
        let bad = str_val(&mut fx, ">>>");
        assert!(matches!(
            n_element_query_selector(&mut fx.heap, root, &[bad]),
            Err(NativeError::SyntaxError(_))
        ));
        let bad_all = str_val(&mut fx, "p, >>>");
        assert!(matches!(
            n_element_query_selector_all(&mut fx.heap, root, &[bad_all]),
            Err(NativeError::SyntaxError(_))
        ));
        // w79k follow-up: `hasAttribute` on the prototype, present
        // and absent cases (fixup-2 reads `root.hasAttribute("unequal")`).
        assert!(
            fx.heap
                .get_property(proto, Wtf8::from_str("hasAttribute"))
                .is_some(),
            "element_proto must define hasAttribute"
        );
        let root_id_attr = str_val(&mut fx, "id");
        let has_id = n_has_attribute(&mut fx.heap, root, &[root_id_attr]).unwrap();
        assert_eq!(has_id, Value::Bool(true));
        let missing_attr = str_val(&mut fx, "unequal");
        let has_unequal = n_has_attribute(&mut fx.heap, root, &[missing_attr]).unwrap();
        assert_eq!(has_unequal, Value::Bool(false));
        // The document wrapper keeps its document-wide form (its own
        // `doc_obj` definitions shadow the prototype methods).
        let doc_val = global_prop(&fx, "document");
        let outside = call_get_element_by_id(&mut fx, "outside");
        let outside_sel = str_val(&mut fx, "#outside");
        let doc_hit = n_query_selector(&mut fx.heap, doc_val, &[outside_sel]).unwrap();
        assert_eq!(node_of(&fx, doc_hit), node_of(&fx, outside));
        // w79fix pins for previously unpinned-but-correct behavior.
        // Empty-valued attribute: present, with an empty value.
        let foo_attr = str_val(&mut fx, "foo");
        let has_foo = n_has_attribute(&mut fx.heap, root, &[foo_attr]).unwrap();
        assert_eq!(has_foo, Value::Bool(true));
        let foo_val = n_get_attribute(&mut fx.heap, root, &[foo_attr]).unwrap();
        assert_eq!(str_contents(&fx, foo_val), "");
        // Attribute names are ASCII case-insensitive on HTML elements.
        let id_upper = str_val(&mut fx, "ID");
        let has_id_upper = n_has_attribute(&mut fx.heap, root, &[id_upper]).unwrap();
        assert_eq!(has_id_upper, Value::Bool(true));
        // `*` returns elements only: the text nodes inside the root
        // ("one", "t", "two") are not in the result.
        let sec = call_get_element_by_id(&mut fx, "sec");
        let sec_id = node_of(&fx, sec);
        let star = qsa(&mut fx, root, "*");
        assert_eq!(star, vec![p1_id, tgt_id2, sec_id, p2_id]);
        // Scope-relative selectors on an element (w79fix): a leading
        // combinator is implicitly scoped to the receiver, `:scope`
        // denotes the receiver, and mixed groups union in order.
        let root_id = node_of(&fx, root);
        let child_p = qs(&mut fx, root, "> p");
        assert_eq!(node_of(&fx, child_p), p1_id);
        let scope_child_p = qs(&mut fx, root, ":scope > p");
        assert_eq!(node_of(&fx, scope_child_p), p1_id);
        let scope_self = qs(&mut fx, root, ":scope");
        assert_eq!(node_of(&fx, scope_self), root_id);
        assert_eq!(qsa(&mut fx, root, "> p"), vec![p1_id]);
        assert_eq!(qsa(&mut fx, root, ":scope"), vec![root_id]);
        assert_eq!(qsa(&mut fx, root, ":scope p"), vec![p1_id, p2_id]);
        assert_eq!(qsa(&mut fx, root, ":scope > p, span"), vec![p1_id, tgt_id2]);
        // The same strings stay invalid on the document: the
        // scope-relative handling lives on the element path only.
        for sel in ["> p", ":scope > p", ":scope"] {
            let s = str_val(&mut fx, sel);
            assert!(
                matches!(
                    n_query_selector(&mut fx.heap, doc_val, &[s]),
                    Err(NativeError::SyntaxError(_))
                ),
                "document.querySelector({sel:?}) must throw SyntaxError"
            );
        }
        // Document dispatch through real property lookup, not a
        // direct native call: the function resolved off `doc_obj`
        // must be the document-wide native (not the element
        // prototype's), and invoking it must query document-wide.
        let Value::Object(doc_obj) = doc_val else {
            panic!("document must be an object")
        };
        let doc_qs = fx
            .heap
            .get_property(doc_obj, Wtf8::from_str("querySelector"))
            .unwrap()
            .value;
        let proto_qs = fx
            .heap
            .get_property(proto, Wtf8::from_str("querySelector"))
            .unwrap()
            .value;
        assert_ne!(doc_qs, proto_qs, "doc_obj must shadow querySelector");
        let Value::Object(doc_qs_obj) = doc_qs else {
            panic!("document.querySelector must be a function object")
        };
        let ObjectKind::NativeFunction(doc_qs_fn) = object_kind(doc_qs_obj) else {
            panic!("document.querySelector must be a native function")
        };
        assert!(
            std::ptr::fn_addr_eq(doc_qs_fn, {
                let expected: NativeFn = n_query_selector;
                expected
            }),
            "doc_obj.querySelector must be the document native"
        );
        let outside_sel2 = str_val(&mut fx, "#outside");
        let resolved_hit = doc_qs_fn(&mut fx.heap, doc_val, &[outside_sel2]).unwrap();
        assert_eq!(node_of(&fx, resolved_hit), node_of(&fx, outside));
        // And the members `Document` does not have are shadowed to
        // `undefined` on `doc_obj` (w79fix), not resolved through
        // the prototype to `false` / `null`.
        for name in [
            "hasAttribute",
            "nextElementSibling",
            "previousElementSibling",
        ] {
            assert_eq!(
                fx.heap
                    .get_property(doc_obj, Wtf8::from_str(name))
                    .unwrap()
                    .value,
                Value::Undefined,
                "document.{name} must be undefined"
            );
        }
        // Detached subtree: queries stay inside it (and scope-relative
        // selectors work there too), never leaking into the document.
        let div_tag = str_val(&mut fx, "div");
        let detached = n_create_element(&mut fx.heap, doc_val, &[div_tag]).unwrap();
        let p_tag = str_val(&mut fx, "p");
        let dp = n_create_element(&mut fx.heap, doc_val, &[p_tag]).unwrap();
        n_append_child(&mut fx.heap, detached, &[dp]).unwrap();
        let dp_id = node_of(&fx, dp);
        let dp_hit = qs(&mut fx, detached, "p");
        assert_eq!(node_of(&fx, dp_hit), dp_id);
        let dp_scope = qs(&mut fx, detached, "> p");
        assert_eq!(node_of(&fx, dp_scope), dp_id);
        let dp_self = qs(&mut fx, detached, ":scope");
        assert_eq!(node_of(&fx, dp_self), node_of(&fx, detached));
        assert_eq!(qs(&mut fx, detached, "#outside"), Value::Null);
    }

    #[test]
    fn w79fix_scope_relative_edges() {
        // w79fix round-2 pins: `:scope*` is scope-relative, a
        // `:scope` compound in a non-leading position evaluates
        // against receiver identity (never via the shared parser),
        // detached mixed groups order in tree order, sibling steps
        // return element siblings outside the receiver's subtree,
        // and a bad compound throws even with zero candidates.
        let mut fx = setup(
            "<html><body><div id=\"recv\"></div>text<!--c--><p id=\"s1\">one</p><p id=\"s2\">two</p></body></html>",
        );
        let recv = call_get_element_by_id(&mut fx, "recv");
        let s1 = call_get_element_by_id(&mut fx, "s1");
        let s2 = call_get_element_by_id(&mut fx, "s2");
        let recv_id = node_of(&fx, recv);
        let s1_id = node_of(&fx, s1);
        let s2_id = node_of(&fx, s2);
        let qs = |fx: &mut Fixture, r: Value, sel: &str| -> Value {
            let s = str_val(fx, sel);
            n_element_query_selector(&mut fx.heap, r, &[s]).unwrap()
        };
        let qsa = |fx: &mut Fixture, r: Value, sel: &str| -> Vec<NodeId> {
            let s = str_val(fx, sel);
            let arr = n_element_query_selector_all(&mut fx.heap, r, &[s]).unwrap();
            let Value::Object(o) = arr else {
                panic!("querySelectorAll must return an object")
            };
            let len = match fx
                .heap
                .get_property(o, Wtf8::from_str("length"))
                .unwrap()
                .value
            {
                Value::Int(n) => n,
                _ => panic!("length must be an int"),
            };
            (0..len)
                .map(|i| {
                    let v = fx
                        .heap
                        .get_property(o, Wtf8::from_str(&i.to_string()))
                        .unwrap()
                        .value;
                    node_of(fx, v)
                })
                .collect()
        };
        // `:scope*` returns the receiver (fail-before: SyntaxError).
        let star_hit = qs(&mut fx, recv, ":scope*");
        assert_eq!(node_of(&fx, star_hit), recv_id);
        assert_eq!(qsa(&mut fx, recv, ":scope*"), vec![recv_id]);
        // `:scope` is not its own child (fail-before: SyntaxError).
        assert_eq!(qs(&mut fx, recv, ":scope > :scope"), Value::Null);
        assert_eq!(qsa(&mut fx, recv, ":scope > :scope"), Vec::<NodeId>::new());
        // A later `div:scope` compound must not throw either.
        assert_eq!(
            qsa(&mut fx, recv, ":scope + div:scope"),
            Vec::<NodeId>::new()
        );
        // Sibling steps return siblings outside the receiver's
        // subtree, element-only (the text and comment between the
        // receiver and `s1` are skipped).
        let plus_hit = qs(&mut fx, recv, ":scope + p");
        assert_eq!(node_of(&fx, plus_hit), s1_id);
        assert_eq!(qsa(&mut fx, recv, ":scope ~ p"), vec![s1_id, s2_id]);
        let lead_plus_hit = qs(&mut fx, recv, "+ p");
        assert_eq!(node_of(&fx, lead_plus_hit), s1_id);
        assert_eq!(qsa(&mut fx, recv, "~ p"), vec![s1_id, s2_id]);
        // Up-front validation: a bad compound throws even though
        // the childless receiver has zero candidates.
        let bad = str_val(&mut fx, ":scope > :bad");
        assert!(matches!(
            n_element_query_selector_all(&mut fx.heap, recv, &[bad]),
            Err(NativeError::SyntaxError(_))
        ));
        // Detached mixed groups in tree order, not group order
        // (fail-before: `[p, scope]`).
        let doc_val = global_prop(&fx, "document");
        let div_tag = str_val(&mut fx, "div");
        let detached = n_create_element(&mut fx.heap, doc_val, &[div_tag]).unwrap();
        let p_tag = str_val(&mut fx, "p");
        let dp = n_create_element(&mut fx.heap, doc_val, &[p_tag]).unwrap();
        n_append_child(&mut fx.heap, detached, &[dp]).unwrap();
        let detached_id = node_of(&fx, detached);
        let dp_id = node_of(&fx, dp);
        assert_eq!(
            qsa(&mut fx, detached, "p, :scope"),
            vec![detached_id, dp_id]
        );
        assert_eq!(
            qsa(&mut fx, detached, ":scope, p"),
            vec![detached_id, dp_id]
        );
        assert_eq!(qsa(&mut fx, detached, "p"), vec![dp_id]);
    }

    #[test]
    fn w79_production_element_siblings() {
        // w79 item H (fail-before: production wrappers expose no
        // `nextElementSibling`/`previousElementSibling` — the shim
        // accessor is stripped at upgrade and `element_proto` never
        // defines one — so table-model-fixup-2's DOMContentLoaded
        // handler throws `cannot read property
        // 'nextElementSibling' of Undefined` before registering any
        // async_test). Element siblings only: text and comment nodes
        // are skipped, `null` at the ends.
        let mut fx = setup(
            "<html><body><hr id=\"h\"><!--sep--><p id=\"p1\">one</p>text<p id=\"p2\">two</p><div id=\"root\"></div><span id=\"last\"></span></body></html>",
        );
        let proto = fx.apis.borrow().gc_roots.borrow().element_proto.unwrap();
        assert!(
            fx.heap
                .get_accessor(proto, Wtf8::from_str("nextElementSibling"))
                .is_some()
        );
        assert!(
            fx.heap
                .get_accessor(proto, Wtf8::from_str("previousElementSibling"))
                .is_some()
        );
        let next = |fx: &mut Fixture, v: Value| -> Value {
            n_next_element_sibling_get(&mut fx.heap, v, &[]).unwrap()
        };
        let prev = |fx: &mut Fixture, v: Value| -> Value {
            n_previous_element_sibling_get(&mut fx.heap, v, &[]).unwrap()
        };
        let h = call_get_element_by_id(&mut fx, "h");
        let p1 = call_get_element_by_id(&mut fx, "p1");
        let p2 = call_get_element_by_id(&mut fx, "p2");
        let root = call_get_element_by_id(&mut fx, "root");
        let last = call_get_element_by_id(&mut fx, "last");
        let h_id = node_of(&fx, h);
        let p1_id = node_of(&fx, p1);
        let p2_id = node_of(&fx, p2);
        let root_id = node_of(&fx, root);
        let last_id = node_of(&fx, last);
        // Skips the comment after <hr> and the text between the <p>s.
        // (Each step is bound before the next read: the getter takes
        // `&mut Fixture`, so chained calls cannot nest in one
        // expression.)
        let n_h = next(&mut fx, h);
        assert_eq!(node_of(&fx, n_h), p1_id);
        let n_p1 = next(&mut fx, p1);
        assert_eq!(node_of(&fx, n_p1), p2_id);
        let n_p2 = next(&mut fx, p2);
        assert_eq!(node_of(&fx, n_p2), root_id);
        let n_root = next(&mut fx, root);
        assert_eq!(node_of(&fx, n_root), last_id);
        assert_eq!(next(&mut fx, last), Value::Null);
        assert_eq!(prev(&mut fx, h), Value::Null);
        let pr_p1 = prev(&mut fx, p1);
        assert_eq!(node_of(&fx, pr_p1), h_id);
        let pr_p2 = prev(&mut fx, p2);
        assert_eq!(node_of(&fx, pr_p2), p1_id);
        let pr_last = prev(&mut fx, last);
        assert_eq!(node_of(&fx, pr_last), root_id);
        // The fixup-2 handler chain, element by element: `hr` ->
        // first <p> -> second <p> (desc) -> <div> (root). Each step
        // must be a real wrapper, never `undefined`, so the chain
        // never throws.
        let inner = next(&mut fx, h);
        let desc = next(&mut fx, inner);
        assert_eq!(node_of(&fx, desc), p2_id);
        let chained_root = next(&mut fx, desc);
        assert_eq!(node_of(&fx, chained_root), root_id);
        // Detached subtree: the same element-only skipping and
        // `null` ends, with a text node between the elements.
        let doc_val = global_prop(&fx, "document");
        let div_tag = str_val(&mut fx, "div");
        let detached = n_create_element(&mut fx.heap, doc_val, &[div_tag]).unwrap();
        let span_tag = str_val(&mut fx, "span");
        let s1 = n_create_element(&mut fx.heap, doc_val, &[span_tag]).unwrap();
        let s2 = n_create_element(&mut fx.heap, doc_val, &[span_tag]).unwrap();
        let text_val = str_val(&mut fx, "gap");
        let gap = n_create_text_node(&mut fx.heap, doc_val, &[text_val]).unwrap();
        n_append_child(&mut fx.heap, detached, &[s1]).unwrap();
        n_append_child(&mut fx.heap, detached, &[gap]).unwrap();
        n_append_child(&mut fx.heap, detached, &[s2]).unwrap();
        let s1_id = node_of(&fx, s1);
        let s2_id = node_of(&fx, s2);
        let n_s1 = next(&mut fx, s1);
        assert_eq!(node_of(&fx, n_s1), s2_id);
        assert_eq!(next(&mut fx, s2), Value::Null);
        assert_eq!(prev(&mut fx, s1), Value::Null);
        let pr_s2 = prev(&mut fx, s2);
        assert_eq!(node_of(&fx, pr_s2), s1_id);
    }

    // -- events ---------------------------------------------------------

    fn add_listener(fx: &mut Fixture, target: Value, etype: &str, listener: Value, capture: bool) {
        let t = str_val(fx, etype);
        n_add_event_listener(&mut fx.heap, target, &[t, listener, Value::Bool(capture)]).unwrap();
    }

    fn plain_event(fx: &mut Fixture, etype: &str, bubbles: bool) -> Value {
        let t = str_val(fx, etype);
        let o = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(o, "type", Property::data(t))
            .unwrap();
        fx.heap
            .define_property_str(o, "bubbles", Property::data(Value::Bool(bubbles)))
            .unwrap();
        Value::Object(o)
    }

    fn dispatch_log(fx: &Fixture) -> Vec<(Value, Option<String>)> {
        let inv = fx.invoker.borrow();
        inv.calls
            .borrow()
            .iter()
            .map(|c| {
                let target_id = match c.this {
                    Value::Object(o) => match fx
                        .heap
                        .get_property(o, Wtf8::from_str(NODE_KEY))
                        .unwrap()
                        .value
                    {
                        Value::Int(h) => {
                            let n = fx.apis.borrow().node_handles[&(h as u32)];
                            node_id_attr(fx, n)
                        }
                        _ => None,
                    },
                    _ => None,
                };
                (c.func, target_id)
            })
            .collect()
    }

    #[test]
    fn event_dispatch_order_capture_target_bubble() {
        let mut fx =
            setup("<html><body><div id=\"outer\"><div id=\"inner\"></div></div></body></html>");
        let outer = call_get_element_by_id(&mut fx, "outer");
        let inner = call_get_element_by_id(&mut fx, "inner");

        let la = probe_listener(&mut fx.heap);
        let lb = probe_listener(&mut fx.heap);
        let lc = probe_listener(&mut fx.heap);
        let ld = probe_listener(&mut fx.heap);
        add_listener(&mut fx, outer, "click", la, true); // outer capture
        add_listener(&mut fx, inner, "click", lb, false); // inner bubble (registered 1st)
        add_listener(&mut fx, inner, "click", lc, true); // inner capture (registered 2nd)
        add_listener(&mut fx, outer, "click", ld, false); // outer bubble

        let ev = plain_event(&mut fx, "click", true);
        let r = n_dispatch_event(&mut fx.heap, inner, &[ev]).unwrap();
        assert_eq!(r, Value::Bool(true));

        // Capture (outer) -> target in registration order (b, c) -> bubble (outer).
        let log = dispatch_log(&fx);
        let funcs: Vec<Value> = log.iter().map(|(f, _)| *f).collect();
        assert_eq!(funcs, vec![la, lb, lc, ld]);
        let targets: Vec<Option<&str>> = log.iter().map(|(_, id)| id.as_deref()).collect();
        assert_eq!(
            targets,
            vec![Some("outer"), Some("inner"), Some("inner"), Some("outer")]
        );

        // Non-bubbling: the outer bubble listener does not fire.
        fx.invoker.borrow().calls.borrow_mut().clear();
        let ev2 = plain_event(&mut fx, "click", false);
        n_dispatch_event(&mut fx.heap, inner, &[ev2]).unwrap();
        let log2 = dispatch_log(&fx);
        let funcs2: Vec<Value> = log2.iter().map(|(f, _)| *f).collect();
        assert_eq!(funcs2, vec![la, lb, lc]);
    }

    #[test]
    fn remove_event_listener_stops_dispatch() {
        let mut fx = setup("<html><body><div id=\"x\"></div></body></html>");
        let el = call_get_element_by_id(&mut fx, "x");
        // The same function Value must be used for add and remove (JS
        // function identity): a fresh wrapper is a different function.
        let t = str_val(&mut fx, "click");
        let l = probe_listener(&mut fx.heap);
        n_add_event_listener(&mut fx.heap, el, &[t, l, Value::Bool(false)]).unwrap();
        let t2 = str_val(&mut fx, "click");
        n_remove_event_listener(&mut fx.heap, el, &[t2, l, Value::Bool(false)]).unwrap();
        let ev = plain_event(&mut fx, "click", true);
        n_dispatch_event(&mut fx.heap, el, &[ev]).unwrap();
        assert!(fx.invoker.borrow().calls.borrow().is_empty());
    }

    #[test]
    fn once_option_removed_after_first_dispatch() {
        let mut fx = setup("<html><body><div id=\"x\"></div></body></html>");
        let el = call_get_element_by_id(&mut fx, "x");
        let t = str_val(&mut fx, "click");
        let l = probe_listener(&mut fx.heap);
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "once", Property::data(Value::Bool(true)))
            .unwrap();
        n_add_event_listener(&mut fx.heap, el, &[t, l, Value::Object(opts)]).unwrap();
        let ev = plain_event(&mut fx, "click", false);
        n_dispatch_event(&mut fx.heap, el, &[ev]).unwrap();
        let ev2 = plain_event(&mut fx, "click", false);
        n_dispatch_event(&mut fx.heap, el, &[ev2]).unwrap();
        assert_eq!(
            fx.invoker.borrow().calls.borrow().len(),
            1,
            "a `once` listener must fire exactly once across dispatches"
        );
    }

    fn capture_true_get(
        _heap: &mut Heap,
        _this: Value,
        _args: &[Value],
    ) -> Result<Value, NativeError> {
        Ok(Value::Bool(true))
    }

    #[test]
    fn listener_options_getter_and_inherited_capture() {
        let mut fx = setup("<html><body><div id=\"x\"></div></body></html>");
        let el = call_get_element_by_id(&mut fx, "x");
        // `capture` from an accessor getter: the getter runs.
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        def_accessor(
            &mut fx.heap,
            opts,
            "capture",
            capture_true_get,
            n_readonly_set,
        )
        .unwrap();
        let t = str_val(&mut fx, "click");
        let l = probe_listener(&mut fx.heap);
        n_add_event_listener(&mut fx.heap, el, &[t, l, Value::Object(opts)]).unwrap();
        // `capture` inherited through the prototype chain.
        let proto = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(proto, "capture", Property::data(Value::Bool(true)))
            .unwrap();
        let opts2 = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap.set_prototype(opts2, Value::Object(proto));
        let t3 = str_val(&mut fx, "click");
        let l2 = probe_listener(&mut fx.heap);
        n_add_event_listener(&mut fx.heap, el, &[t3, l2, Value::Object(opts2)]).unwrap();
        // Removal with a plain `false` must not remove either: both
        // registered with capture=true.
        let t4 = str_val(&mut fx, "click");
        n_remove_event_listener(&mut fx.heap, el, &[t4, l, Value::Bool(false)]).unwrap();
        let t5 = str_val(&mut fx, "click");
        n_remove_event_listener(&mut fx.heap, el, &[t5, l2, Value::Bool(false)]).unwrap();
        let ev = plain_event(&mut fx, "click", false);
        n_dispatch_event(&mut fx.heap, el, &[ev]).unwrap();
        assert_eq!(
            fx.invoker.borrow().calls.borrow().len(),
            2,
            "getter/inherited capture:true registrations survive a capture:false removal"
        );
        // Removal with matching capture:true removes.
        let t6 = str_val(&mut fx, "click");
        n_remove_event_listener(&mut fx.heap, el, &[t6, l, Value::Bool(true)]).unwrap();
        let t7 = str_val(&mut fx, "click");
        n_remove_event_listener(&mut fx.heap, el, &[t7, l2, Value::Bool(true)]).unwrap();
        fx.invoker.borrow().calls.borrow_mut().clear();
        let ev2 = plain_event(&mut fx, "click", false);
        n_dispatch_event(&mut fx.heap, el, &[ev2]).unwrap();
        assert!(fx.invoker.borrow().calls.borrow().is_empty());
    }

    #[test]
    fn event_wrapper_post_dispatch_state() {
        let mut fx = setup("<html><body><div id=\"x\"></div></body></html>");
        let el = call_get_element_by_id(&mut fx, "x");
        let l = probe_listener(&mut fx.heap);
        add_listener(&mut fx, el, "click", l, false);
        let ev = plain_event(&mut fx, "click", false);
        n_dispatch_event(&mut fx.heap, el, &[ev]).unwrap();
        let evw = fx.invoker.borrow().calls.borrow()[0]
            .arg0
            .expect("event arg");
        // `target` is retained after dispatch; `currentTarget` and
        // `eventPhase` reset (DOM).
        let target = n_event_target_get(&mut fx.heap, evw, &[]).unwrap();
        assert_eq!(node_of(&fx, target), node_of(&fx, el));
        assert_eq!(
            n_event_current_target_get(&mut fx.heap, evw, &[]).unwrap(),
            Value::Null
        );
        assert_eq!(
            n_event_phase_get(&mut fx.heap, evw, &[]).unwrap(),
            Value::Int(0)
        );
        // Script-initiated dispatches are untrusted; `timeStamp` is numeric.
        assert_eq!(
            n_event_is_trusted_get(&mut fx.heap, evw, &[]).unwrap(),
            Value::Bool(false)
        );
        assert!(matches!(
            n_event_time_stamp_get(&mut fx.heap, evw, &[]).unwrap(),
            Value::Float(_)
        ));
        assert_eq!(
            n_event_default_prevented_get(&mut fx.heap, evw, &[]).unwrap(),
            Value::Bool(false)
        );
    }

    #[test]
    fn event_composed_path_cancel_bubble_return_value() {
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.log = []; \
             globalThis.saved = null; \
             var inner = document.getElementById('inner'); \
             var outer = document.getElementById('outer'); \
             inner.addEventListener('click', function(e) { \
               saved = e; \
               var p = e.composedPath(); \
               log.push('len=' + p.length); \
               log.push('first-is-inner=' + (p[0] === inner)); \
               log.push('cancelBubble=' + e.cancelBubble); \
               e.cancelBubble = true; \
               log.push('cancelBubble-after=' + e.cancelBubble); \
               log.push('returnValue=' + e.returnValue); \
               e.returnValue = false; \
               log.push('returnValue-after=' + e.returnValue); \
               log.push('defaultPrevented=' + e.defaultPrevented); \
             }); \
             outer.addEventListener('click', function() { log.push('outer-ran'); });",
        )
        .unwrap();
        // `cancelable: true`: a real `click` is cancelable (UI Events),
        // and per the DOM Standard `preventDefault()` — including its
        // legacy alias `returnValue = false` below — is a no-op on a
        // non-cancelable event, so the dispatch must opt into
        // cancelability for the cancellation assertions to apply.
        vm.eval(
            "document.getElementById('inner').dispatchEvent({type: 'click', bubbles: true, cancelable: true});",
        )
        .unwrap();
        // `cancelBubble = true` stopped the bubble: the outer listener
        // never ran.
        assert_eq!(
            eval_log(&mut vm, "log.join('|');"),
            "len=5|first-is-inner=true|cancelBubble=false|cancelBubble-after=true|\
             returnValue=true|returnValue-after=false|defaultPrevented=true"
        );
        // Outside dispatch the path is empty (DOM).
        assert_eq!(
            eval_log(&mut vm, "String(saved.composedPath().length);"),
            "0"
        );
        remove_context(ctx);
    }

    // -- viewport scroll API --------------------------------------------

    fn scroll_offset(fx: &Fixture) -> (f32, f32) {
        fx.apis.borrow().scroll.offset()
    }

    fn set_scroll_max(fx: &Fixture, max: (f32, f32)) {
        fx.apis.borrow().scroll.set_max_offset(max);
    }

    fn scroll_listener_calls(fx: &Fixture) -> usize {
        fx.invoker.borrow().calls.borrow().len()
    }

    #[test]
    fn scroll_to_and_aliases_share_one_offset() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        n_scroll_to(&mut fx.heap, global, &[Value::Int(300), Value::Int(900)]).unwrap();
        // y clamps to the content bound; scrollX/scrollY and
        // pageXOffset/pageYOffset read the same offset.
        assert_eq!(scroll_offset(&fx), (300.0, 800.0));
        assert_eq!(
            n_scroll_x_get(&mut fx.heap, global, &[]).unwrap(),
            Value::Float(300.0)
        );
        assert_eq!(
            n_scroll_y_get(&mut fx.heap, global, &[]).unwrap(),
            Value::Float(800.0)
        );
        let get = |fx: &Fixture, name: &str| {
            let acc = fx
                .heap
                .get_accessor(fx.global, Wtf8::from_str(name))
                .unwrap_or_else(|| panic!("{name} accessor installed"));
            assert!(matches!(acc.get, Value::Object(_)));
            assert!(matches!(acc.set, Value::Object(_)));
        };
        // pageXOffset/pageYOffset are the same accessors under another name.
        get(&fx, "pageXOffset");
        get(&fx, "pageYOffset");
        get(&fx, "scrollX");
        get(&fx, "scrollY");

        // Negative targets clamp at zero.
        n_scroll_to(&mut fx.heap, global, &[Value::Int(-5), Value::Int(-5)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 0.0));

        // The `scroll` alias behaves like `scrollTo`.
        n_scroll_to(&mut fx.heap, global, &[Value::Int(10), Value::Int(20)]).unwrap();
        assert_eq!(scroll_offset(&fx), (10.0, 20.0));
    }

    #[test]
    fn scroll_by_is_relative_and_clamped() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        n_scroll_by(&mut fx.heap, global, &[Value::Int(100), Value::Int(50)]).unwrap();
        assert_eq!(scroll_offset(&fx), (100.0, 50.0));
        n_scroll_by(
            &mut fx.heap,
            global,
            &[Value::Int(10_000), Value::Int(10_000)],
        )
        .unwrap();
        assert_eq!(scroll_offset(&fx), (1000.0, 800.0));
        n_scroll_by(&mut fx.heap, global, &[Value::Int(-2000), Value::Int(0)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 800.0));
    }

    #[test]
    fn scroll_to_accepts_options_object() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let behavior = str_val(&mut fx, "smooth");
        fx.heap
            .define_property_str(opts, "top", Property::data(Value::Int(123)))
            .unwrap();
        fx.heap
            .define_property_str(opts, "behavior", Property::data(behavior))
            .unwrap();
        n_scroll_to(&mut fx.heap, global, &[Value::Object(opts)]).unwrap();
        // `behavior: "smooth"` defers to the embedder: the offset is
        // untouched here, and a pending smooth request is recorded.
        // Missing `left` keeps the current x at drain time.
        assert_eq!(scroll_offset(&fx), (0.0, 0.0));
        assert_eq!(
            take_pending_smooth_scroll(fx.ctx.0),
            Some(PendingSmoothScroll {
                x: Some(0.0),
                y: Some(123.0),
                relative: false,
            })
        );
        // Drained: a second take finds nothing.
        assert_eq!(take_pending_smooth_scroll(fx.ctx.0), None);
    }

    #[test]
    fn scroll_to_smooth_cancelled_by_instant_scroll() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        // A smooth request is pending...
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "top", Property::data(Value::Int(500)))
            .unwrap();
        let __sv1 = str_val(&mut fx, "smooth");
        fx.heap
            .define_property_str(opts, "behavior", Property::data(__sv1))
            .unwrap();
        n_scroll_to(&mut fx.heap, global, &[Value::Object(opts)]).unwrap();
        assert!(take_pending_smooth_scroll(fx.ctx.0).is_some());

        // ...until an instant scroll cancels it and applies at once.
        n_scroll_to(&mut fx.heap, global, &[Value::Int(10), Value::Int(20)]).unwrap();
        assert_eq!(scroll_offset(&fx), (10.0, 20.0));
        assert_eq!(take_pending_smooth_scroll(fx.ctx.0), None);
    }

    #[test]
    fn scroll_to_honors_css_smooth_default() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        // Without an explicit `behavior`, the viewport's CSS
        // `scroll-behavior` default decides: `smooth` defers to the
        // embedder even for the bare `(x, y)` form.
        fx.apis.borrow().scroll.set_smooth_default(true);
        n_scroll_to(&mut fx.heap, global, &[Value::Int(0), Value::Int(300)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 0.0));
        assert_eq!(
            take_pending_smooth_scroll(fx.ctx.0),
            Some(PendingSmoothScroll {
                x: Some(0.0),
                y: Some(300.0),
                relative: false,
            })
        );

        // `behavior: "instant"` overrides the CSS default: synchronous.
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "top", Property::data(Value::Int(100)))
            .unwrap();
        let __sv2 = str_val(&mut fx, "instant");
        fx.heap
            .define_property_str(opts, "behavior", Property::data(__sv2))
            .unwrap();
        n_scroll_to(&mut fx.heap, global, &[Value::Object(opts)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 100.0));
        assert_eq!(take_pending_smooth_scroll(fx.ctx.0), None);

        // An unknown `behavior` keyword is a TypeError and scrolls
        // nothing.
        let opts2 = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts2, "top", Property::data(Value::Int(200)))
            .unwrap();
        let __sv3 = str_val(&mut fx, "fast");
        fx.heap
            .define_property_str(opts2, "behavior", Property::data(__sv3))
            .unwrap();
        assert!(matches!(
            n_scroll_to(&mut fx.heap, global, &[Value::Object(opts2)]),
            Err(NativeError::TypeError(_))
        ));
        assert_eq!(scroll_offset(&fx), (0.0, 100.0));
    }

    #[test]
    fn scroll_by_accepts_options_dict_with_behavior() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        // Dictionary form: members are deltas, missing members are zero.
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "top", Property::data(Value::Int(50)))
            .unwrap();
        n_scroll_by(&mut fx.heap, global, &[Value::Object(opts)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 50.0));

        // `behavior: "smooth"` defers a relative scroll to the embedder.
        let opts2 = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts2, "left", Property::data(Value::Int(25)))
            .unwrap();
        let __sv4 = str_val(&mut fx, "smooth");
        fx.heap
            .define_property_str(opts2, "behavior", Property::data(__sv4))
            .unwrap();
        n_scroll_by(&mut fx.heap, global, &[Value::Object(opts2)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 50.0));
        assert_eq!(
            take_pending_smooth_scroll(fx.ctx.0),
            Some(PendingSmoothScroll {
                x: Some(25.0),
                y: Some(0.0),
                relative: true,
            })
        );
    }

    #[test]
    fn scroll_to_converts_string_and_null_args() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        // WebIDL `ToNumber`: numeric strings parse, `null` becomes 0.
        let ten = str_val(&mut fx, "10");
        n_scroll_to(&mut fx.heap, global, &[ten, Value::Null]).unwrap();
        assert_eq!(scroll_offset(&fx), (10.0, 0.0));

        // Booleans convert; `NaN` still becomes 0.
        n_scroll_to(
            &mut fx.heap,
            global,
            &[Value::Bool(true), Value::Float(f64::NAN)],
        )
        .unwrap();
        assert_eq!(scroll_offset(&fx), (1.0, 0.0));

        // BigInt has no `ToNumber`: a `TypeError`, per WebIDL — and the
        // failed conversion scrolls nothing.
        let bi = fx.heap.alloc_bigint(false, vec![7]).unwrap();
        assert!(matches!(
            n_scroll_to(&mut fx.heap, global, &[Value::BigInt(bi), Value::Int(0)]),
            Err(NativeError::TypeError(_))
        ));
        assert_eq!(scroll_offset(&fx), (1.0, 0.0));
    }

    #[test]
    fn scroll_to_converts_objects_via_to_primitive() {
        fn value_of_42(
            _heap: &mut Heap,
            _this: Value,
            _args: &[Value],
        ) -> Result<Value, NativeError> {
            Ok(Value::Int(42))
        }
        fn to_string_7(
            heap: &mut Heap,
            _this: Value,
            _args: &[Value],
        ) -> Result<Value, NativeError> {
            Ok(Value::Str(heap.alloc_str("7").unwrap()))
        }

        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);

        // WebIDL `ToNumber` on objects is `ToPrimitive` with hint `number`:
        // `valueOf` wins when present. (`scrollTo(obj)` alone takes the
        // dictionary overload, so exercise the value path via `scrollBy`.)
        let obj = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let value_of = fx
            .heap
            .alloc_object(Object::new(ObjectKind::NativeFunction(value_of_42)))
            .unwrap();
        fx.heap
            .define_property_str(obj, "valueOf", Property::data(Value::Object(value_of)))
            .unwrap();
        n_scroll_by(&mut fx.heap, global, &[Value::Object(obj), Value::Int(0)]).unwrap();
        assert_eq!(scroll_offset(&fx), (42.0, 0.0));

        // Without `valueOf`, `toString` is tried next; also works for
        // dictionary members holding objects.
        let obj2 = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let to_string = fx
            .heap
            .alloc_object(Object::new(ObjectKind::NativeFunction(to_string_7)))
            .unwrap();
        fx.heap
            .define_property_str(obj2, "toString", Property::data(Value::Object(to_string)))
            .unwrap();
        n_scroll_by(&mut fx.heap, global, &[Value::Object(obj2), Value::Int(0)]).unwrap();
        assert_eq!(scroll_offset(&fx), (49.0, 0.0));

        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "left", Property::data(Value::Object(obj)))
            .unwrap();
        n_scroll_to(&mut fx.heap, global, &[Value::Object(opts)]).unwrap();
        assert_eq!(scroll_offset(&fx), (42.0, 0.0));
    }

    #[test]
    fn scroll_to_options_reads_inherited_and_accessor_members() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        static GETTER_CALLS: AtomicUsize = AtomicUsize::new(0);
        fn counting_top_getter(
            _heap: &mut Heap,
            _this: Value,
            _args: &[Value],
        ) -> Result<Value, NativeError> {
            GETTER_CALLS.fetch_add(1, Ordering::SeqCst);
            Ok(Value::Int(77))
        }

        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);
        GETTER_CALLS.store(0, Ordering::SeqCst);

        // Inherited `top`: ordinary `[[Get]]` walks the prototype chain.
        let proto = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(proto, "top", Property::data(Value::Int(60)))
            .unwrap();
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap.set_prototype(opts, Value::Object(proto));
        n_scroll_to(&mut fx.heap, global, &[Value::Object(opts)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 60.0));

        // Accessor `top`: the getter runs (side effect observed) and its
        // result converts per WebIDL.
        let getter = fx
            .heap
            .alloc_object(Object::new(ObjectKind::NativeFunction(counting_top_getter)))
            .unwrap();
        let opts2 = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_accessor(
                opts2,
                Wtf8::from_str("top"),
                AccessorProp::new(Value::Object(getter), Value::Undefined),
            )
            .unwrap();
        n_scroll_to(&mut fx.heap, global, &[Value::Object(opts2)]).unwrap();
        assert_eq!(GETTER_CALLS.load(Ordering::SeqCst), 1);
        assert_eq!(scroll_offset(&fx), (0.0, 77.0));
    }

    #[test]
    fn scroll_natives_mutate_offsets_without_firing_listeners() {
        let mut fx = setup("<html><body></body></html>");
        set_scroll_max(&fx, (1000.0, 800.0));
        let global = Value::Object(fx.global);
        let listener = probe_listener(&mut fx.heap);
        add_listener(&mut fx, global, "scroll", listener, false);

        // No movement, no listener — and none on movement either: the
        // scroll natives only mutate offsets. The host dispatches
        // `scroll` listeners once per tick from its offset diff, which is
        // what makes exactly-once delivery hold (firing here as well
        // would double-dispatch every script-driven scroll).
        n_scroll_to(&mut fx.heap, global, &[Value::Int(0), Value::Int(0)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 0.0));
        assert_eq!(scroll_listener_calls(&fx), 0);

        n_scroll_to(&mut fx.heap, global, &[Value::Int(0), Value::Int(50)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 50.0));
        assert_eq!(scroll_listener_calls(&fx), 0);

        // document.addEventListener('scroll') registers on the same root,
        // and scrollBy moves the offset — still no synchronous fire.
        let doc_val = global_prop(&fx, "document");
        let listener2 = probe_listener(&mut fx.heap);
        add_listener(&mut fx, doc_val, "scroll", listener2, false);
        n_scroll_by(&mut fx.heap, global, &[Value::Int(0), Value::Int(10)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 60.0));
        assert_eq!(scroll_listener_calls(&fx), 0);

        // Clamped at the bound; a second identical write moves nowhere.
        n_scroll_to(&mut fx.heap, global, &[Value::Int(0), Value::Int(99_999)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 800.0));
        n_scroll_to(&mut fx.heap, global, &[Value::Int(0), Value::Int(99_999)]).unwrap();
        assert_eq!(scroll_offset(&fx), (0.0, 800.0));
        assert_eq!(scroll_listener_calls(&fx), 0);
    }

    // -- Wave-49 scroll-triage coverage (review findings) ------------------

    /// Publish one nested scroll container for `div#d` in the fixture,
    /// returning its node.
    fn publish_div_container(fx: &Fixture) -> NodeId {
        let div_node = fx.doc.borrow().get_element_by_id("d").expect("div#d");
        let shared = Rc::new(ElementScrollStates::new());
        share_element_scroll_states(fx.ctx.0, shared.clone());
        shared.publish(&[(div_node, (500.0, 300.0))]);
        div_node
    }

    /// Read an element's own scroll-container offset as `(x, y)`.
    fn el_offset(fx: &mut Fixture, el: Value) -> (f64, f64) {
        let f = |v: Value| match v {
            Value::Float(f) => f,
            v => panic!("not a float: {v:?}"),
        };
        (
            f(n_scroll_left_get(&mut fx.heap, el, &[]).unwrap()),
            f(n_scroll_top_get(&mut fx.heap, el, &[]).unwrap()),
        )
    }

    /// A `toString` yielding a non-numeric string, so WebIDL `ToNumber`
    /// on the object goes `ToPrimitive` -> `NaN` -> 0 — like a real
    /// object literal's `"[object Object]"`, without needing
    /// `Object.prototype` linked.
    fn to_string_nope(heap: &mut Heap) -> Value {
        fn nope(heap: &mut Heap, _this: Value, _args: &[Value]) -> Result<Value, NativeError> {
            Ok(Value::Str(heap.alloc_str("nope").unwrap()))
        }
        Value::Object(
            heap.alloc_object(Object::new(ObjectKind::NativeFunction(nope)))
                .unwrap(),
        )
    }

    #[test]
    fn element_scroll_to_dict_vs_positional_overloads() {
        let mut fx = setup("<html><body><div id=\"d\"></div></body></html>");
        let div = call_get_element_by_id(&mut fx, "d");
        publish_div_container(&fx);

        // Positional `(x, y)`: absolute, clamped to the published max.
        n_element_scroll_to(&mut fx.heap, div, &[Value::Int(100), Value::Int(200)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (100.0, 200.0));
        n_element_scroll_to(&mut fx.heap, div, &[Value::Int(9999), Value::Int(9999)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (500.0, 300.0));

        // One object argument: the `ScrollToOptions` dictionary — a
        // missing `left` keeps the current x.
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "top", Property::data(Value::Int(50)))
            .unwrap();
        // A `toString` so the two-argument form below converts via
        // `ToPrimitive` (`NaN` -> 0) instead of throwing.
        let to_string = to_string_nope(&mut fx.heap);
        fx.heap
            .define_property_str(opts, "toString", Property::data(to_string))
            .unwrap();
        n_element_scroll_to(&mut fx.heap, div, &[Value::Object(opts)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (500.0, 50.0));

        // Both members present: absolute on both axes.
        let both = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(both, "left", Property::data(Value::Int(30)))
            .unwrap();
        fx.heap
            .define_property_str(both, "top", Property::data(Value::Int(40)))
            .unwrap();
        n_element_scroll_to(&mut fx.heap, div, &[Value::Object(both)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (30.0, 40.0));

        // Two arguments: only `(x, y)` is viable — the object converts
        // via WebIDL `ToNumber` (`ToPrimitive` -> `NaN` -> 0), it does
        // NOT take the dictionary path.
        n_element_scroll_to(&mut fx.heap, div, &[Value::Object(opts), Value::Int(5)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (0.0, 5.0));

        // The `scroll` alias is a behaviorally identical native: a
        // distinct Function object from `scrollTo` (like browsers), with
        // the same effect.
        let proto_method = |fx: &Fixture, name: &str| {
            walk_proto_chain(&fx.heap, obj_of(div), |o| {
                fx.heap
                    .get_property(o, Wtf8::from_str(name))
                    .map(|p| p.value)
            })
            .unwrap_or_else(|| panic!("{name} on element prototype"))
        };
        let scroll_fn = proto_method(&fx, "scroll");
        let scroll_to_fn = proto_method(&fx, "scrollTo");
        assert!(matches!(scroll_fn, Value::Object(_)));
        assert_ne!(scroll_fn, scroll_to_fn);
        call_function(
            &mut fx.heap,
            scroll_fn,
            div,
            &[Value::Int(11), Value::Int(22)],
        )
        .unwrap();
        assert_eq!(el_offset(&mut fx, div), (11.0, 22.0));
    }

    #[test]
    fn element_scroll_by_dict_vs_positional_overloads() {
        let mut fx = setup("<html><body><div id=\"d\"></div></body></html>");
        let div = call_get_element_by_id(&mut fx, "d");
        publish_div_container(&fx);

        // Positional `(dx, dy)`: relative, clamped at the published max.
        n_element_scroll_by(&mut fx.heap, div, &[Value::Int(100), Value::Int(50)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (100.0, 50.0));

        // One object argument: dictionary deltas — a missing member
        // scrolls by zero on that axis.
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "left", Property::data(Value::Int(10)))
            .unwrap();
        n_element_scroll_by(&mut fx.heap, div, &[Value::Object(opts)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (110.0, 50.0));

        n_element_scroll_by(&mut fx.heap, div, &[Value::Int(9999), Value::Int(0)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (500.0, 50.0));
    }

    #[test]
    fn parse_scroll_args_overload_resolution() {
        let mut heap = Heap::new();
        let dict = heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        heap.define_property_str(dict, "left", Property::data(Value::Int(10)))
            .unwrap();
        heap.define_property_str(dict, "top", Property::data(Value::Int(20)))
            .unwrap();
        // A `toString` so the two-argument form converts via
        // `ToPrimitive` (`NaN` -> 0) instead of throwing.
        let to_string = to_string_nope(&mut heap);
        heap.define_property_str(dict, "toString", Property::data(to_string))
            .unwrap();

        // One object argument: the dictionary overload.
        let (x, y, b) = parse_scroll_args(&mut heap, &[Value::Object(dict)], false).unwrap();
        assert_eq!((x, y), (Some(10.0), Some(20.0)));
        assert!(matches!(b, ScrollBehavior::Auto));

        // Missing members: `None` for `scrollTo` (keep current), zero
        // deltas for `scrollBy`.
        let empty = heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let (x, y, _) = parse_scroll_args(&mut heap, &[Value::Object(empty)], false).unwrap();
        assert_eq!((x, y), (None, None));
        let (x, y, _) = parse_scroll_args(&mut heap, &[Value::Object(empty)], true).unwrap();
        assert_eq!((x, y), (Some(0.0), Some(0.0)));

        // Two arguments: only `(x, y)` is viable. The object converts via
        // WebIDL `ToNumber` (`ToPrimitive` with hint number -> `NaN` ->
        // 0), so the dictionary members are NOT consulted.
        let (x, y, b) =
            parse_scroll_args(&mut heap, &[Value::Object(dict), Value::Int(5)], false).unwrap();
        assert_eq!((x, y), (Some(0.0), Some(5.0)));
        assert!(matches!(b, ScrollBehavior::Auto));

        // The positional form never carries a behavior.
        let (x, y, b) =
            parse_scroll_args(&mut heap, &[Value::Int(3), Value::Int(4)], false).unwrap();
        assert_eq!((x, y), (Some(3.0), Some(4.0)));
        assert!(matches!(b, ScrollBehavior::Auto));

        // `behavior: "smooth"` parses; an unknown keyword is a TypeError.
        let smooth = heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let smooth_s = Value::Str(heap.alloc_str("smooth").unwrap());
        heap.define_property_str(smooth, "behavior", Property::data(smooth_s))
            .unwrap();
        let (_, _, b) = parse_scroll_args(&mut heap, &[Value::Object(smooth)], false).unwrap();
        assert!(matches!(b, ScrollBehavior::Smooth));

        let bogus = heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let bogus_s = Value::Str(heap.alloc_str("warp").unwrap());
        heap.define_property_str(bogus, "behavior", Property::data(bogus_s))
            .unwrap();
        assert!(parse_scroll_args(&mut heap, &[Value::Object(bogus)], false).is_err());
    }

    #[test]
    fn element_smooth_scroll_records_vs_instant_applies() {
        let mut fx = setup("<html><body><div id=\"d\"></div></body></html>");
        let div = call_get_element_by_id(&mut fx, "d");
        let div_node = publish_div_container(&fx);

        // `behavior: "smooth"` records a pending request for the embedder
        // to animate: the offset is untouched here.
        let opts = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        fx.heap
            .define_property_str(opts, "top", Property::data(Value::Int(250)))
            .unwrap();
        let smooth_s = str_val(&mut fx, "smooth");
        fx.heap
            .define_property_str(opts, "behavior", Property::data(smooth_s))
            .unwrap();
        n_element_scroll_to(&mut fx.heap, div, &[Value::Object(opts)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (0.0, 0.0));
        let (node, pending) =
            take_pending_element_smooth_scroll(fx.ctx.0).expect("smooth request recorded");
        assert_eq!(node, div_node);
        assert_eq!(
            pending,
            PendingSmoothScroll {
                x: None,
                y: Some(250.0),
                relative: false,
            }
        );
        // Drained: a second take finds nothing.
        assert!(take_pending_element_smooth_scroll(fx.ctx.0).is_none());

        // A smooth request is pending again...
        n_element_scroll_to(&mut fx.heap, div, &[Value::Object(opts)]).unwrap();
        assert!(take_pending_element_smooth_scroll(fx.ctx.0).is_some());
        // ...until an instant scroll cancels it and applies at once.
        n_element_scroll_to(&mut fx.heap, div, &[Value::Int(10), Value::Int(20)]).unwrap();
        assert_eq!(el_offset(&mut fx, div), (10.0, 20.0));
        assert!(take_pending_element_smooth_scroll(fx.ctx.0).is_none());
    }

    #[test]
    fn parse_shim_scroll_offset_recording() {
        // The parse shim records `scrollTop`/`scrollLeft` writes per
        // element (no layout runs mid-parse): set-then-read observes the
        // write, unset keys read `(0, 0)`.
        let id = PARSE_HOST_IDS.fetch_add(1, Ordering::Relaxed);
        PARSE_HOSTS.with(|hosts| {
            hosts.borrow_mut().insert(
                id,
                ParseHostEntry {
                    host: std::ptr::null_mut(),
                    elements: HashMap::new(),
                    next_element: 1,
                    scroll: HashMap::new(),
                    window_scroll: (0.0, 0.0),
                    window_scroll_written: false,
                    layout_hook: ParseLayoutHook::new(None),
                    listeners: Rc::new(RefCell::new(ParseShimRoots::default())),
                    enum_cache: Rc::new(RefCell::new(None)),
                },
            );
        });
        let key = 42u64;
        assert_eq!(parse_el_scroll_get(id, key), (0.0, 0.0));
        parse_el_scroll_set(id, key, 30.0, 40.0);
        assert_eq!(parse_el_scroll_get(id, key), (30.0, 40.0));
        // Keys are independent: a write to one leaves the other at (0, 0).
        assert_eq!(parse_el_scroll_get(id, key + 1), (0.0, 0.0));
        // The window slot is separate storage on the same entry.
        parse_window_scroll_set(id, 7.0, 9.0);
        assert_eq!(parse_window_scroll_get(id), (7.0, 9.0));
        assert_eq!(parse_el_scroll_get(id, key), (30.0, 40.0));
        PARSE_HOSTS.with(|hosts| {
            hosts.borrow_mut().remove(&id);
        });
    }

    #[test]
    fn parse_shim_initial_target_positions_unwritten_scroller() {
        // `scroll-initial-target: nearest` (CSS Scroll Snap 2
        // §3.1.2): the center box at (200, 200) is the scroller's
        // initial target, aligned start, so a mid-parse read of the
        // never-written scroller reports (200, 200) — its initial
        // scroll position — not (0, 0). (The WPT
        // scroll-initial-target files assert exactly this shape;
        // they failed with "expected 200 but got 0" because the
        // shim only ever served recorded writes.)
        let r = shim_result(
            b"<html><head><style>\
              .scroller { width: 300px; height: 300px; border: solid 1px black; overflow: scroll; position: absolute; }\
              .spacer { width: 1000px; height: 1000px; }\
              .box { position: absolute; width: 200px; height: 200px; }\
              .target { scroll-initial-target: nearest; }\
              </style></head><body>\
              <div class=\"scroller\" id=\"scroller\"><div class=\"spacer\"></div>\
              <div class=\"box\" style=\"top:0px;left:0px\"></div>\
              <div class=\"box target\" style=\"top:200px;left:200px\"></div>\
              <div class=\"box\" style=\"top:400px;left:400px\"></div></div>\
              <script>var sc = document.getElementById('scroller');\
              globalThis.__result = [sc.scrollTop, sc.scrollLeft].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "200|200");
    }

    #[test]
    fn parse_shim_initial_target_yields_to_script_write() {
        // A script write is the container's position from then on:
        // setting `scrollTop` alone moves only that axis off the
        // initial target; the unwritten axis stays at the target.
        let r = shim_result(
            b"<html><head><style>\
              .scroller { width: 300px; height: 300px; overflow: scroll; position: absolute; }\
              .spacer { width: 1000px; height: 1000px; }\
              .box { position: absolute; width: 200px; height: 200px; }\
              .target { scroll-initial-target: nearest; }\
              </style></head><body>\
              <div class=\"scroller\" id=\"scroller\"><div class=\"spacer\"></div>\
              <div class=\"box target\" style=\"top:200px;left:200px\"></div></div>\
              <script>var sc = document.getElementById('scroller');\
              sc.scrollTop = 30;\
              globalThis.__result = [sc.scrollTop, sc.scrollLeft].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "30|200");
    }

    #[test]
    fn parse_shim_initial_target_snaps_in_mandatory_container() {
        // The initial position is a rest position: in a mandatory
        // snap container it is snap-adjusted like any scroll
        // landing there. The target sits at (200, 200) but the only
        // snap area is at 400 on the y axis, so the read is
        // (200, 400) — x has no snap axis and keeps the target's
        // position. (Mirrors the WPT scroll-initial-target-with-
        // scroll-snap geometry.)
        let r = shim_result(
            b"<html><head><style>\
              .scroller { width: 300px; height: 300px; border: solid 1px black; overflow: scroll; position: absolute; scroll-snap-type: y mandatory; }\
              .spacer { width: 1000px; height: 1000px; }\
              .box { position: absolute; width: 200px; height: 200px; }\
              .target { scroll-initial-target: nearest; }\
              .snap { scroll-snap-align: start start; }\
              </style></head><body>\
              <div class=\"scroller\" id=\"scroller\"><div class=\"spacer\"></div>\
              <div class=\"box target\" style=\"top:200px;left:200px\"></div>\
              <div class=\"box snap\" style=\"top:400px;left:400px\"></div></div>\
              <script>var sc = document.getElementById('scroller');\
              globalThis.__result = [sc.scrollLeft, sc.scrollTop].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "200|400");
    }

    #[test]
    fn parse_shim_initial_target_positions_viewport() {
        // The root variant: the target lives in the document flow
        // and the *viewport* is the scroll container — the document
        // element's scroll read (and `window.scrollY`) report the
        // target's position.
        let r = shim_result(
            b"<html><head><style>\
              .target { scroll-initial-target: nearest; }\
              </style></head><body>\
              <div style=\"height:200px\"></div>\
              <div class=\"target\" style=\"height:200px\"></div>\
              <div style=\"height:1000px\"></div>\
              <script>var de = document.documentElement;\
              globalThis.__result = [de.scrollTop, window.scrollY].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "200|200");
    }

    fn point_cand(pos: f32, always: bool) -> ParseSnapCandidate {
        ParseSnapCandidate {
            pos,
            always,
            cover_lo: pos,
            cover_hi: pos,
        }
    }

    #[test]
    fn parse_snap_select_axis_mandatory_and_proximity() {
        let cands = [point_cand(0.0, false), point_cand(1000.0, false)];
        // Mandatory picks the nearest position unconditionally.
        assert_eq!(
            parse_snap_select_axis(&cands, 800.0, 0.0, true, 400.0, false),
            Some(1000.0)
        );
        assert_eq!(
            parse_snap_select_axis(&cands, 300.0, 0.0, true, 400.0, false),
            Some(0.0)
        );
        // Proximity only snaps within the threshold.
        assert_eq!(
            parse_snap_select_axis(&cands, 800.0, 0.0, false, 400.0, false),
            Some(1000.0)
        );
        assert_eq!(
            parse_snap_select_axis(&cands, 550.0, 0.0, false, 400.0, false),
            None
        );
        // No candidates, no snap.
        assert_eq!(
            parse_snap_select_axis(&[], 800.0, 0.0, true, 400.0, false),
            None
        );
    }

    #[test]
    fn parse_snap_select_axis_always_trap() {
        // NOTE (H6): `relative = true` here unit-tests the mirrored
        // selection math in isolation. No shim native takes that
        // path — script scrolls are absolute writes, so
        // `ParseLayoutHook::snap_scroll` always passes
        // `relative = false` into `parse_snap_apply`. The real call
        // path is covered at the apply level by
        // `parse_snap_apply_absolute_scroll_degrades_always` and
        // `parse_snap_apply_diagonal_scroll_only_snaps_covered_axis`
        // below.
        let cands = [point_cand(100.0, true), point_cand(200.0, false)];
        // A relative scroll from 0 to 300 must stop at the first
        // `always` position it passes over.
        assert_eq!(
            parse_snap_select_axis(&cands, 300.0, 0.0, true, 400.0, true),
            Some(100.0)
        );
        // An absolute scroll degrades `always` to normal: nearest wins.
        assert_eq!(
            parse_snap_select_axis(&cands, 300.0, 0.0, true, 400.0, false),
            Some(200.0)
        );
        // Starting exactly on the `always` position lets the scroll
        // leave it (no trap at the start point).
        assert_eq!(
            parse_snap_select_axis(&cands, 300.0, 100.0, true, 400.0, true),
            Some(200.0)
        );
    }

    #[test]
    fn parse_snap_select_axis_cover_range() {
        let big = ParseSnapCandidate {
            pos: 100.0,
            always: false,
            cover_lo: 100.0,
            cover_hi: 200.0,
        };
        let cands = [big, point_cand(600.0, false)];
        // Resting inside the covering range is valid: the scroll stays.
        assert_eq!(
            parse_snap_select_axis(&cands, 150.0, 0.0, true, 400.0, false),
            Some(150.0)
        );
        // Outside it, nearest applies as usual.
        assert_eq!(
            parse_snap_select_axis(&cands, 250.0, 0.0, true, 400.0, false),
            Some(100.0)
        );
    }

    #[test]
    fn parse_snap_apply_snaps_and_clamps() {
        let cont = ParseSnapContainer {
            scrollport: Rect {
                x: 0.0,
                y: 0.0,
                w: 400.0,
                h: 400.0,
            },
            origin: (0.0, 0.0),
            max: (1600.0, 0.0),
            snap_type: SnapType::MandatoryBoth,
            padding: (0.0, 0.0, 0.0, 0.0),
            areas: vec![ParseSnapArea {
                rect: Rect {
                    x: 1000.0,
                    y: 0.0,
                    w: 200.0,
                    h: 200.0,
                },
                align_x: SnapAlign::Start,
                align_y: SnapAlign::Start,
                stop: SnapStop::Normal,
                rev_x: false,
            }],
            initial_target: None,
        };
        // The WPT headline shape: scrollTo({left: 800}) snaps to 1000.
        assert_eq!(
            parse_snap_apply(&cont, (0.0, 0.0), (800.0, 0.0), false),
            (1000.0, 0.0)
        );
        // A target past the scrollable range clamps first, then the
        // nearest position to the clamped offset still applies.
        assert_eq!(
            parse_snap_apply(&cont, (0.0, 0.0), (5000.0, 0.0), false),
            (1000.0, 0.0)
        );
        // No snap type: the offset is only clamped into range.
        let plain = ParseSnapContainer {
            snap_type: SnapType::None,
            max: (1600.0, 300.0),
            ..cont
        };
        assert_eq!(
            parse_snap_apply(&plain, (0.0, 0.0), (500.0, 9999.0), false),
            (500.0, 300.0)
        );
    }

    #[test]
    fn parse_snap_apply_proximity_reach_is_a_third_of_the_snapport() {
        // Wave-50 regression (WPT
        // `snap-after-relayout/not-resnap-outside-proximity-threshold`):
        // the shim received the full snapport extent as the proximity
        // threshold, so a `scrollTo(0, 250)` in a 600px proximity
        // snapport with snap positions at 0 and 500 was dragged to 0
        // mid-parse. The reach is one third of the snapport (200px
        // here): 250 stays, 190 snaps.
        assert_eq!(parse_proximity_threshold(600.0), 200.0);
        let area = |y: f32| ParseSnapArea {
            rect: Rect {
                x: 0.0,
                y,
                w: 300.0,
                h: 300.0,
            },
            align_x: SnapAlign::Start,
            align_y: SnapAlign::Start,
            stop: SnapStop::Normal,
            rev_x: false,
        };
        let cont = ParseSnapContainer {
            scrollport: Rect {
                x: 0.0,
                y: 0.0,
                w: 600.0,
                h: 600.0,
            },
            origin: (0.0, 0.0),
            max: (1400.0, 1400.0),
            snap_type: SnapType::ProximityY,
            padding: (0.0, 0.0, 0.0, 0.0),
            areas: vec![area(0.0), area(500.0)],
            initial_target: None,
        };
        assert_eq!(
            parse_snap_apply(&cont, (0.0, 0.0), (0.0, 250.0), false),
            (0.0, 250.0),
            "250px from the nearest position is outside the 200px reach"
        );
        assert_eq!(
            parse_snap_apply(&cont, (0.0, 0.0), (0.0, 190.0), false),
            (0.0, 0.0),
            "190px from the nearest position is inside the reach"
        );
    }

    /// Run `html` (which ends with a `<script>` storing into
    /// `globalThis.__result`) through the parse shim and read the
    /// result back. Mirrors the integration `run_probe` helper for
    /// unit tests that live next to the shim.
    fn shim_result(html: &[u8]) -> String {
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(html, true, &mut probe);
        node_list_str(&mut probe.vm, "globalThis.__result;")
    }

    #[test]
    fn parse_scroll_extents_transformed_child() {
        // (H5a) A transformed CHILD still extends the scroller's
        // extents by its transformed border box (the pre-existing
        // coverage): a 100x20 child translated by (150, 60) inside a
        // 100x50 scroller lands its far edges at 250|80.
        let r = shim_result(
            b"<html><body><div id=t style=\"width:100px;height:50px\">\
              <div style=\"width:100px;height:20px;transform:translate(150px,60px)\"></div></div>\
              <script>var el = document.getElementById('t');\
              globalThis.__result = [el.scrollWidth, el.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "250|80");
    }

    #[test]
    fn parse_scroll_extents_scroller_own_transform_ignored() {
        // (H5b) The scroller element ITSELF translated: its own
        // transform must not enter its scroll extents. The global
        // accumulation this replaces reported 400 for the overflowing
        // child (300 + the scroller's own 100px translation) and 200
        // for the non-overflowing one (100 client + 100).
        let r = shim_result(
            b"<html><body>\
              <div id=a style=\"width:100px;height:50px;transform:translateX(100px)\">\
              <div style=\"width:300px;height:80px\"></div></div>\
              <div id=b style=\"width:100px;height:50px;transform:translate(100px,40px)\">\
              <div style=\"width:50px;height:20px\"></div></div>\
              <script>var a = document.getElementById('a'); var b = document.getElementById('b');\
              globalThis.__result = [a.scrollWidth, a.scrollHeight, b.scrollWidth, b.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "300|80|100|50");
    }

    #[test]
    fn parse_scroll_extents_ancestor_transform_ignored() {
        // (H5c) An ANCESTOR scaled 2x: the scroller's extents are
        // measured in its own frame, so the ancestor's transform does
        // not double them (the global accumulation reported roughly
        // double, pivot-dependent).
        let r = shim_result(
            b"<html><body><div style=\"transform:scale(2)\">\
              <div id=t style=\"width:100px;height:50px\">\
              <div style=\"width:300px;height:80px\"></div></div></div>\
              <script>var el = document.getElementById('t');\
              globalThis.__result = [el.scrollWidth, el.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "300|80");
    }

    #[test]
    fn parse_scroll_extents_child_translation_grows_extent() {
        // (H5d) A child translated inside the scroller grows the
        // extent by exactly the translation: a 50px-wide child at
        // translateX(80px) lands its far edge at 130, past the 100px
        // client width; untranslated it would leave it at 100.
        let r = shim_result(
            b"<html><body><div id=t style=\"width:100px;height:50px\">\
              <div style=\"width:50px;height:20px;transform:translateX(80px)\"></div></div>\
              <script>var el = document.getElementById('t');\
              globalThis.__result = [el.scrollWidth, el.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "130|50");
    }

    #[test]
    fn parse_scroll_extents_fixed_icb_skipped() {
        // (WPT `scrollable-overflow-fixed-positioned-initial-
        // containing-block`) A `position: fixed` descendant anchored
        // to the initial containing block never scrolls with the
        // element, so it must not extend its scroll extents — the
        // layout crate's `scrollable_extent` pins the same rule
        // (`scrollable_extent_still_skips_viewport_anchored_fixed`).
        // Unfiltered, the 300px-tall fixed box at `top: 400px` would
        // push `scrollHeight` to ~700.
        let r = shim_result(
            b"<html><body><div id=t style=\"width:100px;height:50px\">\
              <div style=\"position:fixed;top:400px;left:0;width:50px;height:300px\"></div></div>\
              <script>var el = document.getElementById('t');\
              globalThis.__result = [el.scrollWidth, el.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "100|50");
    }

    #[test]
    fn parse_scroll_extents_fixed_under_scroller_itself_skipped() {
        // (Layout pin `scrollable_extent_fixed_under_scroller_itself_
        // does_not_extend`) The scroller's OWN transform makes it the
        // fixed box's containing block, but that box is anchored to
        // the scrollport frame, which does not move when the scroller
        // scrolls — it still must not extend the extents.
        let r = shim_result(
            b"<html><body><div id=t style=\"width:100px;height:100px;transform:translateZ(0)\">\
              <div style=\"position:fixed;left:500px;top:0;width:50px;height:50px\"></div></div>\
              <script>var el = document.getElementById('t');\
              globalThis.__result = [el.scrollWidth, el.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "100|100");
    }

    #[test]
    fn parse_scroll_extents_fixed_in_transformed_ancestor_included() {
        // The mirror case (layout pin
        // `scrollable_extent_includes_fixed_in_transformed`): a fixed
        // box whose containing block is a transformed ancestor
        // *inside* the scroller scrolls with the scroller's content
        // and DOES extend the extents: `top: 300px` + 50px tall
        // against the transformed ancestor lands its far edge at 350.
        let r = shim_result(
            b"<html><body><div id=t style=\"width:200px;height:100px\">\
              <div style=\"transform:translate(0,0);height:50px\">\
              <div style=\"position:fixed;top:300px;left:0;width:50px;height:50px\"></div></div></div>\
              <script>var el = document.getElementById('t');\
              globalThis.__result = [el.scrollWidth, el.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "200|350");
    }

    #[test]
    fn parse_scroll_extents_relative_block_in_inline() {
        // (WPT `scrollable-overflow-relative-positioned-block-in-
        // inline`) A relatively positioned block nested in an inline
        // element contributes the same scrollable overflow as the
        // same block as a direct sibling: the split-inline wrapper's
        // unshifted flow footprint (bottom ~704) must not fold in —
        // only the shifted content (bottom ~404) counts.
        // The WPT point is the EQUALITY (nested contributes the same
        // overflow as sibling), so that is asserted — and exactly:
        // since the w78 line-height fix routes `normal` through the
        // face's real typo metrics instead of the hardcoded 1.2em
        // strut, the measured value is 405|405 (the spec value; the
        // pre-fix 403|403 enshrined the wrong descent, and the ~404
        // in the comment above is the shifted content's geometric
        // bottom, not a scroll extent). 0 or ~704 would mean
        // symmetric breakage (empty extents, or the unshifted
        // footprint folding back in).
        let r = shim_result(
            b"<html><head><style>\
              .container { width: 10px; height: 10px; }\
              .shifted { width: 10px; height: 500px; position: relative; bottom: 300px; }\
              </style></head><body style=\"margin:0\">\
              <div class=container id=nested><img style=\"width:10px;height:200px\">\
              <span><div class=shifted></div></span></div>\
              <div class=container id=sibling><img style=\"width:10px;height:200px\">\
              <div class=shifted></div></div>\
              <script>var n = document.getElementById('nested');\
              var s = document.getElementById('sibling');\
              globalThis.__result = [n.scrollHeight, s.scrollHeight].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "405|405");
        let (nested, sibling) = r.split_once('|').expect("nested|sibling extents");
        assert_eq!(nested, sibling);
    }

    #[test]
    fn parse_gcs_orthogonal_caption_pct_margin_left() {
        // WPT css/css-tables/caption-writing-mode-001.html subtest 1,
        // through the parse shim: author stylesheet (not inline
        // styles) on x-table/x-caption custom elements, script
        // mid-parse. 20% of the vertical table's 200px inline size
        // is 40px — not 60px (20% of the 300px physical width) and
        // not the unresolved "20%".
        let r = shim_result(
            b"<html><head><style>\
              x-table{display:table;width:300px;height:200px;writing-mode:vertical-lr}\
              x-caption{display:table-caption;height:50px;width:120px;writing-mode:horizontal-tb}\
              </style></head><body>\
              <x-table><x-caption id=captionMarginLeft style=\"margin-left:20%\">caption</x-caption></x-table>\
              <script>globalThis.__result = getComputedStyle(document.getElementById('captionMarginLeft')).marginLeft;</script>\
              </body></html>",
        );
        assert_eq!(r, "40px");
    }

    #[test]
    fn parse_gcs_calc_pct_margins_resolve() {
        // Shim mirror of `computed_style_calc_pct_margins_resolve`,
        // mid-parse: calc() percentage margins resolve against the
        // parent content width on the parse-shim path too.
        let read = |style: &str| -> String {
            let html = format!(
                "<html><body style=\"margin:0\">\
                 <div style=\"width:500px\"><div id=c style=\"{style}\">x</div></div>\
                 <script>globalThis.__result = getComputedStyle(document.getElementById('c')).marginLeft;</script>\
                 </body></html>"
            );
            shim_result(html.as_bytes())
        };
        assert_eq!(read("margin-left:calc(50% + 60px)"), "310px");
        assert_eq!(read("margin-left:calc(50% - 60px)"), "190px");
        assert_eq!(read("margin-left:calc(20%)"), "100px");
    }

    #[test]
    fn parse_gcs_parent_padding_non_px_resolves() {
        // w77fix: non-px parent padding resolves instead of
        // reading as 0 and overstating the percentage-margin base.
        // Percentage parent padding resolves against the parent's
        // containing-block width (the 800px shim viewport through
        // the margin-0 body): a 500px parent with `padding-left:
        // 10%` has an 80px padding and a 500px content width, so
        // the child's 20% margin is 100px — the old code read the
        // padding as 0 and reported 116px (20% of the 580px border
        // box). `em` parent padding resolves against the parent's
        // font size: 1em at 20px is 20px, so the same 100px (the
        // old code reported 104px).
        let read = |html: &[u8]| -> String { shim_result(html) };
        assert_eq!(
            read(b"<html><body style=\"margin:0\">\
              <div style=\"width:500px;padding-left:10%\"><div id=c style=\"margin-left:20%\">x</div></div>\
              <script>globalThis.__result = getComputedStyle(document.getElementById('c')).marginLeft;</script>\
              </body></html>"),
            "100px",
            "percentage parent padding"
        );
        assert_eq!(
            read(b"<html><body style=\"margin:0\">\
              <div style=\"width:500px;font-size:20px;padding-left:1em\"><div id=c style=\"margin-left:20%\">x</div></div>\
              <script>globalThis.__result = getComputedStyle(document.getElementById('c')).marginLeft;</script>\
              </body></html>"),
            "100px",
            "em parent padding"
        );
    }

