    #[test]
    fn binding_runner_ignores_foreign_tasks() {
        let mut fx = setup("<html></html>");
        let mut runner = BindingRunner::new(&mut fx.heap, fx.apis.clone());
        assert!(!runner.try_run_task(&Task::PromiseJob { job: 9999 }));
        assert!(!runner.try_run_task(&Task::FireTimer {
            timer_id: 7,
            callback: 9999
        }));
        assert!(!runner.try_run_task(&Task::Script { source: "x".into() }));
    }

    #[test]
    fn page_pump_hook_fires_bindings_tasks_on_a_real_vm() {
        // The production page install on a real `Vm`, end to end: the
        // timer/microtask globals are installed (shadowing the VM
        // intrinsics), and `pump_page_event_loop` fires their callbacks
        // through the hidden fire native — the `ReentrantInvoker` pump
        // contract. `drain_page_microtasks` is the between-scripts
        // checkpoint.
        let mut vm = Vm::new();
        let doc = Rc::new(RefCell::new(Document::new()));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        // The install keeps only a `Weak` to the document (the tab owns
        // it in production); the test holds the strong handle.
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("install page web apis");
        for name in [
            "setTimeout",
            "clearTimeout",
            "queueMicrotask",
            "setInterval",
            "clearInterval",
            "requestAnimationFrame",
            "cancelAnimationFrame",
        ] {
            assert!(
                vm.get_global(name).is_some(),
                "{name} not installed on the page global"
            );
        }
        vm.eval("log = []; setTimeout(() => log.push('timer'), 0); queueMicrotask(() => log.push('micro'));")
            .expect("register tasks");
        // Microtask checkpoint: the microtask runs, the timer stays
        // queued for the pump.
        let errors = drain_page_microtasks(&mut vm, ctx);
        assert!(errors.is_empty(), "{errors:?}");
        assert!(matches!(
            vm.eval("log.join(',') === 'micro'"),
            Ok(Value::Bool(true))
        ));
        let errors = pump_page_event_loop(&mut vm, ctx);
        assert!(errors.is_empty(), "{errors:?}");
        assert!(matches!(
            vm.eval("log.join(',') === 'micro,timer'"),
            Ok(Value::Bool(true))
        ));
        // A throwing timer callback is report-and-continue: recorded,
        // not propagated.
        vm.eval("setTimeout(() => { throw new Error('boom'); }, 0);")
            .expect("register throwing timer");
        let errors = pump_page_event_loop(&mut vm, ctx);
        assert_eq!(errors.len(), 1, "{errors:?}");
        assert!(errors[0].contains("boom"), "{errors:?}");
        // Torn-down contexts fall back to the plain VM drain.
        vm.remove_page_web_apis(ctx);
        let errors = pump_page_event_loop(&mut vm, ctx);
        assert!(errors.is_empty(), "{errors:?}");
    }

    #[test]
    fn css_value_to_string_serializes_shadow_lists() {
        use bowser_css::{LengthUnit, Shadow};
        let shadow = |ox: CssValue,
                      oy: CssValue,
                      blur: CssValue,
                      spread: CssValue,
                      color: CssValue,
                      inset: bool| {
            Shadow {
                offset_x: ox,
                offset_y: oy,
                blur,
                spread,
                color,
                inset,
            }
        };
        let px = |x: f32| CssValue::Length(x, LengthUnit::Px);
        let zero = CssValue::Number(0.0);
        let currentcolor = CssValue::Keyword("currentcolor".into());
        // Empty list is `none`.
        assert_eq!(css_value_to_string(&CssValue::Shadows(vec![])), "none");
        // Omitted blur/spread/color serialize back to the omitted form.
        assert_eq!(
            css_value_to_string(&CssValue::Shadows(vec![shadow(
                px(1.0),
                px(2.0),
                zero.clone(),
                zero.clone(),
                currentcolor.clone(),
                false
            )])),
            "1px 2px"
        );
        // Full box-shadow with spread, color, and inset: computed-value
        // order is color first, `inset` last.
        assert_eq!(
            css_value_to_string(&CssValue::Shadows(vec![shadow(
                px(1.0),
                px(2.0),
                px(3.0),
                px(4.0),
                CssValue::Keyword("red".into()),
                true
            )])),
            "red 1px 2px 3px 4px inset"
        );
        // A nonzero spread forces a zero blur to serialize
        // positionally; multiple shadows are comma-joined.
        assert_eq!(
            css_value_to_string(&CssValue::Shadows(vec![
                shadow(
                    px(1.0),
                    px(1.0),
                    zero.clone(),
                    px(5.0),
                    currentcolor.clone(),
                    false
                ),
                shadow(
                    px(0.0),
                    px(0.0),
                    px(2.0),
                    zero.clone(),
                    currentcolor.clone(),
                    false
                ),
            ])),
            "1px 1px 0 5px, 0px 0px 2px"
        );
    }

