    fn response_status(fx: &Fixture, v: Value) -> i32 {
        let Value::Object(o) = v else {
            panic!("not an object")
        };
        match fx
            .heap
            .get_property(o, Wtf8::from_str("status"))
            .unwrap()
            .value
        {
            Value::Int(i) => i,
            _ => panic!("no status"),
        }
    }

    #[test]
    fn fetch_network_error_rejects_via_microtask() {
        let mut fx = setup("<html></html>");
        let global = Value::Object(fx.global);
        // Nothing listens on discard port 9: connection refused, fast, no
        // DNS, no traffic leaves the machine.
        let fetch_url = str_val(&mut fx, "http://127.0.0.1:9/x");
        let promise = n_fetch(&mut fx.heap, global, &[fetch_url]).unwrap();
        let bad = probe_listener(&mut fx.heap);
        n_then(&mut fx.heap, promise, &[Value::Undefined, bad]).unwrap();
        assert!(fx.invoker.borrow().calls.borrow().is_empty());

        // Wait for the worker thread, bounded.
        let mut done = false;
        for _ in 0..200 {
            poll_fetch_completions(&fx.apis);
            done = !fx.apis.borrow().fetch_outcomes.is_empty();
            if done {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert!(done, "fetch worker did not complete");

        run_loop(&mut fx);
        let inv = fx.invoker.borrow();
        assert_eq!(inv.calls.borrow().len(), 1);
        assert_eq!(inv.calls.borrow()[0].func, bad);
        assert_eq!(inv.calls.borrow()[0].argc, 1);
    }

    #[test]
    fn fetch_success_resolves_with_response_object() {
        let mut fx = setup("<html></html>");
        // Build the pending promise + job the way n_fetch does, then
        // deliver a synthetic success outcome.
        let (promise_val, job) = {
            let mut g = fx.apis.borrow_mut();
            let ph = g.next_handle();
            g.gc_roots
                .borrow_mut()
                .promises
                .insert(ph, PendingPromise::pending());
            let pv = wrap_promise(&mut fx.heap, &mut g, ph).unwrap();
            let job = g.next_job();
            g.fetch_promises.insert(job, ph);
            (pv, job)
        };
        let cb = probe_listener(&mut fx.heap);
        n_then(&mut fx.heap, promise_val, &[cb, Value::Undefined]).unwrap();

        let url = bowser_url::parse("http://example.com/app.js", None).unwrap();
        let resp = net_fetch::Response {
            status: 200,
            headers: vec![("content-type".to_string(), "text/plain".to_string())],
            body: b"hi".to_vec(),
            url,
        };
        fx.apis.borrow_mut().fetch_outcomes.insert(job, Ok(resp));

        let mut runner = BindingRunner::new(&mut fx.heap, fx.apis.clone());
        assert!(runner.try_run_task(&Task::PromiseJob { job }));

        let inv = fx.invoker.borrow();
        assert_eq!(inv.calls.borrow().len(), 1);
        assert_eq!(inv.calls.borrow()[0].func, cb);
        assert_eq!(inv.calls.borrow()[0].argc, 1);
        let arg0 = inv.calls.borrow()[0].arg0.expect("reaction arg");
        assert_eq!(response_status(&fx, arg0), 200);
    }

