    fn computed_prop(fx: &mut Fixture, el: Value, name: &str) -> String {
        let global = Value::Object(fx.global);
        let decl = n_get_computed_style(&mut fx.heap, global, &[el]).unwrap();
        let prop_name = str_val(fx, name);
        let v = n_style_get_property_value(&mut fx.heap, decl, &[prop_name]).unwrap();
        match v {
            Value::Str(s) => s.as_wtf8().to_string(),
            _ => panic!("not a string"),
        }
    }

    #[test]
    fn get_computed_style_never_reveals_visited() {
        let mut fx =
            setup("<html><body><a id=\"l\" href=\"http://example.com/\">x</a></body></html>");
        // Even though the link "has been visited" from the page's point of
        // view, :visited rules must not leak through getComputedStyle.
        let sheet = parse_stylesheet("a:visited { color: red; } a { color: blue; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "l");
        // The unvisited color (blue, serialized by the CSS engine) wins:
        // the :visited rule's red must not leak through.
        assert_eq!(computed_prop(&mut fx, el, "color"), "rgb(0, 0, 255)");
    }

    #[test]
    fn get_computed_style_applies_author_rules() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { display: block; color: green; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "display"), "block");
        assert_eq!(computed_prop(&mut fx, el, "color"), "rgb(0, 128, 0)");
    }

    // w79 overlay phase 1: computed read-back + `CSS.supports`.
    // Author `overlay: auto` computes to `none` for a non-top-layer
    // element (UA rule); top-layer promotion is phase 2 work.
    #[test]
    fn get_computed_style_and_supports_overlay() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { overlay: auto; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overlay"), "none");
        let global = Value::Object(fx.global);
        let prop = str_val(&mut fx, "overlay");
        let auto = str_val(&mut fx, "auto");
        let none = str_val(&mut fx, "none");
        let bad = str_val(&mut fx, "banana");
        assert!(matches!(
            n_parse_css_supports(&mut fx.heap, global, &[prop, auto]),
            Ok(Value::Bool(true))
        ));
        assert!(matches!(
            n_parse_css_supports(&mut fx.heap, global, &[prop, none]),
            Ok(Value::Bool(true))
        ));
        assert!(matches!(
            n_parse_css_supports(&mut fx.heap, global, &[prop, bad]),
            Ok(Value::Bool(false))
        ));
        let cond = str_val(&mut fx, "overlay: auto");
        assert!(matches!(
            n_parse_css_supports(&mut fx.heap, global, &[cond]),
            Ok(Value::Bool(true))
        ));
    }

    #[test]
    fn style_overlay_and_logical_border_accessors_reach_specified_style() {
        // w79fix: `overlay`, `border-inline`, and `border-block`
        // were absent from the curated accessor tables, so a direct
        // `el.style.overlay = "auto"` assignment became a silent JS
        // expando and never reached the style attribute (while
        // `setProperty("overlay", "auto")` worked, because it
        // bypasses the table). Fail-before: on the pre-fix tree
        // `getPropertyValue("overlay")` reads `""` and the live
        // `length` does not count `overlay` (a plain `.overlay`
        // read would only show the silent JS expando, never the
        // style attribute).
        // This pins specified retention only: computed `overlay`
        // is still `none` for a non-top-layer element (phase 1 UA
        // rule; top-layer promotion is phase 2), so the computed
        // assertion below is `none`, not `auto`.
        let (mut vm, _doc) = computed_style_vm(b"<html><body><div id=\"d\">x</div></body></html>");
        let el = "document.getElementById(\"d\")";
        vm.eval(&format!("{el}.style.overlay = \"auto\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.overlay;")),
            "auto"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                &format!("{el}.style.getPropertyValue(\"overlay\");")
            ),
            "auto"
        );
        vm.eval(&format!("{el}.style.overlay = \"banana\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.overlay;")),
            "auto",
            "invalid overlay value must be a no-op"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("getComputedStyle({el}).overlay;")),
            "none"
        );
        vm.eval(&format!("{el}.style.borderInline = \"2px solid aqua\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.borderInline;")),
            "2px solid aqua"
        );
        vm.eval(&format!("{el}.style.borderBlock = \"1px dotted red\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.borderBlock;")),
            "1px dotted red"
        );
        vm.eval(&format!("{el}.style.borderInline = \"\";"))
            .unwrap();
        vm.eval(&format!("{el}.style.borderBlock = \"\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.length;")),
            "1",
            "only the overlay declaration survives clearing both axes"
        );
        // Shim mirror: the same assignments through the parse shim.
        let r = shim_result(
            b"<html><body><div id=t></div>\
              <script>var t = document.getElementById('t'); var out = [];\
              t.style.overlay = 'auto';\
              out.push(t.style.overlay === 'auto' ? 'ok' : 'overlay->' + t.style.overlay);\
              out.push(t.style.getPropertyValue('overlay') === 'auto' ? 'ok' : 'overlay-pv->' + t.style.getPropertyValue('overlay'));\
              t.style.borderInline = '2px solid aqua';\
              out.push(t.style.borderInline === '2px solid aqua' ? 'ok' : 'borderInline->' + t.style.borderInline);\
              t.style.borderBlock = '1px dotted red';\
              out.push(t.style.borderBlock === '1px dotted red' ? 'ok' : 'borderBlock->' + t.style.borderBlock);\
              t.style.borderInline = ''; t.style.borderBlock = '';\
              out.push(t.style.length === 1 ? 'ok' : 'clear-len->' + t.style.length);\
              globalThis.__result = out.join('|');</script>\
              </body></html>",
        );
        let failures: Vec<&str> = r.split('|').filter(|s| *s != "ok").collect();
        assert!(
            failures.is_empty(),
            "shim overlay/logical-border failures: {failures:?}"
        );
    }

    fn vm_eval_str(vm: &mut Vm, expr: &str) -> String {
        let v = vm.eval(expr).unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string from {expr:?}, got {v:?}");
        };
        s.as_wtf8().to_string()
    }

    fn computed_style_vm(html: &[u8]) -> (Vm, Rc<RefCell<Document>>) {
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(html);
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        vm.install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        (vm, doc)
    }

    #[test]
    fn computed_style_float_exposed_as_css_float() {
        // `float` is a reserved word in Rust, so the IDL attribute is
        // `cssFloat` (like `element.style` does) — and the computed
        // declaration also answers the `float` named-property form,
        // matching browsers (WPT
        // css/CSS2/floats/computed-float-position-absolute.html reads
        // `getComputedStyle(el)['float']`).
        let (mut vm, _doc) = computed_style_vm(
            b"<html><body><div id=\"d\" style=\"float: left;\">x</div></body></html>",
        );
        assert_eq!(
            vm_eval_str(
                &mut vm,
                "getComputedStyle(document.getElementById('d')).getPropertyValue('float');"
            ),
            "left"
        );
        assert_eq!(
            vm_eval_str(
                &mut vm,
                "getComputedStyle(document.getElementById('d')).cssFloat;"
            ),
            "left"
        );
        assert_eq!(
            vm_eval_str(
                &mut vm,
                "getComputedStyle(document.getElementById('d'))['float'];"
            ),
            "left"
        );
    }

    #[test]
    fn gcs_float_none_for_abspos_display_none() {
        // WPT css/CSS2/floats/computed-float-position-absolute.html:
        // CSS 2.1 §9.7 computes `float` to `none` for absolutely
        // positioned boxes, and the computed-style object exposes it
        // under both `cssFloat` and `float` (like browsers). (The
        // unit-test VM has no author stylesheets, so the WPT's
        // `<style>` rule is inlined here.)
        let (mut vm, _doc) = computed_style_vm(
            b"<html><body><div id=\"test1\" style=\"display: none; position: absolute; float: left\"></div><div id=\"test2\" style=\"display: contents; position: absolute; float: left\"></div><div style=\"display: none\"><div id=\"test3\" style=\"position: absolute; float: left\"></div></div></body></html>",
        );
        for id in ["test1", "test2", "test3"] {
            // The specified values must have applied (else this test is
            // vacuous): position is absolute, specified float is left.
            let expr = format!(
                "getComputedStyle(document.getElementById('{id}')).getPropertyValue('position');"
            );
            assert_eq!(vm_eval_str(&mut vm, &expr), "absolute", "{id}");
            let expr = format!("getComputedStyle(document.getElementById('{id}'))['float'];");
            assert_eq!(vm_eval_str(&mut vm, &expr), "none", "{id}");
            let expr = format!(
                "getComputedStyle(document.getElementById('{id}')).getPropertyValue('float');"
            );
            assert_eq!(vm_eval_str(&mut vm, &expr), "none", "{id}");
            let expr = format!("getComputedStyle(document.getElementById('{id}')).cssFloat;");
            assert_eq!(vm_eval_str(&mut vm, &expr), "none", "{id}");
        }
        // A non-positioned float still reports its keyword.
        let (mut vm2, _doc2) = computed_style_vm(
            b"<html><body><div id=\"d\" style=\"float: left;\">x</div></body></html>",
        );
        assert_eq!(
            vm_eval_str(
                &mut vm2,
                "getComputedStyle(document.getElementById('d'))['float'];"
            ),
            "left"
        );
    }

    #[test]
    fn computed_style_named_props_are_read_only() {
        // CSSOM: the object from getComputedStyle() is read-only; a
        // held reference must not let named-property writes stick.
        let (mut vm, _doc) = computed_style_vm(
            b"<html><body><div id=\"d\" style=\"margin-left: 5px;\">x</div></body></html>",
        );
        vm.eval("var s = getComputedStyle(document.getElementById('d'));")
            .unwrap();
        assert_eq!(vm_eval_str(&mut vm, "s.marginLeft;"), "5px");
        vm.eval("s.marginLeft = '99px';").unwrap();
        assert_eq!(vm_eval_str(&mut vm, "s.marginLeft;"), "5px");
        vm.eval("s['margin-left'] = '42px';").unwrap();
        assert_eq!(vm_eval_str(&mut vm, "s['margin-left'];"), "5px");
    }

    #[test]
    fn get_computed_style_synthesizes_inset_shorthands() {
        // The logical longhands have their own computed slots; the
        // `inset` family never occupies one, so `n_get_computed_style`
        // synthesizes the shorthands: `inset-block` / `inset-inline`
        // compress the logical pairs, and `inset` serializes from the
        // physical longhands the logical values resolve to (top, right,
        // bottom, left in horizontal-tb ltr).
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet(
            "#d { inset-block-start: 1px; inset-block-end: 2px; \
             inset-inline-start: 3px; inset-inline-end: 4px; }",
        );
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "inset-block"), "1px 2px");
        assert_eq!(computed_prop(&mut fx, el, "inset-inline"), "3px 4px");
        assert_eq!(computed_prop(&mut fx, el, "inset"), "1px 4px 2px 3px");
    }

    #[test]
    fn get_computed_style_resolves_auto_height_to_used_value() {
        // Production gCS: computed `height: auto` resolves to the used
        // content-box height from the published layout tree (mirroring
        // the `used_auto_margins` pattern). The dynamic style change is
        // followed by a re-layout + republish — the app's flush — before
        // the read, like WPT
        // css/css-position/position-absolute-abspos-table-dynamic.html.
        let (mut vm, doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"c\"><div id=\"t\"></div></div></body></html>",
            "#c { width: 400px; height: 300px; position: relative; } \
             #t { display: table; position: absolute; top: 0; width: 50%; height: 100px; }",
        );
        // Sanity: the specified 100px still serializes as-is.
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"t\")).height;"
            ),
            "100px"
        );
        // Dynamic change to `auto`, then the flush: re-layout the
        // mutated document and republish the tree.
        vm.eval("document.getElementById(\"t\").style.height = \"auto\";")
            .unwrap();
        let sheet = bowser_css::parse_stylesheet(
            "#c { width: 400px; height: 300px; position: relative; } \
             #t { display: table; position: absolute; top: 0; width: 50%; height: 100px; }",
        );
        let tree = bowser_layout::layout(
            &doc.borrow(),
            &[&sheet],
            bowser_layout::Size { w: 800.0, h: 600.0 },
            &bowser_layout::FixedFontMetrics,
        );
        share_layout_tree(ctx, Rc::new(tree));
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"t\")).height;"
            ),
            "0px"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn get_computed_style_resolves_auto_width_to_used_value() {
        // `width: auto` on a block fills the containing block: the used
        // content-box width (border box minus borders and padding)
        // resolves from the published tree.
        let (mut vm, _doc, ctx) = geometry_vm(
            b"<html><head></head><body><div id=\"c\"><div id=\"w\">x</div></div></body></html>",
            "#c { width: 400px; } #w { width: auto; padding: 10px; border: 5px solid black; }",
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"w\")).width;"
            ),
            "370px"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn get_computed_style_inset_single_value_compression() {
        // All four logical longhands equal: every inset shorthand
        // compresses to the single value.
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet(
            "#d { inset-block-start: 5px; inset-block-end: 5px; \
             inset-inline-start: 5px; inset-inline-end: 5px; }",
        );
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "inset-block"), "5px");
        assert_eq!(computed_prop(&mut fx, el, "inset-inline"), "5px");
        assert_eq!(computed_prop(&mut fx, el, "inset"), "5px");
    }

    #[test]
    fn style_margin_padding_shorthands_reach_computed_style() {
        // Wave-78 sticky driver probe: `sticky.style.margin = '15px'`
        // left `getComputedStyle(sticky).marginTop` at `"0px"` — the
        // `margin`/`padding` shorthands were not in the curated
        // `el_style_props!` table, so the assignment became a plain JS
        // expando on the style object and never reached the `style`
        // attribute / layout. The same holds for the parse shim.
        let (mut vm, _doc) = computed_style_vm(
            b"<html><body><div id=\"d\" style=\"position: sticky; top: 0;\">x</div></body></html>",
        );
        vm.eval("document.getElementById(\"d\").style.margin = \"15px\";")
            .unwrap();
        vm.eval("document.getElementById(\"d\").style.padding = \"2px 4px\";")
            .unwrap();
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).marginTop;"
            ),
            "15px"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).marginLeft;"
            ),
            "15px"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).paddingTop;"
            ),
            "2px"
        );
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).paddingRight;"
            ),
            "4px"
        );
        // Specified-style read-back synthesizes from the expanded
        // longhands (1-4-value compression, like `inset`).
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d\").style.margin;"),
            "15px"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d\").style.padding;"),
            "2px 4px"
        );
        // Computed shorthand synthesizes from the resolved longhands.
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).margin;"
            ),
            "15px"
        );
        // 4-value form: top/right/bottom/left in CSS order.
        vm.eval("document.getElementById(\"d\").style.margin = \"1px 2px 3px 4px\";")
            .unwrap();
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).marginBottom;"
            ),
            "3px"
        );
        assert_eq!(
            node_list_str(&mut vm, "document.getElementById(\"d\").style.margin;"),
            "1px 2px 3px 4px"
        );
        // Clearing the shorthand clears the longhands it set.
        vm.eval("document.getElementById(\"d\").style.margin = \"\";")
            .unwrap();
        assert_eq!(
            node_list_str(
                &mut vm,
                "getComputedStyle(document.getElementById(\"d\")).marginTop;"
            ),
            "0px"
        );
    }

    #[test]
    fn style_audited_shorthands_reach_specified_style() {
        // Same drop-silently failure as `margin`/`padding`, found by
        // the wave-78 audit: the logical margin/padding pairs, `gap`,
        // `border`, `font`, and `flex` were all absent from the
        // curated tables, so assignments became JS expandos and never
        // reached the `style` attribute. Each expands at parse time
        // (bowser_css) and synthesizes back on read.
        let (mut vm, _doc) = computed_style_vm(b"<html><body><div id=\"d\">x</div></body></html>");
        let el = "document.getElementById(\"d\")";
        // Logical box shorthands: 1-2-value compression on read.
        vm.eval(&format!("{el}.style.marginInline = \"3px 9px\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.marginInline;")),
            "3px 9px"
        );
        vm.eval(&format!("{el}.style.paddingBlock = \"5px\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.paddingBlock;")),
            "5px"
        );
        // `gap`: row first, column second.
        vm.eval(&format!("{el}.style.gap = \"6px 8px\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.gap;")),
            "6px 8px"
        );
        // `border`: reaches the computed border longhands, and reads
        // back when all sides agree.
        vm.eval(&format!("{el}.style.border = \"2px solid red\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("getComputedStyle({el}).borderTopWidth;")),
            "2px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.border;")),
            "2px solid red"
        );
        // `font`: reaches the computed font size; specified read-back
        // drops `normal` components and joins size/line-height.
        vm.eval(&format!("{el}.style.font = \"italic bold 12px serif\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("getComputedStyle({el}).fontSize;")),
            "12px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.font;")),
            "italic bold 12px serif"
        );
        vm.eval(&format!("{el}.style.font = \"12px/1.5 serif\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.font;")),
            "12px/1.5 serif"
        );
        // `flex`: grow/shrink/basis, with `none` expanding to `0 0 auto`.
        vm.eval(&format!("{el}.style.flex = \"2 3 10px\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.flex;")),
            "2 3 10px"
        );
        vm.eval(&format!("{el}.style.flex = \"none\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.flex;")),
            "0 0 auto"
        );
        // Clearing a compound shorthand clears its longhands.
        vm.eval(&format!("{el}.style.border = \"\";")).unwrap();
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.border;")), "");
    }

    #[test]
    fn get_computed_style_synthesizes_new_shorthands_and_m4_colors() {
        // w78fix H2 + M4: the live computed surface exposes the
        // newly curated shorthands and their longhands, and the
        // outline/text-decoration color longhands whose cascade
        // slots F-cascade landed. Specified `aqua` serializes to
        // rgb() through `css_value_to_string`.
        let (mut vm, _doc) = computed_style_vm(
            b"<html><body><div id=\"d\" style=\"gap: 6px 8px; flex: 2 3 10px; font: italic bold 12px serif; margin-inline: 3px 9px; padding-block: 5px 7px; border: 2px solid red; outline-color: aqua; text-decoration-color: aqua;\">x</div></body></html>",
        );
        let gcs = "getComputedStyle(document.getElementById(\"d\"))";
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.gap;")), "6px 8px");
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.rowGap;")), "6px");
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.columnGap;")), "8px");
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.flex;")), "2 3 10px");
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.flexGrow;")), "2");
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.flexShrink;")), "3");
        assert_eq!(node_list_str(&mut vm, &format!("{gcs}.flexBasis;")), "10px");
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.font;")),
            "italic bold 12px serif"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.marginInline;")),
            "3px 9px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.marginInlineStart;")),
            "3px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.marginInlineEnd;")),
            "9px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.paddingBlock;")),
            "5px 7px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.paddingBlockStart;")),
            "5px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.paddingBlockEnd;")),
            "7px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.border;")),
            "2px solid rgb(255, 0, 0)"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.borderWidth;")),
            "2px"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.outlineColor;")),
            "rgb(0, 255, 255)"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.textDecorationColor;")),
            "rgb(0, 255, 255)"
        );
    }

    #[test]
    fn style_sibling_shorthands_synthesize_and_clear() {
        // w78fix H3 (live): `border-width`/`border-style`/
        // `border-color`, `overflow`, `border-<side>`, and
        // `columns` were in the curated table but had no specified
        // synthesis and no clearing: a set expanded at parse time
        // and then read back `""`, and clearing left the expanded
        // longhands in `cssText`/`length`.
        let (mut vm, _doc) = computed_style_vm(b"<html><body><div id=\"d\">x</div></body></html>");
        let el = "document.getElementById(\"d\")";
        vm.eval(&format!("{el}.style.borderWidth = \"2px\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.borderWidth;")),
            "2px"
        );
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.length;")), "4");
        vm.eval(&format!("{el}.style.borderWidth = \"\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.borderWidth;")),
            ""
        );
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.length;")), "0");
        vm.eval(&format!("{el}.style.overflow = \"hidden auto\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.overflow;")),
            "hidden auto"
        );
        vm.eval(&format!("{el}.style.removeProperty('overflow');"))
            .unwrap();
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.length;")), "0");
        vm.eval(&format!("{el}.style.borderTop = \"1px dotted blue\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.borderTop;")),
            "1px dotted blue"
        );
        vm.eval(&format!("{el}.style.borderTop = \"\";")).unwrap();
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.length;")), "0");
        vm.eval(&format!("{el}.style.columns = \"200px 3\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.columns;")),
            "200px 3"
        );
        vm.eval(&format!("{el}.style.columns = \"3\";")).unwrap();
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.columns;")), "3");
        vm.eval(&format!("{el}.style.columns = \"\";")).unwrap();
        assert_eq!(node_list_str(&mut vm, &format!("{el}.style.length;")), "0");
    }

    #[test]
    fn style_sibling_shorthands_synthesize_and_clear_shim() {
        // Shim mirror of the live test above, through the shared
        // `style_apply_set` path.
        let r = shim_result(
            b"<html><body><div id=t></div>\
              <script>var t = document.getElementById('t'); var out = [];\
              t.style.borderWidth = '2px';\
              out.push(t.style.borderWidth === '2px' ? 'ok' : 'borderWidth->' + t.style.borderWidth);\
              out.push(t.style.length === 4 ? 'ok' : 'len->' + t.style.length);\
              t.style.borderWidth = '';\
              out.push(t.style.length === 0 ? 'ok' : 'clear-len->' + t.style.length);\
              t.style.overflow = 'hidden auto';\
              out.push(t.style.overflow === 'hidden auto' ? 'ok' : 'overflow->' + t.style.overflow);\
              t.style.removeProperty('overflow');\
              out.push(t.style.length === 0 ? 'ok' : 'overflow-clear->' + t.style.length);\
              t.style.borderTop = '1px dotted blue';\
              out.push(t.style.borderTop === '1px dotted blue' ? 'ok' : 'borderTop->' + t.style.borderTop);\
              t.style.borderTop = '';\
              out.push(t.style.length === 0 ? 'ok' : 'borderTop-clear->' + t.style.length);\
              t.style.columns = '200px 3';\
              out.push(t.style.columns === '200px 3' ? 'ok' : 'columns->' + t.style.columns);\
              t.style.columns = '';\
              out.push(t.style.length === 0 ? 'ok' : 'columns-clear->' + t.style.length);\
              globalThis.__result = out.join('|');</script>\
              </body></html>",
        );
        let failures: Vec<&str> = r.split('|').filter(|s| *s != "ok").collect();
        assert!(
            failures.is_empty(),
            "shim sibling-shorthand failures: {failures:?}"
        );
    }

    #[test]
    fn style_var_and_wide_keyword_shorthands_replace_stale() {
        // w78fix H4 (live): a `var()` set must not leave stale
        // expanded longhands behind, and a CSS-wide-keyword set on
        // `border`/`font`/`flex` must replace the old value, not
        // silently no-op.
        let (mut vm, _doc) = computed_style_vm(b"<html><body><div id=\"d\">x</div></body></html>");
        let el = "document.getElementById(\"d\")";
        vm.eval(&format!("{el}.style.border = \"2px solid red\";"))
            .unwrap();
        vm.eval(&format!("{el}.style.border = \"inherit\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.borderTopWidth;")),
            "inherit"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.border;")),
            "inherit"
        );
        assert!(
            !node_list_str(&mut vm, &format!("{el}.style.cssText;")).contains("red"),
            "old red border survives a border: inherit set"
        );
        vm.eval(&format!("{el}.style.margin = \"15px\";")).unwrap();
        vm.eval(&format!("{el}.style.margin = \"var(--x)\";"))
            .unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.marginTop;")),
            ""
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.margin;")),
            "var(--x)"
        );
        assert!(
            !node_list_str(&mut vm, &format!("{el}.style.cssText;")).contains("margin-top: 15px"),
            "stale margin-top survives a margin: var(--x) set"
        );
        vm.eval(&format!("{el}.style.font = \"italic 12px serif\";"))
            .unwrap();
        vm.eval(&format!("{el}.style.font = \"inherit\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.font;")),
            "inherit"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.fontSize;")),
            "inherit"
        );
        vm.eval(&format!("{el}.style.flex = \"2 3 10px\";"))
            .unwrap();
        vm.eval(&format!("{el}.style.flex = \"unset\";")).unwrap();
        assert_eq!(
            node_list_str(&mut vm, &format!("{el}.style.flex;")),
            "unset"
        );
        // `flex-grow` is not a curated accessor (it is not in the
        // 119-property table), so it is read via `getPropertyValue`,
        // which still goes through the synthesized-aware getter.
        assert_eq!(
            node_list_str(
                &mut vm,
                &format!("{el}.style.getPropertyValue('flex-grow');")
            ),
            "unset"
        );
    }

    #[test]
    fn style_var_and_wide_keyword_shorthands_replace_stale_shim() {
        // Shim mirror of the live test above.
        let r = shim_result(
            b"<html><body><div id=t></div>\
              <script>var t = document.getElementById('t'); var out = [];\
              t.style.border = '2px solid red'; t.style.border = 'inherit';\
              out.push(t.style.borderTopWidth === 'inherit' ? 'ok' : 'border-wide-long->' + t.style.borderTopWidth);\
              out.push(t.style.border === 'inherit' ? 'ok' : 'border-wide->' + t.style.border);\
              out.push(t.style.cssText.indexOf('red') === -1 ? 'ok' : 'red-survives');\
              t.style.margin = '15px'; t.style.margin = 'var(--x)';\
              out.push(t.style.marginTop === '' ? 'ok' : 'marginTop-stale->' + t.style.marginTop);\
              out.push(t.style.margin === 'var(--x)' ? 'ok' : 'margin-var->' + t.style.margin);\
              t.style.font = 'italic 12px serif'; t.style.font = 'inherit';\
              out.push(t.style.font === 'inherit' ? 'ok' : 'font-wide->' + t.style.font);\
              t.style.flex = '2 3 10px'; t.style.flex = 'unset';\
              out.push(t.style.flex === 'unset' ? 'ok' : 'flex-wide->' + t.style.flex);\
              globalThis.__result = out.join('|');</script>\
              </body></html>",
        );
        let failures: Vec<&str> = r.split('|').filter(|s| *s != "ok").collect();
        assert!(failures.is_empty(), "shim var/wide failures: {failures:?}");
    }

