    #[test]
    fn specified_color_keyword_verifies_against_raw_text() {
        // The keyword comes from the raw token only when it re-parses
        // to exactly the parsed color: no reverse RGB lookup, so
        // `aqua`/`cyan` collisions and hex authorship cannot leak.
        let aqua = CssValue::Color(bowser_css::Color {
            r: 0,
            g: 255,
            b: 255,
            a: 255,
        });
        assert_eq!(
            specified_color_keyword(&aqua, "aqua"),
            Some("aqua".to_string())
        );
        assert_eq!(
            specified_color_keyword(&aqua, "cyan"),
            Some("cyan".to_string())
        );
        assert_eq!(
            specified_color_keyword(&aqua, "AQUA"),
            Some("aqua".to_string())
        );
        assert_eq!(specified_color_keyword(&aqua, "#00ffff"), None);
        assert_eq!(specified_color_keyword(&aqua, "rgb(0, 255, 255)"), None);
        assert_eq!(specified_color_keyword(&aqua, "red"), None);
        let transparent = CssValue::Color(bowser_css::Color {
            r: 0,
            g: 0,
            b: 0,
            a: 0,
        });
        assert_eq!(
            specified_color_keyword(&transparent, "transparent"),
            Some("transparent".to_string())
        );
        assert_eq!(specified_color_keyword(&transparent, "black"), None);
        let list = CssValue::List(vec![
            aqua.clone(),
            CssValue::Color(bowser_css::Color {
                r: 255,
                g: 0,
                b: 0,
                a: 255,
            }),
        ]);
        assert_eq!(
            specified_color_keyword(&list, "aqua red"),
            Some("aqua red".to_string())
        );
        assert_eq!(specified_color_keyword(&list, "aqua"), None);
        assert_eq!(specified_color_keyword(&list, "cyan blue"), None);
    }

    #[test]
    fn w79_background_shorthand_synthesis() {
        // w79 item 2 (fail-before: base has no `background`
        // synthesis at all). Specified form drops initial
        // components; computed form (via
        // `synthesize_computed_shorthands`) keeps them all.
        let decls = style_decls_from_text("background: red");
        assert_eq!(
            synthesize_extended_shorthand(&decls, "background"),
            Some("red".to_string())
        );
        let decls =
            style_decls_from_text("background: url(a.png) no-repeat center/cover padding-box");
        assert_eq!(
            synthesize_extended_shorthand(&decls, "background"),
            // Note: `css_value_to_string` renders `CssValue::Url` bare
            // (no `url()` wrapper) — the pre-existing serializer
            // convention for this surface, not a synthesis choice.
            Some("a.png center / cover no-repeat padding-box".to_string())
        );
        let mut props: HashMap<String, String> =
            decls.iter().map(|(n, v)| (n.clone(), v.clone())).collect();
        synthesize_computed_shorthands(&mut props);
        assert_eq!(
            props.get("background").map(String::as_str),
            Some("a.png center / cover no-repeat scroll padding-box padding-box rgba(0, 0, 0, 0)")
        );
    }

    #[test]
    fn w79_specified_expanded_color_keyword() {
        // w79 item 1 (fail-before: on the base tree the expanded
        // longhands serialize rgb() because the keyword is lost at
        // parse time and the raw-text recovery only matches the
        // shorthand's own property name). `border-color: aqua` must
        // read `aqua` on every side on the specified surface and
        // rgb() on the computed surface; same for `border: solid
        // aqua` (color component) and `background: aqua` (color
        // longhand).
        let specified = style_decls_from_text("border-color: aqua");
        for side in ["top", "right", "bottom", "left"] {
            assert_eq!(
                specified
                    .iter()
                    .find(|(n, _)| n == &format!("border-{side}-color"))
                    .map(|(_, v)| v.as_str()),
                Some("aqua"),
                "specified border-{side}-color"
            );
        }
        let computed = computed_style_decls_from_text("border-color: aqua");
        for side in ["top", "right", "bottom", "left"] {
            assert_eq!(
                computed
                    .iter()
                    .find(|(n, _)| n == &format!("border-{side}-color"))
                    .map(|(_, v)| v.as_str()),
                Some("rgb(0, 255, 255)"),
                "computed border-{side}-color"
            );
        }
        let specified = style_decls_from_text("border: solid aqua");
        assert_eq!(
            specified
                .iter()
                .find(|(n, _)| n == "border-top-color")
                .map(|(_, v)| v.as_str()),
            Some("aqua")
        );
        assert_eq!(
            style_decls_from_text("background: aqua")
                .iter()
                .find(|(n, _)| n == "background-color")
                .map(|(_, v)| v.as_str()),
            Some("aqua")
        );
        assert_eq!(
            computed_style_decls_from_text("background: aqua")
                .iter()
                .find(|(n, _)| n == "background-color")
                .map(|(_, v)| v.as_str()),
            Some("rgb(0, 255, 255)")
        );
    }

    #[test]
    fn w79_logical_border_shorthand_synthesis() {
        // w79 item 3: axis shorthands synthesize from their two
        // edges' agreed components (specified form drops initials);
        // edge shorthands synthesize like the physical sides; a
        // disagreement between edges empties the axis shorthand;
        // computed form keeps all three components.
        let decls = style_decls_from_text("border-inline: 2px solid aqua");
        assert_eq!(
            synthesize_extended_shorthand(&decls, "border-inline"),
            Some("2px solid aqua".to_string())
        );
        assert_eq!(
            synthesize_extended_shorthand(&decls, "border-inline-start"),
            Some("2px solid aqua".to_string())
        );
        let decls = style_decls_from_text("border-block-end: dashed");
        assert_eq!(
            synthesize_extended_shorthand(&decls, "border-block-end"),
            Some("dashed".to_string())
        );
        // Edges disagree: no axis shorthand.
        let mut decls = style_decls_from_text("border-inline: 2px solid aqua");
        if let Some((_, v)) = decls
            .iter_mut()
            .find(|(n, _)| n == "border-inline-end-width")
        {
            *v = "3px".to_string();
        }
        assert_eq!(synthesize_extended_shorthand(&decls, "border-inline"), None);
        // Computed form: all components kept, including initials
        // (unlike the specified form, which drops them).
        let decls = style_decls_from_text("border-inline: dashed");
        let mut props: HashMap<String, String> =
            decls.iter().map(|(n, v)| (n.clone(), v.clone())).collect();
        synthesize_computed_shorthands(&mut props);
        assert_eq!(
            props.get("border-inline").map(String::as_str),
            Some("medium dashed currentcolor")
        );
        // Clearing the axis shorthand clears its six longhands, and
        // setting it replaces them (clearing registration).
        let mut decls = style_decls_from_text("border-inline: 2px solid aqua");
        style_apply_set(&mut decls, "border-inline", "");
        assert!(decls.iter().all(|(n, _)| !n.starts_with("border-inline-")));
        style_apply_set(&mut decls, "border-inline", "1px dotted red");
        assert_eq!(
            synthesize_extended_shorthand(&decls, "border-inline"),
            Some("1px dotted red".to_string())
        );
    }

    #[test]
    fn computed_style_decls_serialize_colors_canonically() {
        // w78fix3: the detached computed fallback must not inherit
        // specified-style keyword preservation — `color: red` reads
        // back as rgb() on the computed path while the specified
        // store still keeps the keyword.
        let style = "color: red; background-color: transparent; border-top-color: aqua";
        assert_eq!(
            computed_style_decls_from_text(style),
            vec![
                ("color".to_string(), "rgb(255, 0, 0)".to_string()),
                (
                    "background-color".to_string(),
                    "rgba(0, 0, 0, 0)".to_string()
                ),
                (
                    "border-top-color".to_string(),
                    "rgb(0, 255, 255)".to_string()
                ),
            ]
        );
        assert_eq!(
            style_decls_from_text(style),
            vec![
                ("color".to_string(), "red".to_string()),
                ("background-color".to_string(), "transparent".to_string()),
                ("border-top-color".to_string(), "aqua".to_string()),
            ]
        );
    }

    #[test]
    fn shorthand_synthesis_edge_cases() {
        // `border` synthesizes only when all sides agree.
        let decls = |w: &str| {
            let mut d = Vec::new();
            for side in ["top", "right", "bottom", "left"] {
                d.push((format!("border-{side}-width"), w.to_string()));
                d.push((format!("border-{side}-style"), "solid".to_string()));
                d.push((format!("border-{side}-color"), "red".to_string()));
            }
            d
        };
        assert_eq!(
            synthesize_compound_shorthand(&decls("2px"), "border"),
            Some("2px solid red".to_string())
        );
        let mut differing = decls("2px");
        differing[0].1 = "3px".to_string();
        assert_eq!(synthesize_compound_shorthand(&differing, "border"), None);
        // `font` needs all six longhands; a partial set stays empty.
        let mut font_decls = vec![
            ("font-size".to_string(), "12px".to_string()),
            ("font-family".to_string(), "serif".to_string()),
        ];
        assert_eq!(synthesize_compound_shorthand(&font_decls, "font"), None);
        for (n, v) in [
            ("font-style", "normal"),
            ("font-variant", "normal"),
            ("font-weight", "normal"),
            ("line-height", "normal"),
        ] {
            font_decls.push((n.to_string(), v.to_string()));
        }
        assert_eq!(
            synthesize_compound_shorthand(&font_decls, "font"),
            Some("12px serif".to_string())
        );
        // `style_apply_set` expands and clears the new shorthands.
        let mut decls = Vec::new();
        style_apply_set(&mut decls, "margin-inline", "3px 9px");
        assert!(decls.contains(&("margin-inline-start".to_string(), "3px".to_string())));
        assert!(decls.contains(&("margin-inline-end".to_string(), "9px".to_string())));
        style_apply_set(&mut decls, "margin-inline", "");
        assert!(decls.is_empty());
        let mut decls = Vec::new();
        style_apply_set(&mut decls, "gap", "6px 8px");
        assert!(decls.contains(&("row-gap".to_string(), "6px".to_string())));
        assert!(decls.contains(&("column-gap".to_string(), "8px".to_string())));
        style_apply_set(&mut decls, "gap", "");
        assert!(decls.is_empty());
    }

    #[test]
    fn mixed_wide_keywords_synthesize_empty() {
        // LOW1: wide keywords cannot combine, so a shorthand whose
        // longhands carry differing wide keywords must serialize as
        // empty (None), never as a joined invalid value.
        let border_mixed = |w: &str, s: &str, c: &str| {
            let mut d = Vec::new();
            for side in ["top", "right", "bottom", "left"] {
                d.push((format!("border-{side}-width"), w.to_string()));
                d.push((format!("border-{side}-style"), s.to_string()));
                d.push((format!("border-{side}-color"), c.to_string()));
            }
            d
        };
        assert_eq!(
            synthesize_compound_shorthand(&border_mixed("inherit", "initial", "unset"), "border"),
            None
        );
        assert_eq!(
            synthesize_compound_shorthand(&border_mixed("inherit", "inherit", "inherit"), "border"),
            Some("inherit".to_string())
        );
        assert_eq!(
            synthesize_border_shorthand(&border_mixed("inherit", "initial", "unset"), "border"),
            None
        );
        let border_top_mixed = vec![
            ("border-top-width".to_string(), "inherit".to_string()),
            ("border-top-style".to_string(), "initial".to_string()),
            ("border-top-color".to_string(), "unset".to_string()),
        ];
        assert_eq!(
            synthesize_extended_shorthand(&border_top_mixed, "border-top"),
            None
        );
        let columns_mixed = vec![
            ("column-width".to_string(), "inherit".to_string()),
            ("column-count".to_string(), "initial".to_string()),
        ];
        assert_eq!(
            synthesize_extended_shorthand(&columns_mixed, "columns"),
            None
        );
        let columns_same = vec![
            ("column-width".to_string(), "unset".to_string()),
            ("column-count".to_string(), "unset".to_string()),
        ];
        assert_eq!(
            synthesize_extended_shorthand(&columns_same, "columns"),
            Some("unset".to_string())
        );
        let font_mixed = vec![
            ("font-style".to_string(), "inherit".to_string()),
            ("font-variant".to_string(), "normal".to_string()),
            ("font-weight".to_string(), "normal".to_string()),
            ("font-size".to_string(), "12px".to_string()),
            ("line-height".to_string(), "normal".to_string()),
            ("font-family".to_string(), "serif".to_string()),
        ];
        assert_eq!(synthesize_compound_shorthand(&font_mixed, "font"), None);
        let font_same: Vec<(String, String)> = FONT_SHORTHAND_LONGHANDS
            .iter()
            .map(|lh| (lh.to_string(), "inherit".to_string()))
            .collect();
        assert_eq!(
            synthesize_compound_shorthand(&font_same, "font"),
            Some("inherit".to_string())
        );
        let flex_mixed = vec![
            ("flex-grow".to_string(), "inherit".to_string()),
            ("flex-shrink".to_string(), "initial".to_string()),
            ("flex-basis".to_string(), "unset".to_string()),
        ];
        assert_eq!(synthesize_compound_shorthand(&flex_mixed, "flex"), None);
        let flex_same: Vec<(String, String)> = FLEX_SHORTHAND_LONGHANDS
            .iter()
            .map(|lh| (lh.to_string(), "revert".to_string()))
            .collect();
        assert_eq!(
            synthesize_compound_shorthand(&flex_same, "flex"),
            Some("revert".to_string())
        );
    }

    #[test]
    fn wide_keyword_shorthand_set_is_not_lost() {
        // LOW2, tightened (w79fix, whole-diff review finding 7):
        // setting a shorthand to a lone wide keyword must never
        // silently drop the set. The old form accepted EITHER a
        // stored ("border", "inherit") decl OR >= 12 inherit
        // longhands, so it passed via the expansion disjunct even
        // if the deferred-store path regressed. The exact form
        // below pins the path that actually runs today: the
        // parser expands `border: inherit` to exactly the 12
        // longhands (no stored shorthand decl), the stale value
        // is replaced, unrelated declarations survive, and the
        // compound synthesis reads the set back as `inherit`.
        // NOTE (probe-verified, w79fix): no curated shorthand
        // reaches the empty-`checked` arm of `style_apply_set`
        // today — all 35 shorthands in
        // `specified_shorthand_longhands` expand every one of the
        // five wide keywords at parse time, so the deferred-store
        // push in that arm is defense for a future unexpanded
        // shorthand and cannot be pinned through `border: inherit`
        // (or any other current shorthand) alone. This test pins
        // the observable non-loss property through the expansion
        // path that runs, and the synthesis side (uniform keyword
        // -> the keyword, mixed keywords -> None) is pinned by
        // `mixed_wide_keywords_synthesize_empty`, which is
        // unchanged.
        let mut decls = vec![
            ("border-top-width".to_string(), "2px".to_string()),
            ("border-top-color".to_string(), "red".to_string()),
            ("color".to_string(), "green".to_string()),
        ];
        style_apply_set(&mut decls, "border", "inherit");
        assert!(
            !decls.contains(&("border".to_string(), "inherit".to_string())),
            "border: inherit must expand, not store a shorthand decl: {decls:?}"
        );
        let inherit_longhands: Vec<&(String, String)> = decls
            .iter()
            .filter(|(n, v)| n.starts_with("border-") && v == "inherit")
            .collect();
        assert_eq!(
            inherit_longhands.len(),
            12,
            "border: inherit must yield exactly 12 inherit longhands: {decls:?}"
        );
        assert!(
            !decls.iter().any(|(_, v)| v == "red" || v == "2px"),
            "stale border values survive a border: inherit set: {decls:?}"
        );
        assert!(
            decls.contains(&("color".to_string(), "green".to_string())),
            "unrelated declarations must survive: {decls:?}"
        );
        assert_eq!(
            synthesize_compound_shorthand(&decls, "border"),
            Some("inherit".to_string()),
            "expanded inherit longhands must synthesize back to inherit"
        );
    }

    #[test]
    fn computed_background_synthesizes_on_live_and_shim_surfaces() {
        // w79fix (whole-diff review finding 6): `background`
        // synthesis existed but never fired on the live surface,
        // because neither prop table listed the seven layered
        // longhands, so `getComputedStyle(el).background` read
        // `""`. Wiring the longhands into `STYLE_PROPS` (live)
        // and `PARSE_COMPUTED_PROPS` (shim) makes the shared
        // synthesis fire on both. Fail-before: both reads below
        // are `undefined` (not `""`: `background` was absent from
        // the props map, so `wrap_style` defined no such property;
        // longhands also absent), still a failing test. The serialized form
        // keeps every computed component, and `url()` serializes
        // bare (`a.png`) per the pre-existing serializer
        // convention. A bare element still synthesizes the
        // initial background instead of reading `""`.
        let (mut vm, _doc) = computed_style_vm(
            b"<html><body><div id=\"d\" style=\"background: url(a.png) no-repeat center/cover padding-box\">x</div></body></html>",
        );
        let gcs = "getComputedStyle(document.getElementById(\"d\"))";
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.background;")),
            "a.png center / cover no-repeat scroll padding-box padding-box rgba(0, 0, 0, 0)"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.backgroundImage;")),
            "a.png"
        );
        assert_eq!(
            node_list_str(&mut vm, &format!("{gcs}.backgroundClip;")),
            "padding-box"
        );
        let (mut vm2, _doc2) =
            computed_style_vm(b"<html><body><div id=\"d\">x</div></body></html>");
        assert_eq!(
            node_list_str(
                &mut vm2,
                "getComputedStyle(document.getElementById(\"d\")).background;"
            ),
            "none 0% 0% / auto auto repeat scroll padding-box border-box rgba(0, 0, 0, 0)"
        );
        let r = shim_result(
            b"<html><body><div id=t style=\"background: url(a.png) no-repeat center/cover padding-box\"></div>\
              <script>var t = document.getElementById('t'); var cs = getComputedStyle(t); var out = [];\
              out.push(cs.background === 'a.png center / cover no-repeat scroll padding-box padding-box rgba(0, 0, 0, 0)' ? 'ok' : 'background->' + cs.background);\
              out.push(cs.backgroundImage === 'a.png' ? 'ok' : 'image->' + cs.backgroundImage);\
              out.push(cs.backgroundClip === 'padding-box' ? 'ok' : 'clip->' + cs.backgroundClip);\
              globalThis.__result = out.join('|');</script>\
              </body></html>",
        );
        let failures: Vec<&str> = r.split('|').filter(|s| *s != "ok").collect();
        assert!(
            failures.is_empty(),
            "shim computed background failures: {failures:?}"
        );
    }

    #[test]
    fn shim_logical_inset_specified_serialization_matches_wpt() {
        // WPT css-position/parsing/inset-valid.html through the parse
        // shim: every single value on every logical longhand, plus the
        // shorthand singles and doubles. Mirrors test_valid_value
        // (set, read, re-set the read value, read again).
        let r = shim_result(
            b"<html><body><div id=t></div>\
              <script>var t = document.getElementById('t'); var out = [];\
              function check(prop, val, exp) {\
                t.style[prop] = ''; t.style[prop] = val;\
                var read = t.style.getPropertyValue(prop);\
                out.push(read === exp ? 'ok' : prop + '=' + val + '->' + read + '!=' + exp);\
                t.style[prop] = read;\
                var reread = t.style.getPropertyValue(prop);\
                out.push(reread === read ? 'ok' : prop + ' roundtrip ' + reread + '!=' + read);\
              }\
              var longs = ['inset-block-start', 'inset-block-end', 'inset-inline-start', 'inset-inline-end'];\
              var singles = [['0', '0px'], ['auto', 'auto'], ['10%', '10%'], ['1rem', '1rem'], ['-10px', '-10px'], ['-20%', '-20%'], ['calc(2em + 3ex)', 'calc(2em + 3ex)']];\
              for (var i = 0; i < longs.length; i++)\
                for (var j = 0; j < singles.length; j++) check(longs[i], singles[j][0], singles[j][1]);\
              var shorts = ['inset-block', 'inset-inline'];\
              for (var i = 0; i < shorts.length; i++) {\
                for (var j = 0; j < singles.length; j++) check(shorts[i], singles[j][0], singles[j][1]);\
                check(shorts[i], 'auto auto', 'auto');\
                check(shorts[i], '100px 100px', '100px');\
                check(shorts[i], '10% -5px', '10% -5px');\
                check(shorts[i], '1rem calc(0px)', '1rem calc(0px)');\
              }\
              check('top', 'calc(2em + 3ex)', 'calc(2em + 3ex)');\
              globalThis.__result = out.join('|');</script>\
              </body></html>",
        );
        let failures: Vec<&str> = r.split('|').filter(|s| *s != "ok").collect();
        assert!(
            failures.is_empty(),
            "specified inset failures: {failures:?}"
        );
    }

    #[test]
    fn shim_logical_inset_computed_matches_wpt() {
        // WPT css-position/parsing/inset-computed.html through the
        // parse shim: #target at 40px, every value on every logical
        // longhand, plus the `in getComputedStyle` and CSS.supports
        // gates the testcommon asserts first.
        let r = shim_result(
            b"<html><head><style>#target { font-size: 40px; }</style></head><body><div id=target></div>\
              <script>var t = document.getElementById('target'); var out = [];\
              var longs = ['inset-block-start', 'inset-block-end', 'inset-inline-start', 'inset-inline-end'];\
              var vals = [['auto', 'auto'], ['calc(10px + 0.5em)', '30px'], ['calc(10px - 0.5em)', '-10px'], ['-40%', '-40%'], ['calc(50% + 60px)', 'calc(50% + 60px)']];\
              for (var i = 0; i < longs.length; i++) {\
                var prop = longs[i];\
                var cs = getComputedStyle(t);\
                out.push((prop in cs) ? 'ok' : prop + ' not in computed');\
                for (var j = 0; j < vals.length; j++) {\
                  out.push(CSS.supports(prop, vals[j][0]) ? 'ok' : prop + ' supports(' + vals[j][0] + ') false');\
                  t.style[prop] = ''; t.style[prop] = vals[j][0];\
                  var read = getComputedStyle(t)[prop];\
                  out.push(read === vals[j][1] ? 'ok' : prop + '=' + vals[j][0] + '->' + read + '!=' + vals[j][1]);\
                }\
              }\
              globalThis.__result = out.join('|');</script>\
              </body></html>",
        );
        let failures: Vec<&str> = r.split('|').filter(|s| *s != "ok").collect();
        assert!(failures.is_empty(), "computed inset failures: {failures:?}");
    }

    #[test]
    fn shim_quirks_mode_reaches_rebuilt_documents() {
        // Mid-parse (end-of-body script, `readyState === "loading"`)
        // the shim rebuilds a fresh `Document` from the parser
        // snapshot, whose quirks mode defaults to `NoQuirks` — so
        // the live parser quirks mode must be threaded into the
        // rebuild, or every quirks rule is invisible to mid-parse
        // reads. §3.11 (computed `font-style` stops at the table
        // boundary in full quirks mode) and §3.13 (a cell's
        // `height` resolves as border-box in full quirks mode)
        // discriminate: the standards control must stay
        // `italic|140`, the quirks document must read `normal|100`.
        let script = b"<script>var c = document.getElementById('c');\
              globalThis.__result = getComputedStyle(c)['font-style'] + '|' + c.offsetHeight;</script>\
              </body></html>";
        let mut quirks_html =
            b"<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.0 Transitional//EN\"><html><body>\
              <div style='font-style:italic'><table><tr>\
              <td id=c style='height:100px;box-sizing:content-box;padding:20px'>x</td>\
              </tr></table></div>"
                .to_vec();
        quirks_html.extend_from_slice(script);
        let mut standards_html = b"<!DOCTYPE html><html><body>\
              <div style='font-style:italic'><table><tr>\
              <td id=c style='height:100px;box-sizing:content-box;padding:20px'>x</td>\
              </tr></table></div>"
            .to_vec();
        standards_html.extend_from_slice(script);
        assert_eq!(shim_result(&standards_html), "italic|140");
        assert_eq!(shim_result(&quirks_html), "normal|100");
    }

    #[test]
    fn get_computed_style_table_mapping_and_border_adjustments() {
        // The html-to-css-mapping-2 shapes through the production
        // surface: hints reach computed style, and the CSSOM
        // adjustments resolve border widths / colors.
        let mut fx = setup(
            "<html><body><table id=\"t\" border=\"10\" rules=\"all\">\
             <tr><td id=\"c\">x</td></tr></table></body></html>",
        );
        let t = call_get_element_by_id(&mut fx, "t");
        assert_eq!(computed_prop(&mut fx, t, "border-left-width"), "10px");
        assert_eq!(computed_prop(&mut fx, t, "border-left-style"), "outset");
        assert_eq!(
            computed_prop(&mut fx, t, "border-left-color"),
            "rgb(128, 128, 128)"
        );
        assert_eq!(computed_prop(&mut fx, t, "border-width"), "10px");
        assert_eq!(computed_prop(&mut fx, t, "border-collapse"), "collapse");
        let c = call_get_element_by_id(&mut fx, "c");
        assert_eq!(computed_prop(&mut fx, c, "border-left-width"), "1px");
        assert_eq!(computed_prop(&mut fx, c, "border-left-style"), "solid");
        assert_eq!(
            computed_prop(&mut fx, c, "border-top-color"),
            "rgb(128, 128, 128)"
        );
    }

    #[test]
    fn get_computed_style_border_width_zeroed_by_none_style() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet(
            "#d { border-top-width: 9px; border-bottom-style: solid; \
             border-bottom-width: thick; }",
        );
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        // Style `none` (the initial) zeroes the computed width;
        // `thick` computes to 5px against a solid style.
        assert_eq!(computed_prop(&mut fx, el, "border-top-width"), "0px");
        assert_eq!(computed_prop(&mut fx, el, "border-bottom-width"), "5px");
    }

    #[test]
    fn get_computed_style_border_spacing_absolute_pair_and_currentcolor() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet(
            "#d { font-size: 10px; border-spacing: 1em 2px; color: red; \
             border-top-style: solid; }",
        );
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        // `em` resolves against the computed font-size; the value
        // serializes as an absolute pair.
        assert_eq!(computed_prop(&mut fx, el, "border-spacing"), "10px 2px");
        // The initial border color is `currentcolor`, which computes
        // to the element's computed color.
        assert_eq!(
            computed_prop(&mut fx, el, "border-top-color"),
            "rgb(255, 0, 0)"
        );
        assert_eq!(computed_prop(&mut fx, el, "table-layout"), "auto");
    }

    #[test]
    fn border_spacing_value_resolution_collapses_and_evaluates_calc() {
        // The component resolution behind `adjust_computed_props`:
        // absolute lengths absolutize, an equal pair collapses to the
        // CSSOM shortest serialization, and `calc()` components
        // evaluate against the adjust metrics (here a 40px font size,
        // so `0.5em` is 20px) with negative results clamped to zero.
        let ctx = ComputedAdjustCtx {
            font_px: 40.0,
            root_px: 16.0,
            vw: 1280.0,
            vh: 800.0,
        };
        let r = |s: &str| resolve_border_spacing_value(s, &ctx).map(|v| v.to_string());
        assert_eq!(r("0").as_deref(), Some("0px"));
        assert_eq!(r("5px").as_deref(), Some("5px"));
        assert_eq!(r("5px 5px").as_deref(), Some("5px"));
        assert_eq!(r("5px 10px").as_deref(), Some("5px 10px"));
        assert_eq!(r("10px 20px").as_deref(), Some("10px 20px"));
        assert_eq!(
            r("calc(10px + 0.5em) calc(10px - 0.5em)").as_deref(),
            Some("30px 0px")
        );
        assert_eq!(
            r("calc(10px - 0.5em) calc(10px + 0.5em)").as_deref(),
            Some("0px 30px")
        );
        assert_eq!(r("calc(30px)").as_deref(), Some("30px"));
        assert_eq!(r("min(50px, 2em)").as_deref(), Some("50px"));
        // Percentages have no base here: unresolvable, left as-is by
        // the caller.
        assert_eq!(r("50%"), None);
        assert_eq!(r("5px 10px 15px"), None);
    }

    #[test]
    fn get_computed_style_border_spacing_collapse_and_calc() {
        // CSSOM shortest serialization + math resolution through the
        // production surface (WPT
        // `css-tables/parsing/border-spacing-computed.html` shapes):
        // a single value stays single, an equal pair collapses, and
        // inline `calc()` pairs resolve (the negative component
        // clamps to zero).
        let mut fx = setup(
            "<html><body>\
             <div id=a style=\"border-spacing: 0\"></div>\
             <div id=b style=\"border-spacing: 5px\"></div>\
             <div id=c style=\"border-spacing: 5px 5px\"></div>\
             <div id=d style=\"border-spacing: 5px 10px\"></div>\
             <div id=e style=\"font-size: 40px; border-spacing: calc(10px + 0.5em) calc(10px - 0.5em)\"></div>\
             <div id=f style=\"font-size: 40px; border-spacing: calc(10px - 0.5em) calc(10px + 0.5em)\"></div>\
             <div id=g></div>\
             </body></html>",
        );
        let sheet = parse_stylesheet("#g { border-spacing: calc(10px + 5px) calc(20px); }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        for (id, want) in [
            ("a", "0px"),
            ("b", "5px"),
            ("c", "5px"),
            ("d", "5px 10px"),
            ("e", "30px 0px"),
            ("f", "0px 30px"),
            ("g", "15px 20px"),
        ] {
            let el = call_get_element_by_id(&mut fx, id);
            assert_eq!(computed_prop(&mut fx, el, "border-spacing"), want, "#{id}");
        }
    }

    #[test]
    fn parse_computed_border_spacing_collapse_and_calc() {
        // The same shapes through the parse shim: values written via
        // `el.style` keep their raw `calc()` text in the declaration
        // store (not the serializer's debug form), and the computed
        // read resolves them; a single value no longer duplicates.
        let r = shim_result(
            b"<html><head><style>#t { font-size: 40px; }</style></head><body>\
              <div id=t></div>\
              <div id=u style=\"border-spacing: 5px\"></div>\
              <div id=v style=\"border-spacing: 5px 5px\"></div>\
              <script>var t = document.getElementById('t');\
              t.style.borderSpacing = 'calc(10px + 0.5em) calc(10px - 0.5em)';\
              var a = getComputedStyle(t).borderSpacing;\
              t.style.borderSpacing = '0';\
              var b = getComputedStyle(t).borderSpacing;\
              globalThis.__result = [a, b,\
                getComputedStyle(document.getElementById('u')).borderSpacing,\
                getComputedStyle(document.getElementById('v')).borderSpacing].join('|');</script>\
              </body></html>",
        );
        assert_eq!(r, "30px 0px|0px|5px|5px");
    }

    #[test]
    fn get_computed_style_only_overflow_x_has_no_stale_bare_overflow() {
        // Only `overflow-x` is declared. The cascade's bare `overflow`
        // slot stays at its stale `visible` keyword in this case, so
        // the CSSOM surface must not serialize that slot: the only
        // `overflow` value it may emit is the shorthand synthesized
        // from the two axes (`hidden` + the computed `auto` the
        // visible y axis adjusts to).
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { overflow-x: hidden; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overflow-x"), "hidden");
        assert_eq!(computed_prop(&mut fx, el, "overflow-y"), "auto");
        assert_eq!(computed_prop(&mut fx, el, "overflow"), "hidden auto");
        assert_ne!(computed_prop(&mut fx, el, "overflow"), "visible");
        // Both axes set: the shorthand still synthesizes.
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { overflow-x: scroll; overflow-y: hidden; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overflow"), "scroll hidden");
    }

    #[test]
    fn get_computed_style_exposes_overflow_axes_and_shorthand() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { overflow: hidden auto; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overflow-x"), "hidden");
        assert_eq!(computed_prop(&mut fx, el, "overflow-y"), "auto");
        // The shorthand serializes from the axes: two different
        // keywords stay a two-value shorthand.
        assert_eq!(computed_prop(&mut fx, el, "overflow"), "hidden auto");
    }

    #[test]
    fn get_computed_style_overflow_shorthand_collapses_equal_axes() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { overflow: hidden; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overflow-x"), "hidden");
        assert_eq!(computed_prop(&mut fx, el, "overflow-y"), "hidden");
        assert_eq!(computed_prop(&mut fx, el, "overflow"), "hidden");
        // Undeclared: the initial `visible` on both axes collapses to
        // the single keyword, never the bare `overflow` slot's content.
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overflow"), "visible");
        assert_eq!(computed_prop(&mut fx, el, "overflow-x"), "visible");
        assert_eq!(computed_prop(&mut fx, el, "overflow-y"), "visible");
    }

    #[test]
    fn get_computed_style_exposes_overflow_logical_longhands() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { overflow-block: scroll; overflow-inline: clip; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "overflow-block"), "scroll");
        assert_eq!(computed_prop(&mut fx, el, "overflow-inline"), "clip");
        // Block folds to the y axis, inline to the x axis (horizontal
        // writing mode); the shorthand follows the physical axes.
        assert_eq!(computed_prop(&mut fx, el, "overflow-x"), "clip");
        assert_eq!(computed_prop(&mut fx, el, "overflow-y"), "scroll");
        assert_eq!(computed_prop(&mut fx, el, "overflow"), "clip scroll");
    }

    #[test]
    fn get_computed_style_scroll_margin_negative_longhand() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        // `scroll-margin` keeps negative computed lengths (unlike
        // `scroll-padding`, which clamps them to zero): the negative
        // must read back, not collapse to `0px`.
        let sheet = parse_stylesheet("#d { scroll-margin-top: -10px; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-top"), "-10px");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-right"), "0px");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-bottom"), "0px");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-left"), "0px");
        // Standard 1-4-value compression (right == left collapses
        // the 4-value form to 3).
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin"), "-10px 0px 0px");
    }

    #[test]
    fn get_computed_style_scroll_margin_shorthand_compression() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { scroll-margin: 5px 10px 5px 10px; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin"), "5px 10px");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-top"), "5px");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-bottom"), "5px");

        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { scroll-margin: 1px 2px 3px; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin"), "1px 2px 3px");

        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { scroll-margin: 0; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        // A unitless zero is a `<length>` zero: `0px`, never `0`.
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin-top"), "0px");
        assert_eq!(computed_prop(&mut fx, el, "scroll-margin"), "0px");
    }

    #[test]
    fn get_computed_style_scroll_padding_calc_serializes() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { scroll-padding-top: calc(10% + 5px); }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(
            computed_prop(&mut fx, el, "scroll-padding-top"),
            "calc(10% + 5px)"
        );
        // Untouched sides fall back to the `auto` initial; the
        // shorthand compresses (right == left) to the 3-value form.
        assert_eq!(
            computed_prop(&mut fx, el, "scroll-padding"),
            "calc(10% + 5px) auto auto"
        );
    }

    #[test]
    fn get_computed_style_scroll_snap_serializes() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet =
            parse_stylesheet("#d { scroll-snap-type: x mandatory; scroll-snap-align: start end; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(
            computed_prop(&mut fx, el, "scroll-snap-type"),
            "x mandatory"
        );
        assert_eq!(computed_prop(&mut fx, el, "scroll-snap-align"), "start end");

        // `proximity` is the default strictness: canonical computed
        // form folds to the bare axis keyword.
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { scroll-snap-type: y proximity; }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "scroll-snap-type"), "y");

        // Initials: not a snap container, not a snap area.
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let el = call_get_element_by_id(&mut fx, "d");
        assert_eq!(computed_prop(&mut fx, el, "scroll-snap-type"), "none");
        assert_eq!(computed_prop(&mut fx, el, "scroll-snap-align"), "none");
    }

    #[test]
    fn custom_property_calc_serializes_unevaluated() {
        let mut fx = setup("<html><body><div id=\"d\">x</div></body></html>");
        let sheet = parse_stylesheet("#d { --x: calc(1em + 1px); }");
        fx.apis.borrow_mut().set_author_stylesheets(vec![sheet]);
        let el = call_get_element_by_id(&mut fx, "d");
        // Same computed-style pipeline as `n_get_computed_style`, but the
        // JS-facing object only projects STYLE_PROPS, so query the
        // `ComputedStyle` for the custom property directly.
        let s = {
            let rc = fx.apis.clone();
            let g = rc.borrow();
            let node = target_node(&fx.heap, el, &g).unwrap();
            let doc_rc = g.live_document().expect("document is gone");
            let doc = doc_rc.borrow();
            let author: Vec<&Stylesheet> = g.author_stylesheets.iter().collect();
            let computed = compute_style(&doc, node, &author, &g.ua_stylesheet, &g.viewport);
            let v = computed
                .get("--x")
                .expect("custom property in computed style");
            css_value_to_string(v)
        };
        // Per CSS Custom Properties the calc must round-trip unevaluated:
        // evaluating with a zero-metric context used to report "1px".
        // The real `calc()` serialization keeps the source form
        // (`calc(1em + 1px)`), which is unevaluated — not the folded
        // "1px" the zero-metric evaluation produced.
        assert!(s.contains("calc("), "expected unevaluated calc, got {s}");
        assert_ne!(s, "1px", "calc must not be evaluated, got {s}");
    }

    #[test]
    fn transform_serializes_single_axis_forms() {
        use bowser_css::LengthUnit;
        let len = |n: f32, u: LengthUnit| CssValue::Length(n, u);
        // `translatex(1em)` parses with y defaulted to zero; the
        // serializer keeps the single-axis form.
        let t = CssValue::Transform(vec![TransformFunction::Translate {
            x: len(1.0, LengthUnit::Em),
            y: CssValue::Number(0.0),
        }]);
        assert_eq!(css_value_to_string(&t), "translatex(1em)");
        // An explicit zero length on the second axis also collapses.
        let t = CssValue::Transform(vec![TransformFunction::Translate {
            x: len(1.0, LengthUnit::Em),
            y: len(0.0, LengthUnit::Px),
        }]);
        assert_eq!(css_value_to_string(&t), "translatex(1em)");
        // A nonzero second axis keeps the two-argument form.
        let t = CssValue::Transform(vec![TransformFunction::Translate {
            x: len(1.0, LengthUnit::Em),
            y: len(2.0, LengthUnit::Px),
        }]);
        assert_eq!(css_value_to_string(&t), "translate(1em, 2px)");
        // `scale(2)` duplicates x into y; the serializer drops the copy.
        let s = CssValue::Transform(vec![TransformFunction::Scale {
            x: CssValue::Number(2.0),
            y: CssValue::Number(2.0),
        }]);
        assert_eq!(css_value_to_string(&s), "scale(2)");
        // Distinct axes keep both arguments.
        let s = CssValue::Transform(vec![TransformFunction::Scale {
            x: CssValue::Number(2.0),
            y: CssValue::Number(3.0),
        }]);
        assert_eq!(css_value_to_string(&s), "scale(2, 3)");
        // Opaque functions round-trip as authored.
        let o = CssValue::Transform(vec![TransformFunction::Other {
            name: "skew".to_string(),
            raw_args: "10deg, 20deg".to_string(),
        }]);
        assert_eq!(css_value_to_string(&o), "skew(10deg, 20deg)");
        // Multi-function lists keep order and spacing.
        let m = CssValue::Transform(vec![
            TransformFunction::Translate {
                x: len(1.0, LengthUnit::Em),
                y: CssValue::Number(0.0),
            },
            TransformFunction::Rotate { angle_deg: 45.0 },
        ]);
        assert_eq!(css_value_to_string(&m), "translatex(1em) rotate(45deg)");
    }

    // -- wrapper identity and element/document properties ------------------

    fn obj_of(v: Value) -> Gc<Object> {
        match v {
            Value::Object(o) => o,
            _ => panic!("expected an object, got {v:?}"),
        }
    }

    fn prop_str(fx: &Fixture, obj: Gc<Object>, name: &str) -> String {
        match fx
            .heap
            .get_property(obj, Wtf8::from_str(name))
            .unwrap()
            .value
        {
            Value::Str(s) => s.as_wtf8().to_string(),
            v => panic!("{name} is not a string: {v:?}"),
        }
    }

    /// `textContent` read through either representation: the eager data
    /// snapshot, or the retired lazily-computed accessor (installed by
    /// `retire_text_content` for ancestors of a mutation). The raw
    /// `prop_str` helper only sees data properties, so it cannot read
    /// the retired form.
    fn prop_text_content(fx: &mut Fixture, obj: Gc<Object>) -> String {
        if let Some(p) = fx.heap.get_property(obj, Wtf8::from_str("textContent")) {
            match p.value {
                Value::Str(s) => return s.as_wtf8().to_string(),
                v => panic!("textContent is not a string: {v:?}"),
            }
        }
        // Retired accessor: invoke the bindings' lazy getter, which
        // recomputes from the DOM (and self-heals by materializing the
        // snapshot).
        match n_text_content_get(&mut fx.heap, Value::Object(obj), &[]) {
            Ok(Value::Str(s)) => s.as_wtf8().to_string(),
            v => panic!("textContent getter did not return a string: {v:?}"),
        }
    }

    fn prop_val(fx: &Fixture, obj: Gc<Object>, name: &str) -> Value {
        fx.heap
            .get_property(obj, Wtf8::from_str(name))
            .unwrap()
            .value
    }

    fn call_method(
        fx: &mut Fixture,
        recv: Value,
        method: fn(&mut Heap, Value, &[Value]) -> Result<Value, NativeError>,
        args: &[Value],
    ) -> Value {
        method(&mut fx.heap, recv, args).unwrap()
    }

    #[test]
    fn wrapper_identity_across_repeated_lookups() {
        let mut fx =
            setup("<html><body><div id=\"a\"><span id=\"b\">hi</span></div></body></html>");
        // `===`: the same Gc address on every lookup of the same node.
        let w1 = call_get_element_by_id(&mut fx, "a");
        let w2 = call_get_element_by_id(&mut fx, "a");
        assert_eq!(w1, w2);
        // A different lookup path for the same node yields the same wrapper.
        let doc_val = global_prop(&fx, "document");
        let sel = str_val(&mut fx, "#a");
        let w3 = n_query_selector(&mut fx.heap, doc_val, &[sel]).unwrap();
        assert_eq!(w1, w3);
        // ...via parentNode/children too.
        let b = call_get_element_by_id(&mut fx, "b");
        let parent = prop_val(&fx, obj_of(b), "parentNode");
        assert_eq!(parent, w1);
        let kids = obj_of(prop_val(&fx, obj_of(w1), "children"));
        assert_eq!(prop_val(&fx, kids, "0"), b);
        // Different nodes get different wrappers.
        assert_ne!(w1, b);
    }

    #[test]
    fn wrapper_identity_survives_removal() {
        let mut fx =
            setup("<html><body><div id=\"a\"><span id=\"b\">hi</span></div></body></html>");
        let a = call_get_element_by_id(&mut fx, "a");
        let b = call_get_element_by_id(&mut fx, "b");
        let b_node = node_of(&fx, b);
        n_remove_child(&mut fx.heap, a, &[b]).unwrap();
        // The node is gone from the tree...
        assert_eq!(call_get_element_by_id(&mut fx, "b"), Value::Null);
        assert_eq!(prop_val(&fx, obj_of(b), "parentNode"), Value::Null);
        // ...but the detached node keeps its wrapper: no invalidation, no
        // aliasing (NodeIds are never reused).
        assert_eq!(
            fx.apis.borrow().gc_roots.borrow().wrapper_cache[&b_node],
            obj_of(b)
        );
        assert_eq!(prop_str(&fx, obj_of(b), "textContent"), "hi");
    }

    #[test]
    fn attached_wrappers_survive_collection() {
        // (was `cached_wrappers_are_gc_roots`): the cache holds WEAK
        // values now — an attached node's wrapper survives a collection
        // because the wrapper graph (document wrapper -> body ->
        // children) keeps it reachable, not because the cache pins it.
        let mut fx = setup("<html><body><div id=\"a\">x</div></body></html>");
        let w = call_get_element_by_id(&mut fx, "a");
        // Register the apis as an embedder trace root, the way the engine
        // will via `Heap::add_trace_root`.
        struct ApisRoot(Rc<RefCell<WebApis>>);
        unsafe impl Trace for ApisRoot {
            fn trace(&self, t: &mut Tracer) {
                self.0.borrow().gc_roots.borrow().trace(t);
            }
        }
        let root = Box::leak(Box::new(ApisRoot(fx.apis.clone())));
        unsafe {
            fx.heap.add_trace_root(root as *mut ApisRoot);
        }
        // Allocate garbage, then collect: the attached wrapper (and its
        // properties) must survive, with its cache entry and identity
        // intact.
        for i in 0..200 {
            fx.heap.alloc_str(&format!("trash-{i}")).unwrap();
        }
        fx.heap.collect();
        let a_node = node_of(&fx, w);
        assert!(
            fx.apis
                .borrow()
                .gc_roots
                .borrow()
                .wrapper_cache
                .contains_key(&a_node),
            "attached wrapper's cache entry must survive"
        );
        let w2 = call_get_element_by_id(&mut fx, "a");
        assert_eq!(w, w2);
        assert_eq!(prop_str(&fx, obj_of(w2), "tagName"), "DIV");
        assert_eq!(prop_str(&fx, obj_of(w2), "textContent"), "x");
    }

    #[test]
    fn detached_unreachable_wrappers_are_evicted() {
        // The leak this fixes: a detached node's wrapper, unreachable
        // from JS, must be freed by the collection and evicted from the
        // cache — the cache no longer pins detached subtrees for the
        // context's lifetime (unbounded growth on SPA churn).
        let mut fx =
            setup("<html><body><div id=\"a\"><span id=\"b\">hi</span></div></body></html>");
        let a = call_get_element_by_id(&mut fx, "a");
        let b = call_get_element_by_id(&mut fx, "b");
        let b_node = node_of(&fx, b);
        n_remove_child(&mut fx.heap, a, &[b]).unwrap();
        // Until a collection runs the entry (and identity) is intact —
        // `wrapper_identity_survives_removal` pins this.
        assert_eq!(
            fx.apis.borrow().gc_roots.borrow().wrapper_cache[&b_node],
            obj_of(b)
        );
        // Every handle to the detached wrapper is a plain Rust local now
        // (Rust locals are not GC roots; script never saw this wrapper),
        // so it is reachable only through the weak cache entry.
        fx.heap.collect();
        assert!(
            !fx.apis
                .borrow()
                .gc_roots
                .borrow()
                .wrapper_cache
                .contains_key(&b_node),
            "detached unreachable wrapper must be evicted from the cache"
        );
    }

    #[test]
    fn element_tag_name_and_text_content() {
        let mut fx =
            setup("<html><body><div id=\"a\">hello <span>world</span></div></body></html>");
        let w = call_get_element_by_id(&mut fx, "a");
        let o = obj_of(w);
        // tagName is the ASCII-uppercased tag name.
        assert_eq!(prop_str(&fx, o, "tagName"), "DIV");
        // textContent is the concatenated descendant text.
        assert_eq!(prop_str(&fx, o, "textContent"), "hello world");
        // A text node has textContent but no tagName.
        let kids = obj_of(prop_val(&fx, o, "children"));
        let text_w = prop_val(&fx, kids, "0");
        assert_eq!(prop_str(&fx, obj_of(text_w), "textContent"), "hello ");
        assert!(
            fx.heap
                .get_property(obj_of(text_w), Wtf8::from_str("tagName"))
                .is_none()
        );
    }

    #[test]
    fn get_set_remove_attribute() {
        let mut fx = setup("<html><body><div id=\"a\" class=\"c\"></div></body></html>");
        let w = call_get_element_by_id(&mut fx, "a");
        let name = str_val(&mut fx, "class");
        let got = call_method(&mut fx, w, n_get_attribute, &[name]);
        assert_eq!(str_contents(&fx, got), "c");
        let missing = str_val(&mut fx, "nope");
        assert_eq!(
            call_method(&mut fx, w, n_get_attribute, &[missing]),
            Value::Null
        );
        // setAttribute writes through to the real DOM...
        let k = str_val(&mut fx, "data-x");
        let v = str_val(&mut fx, "1");
        call_method(&mut fx, w, n_set_attribute, &[k, v]);
        let k2 = str_val(&mut fx, "data-x");
        let got2 = call_method(&mut fx, w, n_get_attribute, &[k2]);
        assert_eq!(str_contents(&fx, got2), "1");
        assert_eq!(
            fx.doc.borrow().get_attribute(node_of(&fx, w), "data-x"),
            Some("1")
        );
        // ...and removeAttribute clears it.
        let k3 = str_val(&mut fx, "data-x");
        call_method(&mut fx, w, n_remove_attribute, &[k3]);
        let k4 = str_val(&mut fx, "data-x");
        assert_eq!(call_method(&mut fx, w, n_get_attribute, &[k4]), Value::Null);
    }

    /// `{ mode }` init dictionary for `attachShadow` calls.
    fn shadow_init(fx: &mut Fixture, mode: &str) -> Value {
        let o = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        let v = str_val(fx, mode);
        fx.heap
            .define_property_str(o, "mode", Property::data(v))
            .unwrap();
        Value::Object(o)
    }

    /// Read an inherited WebIDL attribute through the wrapper's
    /// prototype chain: `shadowRoot` is a prototype accessor, and the
    /// `prop_val` helper only reads own data properties.
    fn proto_attr(fx: &mut Fixture, recv: Value, name: &str) -> Value {
        let getter = walk_proto_chain(&fx.heap, obj_of(recv), |o| {
            fx.heap.get_accessor(o, Wtf8::from_str(name)).map(|a| a.get)
        })
        .unwrap_or_else(|| panic!("{name} accessor on prototype chain"));
        call_function(&mut fx.heap, getter, recv, &[]).expect("getter call")
    }

    #[test]
    fn attach_shadow_open_returns_root_and_shadow_root_getter() {
        let mut fx = setup("<html><body><div id=\"h\"></div></body></html>");
        let h = call_get_element_by_id(&mut fx, "h");
        let init = shadow_init(&mut fx, "open");
        let root = call_method(&mut fx, h, n_attach_shadow, &[init]);
        // Returned a wrapper for the shadow fragment node.
        let frag = node_of(&fx, root);
        assert!(matches!(
            fx.doc.borrow().kind(frag),
            NodeKind::DocumentFragment
        ));
        assert!(fx.doc.borrow().is_shadow_root(frag));
        // `shadowRoot` getter exposes the open root (identity-stable).
        // The accessor lives on the shared element prototype, so read it
        // through the chain rather than via the own-property helper.
        let via_getter = proto_attr(&mut fx, h, "shadowRoot");
        assert_eq!(via_getter, root);
        // The shadow root accepts children via the shared appendChild.
        let doc_val = global_prop(&fx, "document");
        let span_tag = str_val(&mut fx, "span");
        let kid = call_method(&mut fx, doc_val, n_create_element, &[span_tag]);
        let back = call_method(&mut fx, root, n_append_child, &[kid]);
        assert_eq!(back, kid);
        assert_eq!(node_of(&fx, kid), {
            let d = fx.doc.borrow();
            d.children(frag).into_iter().next().expect("kid linked")
        });
        // ...but stays out of the host's light-DOM children.
        let kids = obj_of(prop_val(&fx, obj_of(h), "children"));
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(0));
    }

    #[test]
    fn attach_shadow_closed_hides_shadow_root_getter() {
        let mut fx = setup("<html><body><div id=\"h\"></div></body></html>");
        let h = call_get_element_by_id(&mut fx, "h");
        let init = shadow_init(&mut fx, "closed");
        let root = call_method(&mut fx, h, n_attach_shadow, &[init]);
        // The closed root is a real fragment node internally...
        let frag = node_of(&fx, root);
        assert!(fx.doc.borrow().is_shadow_root(frag));
        assert_eq!(fx.doc.borrow().shadow_host_for(frag), Some(node_of(&fx, h)));
        // ...but the page cannot reach it through `shadowRoot`.
        assert_eq!(proto_attr(&mut fx, h, "shadowRoot"), Value::Null);
    }

    #[test]
    fn attach_shadow_rejects_bad_init_and_double_attach() {
        let mut fx = setup("<html><body><div id=\"h\"></div></body></html>");
        let h = call_get_element_by_id(&mut fx, "h");
        // Missing init.
        assert!(n_attach_shadow(&mut fx.heap, h, &[]).is_err());
        // Missing mode.
        let empty = fx
            .heap
            .alloc_object(Object::new(ObjectKind::Ordinary))
            .unwrap();
        assert!(n_attach_shadow(&mut fx.heap, h, &[Value::Object(empty)]).is_err());
        // Bad mode value.
        let bad = shadow_init(&mut fx, "bogus");
        assert!(n_attach_shadow(&mut fx.heap, h, &[bad]).is_err());
        // First attach wins; the second throws.
        let init = shadow_init(&mut fx, "open");
        assert!(n_attach_shadow(&mut fx.heap, h, &[init]).is_ok());
        let init2 = shadow_init(&mut fx, "closed");
        let err = n_attach_shadow(&mut fx.heap, h, &[init2]).unwrap_err();
        assert!(matches!(err, NativeError::TypeError(_)));
    }

    #[test]
    fn append_child_rejects_shadow_root_as_child() {
        let mut fx = setup("<html><body><div id=\"h\"></div><div id=\"o\"></div></body></html>");
        let h = call_get_element_by_id(&mut fx, "h");
        let o = call_get_element_by_id(&mut fx, "o");
        let init = shadow_init(&mut fx, "open");
        let root = call_method(&mut fx, h, n_attach_shadow, &[init]);
        // Inserting the shadow root itself anywhere throws (it would
        // splice the fragment and empty the shadow tree).
        let err = n_append_child(&mut fx.heap, o, &[root]).unwrap_err();
        assert!(matches!(err, NativeError::TypeError(_)));
        let err = n_insert_before(&mut fx.heap, o, &[root, Value::Null]).unwrap_err();
        assert!(matches!(err, NativeError::TypeError(_)));
        // The shadow tree is intact.
        assert!(fx.doc.borrow().is_shadow_root(node_of(&fx, root)));
    }

    #[test]
    fn append_child_returns_child_and_updates_live_props() {
        let mut fx = setup("<html><body><div id=\"a\"></div></body></html>");
        let doc_val = global_prop(&fx, "document");
        let a = call_get_element_by_id(&mut fx, "a");
        let ao = obj_of(a);
        // document.createTextNode produces a detached text wrapper.
        let data = str_val(&mut fx, "hi");
        let text = call_method(&mut fx, doc_val, n_create_text_node, &[data]);
        assert_eq!(prop_val(&fx, obj_of(text), "parentNode"), Value::Null);
        // appendChild returns the child wrapper (identity) and links it.
        let back = call_method(&mut fx, a, n_append_child, &[text]);
        assert_eq!(back, text);
        assert_eq!(prop_val(&fx, obj_of(text), "parentNode"), a);
        // children is identity-stable and live.
        let kids1 = prop_val(&fx, ao, "children");
        let kids2 = prop_val(&fx, ao, "children");
        assert_eq!(kids1, kids2);
        let kids = obj_of(kids1);
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(1));
        assert_eq!(prop_val(&fx, kids, "0"), text);
        // textContent picked up the new descendant text (the parent's
        // snapshot retires to the lazy accessor on mutation; read it
        // through either representation).
        assert_eq!(prop_text_content(&mut fx, ao), "hi");
    }

    #[test]
    fn append_child_moves_between_parents() {
        let mut fx = setup(
            "<html><body><div id=\"a\"><span id=\"s\">x</span></div><div id=\"b\"></div></body></html>",
        );
        let a = call_get_element_by_id(&mut fx, "a");
        let b = call_get_element_by_id(&mut fx, "b");
        let s = call_get_element_by_id(&mut fx, "s");
        call_method(&mut fx, b, n_append_child, &[s]);
        // The old parent's children/textContent re-synced...
        let ak = obj_of(prop_val(&fx, obj_of(a), "children"));
        assert_eq!(prop_val(&fx, ak, "length"), Value::Int(0));
        assert_eq!(prop_text_content(&mut fx, obj_of(a)), "");
        // ...and the new parent's did too, with wrapper identity intact.
        let bk = obj_of(prop_val(&fx, obj_of(b), "children"));
        assert_eq!(prop_val(&fx, bk, "length"), Value::Int(1));
        assert_eq!(prop_val(&fx, bk, "0"), s);
        assert_eq!(prop_val(&fx, obj_of(s), "parentNode"), b);
        assert_eq!(prop_text_content(&mut fx, obj_of(b)), "x");
    }

    #[test]
    fn insert_before_orders_children() {
        let mut fx = setup(
            "<html><body><div id=\"a\"><i id=\"i1\">1</i><i id=\"i3\">3</i></div></body></html>",
        );
        let doc_val = global_prop(&fx, "document");
        let a = call_get_element_by_id(&mut fx, "a");
        let i3 = call_get_element_by_id(&mut fx, "i3");
        let tag = str_val(&mut fx, "i");
        let i2 = call_method(&mut fx, doc_val, n_create_element, &[tag]);
        let idk = str_val(&mut fx, "id");
        let idv = str_val(&mut fx, "i2");
        call_method(&mut fx, i2, n_set_attribute, &[idk, idv]);
        let back = call_method(&mut fx, a, n_insert_before, &[i2, i3]);
        assert_eq!(back, i2);
        let kids = obj_of(prop_val(&fx, obj_of(a), "children"));
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(3));
        let child_id = |i: u32| {
            let w = prop_val(&fx, kids, &i.to_string());
            node_id_attr(&fx, node_of(&fx, w))
        };
        assert_eq!(child_id(0), Some("i1".to_string()));
        assert_eq!(child_id(1), Some("i2".to_string()));
        assert_eq!(child_id(2), Some("i3".to_string()));
        // A null reference appends.
        let tag2 = str_val(&mut fx, "i");
        let i4 = call_method(&mut fx, doc_val, n_create_element, &[tag2]);
        call_method(&mut fx, a, n_insert_before, &[i4, Value::Null]);
        let kids = obj_of(prop_val(&fx, obj_of(a), "children"));
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(4));
    }

    #[test]
    fn remove_child_detaches_and_returns_child() {
        let mut fx = setup("<html><body><div id=\"a\"><span id=\"s\">x</span></div></body></html>");
        let a = call_get_element_by_id(&mut fx, "a");
        let s = call_get_element_by_id(&mut fx, "s");
        let back = call_method(&mut fx, a, n_remove_child, &[s]);
        assert_eq!(back, s);
        assert_eq!(prop_val(&fx, obj_of(s), "parentNode"), Value::Null);
        let kids = obj_of(prop_val(&fx, obj_of(a), "children"));
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(0));
        assert_eq!(prop_str(&fx, obj_of(a), "textContent"), "");
        // The DOM agrees the child is gone.
        assert!(fx.doc.borrow().get_element_by_id("s").is_none());
    }

    #[test]
    fn hierarchy_violations_are_type_errors_not_panics() {
        let mut fx =
            setup("<html><body><div id=\"a\">text</div><div id=\"b\"></div></body></html>");
        let a = call_get_element_by_id(&mut fx, "a");
        let b = call_get_element_by_id(&mut fx, "b");
        // The text child of `a`, reached through the children array.
        let kids = obj_of(prop_val(&fx, obj_of(a), "children"));
        let text_w = prop_val(&fx, kids, "0");
        // Appending to a text node: HierarchyRequestError, not a panic.
        let r = n_append_child(&mut fx.heap, text_w, &[b]);
        assert!(matches!(r, Err(NativeError::TypeError(_))));
        // insertBefore with a reference that is not a child: NotFoundError.
        let r2 = n_insert_before(&mut fx.heap, a, &[b, b]);
        assert!(matches!(r2, Err(NativeError::TypeError(_))));
        // removeChild of a non-child: NotFoundError.
        let r3 = n_remove_child(&mut fx.heap, a, &[b]);
        assert!(matches!(r3, Err(NativeError::TypeError(_))));
        // Appending the document node itself is rejected too.
        let doc_val = global_prop(&fx, "document");
        let r4 = n_append_child(&mut fx.heap, a, &[doc_val]);
        assert!(matches!(r4, Err(NativeError::TypeError(_))));
    }

    #[test]
    fn document_body_document_element_title() {
        let mut fx = setup("<html><head><title>Hi</title></head><body><p>x</p></body></html>");
        let doc_val = global_prop(&fx, "document");
        let d = obj_of(doc_val);
        let body = prop_val(&fx, d, "body");
        assert_eq!(prop_str(&fx, obj_of(body), "tagName"), "BODY");
        let de = prop_val(&fx, d, "documentElement");
        assert_eq!(prop_str(&fx, obj_of(de), "tagName"), "HTML");
        assert_eq!(prop_str(&fx, d, "title"), "Hi");
        // document.body is the identity wrapper for the body node.
        let body_node = fx
            .doc
            .borrow()
            .get_elements_by_tag_name("body")
            .item(0)
            .unwrap();
        assert_eq!(
            fx.apis.borrow().gc_roots.borrow().wrapper_cache[&body_node],
            obj_of(body)
        );
        // Mutating the tree keeps document-level props live: replace the
        // title text through the DOM and append a node to the body.
        {
            let title_el = fx
                .doc
                .borrow()
                .get_elements_by_tag_name("title")
                .item(0)
                .unwrap();
            fx.doc.borrow_mut().set_text_content(title_el, "Yo");
        }
        let p_tag = str_val(&mut fx, "p");
        let p = call_method(&mut fx, doc_val, n_create_element, &[p_tag]);
        call_method(&mut fx, body, n_append_child, &[p]);
        assert_eq!(prop_str(&fx, d, "title"), "Yo");
        let body_kids = obj_of(prop_val(&fx, obj_of(body), "children"));
        assert_eq!(prop_val(&fx, body_kids, "length"), Value::Int(2));
    }

    #[test]
    fn document_head_lookup() {
        let mut fx = setup("<html><head><title>Hi</title></head><body><p>x</p></body></html>");
        let doc_val = global_prop(&fx, "document");
        let d = obj_of(doc_val);
        let head = prop_val(&fx, d, "head");
        assert_eq!(prop_str(&fx, obj_of(head), "tagName"), "HEAD");
        // document.head is the identity wrapper for the head node.
        let head_node = fx
            .doc
            .borrow()
            .get_elements_by_tag_name("head")
            .item(0)
            .unwrap();
        assert_eq!(
            fx.apis.borrow().gc_roots.borrow().wrapper_cache[&head_node],
            obj_of(head)
        );
        // Removing the head refreshes document.head to null via
        // after_dom_mutation; body is unaffected.
        let de = prop_val(&fx, d, "documentElement");
        call_method(&mut fx, de, n_remove_child, &[head]);
        assert_eq!(prop_val(&fx, d, "head"), Value::Null);
        assert_eq!(
            prop_str(&fx, obj_of(prop_val(&fx, d, "body")), "tagName"),
            "BODY"
        );
    }

    // -- scripts ----------------------------------------------------------

    struct TouchEngine {
        doc: Rc<RefCell<Document>>,
        saw: Vec<String>,
        saw_modules: Vec<(String, String)>,
    }

    impl ScriptEngine for TouchEngine {
        fn evaluate(&mut self, _heap: &mut Heap, source: &str) -> Result<(), ScriptError> {
            self.saw.push(source.to_string());
            // The script touches the DOM: append a marker node.
            let mut doc = self.doc.borrow_mut();
            let div = doc.create_element("div");
            doc.set_attribute(div, "id", "from-script");
            let body = doc.get_elements_by_tag_name("body").item(0).unwrap();
            doc.append_child(body, div);
            Ok(())
        }

        fn evaluate_module(
            &mut self,
            _heap: &mut Heap,
            url: &str,
            source: &str,
        ) -> Result<(), ScriptError> {
            self.saw_modules.push((url.to_string(), source.to_string()));
            Ok(())
        }
    }

    #[test]
    fn run_script_element_runs_inline_and_touches_dom() {
        let mut fx =
            setup("<html><body><script id=\"s\">/* inline source */</script></body></html>");
        let script = fx.doc.borrow().get_element_by_id("s").unwrap();
        let mut engine = TouchEngine {
            doc: fx.doc.clone(),
            saw: Vec::new(),
            saw_modules: Vec::new(),
        };
        run_script_element(&mut fx.heap, &fx.apis, script, &mut engine).unwrap();
        assert_eq!(engine.saw, vec!["/* inline source */".to_string()]);
        assert!(fx.doc.borrow().get_element_by_id("from-script").is_some());
    }

    #[test]
    fn run_script_element_executes_module_and_rejects_non_scripts() {
        let mut fx = setup(
            "<html><body><script id=\"m\" type=\"module\">evil()</script><div id=\"d\"></div></body></html>",
        );
        let module_script = fx.doc.borrow().get_element_by_id("m").unwrap();
        let div = fx.doc.borrow().get_element_by_id("d").unwrap();
        let mut engine = TouchEngine {
            doc: fx.doc.clone(),
            saw: Vec::new(),
            saw_modules: Vec::new(),
        };
        // type="module" executes through the module path, with the
        // document URL as the referrer for inline modules.
        run_script_element(&mut fx.heap, &fx.apis, module_script, &mut engine).unwrap();
        assert!(
            engine.saw.is_empty(),
            "module must not hit the classic runner"
        );
        assert_eq!(engine.saw_modules.len(), 1);
        let (referrer, source) = &engine.saw_modules[0];
        assert_eq!(source, "evil()");
        assert_eq!(referrer, "http://example.com/");
        // A non-script element is an error.
        let err = run_script_element(&mut fx.heap, &fx.apis, div, &mut engine);
        assert_eq!(err, Err(ScriptError::NotAScriptElement));
    }

    /// A [`ScriptEngine`] that really executes modules: it owns a [`Vm`]
    /// and a [`ModuleLoader`] whose import resolution is driven by the
    /// loader's in-memory source map, with the network disabled.
    struct LiveModuleEngine {
        vm: Vm,
        loader: ModuleLoader,
    }

    impl LiveModuleEngine {
        fn with_dep(dep_url: &str, dep_source: &str) -> Self {
            let mut loader = ModuleLoader::new();
            loader.set_allow_net(false);
            loader.add_source(dep_url, dep_source);
            Self {
                vm: Vm::new(),
                loader,
            }
        }
    }

    impl ScriptEngine for LiveModuleEngine {
        fn evaluate(&mut self, _heap: &mut Heap, source: &str) -> Result<(), ScriptError> {
            self.vm
                .eval(source)
                .map(|_| ())
                .map_err(|e| ScriptError::Eval(e.to_string()))
        }

        fn evaluate_module(
            &mut self,
            _heap: &mut Heap,
            url: &str,
            source: &str,
        ) -> Result<(), ScriptError> {
            self.loader
                .load_source(&mut self.vm, url, source)
                .map(|_| ())
                .map_err(|e| ScriptError::Eval(e.to_string()))
        }
    }

    #[test]
    fn run_script_element_module_import_live_binding() {
        // The dependency exports a mutable binding plus a mutator. It is
        // resolved through the loader's in-memory source map (network
        // disabled), so this test never touches the network.
        let dep_url = "http://example.com/dep.js";
        let mut engine = LiveModuleEngine::with_dep(
            dep_url,
            "export let counter = 1;\nexport function bump() { counter += 1; }\n",
        );
        let mut fx = setup(
            "<html><body><script id=\"m\" type=\"module\">\
             import { counter, bump } from \"./dep.js\";\n\
             globalThis.seenBefore = counter;\n\
             bump();\n\
             globalThis.seenAfter = counter;\n\
             </script></body></html>",
        );
        let script = fx.doc.borrow().get_element_by_id("m").unwrap();
        run_script_element(&mut fx.heap, &fx.apis, script, &mut engine).unwrap();

        // The importer saw the initial value, then the mutation made by
        // the defining module's own `bump()`: the import is a live
        // binding, not a snapshot.
        let before = engine.vm.eval("globalThis.seenBefore").unwrap();
        let after = engine.vm.eval("globalThis.seenAfter").unwrap();
        assert_eq!(before, Value::Int(1));
        assert_eq!(after, Value::Int(2));

        // The dep's namespace object is the single source of truth for
        // the live binding.
        let ns = engine
            .loader
            .namespace_of(&engine.vm, dep_url)
            .expect("dep namespace registered");
        let Value::Object(ns_obj) = ns else {
            panic!("dep namespace is not an object");
        };
        let counter = engine
            .vm
            .heap()
            .get_property(ns_obj, Wtf8::from_str("counter"))
            .expect("counter exported")
            .value;
        assert_eq!(counter, Value::Int(2));
    }

    #[test]
    fn run_script_element_external_src_fetch_failure() {
        let mut fx = setup(
            "<html><body><script id=\"e\" src=\"foo://example.com/app.js\"></script></body></html>",
        );
        let script = fx.doc.borrow().get_element_by_id("e").unwrap();
        let mut engine = TouchEngine {
            doc: fx.doc.clone(),
            saw: Vec::new(),
            saw_modules: Vec::new(),
        };
        // Unsupported scheme fails fast in bowser_net, without network I/O.
        let err = run_script_element(&mut fx.heap, &fx.apis, script, &mut engine);
        assert!(matches!(err, Err(ScriptError::Fetch(_))));
        assert!(engine.saw.is_empty());
    }

    #[test]
    fn run_script_element_document_gone() {
        // A torn-down document must surface as `ScriptError::DocumentGone`,
        // not panic the process (the old `.expect("document is gone")`).
        let mut fx = setup("<html><body><script id=\"s\">evil()</script></body></html>");
        let script = fx.doc.borrow().get_element_by_id("s").unwrap();
        // Tear down the document: drop the fixture's strong handle so
        // the weak registry handle dangles.
        drop(fx.doc);
        // The engine is never reached (the failure happens before
        // evaluation), so it gets a dummy document.
        let (dummy, _) = Document::parse_html(b"".as_slice());
        let mut engine = TouchEngine {
            doc: Rc::new(RefCell::new(dummy)),
            saw: Vec::new(),
            saw_modules: Vec::new(),
        };
        let err = run_script_element(&mut fx.heap, &fx.apis, script, &mut engine);
        assert_eq!(err, Err(ScriptError::DocumentGone));
        assert!(engine.saw.is_empty());
        assert!(engine.saw_modules.is_empty());
    }

    // -- fetch worker pool --------------------------------------------------

    fn test_fetch_request() -> net_fetch::Request {
        net_fetch::Request {
            method: "GET".to_string(),
            url: bowser_url::parse("http://example.com/", None).unwrap(),
            headers: Vec::new(),
            body: None,
        }
    }

    fn test_fetch_task(
        tx: &Sender<(u32, FetchOutcome)>,
        cancel: &Arc<AtomicBool>,
        job: u32,
    ) -> FetchTask {
        FetchTask {
            tx: tx.clone(),
            job,
            request: test_fetch_request(),
            cancel: cancel.clone(),
            jar: None,
            nav: net_fetch::NavigationContext::default(),
            credentials_sent: None,
        }
    }

    static POOL_THREAD_IDS: OnceLock<Mutex<Vec<thread::ThreadId>>> = OnceLock::new();

    /// Test fetch impl: records the executing thread, fails fast.
    fn recording_fetch(_task: &FetchTask) -> FetchOutcome {
        POOL_THREAD_IDS
            .get_or_init(|| Mutex::new(Vec::new()))
            .lock()
            .unwrap()
            .push(thread::current().id());
        Err("injected failure".to_string())
    }

    #[test]
    fn fetch_pool_shares_workers_across_fetches() {
        let ids = POOL_THREAD_IDS.get_or_init(|| Mutex::new(Vec::new()));
        ids.lock().unwrap().clear();

        let pool = FetchPool::new(4, 64, recording_fetch);
        let (ctx_tx, ctx_rx) = mpsc::channel::<(u32, FetchOutcome)>();
        let cancel = Arc::new(AtomicBool::new(false));
        const JOBS: u32 = 16;
        for job in 0..JOBS {
            pool.submit(test_fetch_task(&ctx_tx, &cancel, job)).unwrap();
        }
        // Every job runs to completion; each completion proves its task ran.
        // Outcomes are recorded via POOL_THREAD_IDS; the Result payload
        // itself is intentionally discarded here.
        for _ in 0..JOBS {
            let _ = ctx_rx.recv().expect("fetch completion");
        }

        let ids = ids.lock().unwrap();
        assert_eq!(ids.len(), JOBS as usize, "every submitted fetch must run");
        let distinct: HashSet<thread::ThreadId> = ids.iter().copied().collect();
        assert!(
            distinct.len() <= 4,
            "16 fetches must share the 4 pool workers, ran on {} threads",
            distinct.len()
        );
        assert!(
            (distinct.len() as u32) < JOBS,
            "no thread-per-fetch: each fetch must not get its own thread"
        );
        // Spawned handles, not live count: thread startup is not
        // instantaneous, so `live_workers()` may legitimately lag here.
        assert_eq!(pool.workers.len(), 4, "pool must spawn 4 workers");
    }

    #[test]
    fn fetch_pool_drop_joins_workers() {
        let live = {
            let pool = FetchPool::new(4, 16, recording_fetch);
            let live = pool.live_workers.clone();
            while live.load(Ordering::Relaxed) != 4 {
                thread::yield_now();
            }
            live
        };
        assert_eq!(
            live.load(Ordering::Relaxed),
            0,
            "dropping the pool must join every worker: no leaked threads"
        );
    }

    static FETCH_GATE: Mutex<Option<mpsc::Receiver<()>>> = Mutex::new(None);

    /// Test fetch impl: blocks until the test releases the gate.
    /// The gate receiver is taken under the lock and the lock released
    /// before the blocking `recv`: holding a mutex across a blocking
    /// wait would deadlock the test thread spinning on the same mutex.
    fn blocking_fetch(_task: &FetchTask) -> FetchOutcome {
        let rx = FETCH_GATE.lock().unwrap().take();
        if let Some(rx) = rx {
            let _ = rx.recv();
        }
        Err("gate released".to_string())
    }

    #[test]
    fn fetch_pool_bounded_queue_rejects_when_full() {
        let (gate_tx, gate_rx) = mpsc::channel::<()>();
        *FETCH_GATE.lock().unwrap() = Some(gate_rx);

        // One worker, one queue slot: the first task pins the worker on
        // the gate, the second fills the queue, the third must be
        // rejected rather than block or grow memory.
        let pool = FetchPool::new(1, 1, blocking_fetch);
        let (ctx_tx, _ctx_rx) = mpsc::channel::<(u32, FetchOutcome)>();
        let cancel = Arc::new(AtomicBool::new(false));
        pool.submit(test_fetch_task(&ctx_tx, &cancel, 1)).unwrap();
        // Wait until the worker has taken task 1 and is blocked in the
        // fetch; only then is the queue deterministically busy-but-empty.
        while FETCH_GATE.lock().unwrap().is_some() {
            thread::yield_now();
        }
        pool.submit(test_fetch_task(&ctx_tx, &cancel, 2)).unwrap();
        assert_eq!(
            pool.submit(test_fetch_task(&ctx_tx, &cancel, 3)),
            Err(FetchSubmitError::QueueFull),
            "a full bounded queue must reject, not block or grow"
        );
        // Release the gate; the worker drains and the pool joins on drop.
        drop(gate_tx);
    }

    static CANCELLED_RUNS: OnceLock<AtomicUsize> = OnceLock::new();

    /// Test fetch impl: counts invocations.
    fn counting_fetch(_task: &FetchTask) -> FetchOutcome {
        CANCELLED_RUNS
            .get_or_init(|| AtomicUsize::new(0))
            .fetch_add(1, Ordering::SeqCst);
        Err("counted".to_string())
    }

    #[test]
    fn net_fetch_impl_does_not_hold_jar_lock_across_io() {
        // w77fix: the shared profile jar must not be locked across
        // network I/O. A slow font fetch held the lock for its whole
        // duration, so navigation initiation (whose jar swap takes
        // the same lock on the event thread) stalled behind it and
        // concurrent JS font fetches serialized. The server delays
        // its response 500ms; once it has read the request the
        // fetch is in flight, and the jar lock must already be
        // free — while the seeded profile cookie must still have
        // been sent (snapshot semantics) and the server's
        // `Set-Cookie` must land in the live jar afterwards.
        use std::io::{Read, Write};
        use std::net::TcpListener;
        use std::sync::atomic::AtomicBool;

        let listener = TcpListener::bind("127.0.0.1:0").expect("bind slow server");
        let addr = listener.local_addr().expect("slow server addr");
        let seen_req = Arc::new(AtomicBool::new(false));
        let seen_req_server = Arc::clone(&seen_req);
        let seen_cookie: Arc<std::sync::Mutex<Vec<String>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen_cookie_server = Arc::clone(&seen_cookie);
        std::thread::spawn(move || {
            for stream in listener.incoming() {
                let Ok(mut stream) = stream else { continue };
                let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
                let mut buf = Vec::new();
                let mut chunk = [0u8; 4096];
                loop {
                    match stream.read(&mut chunk) {
                        Ok(0) => break,
                        Ok(n) => {
                            buf.extend_from_slice(&chunk[..n]);
                            if buf.windows(4).any(|w| w == b"\r\n\r\n") || buf.len() > 65_536 {
                                break;
                            }
                        }
                        Err(_) => break,
                    }
                }
                let head = String::from_utf8_lossy(&buf);
                let cookie = head
                    .lines()
                    .find_map(|line| line.strip_prefix("Cookie:"))
                    .map(str::trim)
                    .unwrap_or("(none)")
                    .to_string();
                seen_cookie_server.lock().expect("seen").push(cookie);
                seen_req_server.store(true, Ordering::SeqCst);
                std::thread::sleep(Duration::from_millis(500));
                let response = "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nSet-Cookie: srv=1; Path=/\r\nConnection: close\r\n\r\nhi";
                let _ = stream.write_all(response.as_bytes());
            }
        });

        let jar: Arc<std::sync::Mutex<CookieJar>> =
            Arc::new(std::sync::Mutex::new(CookieJar::new()));
        jar.lock().expect("test jar").set_cookie(
            "session=abc123; Path=/",
            &bowser_net::cookies::RequestContext {
                host: "127.0.0.1",
                path: "/",
                secure: false,
                http_api: true,
                top_host: None,
                top_secure: None,
                top_level_safe_navigation: false,
            },
            0,
        );
        let (tx, _rx) = mpsc::channel::<(u32, FetchOutcome)>();
        let task = FetchTask {
            tx,
            job: 1,
            request: net_fetch::Request {
                method: "GET".to_string(),
                url: bowser_url::parse(&format!("http://{addr}/slow"), None).unwrap(),
                headers: Vec::new(),
                body: None,
            },
            cancel: Arc::new(AtomicBool::new(false)),
            jar: Some(Arc::clone(&jar)),
            nav: net_fetch::NavigationContext::default(),
            credentials_sent: None,
        };
        let handle = std::thread::spawn(move || net_fetch_impl(&task));
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        while !seen_req.load(Ordering::SeqCst) && std::time::Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(
            seen_req.load(Ordering::SeqCst),
            "server must see the request"
        );
        assert!(
            jar.try_lock().is_ok(),
            "jar lock must be free while the fetch is in flight"
        );
        let outcome = handle.join().expect("fetch thread");
        let resp = outcome.expect("slow fetch must succeed");
        assert_eq!(resp.body, b"hi");
        let cookies = seen_cookie.lock().expect("seen").clone();
        assert!(
            cookies.iter().any(|c| c.contains("session=abc123")),
            "snapshot must still send the seeded profile cookie; saw {cookies:?}"
        );
        assert_eq!(
            jar.lock().expect("test jar").len(),
            2,
            "seeded cookie plus the server's Set-Cookie must both be in the live jar"
        );
    }

    #[test]
    fn net_fetch_impl_redirect_hop_cookies_merge_back() {
        // w77fix: redirect-hop `Set-Cookie` headers must survive
        // the snapshot discipline — the fetch runs against a
        // private clone, so a hop cookie that only the clone saw
        // has to merge back into the live jar, not just the final
        // hop's. `/redir` sets `hop=1` and redirects to `/final`,
        // which sets `fin=1`: the live jar must hold both.
        use std::io::{Read, Write};
        use std::net::TcpListener;

        let listener = TcpListener::bind("127.0.0.1:0").expect("bind redir server");
        let addr = listener.local_addr().expect("redir server addr");
        std::thread::spawn(move || {
            for stream in listener.incoming() {
                let Ok(mut stream) = stream else { continue };
                let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
                let mut buf = Vec::new();
                let mut chunk = [0u8; 4096];
                loop {
                    match stream.read(&mut chunk) {
                        Ok(0) => break,
                        Ok(n) => {
                            buf.extend_from_slice(&chunk[..n]);
                            if buf.windows(4).any(|w| w == b"\r\n\r\n") || buf.len() > 65_536 {
                                break;
                            }
                        }
                        Err(_) => break,
                    }
                }
                let head = String::from_utf8_lossy(&buf);
                let raw_path = head
                    .lines()
                    .next()
                    .and_then(|l| l.split_whitespace().nth(1))
                    .unwrap_or("/")
                    .to_string();
                // The client sends absolute-form targets
                // (`GET http://host/redir ...`): strip the
                // scheme+authority to get the path.
                let path = if let Some(rest) = raw_path.strip_prefix("http://") {
                    match rest.find('/') {
                        Some(i) => rest[i..].to_string(),
                        None => "/".to_string(),
                    }
                } else {
                    raw_path
                };
                let response = if path == "/redir" {
                    "HTTP/1.1 302 Found\r\nLocation: /final\r\nSet-Cookie: hop=1; Path=/\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                } else {
                    "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nSet-Cookie: fin=1; Path=/\r\nConnection: close\r\n\r\nok"
                };
                let _ = stream.write_all(response.as_bytes());
            }
        });

        let jar: Arc<std::sync::Mutex<CookieJar>> =
            Arc::new(std::sync::Mutex::new(CookieJar::new()));
        let (tx, _rx) = mpsc::channel::<(u32, FetchOutcome)>();
        let task = FetchTask {
            tx,
            job: 1,
            request: net_fetch::Request {
                method: "GET".to_string(),
                url: bowser_url::parse(&format!("http://{addr}/redir"), None).unwrap(),
                headers: Vec::new(),
                body: None,
            },
            cancel: Arc::new(AtomicBool::new(false)),
            jar: Some(Arc::clone(&jar)),
            nav: net_fetch::NavigationContext::default(),
            credentials_sent: None,
        };
        let outcome = net_fetch_impl(&task);
        let resp = outcome.expect("redirect fetch must succeed");
        assert_eq!(resp.body, b"ok");
        assert_eq!(
            jar.lock().expect("test jar").len(),
            2,
            "both the redirect hop's and the final hop's cookies must merge back"
        );
    }

    #[test]
    fn fetch_pool_skips_tasks_of_dropped_contexts() {
        let runs = CANCELLED_RUNS.get_or_init(|| AtomicUsize::new(0));
        runs.store(0, Ordering::SeqCst);

        let pool = FetchPool::new(2, 8, counting_fetch);
        let (ctx_tx, ctx_rx) = mpsc::channel::<(u32, FetchOutcome)>();
        let dead = Arc::new(AtomicBool::new(true));
        let live = Arc::new(AtomicBool::new(false));
        // The cancelled task is queued first; FIFO order means the
        // worker must skip its network call — but it still delivers
        // a cancellation outcome (w77fix: dropping it silently
        // leaked the retained context's font-load maps and left its
        // promise hanging), and the live task behind it still runs.
        // Order between the two workers is not guaranteed, so both
        // completions are collected before asserting.
        pool.submit(test_fetch_task(&ctx_tx, &dead, 7)).unwrap();
        pool.submit(test_fetch_task(&ctx_tx, &live, 8)).unwrap();

        let mut got: HashMap<u32, FetchOutcome> = HashMap::new();
        for _ in 0..2 {
            let (job, outcome) = ctx_rx
                .recv_timeout(Duration::from_secs(10))
                .expect("fetch completion");
            got.insert(job, outcome);
        }
        assert!(
            matches!(got.get(&7), Some(Err(_))),
            "cancelled task must deliver a cancellation outcome, got {got:?}"
        );
        assert!(
            got.contains_key(&8),
            "live task must still deliver its completion"
        );
        assert_eq!(
            runs.load(Ordering::SeqCst),
            1,
            "fetch must run exactly once: the cancelled task is skipped"
        );
    }

    /// Test fetch impl for the cancellation test: a cancelled task
    /// must never reach the fetch implementation at all. Panicking
    /// here (rather than returning an error) keeps the test
    /// sensitive: an error outcome would drain the maps through
    /// `complete_font_load` anyway and mask a missed cancel check.
    fn cancelled_must_not_run_fetch(_task: &FetchTask) -> FetchOutcome {
        panic!("cancelled task must not run its fetch")
    }

    #[test]
    fn cancelled_font_load_drains_job_and_credentials_maps() {
        // w77fix: a cancelled font-load job leaked both its
        // `font_load_jobs` entry and its `font_load_credentials`
        // flag entry, because the worker dropped the cancelled
        // task without an outcome and nothing ever removed them
        // (and the face's promise hung). The worker now delivers
        // a cancellation outcome, so `poll_fetch_completions` +
        // the page pump run it through `complete_font_load`,
        // which removes both entries and settles the face as an
        // error. The cancel flag is set directly (what
        // `remove_context` does) while the context stays
        // registered, so the pump can still run.
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc, base, "BowserTest/1.0")
            .expect("production install");
        node_list_str(
            &mut vm,
            "globalThis.__face = new FontFace('CancelFam', 'url(http://example.com/cancel.ttf)'); \
             document.fonts.add(globalThis.__face); \
             'setup';",
        );
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        let face = {
            let g = apis.borrow();
            g.gc_roots
                .borrow()
                .font_faces
                .iter()
                .find(|(_, rec)| rec.family == "CancelFam")
                .map(|(h, _)| *h)
                .expect("CancelFam face record")
        };
        let job = 0xC0FF_EE03u32;
        let (tx, cancel) = {
            let mut g = apis.borrow_mut();
            g.font_load_jobs.insert(job, face);
            let flag = Arc::new(AtomicBool::new(false));
            g.font_load_credentials.insert(job, flag);
            (g.fetch_tx.clone(), g.fetch_cancel.clone())
        };
        assert!(
            apis.borrow().font_load_jobs.contains_key(&job)
                && apis.borrow().font_load_credentials.contains_key(&job),
            "job and credentials entries must be present before the cancel"
        );
        cancel.store(true, Ordering::SeqCst);
        let pool = FetchPool::new(2, 8, cancelled_must_not_run_fetch);
        pool.submit(FetchTask {
            tx,
            job,
            request: test_fetch_request(),
            cancel,
            jar: None,
            nav: net_fetch::NavigationContext::default(),
            credentials_sent: None,
        })
        .expect("submit cancelled font task");
        // The worker delivers the cancellation outcome promptly;
        // poll it into the outcome table (bounded: a missing
        // outcome fails instead of hanging the test).
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            poll_fetch_completions(&apis);
            if apis.borrow().font_load_outcomes.contains_key(&job) {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "cancelled font task must deliver its outcome"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        let _errors = pump_page_event_loop(&mut vm, ctx);
        assert!(
            !apis.borrow().font_load_jobs.contains_key(&job),
            "cancelled font load must remove its job entry"
        );
        assert!(
            !apis.borrow().font_load_credentials.contains_key(&job),
            "cancelled font load must remove its credentials-flag entry"
        );
        assert_eq!(
            node_list_str(&mut vm, "globalThis.__face.status;"),
            "error",
            "cancelled load must settle the face as an error, not hang"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn dropping_context_cancels_queued_fetches() {
        let fx = setup("<html><body></body></html>");
        let cancel = fx.apis.borrow().fetch_cancel.clone();
        assert!(!cancel.load(Ordering::SeqCst));
        let ctx = fx.apis.borrow().context_id();
        // Keep a clone alive: remove_context must cancel immediately,
        // not wait for the last Rc to drop.
        let retained = fx.apis.clone();
        remove_context(ctx);
        assert!(
            cancel.load(Ordering::SeqCst),
            "remove_context must set the fetch cancellation flag immediately"
        );
        drop(retained);
        drop(fx.apis);
        assert!(
            cancel.load(Ordering::SeqCst),
            "dropping the last WebApis must set the fetch cancellation flag"
        );
    }

    /// Pump pool completions into the event loop until the fetch's
    /// outcome arrives, like the embedder does around `run_until_idle`.
    /// The outcome lands in `fetch_outcomes` with a queued microtask;
    /// running the loop (`run_loop`) then settles the promise.
    fn pump_fetch(fx: &Fixture) {
        for _ in 0..10_000 {
            poll_fetch_completions(&fx.apis);
            if !fx.apis.borrow().fetch_outcomes.is_empty() {
                return;
            }
            thread::sleep(Duration::from_millis(1));
        }
        panic!("fetch outcome never arrived from the pool");
    }

    #[test]
    fn fetch_end_to_end_rejects_without_network() {
        let mut fx = setup("<html><body></body></html>");
        // Unsupported scheme fails fast in bowser_net: no network I/O,
        // so this exercises the real pool path deterministically.
        let url = str_val(&mut fx, "foo://example.com/app.js");
        let promise =
            n_fetch(&mut fx.heap, Value::Object(fx.global), &[url]).expect("fetch accepts the URL");
        let probe = probe_listener(&mut fx.heap);
        n_then(&mut fx.heap, promise, &[Value::Undefined, probe]).expect("then attaches");

        pump_fetch(&fx);
        run_loop(&mut fx);

        let inv = fx.invoker.borrow();
        let calls = inv.calls.borrow();
        assert_eq!(calls.len(), 1, "the rejection handler must fire once");
        let reason = str_contents(&fx, calls[0].arg0.expect("rejection reason"));
        assert!(
            reason.contains("unsupported URL scheme: foo"),
            "rejection reason should name the failure, got: {reason}"
        );
    }

    // -- Parse-phase `document` shim ------------------------------------

    /// The slot id the global `document` wrapper currently points at.
    fn parse_wrapper_slot(vm: &Vm) -> u64 {
        let Value::Object(doc) = vm.get_global("document").expect("shim document installed") else {
            panic!("global document is not an object");
        };
        match vm.heap().get_property(doc, Wtf8::from_str(PARSE_CTX_KEY)) {
            Some(p) => match p.value {
                Value::Float(f) => f as u64,
                other => panic!("shim slot id has wrong type: {other:?}"),
            },
            None => panic!("shim document lost its slot id"),
        }
    }

    #[test]
    fn nested_parse_shim_install_shares_one_document_wrapper() {
        // Simulate re-entrant parser-inserted scripts: the inner install
        // reuses the one `document` wrapper and points it at the inner
        // host; `uninstall` points it back at the outer host before the
        // inner slot is popped.
        let mut vm = Vm::new();
        // The host pointers are never dereferenced here — no native
        // runs — so null pointers are sound for this mechanism test.
        let guard_a = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let doc_a = vm.get_global("document").expect("shim document installed");
        assert_eq!(parse_wrapper_slot(&vm), guard_a.id);

        let guard_b = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        // One wrapper, not two: `document` keeps its identity across
        // nesting, like the one real `Document`.
        assert_eq!(vm.get_global("document"), Some(doc_a));
        assert_eq!(parse_wrapper_slot(&vm), guard_b.id);
        assert_ne!(guard_a.id, guard_b.id);

        guard_b.uninstall(&mut vm);
        // The wrapper points back at the still-live outer host.
        assert_eq!(vm.get_global("document"), Some(doc_a));
        assert_eq!(parse_wrapper_slot(&vm), guard_a.id);

        drop(guard_a);
        PARSE_HOSTS.with(|hosts| assert!(hosts.borrow().is_empty()));
    }

    #[test]
    fn sequential_parse_shim_installs_share_one_document_wrapper() {
        // The common parser shape: the outer script's shim is fully
        // uninstalled before the written `<script>` runs. The parse
        // keeps one shared `document` wrapper (like the one real
        // `Document`), so the second install repoints the same wrapper
        // at its own host instead of minting a fresh one — a wrapper
        // captured by the first script keeps resolving to the live
        // document. The wrapper must never serve the dead parent slot.
        let mut vm = Vm::new();
        let guard_a = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let doc_a = vm.get_global("document").expect("shim document installed");
        let id_a = guard_a.id;
        guard_a.uninstall(&mut vm);
        // (`guard_a` was consumed by `uninstall`; its slot is popped.)

        let guard_b = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let doc_b = vm.get_global("document").expect("shim document installed");
        assert_eq!(doc_b, doc_a, "the parse shares one document wrapper");
        assert_eq!(parse_wrapper_slot(&vm), guard_b.id);
        assert_ne!(guard_b.id, id_a);
        // The wrapper serves the new host, not the dead parent slot.
        PARSE_HOSTS.with(|hosts| {
            assert!(hosts.borrow().get(&id_a).is_none());
            assert!(hosts.borrow().contains_key(&guard_b.id));
        });
        let id_b = guard_b.id;
        guard_b.uninstall(&mut vm);
        // Back at the parent slot, whose pop fails closed.
        assert_eq!(parse_wrapper_slot(&vm), id_a);
        PARSE_HOSTS.with(|hosts| {
            assert!(hosts.borrow().is_empty());
            assert!(!hosts.borrow().contains_key(&id_b));
        });
    }

    // -- WPT Blocker C: parse-shim fixes ----------------------------------

    /// A [`bowser_html::ScriptExecutor`] that installs the parse-phase
    /// document shim around each parser-inserted script and evaluates
    /// the script's own source (like the app's executor, minus the
    /// app).
    struct ShimEval {
        vm: Vm,
    }

    impl bowser_html::ScriptExecutor for ShimEval {
        fn execute_script(
            &mut self,
            host: &mut ScriptHost<'_, '_, '_>,
            _el: ScriptElement,
            _attrs: &[(String, String)],
            script: &str,
        ) {
            // Same raw-pointer contract as the app's executor: the guard
            // lives across the eval below and the `&mut` borrow is not
            // touched again until the guard drops.
            #[allow(clippy::unnecessary_cast)]
            let host_ptr =
                host as *mut ScriptHost<'_, '_, '_> as *mut ScriptHost<'static, 'static, 'static>;
            let shim = install_parse_document_shim(&mut self.vm, host_ptr, None)
                .expect("parse shim install");
            if let Err(e) = self.vm.eval(script) {
                panic!("mid-parse script failed: {e:?}");
            }
            shim.uninstall(&mut self.vm);
        }
    }

    /// Read a parse wrapper's slot tag ([`PARSE_CTX_KEY`]).
    fn parse_el_slot(vm: &Vm, name: &str) -> u64 {
        let Value::Object(obj) = vm.get_global(name).expect("global installed") else {
            panic!("{name} is not an object");
        };
        match vm
            .heap()
            .get_property(obj, Wtf8::from_str(PARSE_CTX_KEY))
            .expect("shim wrapper tag")
            .value
        {
            Value::Float(f) => f as u64,
            v => panic!("slot tag has wrong type: {v:?}"),
        }
    }

    #[test]
    fn id_named_global_repointed_after_earlier_script() {
        // `<template id="tpl">` parsed before any script: the first
        // script's install snapshots the `tpl` id-global tagged with
        // the first script's slot, which is popped when that script
        // ends. The second script's install must repoint the wrapper
        // at its own slot; leaving the dead slot behind made every DOM
        // API on it throw `TypeError: document is not available outside
        // the parser`.
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><template id=\"tpl\"><span>hi</span></template>\
              <script>globalThis.__s1 = typeof tpl;</script>\
              <script>try { globalThis.__s2 = tpl.tagName + '/' + (tpl.content ? 'content-ok' : 'no-content'); } \
               catch (e) { globalThis.__s2 = 'THREW: ' + e; }</script>\
              </body></html>",
            true,
            &mut probe,
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__s1;"), "object");
        assert_eq!(
            node_list_str(&mut probe.vm, "globalThis.__s2;"),
            "TEMPLATE/content-ok"
        );
    }

    #[test]
    fn parse_gcs_resolves_auto_height_to_used_zero_for_abspos_table() {
        // WPT css/css-position/position-absolute-abspos-table-dynamic.html:
        // `display: table; position: absolute; height: 100px`, then the
        // script sets `height: auto`; `getComputedStyle(target).height`
        // must read the used value `"0px"`, not the computed `"auto"`.
        // The script runs mid-parse, so this exercises the parse shim's
        // used-value resolution (layout flushed after the dynamic style
        // change via `ensure_layout`).
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><head><style>#container{width:400px;height:300px;position:relative}\
              #target{display:table;position:absolute;top:0;width:50%;height:100px}</style></head>\
              <body><div id=\"container\"><div id=\"target\"></div></div>\
              <script>document.body.offsetTop;\
              var target = document.querySelector('#target');\
              target.style.height = 'auto';\
              globalThis.__h = getComputedStyle(target).height;</script>\
              </body></html>",
            true,
            &mut probe,
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__h;"), "0px");
    }

    #[test]
    fn parse_gcs_keeps_auto_height_for_display_none() {
        // No box, no used value: `display: none` keeps the computed
        // `"auto"` instead of resolving against a missing layout.
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><div id=\"d\" style=\"display:none\">x</div>\
              <script>globalThis.__h = \
              getComputedStyle(document.querySelector('#d')).height;</script>\
              </body></html>",
            true,
            &mut probe,
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__h;"), "auto");
    }

    #[test]
    fn id_named_global_keeps_live_outer_slot_when_nested() {
        // The repoint above must not fire while the installing script's
        // slot is still live: a nested install (e.g. via
        // `document.write`) leaves the outer install's wrapper alone,
        // because the outer script resumes afterwards and must keep
        // serving its slot.
        struct NestedProbe {
            vm: Vm,
        }
        impl bowser_html::ScriptExecutor for NestedProbe {
            fn execute_script(
                &mut self,
                host: &mut ScriptHost<'_, '_, '_>,
                _el: ScriptElement,
                _attrs: &[(String, String)],
                _script: &str,
            ) {
                #[allow(clippy::unnecessary_cast)]
                let host_ptr = host as *mut ScriptHost<'_, '_, '_>
                    as *mut ScriptHost<'static, 'static, 'static>;
                // Outer install: `foo` is tagged with slot A.
                let guard_a = install_parse_document_shim(&mut self.vm, host_ptr, None)
                    .expect("outer install");
                assert_eq!(parse_el_slot(&self.vm, "foo"), guard_a.id);
                // Nested install on the same host: slot A is still
                // live, so `foo` must keep pointing at it.
                let guard_b = install_parse_document_shim(&mut self.vm, host_ptr, None)
                    .expect("nested install");
                assert_eq!(parse_el_slot(&self.vm, "foo"), guard_a.id);
                assert_ne!(guard_a.id, guard_b.id);
                guard_b.uninstall(&mut self.vm);
                // The outer wrapper still serves its slot after the
                // nested install ends.
                assert_eq!(parse_el_slot(&self.vm, "foo"), guard_a.id);
                let v = self
                    .vm
                    .eval("foo.textContent")
                    .expect("outer wrapper usable after nested install");
                match v {
                    Value::Str(s) => assert_eq!(s.as_wtf8(), "x"),
                    v => panic!("unexpected textContent: {v:?}"),
                }
                guard_a.uninstall(&mut self.vm);
            }
        }
        let mut probe = NestedProbe { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><div id=\"foo\">x</div><script>1</script></body></html>",
            true,
            &mut probe,
        );
        PARSE_HOSTS.with(|hosts| assert!(hosts.borrow().is_empty()));
    }

    #[test]
    fn parse_shim_replace_child_terminates_setup_loop() {
        // The css-tables WPT setup loops `while (true)` replacing
        // `x-td[rowspan], x-td[colspan]` with `td` until none remain.
        // The old no-op `replaceChild` made that loop spin forever
        // (runner watchdog TIMEOUT); the real implementation below
        // terminates and leaves the tree correct.
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><div><x-td rowspan=\"2\">a</x-td><x-td>b</x-td></div><script>\
              var __n = 0; \
              while (true) { \
                if (++__n > 50) throw new Error('replaceChild loop did not terminate'); \
                var xtd = document.querySelector('x-td[rowspan], x-td[colspan]'); \
                if (!xtd) break; \
                var td = document.createElement('td'); \
                for (var i = xtd.attributes.length; i--;) { td.setAttribute(xtd.attributes[i].name, xtd.attributes[i].value); } \
                xtd.parentNode.replaceChild(td, xtd); \
              } \
              globalThis.__rc = document.querySelectorAll('td').length + '/' + document.querySelectorAll('x-td').length; \
              globalThis.__first = document.querySelector('div').firstChild.tagName + ':' + document.querySelector('td').getAttribute('rowspan'); \
              </script></body></html>",
            true,
            &mut probe,
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__rc;"), "1/1");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__first;"), "TD:2");
    }

    #[test]
    fn parse_shim_replace_child_semantics() {
        // Return value, in-place ordering, and the failure modes:
        // replacing with a non-child throws, and `replaceChild(x, x)`
        // is a no-op (inserting first would move it to the end).
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><div id=\"d\"><i id=\"a\">x</i><i id=\"b\">y</i></div><i id=\"z\">w</i><script>\
              var d = document.querySelector('#d'); \
              var a = document.querySelector('#a'); \
              var nb = document.createElement('b'); \
              var back = d.replaceChild(nb, a); \
              globalThis.__same = (back === a); \
              globalThis.__order = d.children[0].tagName + ',' + d.children[1].tagName; \
              globalThis.__found = !!document.querySelector('b'); \
              try { d.replaceChild(nb, document.querySelector('#z')); globalThis.__nf = 'no-throw'; } \
              catch (e) { globalThis.__nf = 'threw'; } \
              var kids = d.children; \
              d.replaceChild(kids[0], kids[0]); \
              var kids2 = d.children; \
              globalThis.__self = kids2.length + '/' + kids2[0].tagName + '/' + kids2[1].tagName; \
              </script></body></html>",
            true,
            &mut probe,
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__same;"), "true");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__order;"), "B,I");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__found;"), "true");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__nf;"), "threw");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__self;"), "2/B/I");
    }

    #[test]
    fn parse_shim_replace_child_cross_install_fragment_throws() {
        // B1: a `template.content` fragment captured by an outer install
        // and passed to `replaceChild` while that install is still live
        // (nested installs, as a `document.write` script nests inside
        // the writing script) must throw a TypeError and leave the old
        // child in place. Before the fix the foreign fragment's handle
        // resolved and the call mutated the tree across installs — with
        // a stale generation the splice even no-opped while
        // `remove_child` still deleted the old child.
        struct NestedFragProbe {
            vm: Vm,
        }
        impl bowser_html::ScriptExecutor for NestedFragProbe {
            fn execute_script(
                &mut self,
                host: &mut ScriptHost<'_, '_, '_>,
                _el: ScriptElement,
                _attrs: &[(String, String)],
                _script: &str,
            ) {
                #[allow(clippy::unnecessary_cast)]
                let host_ptr = host as *mut ScriptHost<'_, '_, '_>
                    as *mut ScriptHost<'static, 'static, 'static>;
                // Outer install: capture the fragment wrapper, tagged
                // with the outer slot.
                let guard_a = install_parse_document_shim(&mut self.vm, host_ptr, None)
                    .expect("outer install");
                self.vm
                    .eval("globalThis.__frag = tpl.content;")
                    .expect("capture fragment");
                // Nested install while the outer slot is still live.
                let guard_b = install_parse_document_shim(&mut self.vm, host_ptr, None)
                    .expect("nested install");
                assert_ne!(guard_a.id, guard_b.id);
                self.vm
                    .eval(
                        "var d2 = document.querySelector('#d'); \
                         var old2 = document.querySelector('#old'); \
                         try { \
                           d2.replaceChild(globalThis.__frag, old2); \
                           globalThis.__threw = 'no-throw'; \
                         } catch (e) { \
                           globalThis.__threw = (e instanceof TypeError) ? 'type-error' : 'other'; \
                         } \
                         globalThis.__kept = !!document.querySelector('#old');",
                    )
                    .expect("inner eval");
                guard_b.uninstall(&mut self.vm);
                guard_a.uninstall(&mut self.vm);
            }
        }
        let mut probe = NestedFragProbe { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><template id=\"tpl\"><b>k</b></template>\
              <div id=\"d\"><i id=\"old\">x</i></div><script>1</script></body></html>",
            true,
            &mut probe,
        );
        assert_eq!(
            node_list_str(&mut probe.vm, "globalThis.__threw;"),
            "type-error"
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__kept;"), "true");
        PARSE_HOSTS.with(|hosts| assert!(hosts.borrow().is_empty()));
    }

    #[test]
    fn parse_shim_replace_child_fragment_hierarchy_error_is_atomic() {
        // B2: when a fragment kid is `parent` itself (`parent` sits
        // inside the fragment), `replaceChild` must throw before
        // mutating anything. Before the fix, earlier kids were already
        // spliced in when the late `insert_before` failed, and the old
        // child was left behind with a half-moved fragment.
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><template id=\"tpl\"><b id=\"k1\">a</b></template><script>\
              var f = tpl.content; \
              var p = document.createElement('div'); \
              var old2 = document.createElement('i'); \
              p.appendChild(old2); \
              f.appendChild(p); \
              try { \
                p.replaceChild(f, old2); \
                globalThis.__threw = 'no-throw'; \
              } catch (e) { \
                globalThis.__threw = (e instanceof TypeError) ? 'type-error' : 'other'; \
              } \
              globalThis.__fkids = f.children.length; \
              globalThis.__pkids = p.children.length + '/' + p.children[0].tagName; \
              </script></body></html>",
            true,
            &mut probe,
        );
        assert_eq!(
            node_list_str(&mut probe.vm, "globalThis.__threw;"),
            "type-error"
        );
        // Nothing moved: the fragment keeps both kids, `p` keeps only
        // the old child.
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__fkids;"), "2");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__pkids;"), "1/I");
    }

    #[test]
    fn element_constructor_global_supports_feature_detection() {
        // Production: `Element` exists with the shared element
        // prototype, so WAAPI-style feature detection (`'animate' in
        // Element.prototype`) degrades to `false` instead of throwing
        // `ReferenceError`. The constructor itself throws per WebIDL.
        let mut fx = setup("<html><body><p>hi</p></body></html>");
        let el_ctor = obj_of(global_prop(&fx, "Element"));
        let proto = obj_of(prop_val(&fx, el_ctor, "prototype"));
        assert_eq!(
            proto,
            fx.apis.borrow().gc_roots.borrow().element_proto.unwrap()
        );
        assert_eq!(prop_val(&fx, proto, "constructor"), Value::Object(el_ctor));
        assert!(
            fx.heap
                .get_property(proto, Wtf8::from_str("animate"))
                .is_none()
        );
        assert!(matches!(
            n_element_ctor(&mut fx.heap, Value::Undefined, &[]),
            Err(NativeError::TypeError(_))
        ));
    }

    #[test]
    fn css_supports_value_rejects_smuggled_second_declaration() {
        // `CSS.supports('width', '10px; color: red')` is false in
        // browsers: the value must be a single declaration for the
        // named property.
        assert!(!css_supports_value("width", "10px; color: red"));
        assert!(!css_supports_value("width", "10px;color:red"));
        // Sanity: single declarations still validate, including a
        // trailing semicolon and a shorthand (expands to longhands).
        assert!(css_supports_value("width", "10px"));
        assert!(css_supports_value("width", "10px;"));
        assert!(css_supports_value("scroll-margin", "10px"));
        // A semicolon inside a string is not a declaration boundary.
        assert!(css_supports_value("content", "\";\""));
    }

    #[test]
    fn css_supports_value_var_function_gate() {
        // A whole-value `var()` reference counts as supported (CSS
        // Conditional; matches browsers).
        assert!(css_supports_value("width", "var(--x)"));
        assert!(css_supports_value("width", "VAR(--x, 10px)"));
        // Trailing garbage after the `var()` fails the grammar check.
        assert!(!css_supports_value("width", "var(--x) garbage garbage"));
        // An ident merely containing the substring is not a `var()`
        // function token.
        assert!(!css_supports_value("width", "avar(--x)"));
        // Sanity: plain values are unaffected.
        assert!(css_supports_value("width", "10px"));
        assert!(!css_supports_value("width", "banana"));
    }

    #[test]
    fn parse_shim_element_constructor_global_supports_feature_detection() {
        // Parse shim: same degradation mid-parse.
        let mut probe = ShimEval { vm: Vm::new() };
        bowser_html::parse_with_scripting_and_executor(
            b"<html><body><script>\
              globalThis.__el = typeof Element; \
              globalThis.__feat = ('animate' in Element.prototype); \
              globalThis.__ctor = (Element.prototype.constructor === Element); \
              try { new Element(); globalThis.__new = 'no-throw'; } \
              catch (e) { globalThis.__new = 'threw'; } \
              </script></body></html>",
            true,
            &mut probe,
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__el;"), "function");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__feat;"), "false");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__ctor;"), "true");
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__new;"), "threw");
    }

    #[test]
    fn parse_shim_window_event_target_registers_and_dispatches() {
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let log = vm
            .eval(
                "globalThis.log = [];\
                 function a(e) { log.push('a:' + e); }\
                 window.addEventListener('load', a);\
                 window.addEventListener('load', a);\
                 window.addEventListener('load', function(e) { log.push('b:' + e); }, { capture: true });\
                 window.dispatchEvent('load');\
                 window.removeEventListener('load', a);\
                 window.dispatchEvent('load');\
                 addEventListener('bare', function() { log.push('c'); });\
                 dispatchEvent('bare');\
                 log.join(',');",
            )
            .unwrap();
        // Duplicate registration ignored; capture listeners fire at the
        // target in registration order (no capture/bubble phases mid-parse).
        // Bare sloppy-mode calls resolve the receiver to the global object.
        let Value::Str(s) = log else {
            panic!("expected a string log, got {log:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("a:load,b:load,b:load,c"));
        guard.uninstall(&mut vm);
    }

    #[test]
    fn parse_shim_request_animation_frame_aliased_mid_parse() {
        // Harness helpers (WPT scroll_support.js's
        // `waitForCompositorCommit`) call `requestAnimationFrame` from
        // promise continuations that begin mid-parse, before the
        // production surface exists: the name must resolve to a
        // callable in the shim realm (the wave-50 snap-event failures
        // were `TypeError: callee is not a function` on exactly this),
        // and registering must hand back a timer-style handle.
        let r = shim_result(
            b"<html><body><script>\
              var id = requestAnimationFrame(function() {});\
              globalThis.__result = [typeof requestAnimationFrame, typeof cancelAnimationFrame, typeof id].join('|');\
              </script></body></html>",
        );
        assert_eq!(r, "function|function|number");
    }

    #[test]
    fn host_callback_promise_resolver_settles() {
        // A promise resolver used directly as a host callback
        // (`setTimeout(resolve)`, the shape of every
        // `waitForSnapEvent`-style helper) must settle the promise
        // when the host fires it. The resolver is a native function
        // the VM's invoke path intercepts by flag; the bindings
        // invoker used to dispatch it directly, and the fallback
        // native threw "resolve called outside executor" — the
        // rejection behind the wave-50 snap-event WPT failures.
        let mut vm = Vm::new();
        let doc = Rc::new(RefCell::new(Document::new()));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("install page web apis");
        vm.eval(
            "log = []; \
             new Promise((resolve) => { setTimeout(resolve, 0); }) \
               .then(() => { log.push('settled'); });",
        )
        .expect("register resolver as timer callback");
        let errors = pump_page_event_loop(&mut vm, ctx);
        assert!(errors.is_empty(), "{errors:?}");
        let errors = drain_page_microtasks(&mut vm, ctx);
        assert!(errors.is_empty(), "{errors:?}");
        assert!(matches!(
            vm.eval("log.join(',') === 'settled'"),
            Ok(Value::Bool(true))
        ));
        remove_context(ContextId(ctx));
    }

    #[test]
    fn scrolling_element_survives_production_install() {
        // The document wrapper is upgraded in place at production
        // install; the parse shim's `scrollingElement` accessor on it
        // must not survive — its parse context is stripped during the
        // upgrade, so a surviving accessor throws on every read
        // (WPT snap-event helpers read
        // `document.scrollingElement.scrollTo(...)`).
        let mut probe = ShimEval { vm: Vm::new() };
        let (doc, _) = Document::parse_html_with_executor(
            b"<html><head></head><body><div id=\"x\">y</div></body></html>",
            true,
            &mut probe,
        );
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = probe
            .vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        let v = probe
            .vm
            .eval("document.scrollingElement === document.documentElement;")
            .expect("scrollingElement read must not throw");
        assert_eq!(v, Value::Bool(true));
        remove_context(ContextId(ctx));
    }

    #[test]
    fn parse_shim_listeners_survive_gc_until_dispatch() {
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        vm.eval(
            "globalThis.n = 0;\
             window.addEventListener('x', function() { globalThis.n = 42; });",
        )
        .unwrap();
        // The callback is reachable only through the shim's listener
        // roots now: a collection must not free it.
        vm.heap_mut().collect();
        vm.heap_mut().collect();
        let n = vm.eval("window.dispatchEvent('x'); globalThis.n;").unwrap();
        assert_eq!(n, Value::Int(42));
        guard.uninstall(&mut vm);
    }

    #[test]
    fn parse_shim_exposes_text_encoder_decoder_mid_parse() {
        // WPT's testharness.js and the test scripts themselves run as
        // parser-inserted scripts, mid-parse — before the production web
        // API install. The encoding globals must already be visible
        // there (`encoding/api-basics` does `new TextEncoder()` at the
        // top level of a parser-inserted script).
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let v = vm
            .eval("typeof TextEncoder === 'function' && typeof TextDecoder === 'function';")
            .unwrap();
        assert_eq!(v, Value::Bool(true));
        let v = vm.eval("new TextEncoder().encoding;").unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("utf-8"));
        let v = vm.eval("new TextDecoder('utf-16le').encoding;").unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("utf-16le"));
        guard.uninstall(&mut vm);
    }

    #[test]
    fn parse_shim_encoding_install_is_idempotent_across_scripts() {
        // The shim installs once per parser-inserted script on the same
        // realm: every script must share one constructor pair (browser
        // semantics), and the later production install must keep it.
        let mut vm = Vm::new();
        let guard_a = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let te_a = vm.eval("TextEncoder;").unwrap();
        guard_a.uninstall(&mut vm);

        let guard_b = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let te_b = vm.eval("TextEncoder;").unwrap();
        assert_eq!(te_a, te_b, "one TextEncoder per realm");
        guard_b.uninstall(&mut vm);

        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        let te_c = vm.eval("TextEncoder;").unwrap();
        assert_eq!(te_a, te_c, "production install keeps the shim's pair");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn parse_shim_location_reports_seeded_document_url() {
        // WPT's `/common/subset-tests.js` reads bare `location.search`
        // from a parser-inserted script: without a mid-parse `location`
        // that is a `ReferenceError`. The shim reports the document URL
        // seeded via `set_parse_shim_document_url`.
        let mut vm = Vm::new();
        set_parse_shim_document_url(&mut vm, "https://example.com/app/page.html?foo=1&bar=2");
        let guard_a = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let loc_a = vm.get_global("location").expect("shim location installed");
        let v = vm
            .eval("typeof location === 'object' && location.href + '|' + location.search;")
            .unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(
            s.as_wtf8(),
            Wtf8::from_str("https://example.com/app/page.html?foo=1&bar=2|?foo=1&bar=2")
        );
        // One wrapper per parse: a nested parser-inserted script reuses
        // the recorded wrapper instead of minting a fresh one.
        let guard_b = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let loc_b = vm.get_global("location").expect("shim location installed");
        assert_eq!(loc_a, loc_b, "the parse shares one location wrapper");
        guard_b.uninstall(&mut vm);
        // A script that replaced `global.location` gets a fresh wrapper
        // on the next install — the recorded identity is not the
        // script's object, so it is not reused.
        vm.eval("location = { custom: 1 };").unwrap();
        let guard_c = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let loc_c = vm.get_global("location").expect("shim location installed");
        assert_ne!(loc_c, loc_b, "replaced location is not reused");
        let v = vm.eval("location.search;").unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("?foo=1&bar=2"));
        guard_c.uninstall(&mut vm);
        guard_a.uninstall(&mut vm);
    }

    #[test]
    fn parse_shim_location_defaults_to_empty_when_unseeded() {
        // No seeded URL (the embedder never called
        // `set_parse_shim_document_url`): the globals still exist so
        // mid-parse scripts never throw; an empty search makes WPT's
        // subset scripts run everything.
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let v = vm.eval("location.href + '|' + location.search;").unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("|"));
        guard.uninstall(&mut vm);
    }

    #[test]
    fn parse_shim_location_search_empty_without_query() {
        let mut vm = Vm::new();
        set_parse_shim_document_url(&mut vm, "https://example.com/app/page.html");
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let v = vm.eval("location.href + '|' + location.search;").unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(
            s.as_wtf8(),
            Wtf8::from_str("https://example.com/app/page.html|")
        );
        guard.uninstall(&mut vm);
    }

    #[test]
    fn parse_shim_location_upgraded_in_place_by_production_install() {
        // The production install (after the parse) upgrades the shim's
        // `location` wrapper in place by recorded identity — like the
        // `document` upgrade — instead of replacing it, and refreshes
        // the snapshot to the production base URL. A wrapper captured
        // mid-parse keeps resolving to the live values.
        let mut vm = Vm::new();
        set_parse_shim_document_url(&mut vm, "https://example.com/shim?a=1");
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let loc_before = vm.get_global("location").expect("shim location installed");
        vm.eval("globalThis.captured = location;").unwrap();
        guard.uninstall(&mut vm);

        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("https://example.com/prod/page?x=9", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        let loc_after = vm
            .get_global("location")
            .expect("production location installed");
        assert_eq!(
            loc_before, loc_after,
            "production install upgrades the shim wrapper in place"
        );
        let v = vm.eval("captured.href + '|' + captured.search;").unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        assert_eq!(
            s.as_wtf8(),
            Wtf8::from_str("https://example.com/prod/page?x=9|?x=9")
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn anchor_href_and_search_accessors() {
        // `HTMLAnchorElement` URL decomposition end to end:
        // `document.createElement("a")`, the `href` reflection, and the
        // `search` getter/setter (`encoding/big5-encoder.html` needs
        // `a.search` to exist and report the query).
        fn eval_str(vm: &mut Vm, expr: &str) -> String {
            let v = vm.eval(expr).unwrap();
            let Value::Str(s) = v else {
                panic!("expected a string from {expr:?}, got {v:?}");
            };
            s.as_wtf8().to_string()
        }
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        vm.eval("var a = document.createElement(\"a\");").unwrap();
        // No href yet: search is the empty string, not undefined.
        assert_eq!(eval_str(&mut vm, "typeof a.search;"), "string");
        assert_eq!(eval_str(&mut vm, "a.search;"), "");
        // The href setter reflects to the content attribute; the search
        // getter reports the query with its leading `?`.
        vm.eval("a.href = \"https://example.com/?XabX\";").unwrap();
        assert_eq!(eval_str(&mut vm, "a.search;"), "?XabX");
        assert_eq!(eval_str(&mut vm, "a.search.substr(1);"), "XabX");
        assert_eq!(
            eval_str(&mut vm, "a.getAttribute(\"href\");"),
            "https://example.com/?XabX"
        );
        // The search setter re-parses as a query and writes href back.
        vm.eval("a.search = \"y=2\";").unwrap();
        assert_eq!(eval_str(&mut vm, "a.search;"), "?y=2");
        assert_eq!(eval_str(&mut vm, "a.href;"), "https://example.com/?y=2");
        // A leading `?` on the assigned value is stripped, per `URL`.
        vm.eval("a.search = \"?z=3\";").unwrap();
        assert_eq!(eval_str(&mut vm, "a.search;"), "?z=3");
        // Relative hrefs resolve against the document base URL.
        vm.eval("a.href = \"other?p=1\";").unwrap();
        assert_eq!(eval_str(&mut vm, "a.search;"), "?p=1");
        // Non-anchor elements do not grow the accessors.
        vm.eval("var d = document.createElement(\"div\");").unwrap();
        assert_eq!(eval_str(&mut vm, "typeof d.search;"), "undefined");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn img_src_and_complete_accessors() {
        // `HTMLImageElement.src` reflects to the content attribute and
        // `complete` reads the embedder-shared completed-load set.
        fn eval_str(vm: &mut Vm, expr: &str) -> String {
            let v = vm.eval(expr).unwrap();
            let Value::Str(s) = v else {
                panic!("expected a string from {expr:?}, got {v:?}");
            };
            s.as_wtf8().to_string()
        }
        fn eval_bool(vm: &mut Vm, expr: &str) -> bool {
            let Value::Bool(b) = vm.eval(expr).unwrap() else {
                panic!("expected a bool from {expr:?}");
            };
            b
        }
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        vm.eval("var img = document.createElement(\"img\");")
            .unwrap();
        // No `src` attribute: the getter is the empty string and the
        // image is never complete (the load never started).
        assert_eq!(eval_str(&mut vm, "img.src;"), "");
        assert!(!eval_bool(&mut vm, "img.complete;"));
        // The setter reflects to the content attribute; `complete`
        // stays false until the embedder records the load.
        vm.eval("img.src = \"http://example.com/x.png\";").unwrap();
        assert_eq!(
            eval_str(&mut vm, "img.getAttribute(\"src\");"),
            "http://example.com/x.png"
        );
        assert_eq!(eval_str(&mut vm, "img.src;"), "http://example.com/x.png");
        assert!(!eval_bool(&mut vm, "img.complete;"));
        // The embedder records the completion in the shared set (what
        // `share_completed_image_loads` aliases): `complete` flips.
        // Resolve the wrapper's node handle through the vm's own heap.
        let img_val = vm.eval("img;").unwrap();
        let Value::Object(o) = img_val else {
            panic!("expected an object for img, got {img_val:?}");
        };
        let handle = match vm
            .heap_mut()
            .get_property(o, Wtf8::from_str(NODE_KEY))
            .unwrap()
            .value
        {
            Value::Int(h) => h as u32,
            v => panic!("no node handle on img wrapper: {v:?}"),
        };
        let node = web_apis(ContextId(ctx)).unwrap().borrow().node_handles[&handle];
        web_apis(ContextId(ctx))
            .unwrap()
            .borrow()
            .completed_image_loads
            .borrow_mut()
            .insert(node);
        assert!(eval_bool(&mut vm, "img.complete;"));
        // `complete` is readonly: the setter is a silent no-op.
        vm.eval("img.complete = false;").unwrap();
        assert!(eval_bool(&mut vm, "img.complete;"));
        // Non-img elements do not grow the accessors.
        vm.eval("var d = document.createElement(\"div\");").unwrap();
        assert_eq!(eval_str(&mut vm, "typeof d.src;"), "undefined");
        assert_eq!(eval_str(&mut vm, "typeof d.complete;"), "undefined");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn anchor_accessors_are_own_and_enumerable() {
        // Deliberate deviation, pinned: WebIDL exposes the
        // `HTMLHyperlinkElementUtils` attributes as *enumerable* accessors on
        // `HTMLAnchorElement.prototype`; bowser installs them as own accessors
        // instead (the `create_wrapper` accessor discipline: `sync_props`
        // never touches them, so page overrides survive re-sync), but keeps
        // them enumerable so `for`-`in`/spread/`Object.assign` observe them
        // exactly as in browsers. Non-enumerable would hide them from
        // enumeration while browsers show them.
        //
        // Own-ness is pinned via `Object.getOwnPropertyDescriptor`, not
        // `Object.hasOwn`: the engine's `hasOwn` only sees data properties
        // (a pre-existing quirk shared by every accessor, e.g. `innerHTML`),
        // while `getOwnPropertyDescriptor` and `Object.keys` observe own
        // accessors.
        fn eval_str(vm: &mut Vm, expr: &str) -> String {
            let v = vm.eval(expr).unwrap();
            let Value::Str(s) = v else {
                panic!("expected a string from {expr:?}, got {v:?}");
            };
            s.as_wtf8().to_string()
        }
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        vm.eval("var a = document.createElement(\"a\");").unwrap();
        // Own accessor properties (not inherited through the prototype)...
        for name in ["href", "search"] {
            assert_eq!(
                eval_str(
                    &mut vm,
                    &format!(
                        "String(typeof Object.getOwnPropertyDescriptor(a, \"{name}\") !== \"undefined\");"
                    )
                ),
                "true",
                "{name} must be an own property"
            );
            // ...with getter/setter pairs, enumerable like their WebIDL
            // prototype counterparts...
            assert_eq!(
                eval_str(
                    &mut vm,
                    &format!("String(Object.getOwnPropertyDescriptor(a, \"{name}\").enumerable);")
                ),
                "true",
                "{name} must stay enumerable"
            );
            assert_eq!(
                eval_str(
                    &mut vm,
                    &format!("typeof Object.getOwnPropertyDescriptor(a, \"{name}\").get;")
                ),
                "function",
                "{name} must have a getter"
            );
            assert_eq!(
                eval_str(
                    &mut vm,
                    &format!("typeof Object.getOwnPropertyDescriptor(a, \"{name}\").set;")
                ),
                "function",
                "{name} must have a setter"
            );
            // ...and visible to Object.keys, like their enumerable
            // prototype counterparts in browsers.
            assert_eq!(
                eval_str(
                    &mut vm,
                    &format!("String(Object.keys(a).includes(\"{name}\"));")
                ),
                "true",
                "{name} must be Object.keys-visible"
            );
        }
        remove_context(ContextId(ctx));
    }

    #[test]
    fn parse_shim_installs_share_one_trace_root() {
        // Gap 1 regression: the leaked `ParseShimGcRoot` is created once
        // per Vm (document load), not once per installation. The leak
        // lives in the `pending_shim_listeners.is_none()` branch of
        // `install_parse_document_shim`, so sharing the table across
        // installs is exactly sharing the one root: a page with N
        // mid-parse scripts leaves one root on the heap, not N.
        let mut vm = Vm::new();
        // The host pointers are never dereferenced here — no native
        // runs — so null pointers are sound for this mechanism test.
        assert!(vm.pending_shim_listeners.is_none());
        let guard_a = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let roots_a = vm
            .pending_shim_listeners
            .clone()
            .expect("first install creates the table");
        guard_a.uninstall(&mut vm);

        let guard_b = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let roots_b = vm
            .pending_shim_listeners
            .clone()
            .expect("table survives uninstall");
        assert!(
            Rc::ptr_eq(&roots_a, &roots_b),
            "a second install must reuse the Vm's listener table (and its one trace root), not leak another"
        );
        guard_b.uninstall(&mut vm);
        // The table — and the root's Weak target — lives until the Vm
        // drops or the production install drains it.
        assert!(vm.pending_shim_listeners.is_some());
        PARSE_HOSTS.with(|hosts| assert!(hosts.borrow().is_empty()));
    }

    #[test]
    fn parse_shim_load_listeners_survive_production_install() {
        // A mid-parse `window.addEventListener("load", cb)` must survive
        // `install_page_web_apis`: the production install drains the
        // shim's table into its own, preserving registration order and
        // the seq space, so the listener still fires on the window
        // `load` event.
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        vm.eval(
            "globalThis.log = [];\
             window.addEventListener('load', function() { log.push('first'); });",
        )
        .unwrap();
        guard.uninstall(&mut vm);
        // A second parser-inserted script registers into the same
        // shared table.
        let guard2 = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        vm.eval("window.addEventListener('load', function() { log.push('second'); });")
            .unwrap();
        guard2.uninstall(&mut vm);

        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        // The registry keeps only a `Weak`; the embedder (here, the test)
        // must retain a strong handle, as the tab does in production.
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        // The shim table was drained into the production install.
        assert!(
            vm.pending_shim_listeners.is_none(),
            "production install must take the shim listener table"
        );

        // A post-parse registration sorts after the adopted ones: the
        // shim's seq space continues the production one.
        vm.eval("window.addEventListener('load', function() { log.push('third'); });")
            .unwrap();
        let log = vm
            .eval("window.dispatchEvent({type: 'load'}); log.join(',');")
            .unwrap();
        let Value::Str(s) = log else {
            panic!("expected a string log, got {log:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("first,second,third"));
        remove_context(ContextId(ctx));
    }

    #[test]
    fn parse_shim_document_listeners_survive_production_install() {
        // A mid-parse `document.addEventListener('TestRendered', cb)`
        // must survive `install_page_web_apis` exactly like the window
        // registration: the shim document wrapper records into the same
        // listener table, and `adopt_shim_listeners` drains it into the
        // production document root — so the WPT `TestRendered`
        // handshake (css/css-overflow/scrollbar-gutter-dynamic-004.html
        // registers mid-parse and never sees the listener fire) reaches
        // the adopted listener when the production dispatch bubbles.
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        vm.eval(
            "globalThis.log = [];\
             document.addEventListener('TestRendered', function() { log.push('doc'); });\
             window.addEventListener('TestRendered', function() { log.push('win'); });",
        )
        .unwrap();
        guard.uninstall(&mut vm);

        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        // The registry keeps only a `Weak`; the embedder (here, the test)
        // must retain a strong handle, as the tab does in production.
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        // The shim table was drained into the production install.
        assert!(
            vm.pending_shim_listeners.is_none(),
            "production install must take the shim listener table"
        );

        // The adopted listeners live on the document root: dispatching
        // on the document fires both the document and the window
        // registrations, in registration order.
        let log = vm
            .eval("document.dispatchEvent({type: 'TestRendered'}); log.join(',');")
            .unwrap();
        let Value::Str(s) = log else {
            panic!("expected a string log, got {log:?}");
        };
        assert_eq!(s.as_wtf8(), Wtf8::from_str("doc,win"));
        remove_context(ContextId(ctx));
    }

    #[test]
    fn parse_shim_scroll_positions_survive_production_install() {
        // (M7) The handoff end to end: a mid-parse script scrolls
        // the window and two elements through the shim; the
        // production install on the same realm adopts the positions;
        // `share_scroll_state`/`share_element_scroll_states` seed
        // them into the production scroll states. Without the
        // mirror + adoption the positions evaporated with the last
        // script's `ParseHostEntry`.
        let mut probe = ShimEval { vm: Vm::new() };
        let (doc, _) = Document::parse_html_with_executor(
            b"<html><body>\
              <div style=\"width:2000px;height:2000px\"></div>\
              <div id=\"sc\"></div><div id=\"anon\"></div>\
              <script>\
                window.scrollTo(30, 120);\
                var sc = document.getElementById('sc');\
                sc.scrollLeft = 15; sc.scrollTop = 45;\
                var anon = document.getElementById('anon');\
                anon.scrollTop = 60;\
              </script></body></html>",
            true,
            &mut probe,
        );
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = probe
            .vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");

        // Window: the production state has its range published (as
        // after the first layout), so the shim position lands
        // immediately at share time.
        let window_state = Rc::new(ScrollState::new());
        window_state.set_max_offset((500.0, 500.0));
        share_scroll_state(ctx, window_state.clone());
        assert_eq!(
            window_state.offset(),
            (30.0, 120.0),
            "window scroll position survives the handoff"
        );

        // Elements: no production states exist at share time, so the
        // positions stay pending until each container's first
        // publish — then they land, clamped by the published range.
        // Both elements resolve by their `id` attributes here; the
        // id-less ordinal fallback is covered by
        // `adopt_shim_scroll_resolves_idless_records_by_ordinal`.
        let elements = Rc::new(ElementScrollStates::new());
        share_element_scroll_states(ctx, elements.clone());
        let sc_node = doc.borrow().get_element_by_id("sc").expect("div#sc");
        let anon_node = doc.borrow().get_element_by_id("anon").expect("div#anon");
        assert!(elements.state_for(sc_node).is_none(), "not yet published");
        elements.publish(&[(sc_node, (100.0, 100.0)), (anon_node, (100.0, 40.0))]);
        assert_eq!(
            elements.state_for(sc_node).expect("sc state").offset(),
            (15.0, 45.0),
            "element scroll position survives the handoff"
        );
        assert_eq!(
            elements.state_for(anon_node).expect("anon state").offset(),
            (0.0, 40.0),
            "the shim's 60px clamps into the published 40px maximum"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn adopt_shim_scroll_resolves_idless_records_by_ordinal() {
        // (M7) An element without an `id` is resolved by the
        // document-order ordinal the shim mirror recorded, and the
        // window position rides along verbatim.
        let mut vm = Vm::new();
        let (doc, _) =
            Document::parse_html(b"<html><body><div id=\"sc\"></div><div></div></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        let anon = doc
            .borrow()
            .get_elements_by_tag_name("div")
            .item(1)
            .expect("second div");
        let ordinal = {
            let d = doc.borrow();
            let all: Vec<NodeId> = d.get_elements_by_tag_name("*").into_iter().collect();
            all.iter().position(|&n| n == anon).expect("anon in *")
        };
        let roots = RefCell::new(ParseShimRoots {
            shim_window_scroll: Some((5.0, 6.0)),
            shim_element_scroll: vec![ParseShimElementScroll {
                arena: 0,
                id_attr: None,
                ordinal,
                offset: (7.0, 8.0),
            }],
            ..Default::default()
        });
        adopt_shim_scroll(ContextId(ctx), &roots);

        let window_state = Rc::new(ScrollState::new());
        window_state.set_max_offset((500.0, 500.0));
        share_scroll_state(ctx, window_state.clone());
        assert_eq!(window_state.offset(), (5.0, 6.0));

        let elements = Rc::new(ElementScrollStates::new());
        share_element_scroll_states(ctx, elements.clone());
        elements.publish(&[(anon, (100.0, 100.0))]);
        assert_eq!(
            elements.state_for(anon).expect("anon state").offset(),
            (7.0, 8.0),
            "id-less record resolved by ordinal"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn scroll_state_adopt_shim_offset_precedence_clamp_and_defer() {
        // (M7) Precedence: a production offset already set by real
        // scrolling wins over the shim value.
        let s = ScrollState::new();
        s.set_max_offset((500.0, 500.0));
        s.set_offset(10.0, 10.0);
        s.adopt_shim_offset(Some((30.0, 120.0)));
        assert_eq!(s.offset(), (10.0, 10.0), "production wins");

        // Clamp: with a range published, the shim value lands
        // clamped into it.
        let s = ScrollState::new();
        s.set_max_offset((100.0, 100.0));
        s.adopt_shim_offset(Some((30.0, 120.0)));
        assert_eq!(s.offset(), (30.0, 100.0), "clamped to the production max");

        // Defer: before any range publish the value must NOT clamp
        // against the empty (0, 0) range — it stays pending and the
        // first publish resolves it.
        let s = ScrollState::new();
        s.adopt_shim_offset(Some((30.0, 120.0)));
        assert_eq!(s.offset(), (0.0, 0.0), "pending, not clamped to zero");
        s.set_max_offset((500.0, 500.0));
        assert_eq!(s.offset(), (30.0, 120.0), "resolved at first publish");

        // A later document whose parse never scrolled clears the
        // pending value instead of inheriting it.
        let s = ScrollState::new();
        s.adopt_shim_offset(Some((30.0, 120.0)));
        s.adopt_shim_offset(None);
        s.set_max_offset((500.0, 500.0));
        assert_eq!(s.offset(), (0.0, 0.0), "cleared adoption stays cleared");
    }

    #[test]
    fn forged_parse_tag_cannot_divert_upgrade() {
        // A mid-parse script forges the `PARSE_CTX_KEY` float tag onto a
        // decoy object (plain assignment forges it just as well as
        // `Object.defineProperty` — the tag property is writable) and
        // repoints the writable `global.document` at the decoy. The
        // production install must authenticate the upgrade target by
        // object identity, not by the tag: the genuine wrapper is
        // upgraded in place, the decoy is left untouched, and
        // `global.document` points at the genuine wrapper again.
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        vm.eval(
            "var __genuine = document;\
             var __tagKey = '\\u0000bowser:parse-ctx';\
             var __forged = __genuine[__tagKey];\
             var __decoy = {};\
             __decoy[__tagKey] = __forged;\
             __decoy.planted = 'decoy';\
             document = __decoy;",
        )
        .unwrap();
        // The repoint actually happened: the global no longer holds the
        // genuine wrapper.
        let repointed = vm.eval("document === __decoy;").unwrap();
        assert_eq!(repointed, Value::Bool(true));
        guard.uninstall(&mut vm);

        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        // The registry keeps only a `Weak`; the embedder (here, the test)
        // must retain a strong handle, as the tab does in production.
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");

        fn eval_str(vm: &mut Vm, expr: &str) -> String {
            let v = vm.eval(expr).unwrap();
            let Value::Str(s) = v else {
                panic!("expected a string from {expr:?}, got {v:?}");
            };
            s.as_wtf8().to_string()
        }
        // The genuine wrapper was upgraded in place: full production
        // surface, shim state stripped.
        assert_eq!(
            eval_str(&mut vm, "typeof __genuine.createElement;"),
            "function"
        );
        assert_eq!(
            eval_str(&mut vm, "typeof __genuine.querySelector;"),
            "function"
        );
        assert_eq!(eval_str(&mut vm, "typeof __genuine.write;"), "undefined");
        // The shim's `"loading"` data prop was stripped and replaced by
        // the production accessor: the upgraded wrapper reports the
        // `"interactive"` lifecycle state through the captured reference.
        assert_eq!(eval_str(&mut vm, "typeof __genuine.readyState;"), "string");
        assert_eq!(eval_str(&mut vm, "__genuine.readyState;"), "interactive");
        assert_eq!(
            eval_str(&mut vm, "typeof __genuine[__tagKey];"),
            "undefined",
            "the slot tag must be stripped from the upgraded wrapper"
        );
        // `global.document` points at the genuine wrapper again.
        let restored = vm.eval("document === __genuine;").unwrap();
        assert_eq!(restored, Value::Bool(true));
        // The decoy was not upgraded: no production surface, forged tag
        // and planted marker intact.
        assert_eq!(
            eval_str(&mut vm, "typeof __decoy.createElement;"),
            "undefined"
        );
        assert_eq!(
            eval_str(&mut vm, "typeof __decoy.querySelectorAll;"),
            "undefined"
        );
        let tag_kept = vm.eval("__decoy[__tagKey] === __forged;").unwrap();
        assert_eq!(tag_kept, Value::Bool(true));
        assert_eq!(eval_str(&mut vm, "__decoy.planted;"), "decoy");
        remove_context(ContextId(ctx));
    }

    /// A `Vm` with the production web APIs installed on a document with an
    /// `#outer > #inner` fixture. Returns the document's strong handle too:
    /// the registry keeps only a `Weak`, so the caller must hold it for
    /// the test's duration (as the tab does in production). The caller
    /// must `remove_context` the returned id when done.
    fn production_vm() -> (Vm, Rc<RefCell<Document>>, ContextId) {
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(
            b"<html><head></head><body><div id=\"outer\"><div id=\"inner\"></div></div></body></html>",
        );
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = ContextId(
            vm.install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
                .expect("production install"),
        );
        (vm, doc, ctx)
    }

    fn eval_log(vm: &mut Vm, expr: &str) -> String {
        let v = vm.eval(expr).unwrap();
        let Value::Str(s) = v else {
            panic!("expected a string, got {v:?}");
        };
        s.as_wtf8().to_string()
    }

    #[test]
    fn window_load_survives_page_dispatch_event_override() {
        // `window.dispatchEvent` is writable: a page override must not
        // swallow the engine's `load` dispatch, which goes through the
        // stashed trusted native — and the load event is trusted.
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.log = []; \
             window.addEventListener('load', function(e) { log.push(e.isTrusted); log.push(e.type); }); \
             window.dispatchEvent = function() { log.push('override'); };",
        )
        .unwrap();
        vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut vm, "log.join(',');"), "true,load");
        // The public property is still the page's override for script use.
        vm.eval("window.dispatchEvent({type: 'load'});").unwrap();
        assert_eq!(eval_log(&mut vm, "log.join(',');"), "true,load,override");
        remove_context(ctx);
    }

    #[test]
    fn once_listener_removed_before_first_invoke() {
        // A `once` listener is removed before it runs: a synchronous
        // re-dispatch from inside the listener cannot re-enter it.
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.n = 0; \
             window.addEventListener('x', function() { n++; window.dispatchEvent({type: 'x'}); }, {once: true});",
        )
        .unwrap();
        vm.eval("window.dispatchEvent({type: 'x'});").unwrap();
        let n = vm.eval("n;").unwrap();
        assert_eq!(n, Value::Int(1));
        remove_context(ctx);
    }

    #[test]
    fn passive_listener_prevent_default_noops() {
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.r = []; \
             window.addEventListener('x', function(e) { e.preventDefault(); r.push(e.defaultPrevented); }, {passive: true}); \
             window.addEventListener('y', function(e) { e.preventDefault(); r.push(e.defaultPrevented); });",
        )
        .unwrap();
        let rx = vm
            .eval("window.dispatchEvent({type: 'x', cancelable: true});")
            .unwrap();
        let ry = vm
            .eval("window.dispatchEvent({type: 'y', cancelable: true});")
            .unwrap();
        assert_eq!(
            rx,
            Value::Bool(true),
            "preventDefault in a passive listener is ignored"
        );
        assert_eq!(
            ry,
            Value::Bool(false),
            "preventDefault in a normal listener sticks"
        );
        assert_eq!(eval_log(&mut vm, "r.join(',');"), "false,true");
        remove_context(ctx);
    }

    #[test]
    fn prevent_default_on_non_cancelable_event_noops() {
        // DOM Standard: `preventDefault()` sets the canceled flag only
        // when the event's `cancelable` is true; on a non-cancelable
        // event it is a no-op (`defaultPrevented` stays false and
        // `dispatchEvent` returns true).
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.r = []; \
             window.addEventListener('x', function(e) { e.preventDefault(); r.push(e.defaultPrevented); }); \
             window.addEventListener('y', function(e) { e.preventDefault(); r.push(e.defaultPrevented); });",
        )
        .unwrap();
        let rx = vm
            .eval("window.dispatchEvent({type: 'x', cancelable: false});")
            .unwrap();
        let ry = vm
            .eval("window.dispatchEvent({type: 'y', cancelable: true});")
            .unwrap();
        assert_eq!(rx, Value::Bool(true), "non-cancelable event not prevented");
        assert_eq!(ry, Value::Bool(false), "cancelable event still prevents");
        assert_eq!(eval_log(&mut vm, "r.join(',');"), "false,true");
        remove_context(ctx);
    }

    #[test]
    fn snap_event_constructor_and_prototype() {
        let (mut vm, _doc, ctx) = production_vm();
        // The type argument is required.
        assert!(vm.eval("new SnapEvent();").is_err());
        // A non-node snap target member is a WebIDL `Node?` TypeError.
        assert!(
            vm.eval("new SnapEvent('x', {snapTargetBlock: 42});")
                .is_err()
        );
        let ok = vm
            .eval(
                "var outer = document.getElementById('outer'); \
                 var ev = new SnapEvent('scrollsnapchange'); \
                 var ev2 = new SnapEvent('scrollsnapchanging', \
                     {snapTargetBlock: outer, snapTargetInline: document, bubbles: true}); \
                 ev.snapTargetBlock === null && ev.snapTargetInline === null \
                 && ev.bubbles === false && ev.cancelable === false \
                 && ev2.snapTargetBlock === outer && ev2.snapTargetInline === document \
                 && ev2.bubbles === true \
                 && (ev instanceof SnapEvent) && (ev instanceof Event) \
                 && Object.getPrototypeOf(SnapEvent.prototype) === Event.prototype;",
            )
            .unwrap();
        assert_eq!(ok, Value::Bool(true));
        remove_context(ctx);
    }

    #[test]
    fn dispatch_snap_event_element_and_document() {
        let (mut vm, doc, ctx) = production_vm();
        let inner = doc.borrow().get_element_by_id("inner").unwrap();
        let outer = doc.borrow().get_element_by_id("outer").unwrap();
        let root = doc.borrow().root();
        vm.eval(
            "globalThis.seen = []; \
             var innerEl = document.getElementById('inner'); \
             var outerEl = document.getElementById('outer'); \
             innerEl.addEventListener('scrollsnapchange', function(e) { \
                 seen.push('el:' + (e.target === innerEl) + ',' + e.bubbles + ',' \
                     + e.cancelable + ',' + e.isTrusted + ',' \
                     + (e.snapTargetBlock === outerEl) + ',' + (e.snapTargetInline === innerEl) \
                     + ',' + (e instanceof SnapEvent)); \
             }); \
             document.documentElement.addEventListener('scrollsnapchange', function(e) { \
                 seen.push('html'); \
             }); \
             window.addEventListener('scrollsnapchange', function(e) { \
                 seen.push('win:' + (e.target === document) + ',' + e.bubbles + ',' \
                     + (e.snapTargetBlock === outerEl) + ',' + (e.snapTargetInline === null)); \
             });",
        )
        .unwrap();
        // Element target: no bubbling, targets resolve to the
        // canonical wrappers.
        vm.dispatch_snap_event(inner, "scrollsnapchange", Some(outer), Some(inner), false);
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "el:true,false,false,true,true,true,true"
        );
        // Document target (viewport scroller): bubbles, so the window
        // listener receives it with `target === document`; the
        // documentElement listener is a different bucket and does not
        // fire.
        vm.eval("globalThis.seen = [];").unwrap();
        vm.dispatch_snap_event(root, "scrollsnapchange", Some(outer), None, true);
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "win:true,true,true,true"
        );
        remove_context(ctx);
    }

    #[test]
    fn snap_event_redispatch_preserves_targets() {
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.seen = []; \
             var innerEl = document.getElementById('inner'); \
             var outerEl = document.getElementById('outer'); \
             innerEl.addEventListener('scrollsnapchange', function(e) { \
                 seen.push('ctor:' + (e.snapTargetBlock === outerEl) + ',' \
                     + (e.snapTargetInline === document) + ',' + (e instanceof SnapEvent)); \
             }); \
             innerEl.addEventListener('scrollsnapchanging', function(e) { \
                 seen.push('plain:' + (e.snapTargetBlock === outerEl) + ',' \
                     + (e.snapTargetInline === null)); \
             }); \
             var ev = new SnapEvent('scrollsnapchange', \
                 {snapTargetBlock: outerEl, snapTargetInline: document}); \
             innerEl.dispatchEvent(ev); \
             innerEl.dispatchEvent({type: 'scrollsnapchanging', \
                 snapTargetBlock: outerEl, snapTargetInline: null});",
        )
        .unwrap();
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "ctor:true,true,true;plain:true,true"
        );
        remove_context(ctx);
    }

    #[test]
    fn onload_handler_attribute() {
        let (mut vm, _doc, ctx) = production_vm();
        // Support check shape: `null`, never `undefined`, on window,
        // document, and elements.
        let ok = vm
            .eval(
                "window.onload === null && document.onload === null \
                 && document.documentElement.onload === null;",
            )
            .unwrap();
        assert_eq!(ok, Value::Bool(true));
        // `window.onload = f` fires exactly once on the load dispatch,
        // and the getter returns the installed function.
        vm.eval(
            "globalThis.calls = []; \
             globalThis.f = function(e) { calls.push(e.type + ':' + e.isTrusted); }; \
             window.onload = f; \
             if (window.onload !== f) throw new Error('getter must return the handler');",
        )
        .unwrap();
        vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut vm, "calls.join(',');"), "load:true");
        // Reassignment replaces: the old callback no longer runs.
        vm.eval("window.onload = function() { calls.push('two'); };")
            .unwrap();
        vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut vm, "calls.join(',');"), "load:true,two");
        // Setting `null` unregisters.
        vm.eval("window.onload = null;").unwrap();
        vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut vm, "calls.join(',');"), "load:true,two");
        remove_context(ctx);
    }

    #[test]
    fn body_onload_content_attribute() {
        // `<body onload="...">` installs the Window `load` handler at
        // install time, visible through the `window.onload` getter and
        // invoked by the load dispatch.
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(
            b"<html><head></head><body onload=\"globalThis.fired = (globalThis.fired || 0) + 1;\"></body></html>",
        );
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = ContextId(
            vm.install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
                .expect("production install"),
        );
        let ok = vm.eval("window.onload !== null;").unwrap();
        assert_eq!(ok, Value::Bool(true));
        vm.dispatch_window_load().expect("load dispatch");
        let fired = vm.eval("globalThis.fired || 0;").unwrap();
        assert_eq!(fired, Value::Int(1));
        remove_context(ctx);
    }

    #[test]
    fn prod_class_list_class_name_roundtrip() {
        let (mut vm, doc, ctx) = production_vm();
        // The reftest-wait.js shape: removing a class from
        // `document.documentElement` must not throw.
        vm.eval(
            "var de = document.documentElement; \
             de.className = 'reftest-wait foo'; \
             if (de.className !== 'reftest-wait foo') throw new Error('className get/set'); \
             de.classList.add('bar'); \
             if (!de.classList.contains('bar')) throw new Error('classList.add'); \
             if (de.classList.toggle('bar') !== false) throw new Error('classList.toggle off'); \
             if (de.classList.toggle('baz') !== true) throw new Error('classList.toggle on'); \
             de.classList.remove('reftest-wait', 'baz'); \
             if (de.classList.contains('reftest-wait')) throw new Error('classList.remove'); \
             if (de.className !== 'foo') throw new Error('class attr now: ' + de.className);",
        )
        .unwrap();
        // Backed by the live `class` attribute.
        let de = {
            let d = doc.borrow();
            d.descendants(d.root())
                .into_iter()
                .find(
                    |&n| matches!(d.kind(n), NodeKind::Element(e) if e.tag_name.as_str() == "html"),
                )
                .unwrap()
        };
        assert_eq!(
            doc.borrow().get_attribute(de, "class"),
            Some("foo"),
            "class attribute holds the tokens"
        );
        remove_context(ctx);
    }

    #[test]
    fn prod_class_list_same_object() {
        let (mut vm, _doc, ctx) = production_vm();
        // WebIDL `[SameObject]`: repeated reads return the same view,
        // and mutations through one reference are visible through
        // another (the view reads the live `class` attribute per call).
        vm.eval(
            "var de = document.documentElement; \
             var a = de.classList; \
             if (a !== de.classList) throw new Error('classList not [SameObject]'); \
             de.classList.add('x'); \
             if (!a.contains('x')) throw new Error('add through one view'); \
             de.className = 'y'; \
             if (a.contains('x')) throw new Error('stale contains after className set'); \
             if (!a.contains('y')) throw new Error('attr change visible in view'); \
             if (a.toggle('z') !== true) throw new Error('toggle on'); \
             if (!de.classList.contains('z')) throw new Error('toggle visible in other view'); \
             a.remove('y', 'z'); \
             if (de.className !== '') throw new Error('remove: ' + de.className);",
        )
        .unwrap();
        remove_context(ctx);
    }

    #[test]
    fn prod_style_property_set_reflected() {
        let (mut vm, doc, ctx) = production_vm();
        // The scrollbar-gutter-dynamic-004 handshake shape: assigning an
        // unknown-to-JS property through the curated accessor writes
        // the `style` attribute and reads back. (The `color` read
        // below expects the keyword: colors-007 Family B fixed
        // specified style to keep named colors instead of folding
        // them to rgb(); hex authorship still reads back rgb().)
        vm.eval(
            "var de = document.documentElement; \
             de.style.scrollbarGutter = 'initial'; \
             if (de.style.scrollbarGutter !== 'initial') throw new Error('style get'); \
             if (de.style.getPropertyValue('scrollbar-gutter') !== 'initial') \
                 throw new Error('getPropertyValue'); \
             de.style.setProperty('color', 'red'); \
             if (de.style.color !== 'red') throw new Error('setProperty'); \
             if (de.style.length !== 2) throw new Error('length: ' + de.style.length); \
             de.style.removeProperty('color'); \
             if (de.style.length !== 1) throw new Error('removeProperty'); \
             de.style.cssText = 'margin-top: 5px; color: notacolor'; \
             if (de.style.marginTop !== '5px') throw new Error('cssText set');",
        )
        .unwrap();
        let de = {
            let d = doc.borrow();
            d.descendants(d.root())
                .into_iter()
                .find(
                    |&n| matches!(d.kind(n), NodeKind::Element(e) if e.tag_name.as_str() == "html"),
                )
                .unwrap()
        };
        let style = doc
            .borrow()
            .get_attribute(de, "style")
            .map(str::to_owned)
            .unwrap_or_default();
        assert!(
            style.contains("margin-top: 5px") && !style.contains("notacolor"),
            "style attribute round-trips valid decls only, got: {style}"
        );
        remove_context(ctx);
    }

    #[test]
    fn prod_style_remove_property_clears_shorthand_longhands() {
        // W9: removing a shorthand must also clear the longhands it
        // expanded into at parse time, mirroring the set path's
        // shorthand→longhand expansion.
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "var de = document.documentElement; \
             de.style.setProperty('scroll-margin', '1px 2px 3px 4px'); \
             if (de.style.length !== 4) throw new Error('expanded length: ' + de.style.length); \
             if (de.style.getPropertyValue('scroll-margin-top') !== '1px') \
                 throw new Error('longhand read'); \
             de.style.removeProperty('scroll-margin'); \
             if (de.style.length !== 0) throw new Error('shorthand remove length: ' + de.style.length); \
             if (de.style.getPropertyValue('scroll-margin-top') !== '') \
                 throw new Error('longhand survived'); \
             if (de.style.cssText !== '') throw new Error('cssText survived: ' + de.style.cssText); \
             de.style.setProperty('scroll-padding', '5px 6px'); \
             if (de.style.length !== 4) throw new Error('padding expanded length: ' + de.style.length); \
             de.style.removeProperty('scroll-padding-top'); \
             if (de.style.length !== 3) throw new Error('longhand remove length: ' + de.style.length); \
             if (de.style.getPropertyValue('scroll-padding-right') !== '6px') \
                 throw new Error('sibling longhand dropped');",
        )
        .unwrap();
        remove_context(ctx);
    }

    #[test]
    fn prod_el_style_cache_key_not_enumerable() {
        // W11: the `"\0bowser:el-style"` cache key must not leak into
        // `Object.keys(el)` (non-enumerable, like [`NODE_LIST_KEY`]).
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "var de = document.documentElement; \
             void de.style; \
             var keys = Object.keys(de); \
             for (var i = 0; i < keys.length; i++) { \
                 if (keys[i].indexOf('bowser:el-style') !== -1) \
                     throw new Error('style cache key leaked into Object.keys'); \
             }",
        )
        .unwrap();
        remove_context(ctx);
    }

    #[test]
    fn body_onload_yields_to_script_assignment() {
        // A script assignment after the install replaces the content
        // attribute handler (document order: the attribute was set
        // during the parse, the script runs later).
        let mut vm = Vm::new();
        let (doc, _) = Document::parse_html(
            b"<html><head></head><body onload=\"globalThis.fired = 'attr';\"></body></html>",
        );
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = ContextId(
            vm.install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
                .expect("production install"),
        );
        vm.eval("window.onload = function() { globalThis.fired = 'script'; };")
            .unwrap();
        vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut vm, "globalThis.fired;"), "script");
        remove_context(ctx);
    }

    /// Run `html` through the scripting parse with [`ShimEval`] (each
    /// parser-inserted script runs under the parse shim on the probe's
    /// `Vm`), then install the production web APIs on that same `Vm`
    /// with the parsed document — the app's parse-then-install flow in
    /// miniature. Returns the probe, the document (the registry keeps
    /// only a `Weak`, so the caller must hold the strong `Rc`), and the
    /// context id (the caller must [`remove_context`] it).
    fn mid_parse_vm(html: &[u8]) -> (ShimEval, Rc<RefCell<Document>>, ContextId) {
        let mut probe = ShimEval { vm: Vm::new() };
        let (doc, _) = Document::parse_html_with_executor(html, true, &mut probe);
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = ContextId(
            probe
                .vm
                .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
                .expect("production install"),
        );
        (probe, doc, ctx)
    }

    #[test]
    fn mid_parse_window_onload_survives_upgrade() {
        // A mid-parse `window.onload = f` must survive the production
        // install — which replaces the shim's `onload` with the
        // production accessor — and fire on the load dispatch.
        let (mut probe, _doc, ctx) = mid_parse_vm(
            b"<html><head><script>\
              globalThis.fired = 0; \
              window.onload = function() { globalThis.fired = 42; }; \
              </script></head><body></body></html>",
        );
        // Visible through the production getter, not dropped.
        let ok = probe
            .vm
            .eval("typeof window.onload === 'function';")
            .unwrap();
        assert_eq!(ok, Value::Bool(true));
        probe.vm.dispatch_window_load().expect("load dispatch");
        let fired = probe.vm.eval("globalThis.fired;").unwrap();
        assert_eq!(fired, Value::Int(42));
        remove_context(ctx);
    }

    #[test]
    fn body_onload_attribute_yields_to_later_mid_parse_assignment() {
        // Document order: the `<script>` runs after the `<body>` start
        // tag, so its `window.onload` assignment is later in document
        // order than the `<body onload>` attribute and wins.
        let (mut probe, _doc, ctx) = mid_parse_vm(
            b"<html><head></head><body onload=\"globalThis.fired = 'attr';\">\
              <script>window.onload = function() { globalThis.fired = 'script'; };</script>\
              </body></html>",
        );
        probe.vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut probe.vm, "globalThis.fired;"), "script");
        remove_context(ctx);
    }

    #[test]
    fn body_onload_attribute_beats_earlier_mid_parse_assignment() {
        // Document order: the `<script>` in `<head>` runs before the
        // `<body>` start tag is parsed, so the `<body onload>`
        // attribute is the later assignment and wins.
        let (mut probe, _doc, ctx) = mid_parse_vm(
            b"<html><head><script>\
              window.onload = function() { globalThis.fired = 'script'; }; \
              </script></head><body onload=\"globalThis.fired = 'attr';\"></body></html>",
        );
        probe.vm.dispatch_window_load().expect("load dispatch");
        assert_eq!(eval_log(&mut probe.vm, "globalThis.fired;"), "attr");
        remove_context(ctx);
    }

    #[test]
    fn document_body_onload_idl_forwards_to_window() {
        // Per HTML, `body`/`frameset` `onload` IDL forwards to the
        // Window event handler: `document.body.onload = f` must land in
        // the window bucket, be visible through both getters, and fire
        // on the window `load` dispatch.
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.fired = 0; \
             document.body.onload = function() { globalThis.fired = 7; }; \
             if (document.body.onload === null) throw new Error('body getter must reflect the handler'); \
             if (window.onload === null) throw new Error('must land in the window bucket');",
        )
        .unwrap();
        vm.dispatch_window_load().expect("load dispatch");
        let fired = vm.eval("globalThis.fired;").unwrap();
        assert_eq!(fired, Value::Int(7));
        remove_context(ctx);
    }

    #[test]
    fn onscrollsnap_handler_attributes() {
        let (mut vm, doc, ctx) = production_vm();
        let inner = doc.borrow().get_element_by_id("inner").unwrap();
        let root = doc.borrow().root();
        // Support check shape: the attributes exist and start `null`
        // on elements, document, and window.
        let ok = vm
            .eval(
                "window.onscrollsnapchange === null && window.onscrollsnapchanging === null \
                 && document.onscrollsnapchange === null \
                 && document.getElementById('inner').onscrollsnapchange === null;",
            )
            .unwrap();
        assert_eq!(ok, Value::Bool(true));
        vm.eval(
            "globalThis.calls = []; \
             var el = document.getElementById('inner'); \
             globalThis.f1 = function(e) { calls.push('one'); }; \
             el.onscrollsnapchange = f1; \
             if (el.onscrollsnapchange !== f1) throw new Error('getter must return the handler');",
        )
        .unwrap();
        vm.dispatch_snap_event(inner, "scrollsnapchange", None, None, false);
        assert_eq!(eval_log(&mut vm, "calls.join(',');"), "one");
        // Reassignment replaces: the old callback no longer runs.
        vm.eval("el.onscrollsnapchange = function(e) { calls.push('two'); };")
            .unwrap();
        vm.dispatch_snap_event(inner, "scrollsnapchange", None, None, false);
        assert_eq!(eval_log(&mut vm, "calls.join(',');"), "one,two");
        // Setting `null` unregisters.
        vm.eval("el.onscrollsnapchange = null;").unwrap();
        vm.dispatch_snap_event(inner, "scrollsnapchange", None, None, false);
        assert_eq!(eval_log(&mut vm, "calls.join(',');"), "one,two");
        // Document and window handlers receive document dispatches.
        vm.eval(
            "document.onscrollsnapchange = function(e) { calls.push('doc:' + (e.target === document)); }; \
             window.onscrollsnapchanging = function(e) { calls.push('win'); };",
        )
        .unwrap();
        vm.dispatch_snap_event(root, "scrollsnapchange", None, None, true);
        vm.dispatch_snap_event(root, "scrollsnapchanging", None, None, true);
        assert_eq!(
            eval_log(&mut vm, "calls.join(',');"),
            "one,two,doc:true,win"
        );
        remove_context(ctx);
    }

    #[test]
    fn parse_shim_snap_event_mirror() {
        // Mid-parse, `new SnapEvent(...)` works through the shim
        // mirror: init values are stored verbatim (identity holds),
        // and the `on*` support props read `null`.
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        assert!(vm.eval("new SnapEvent();").is_err());
        let ok = vm
            .eval(
                "var ev = new SnapEvent('scrollsnapchange', \
                     {snapTargetBlock: document, snapTargetInline: document}); \
                 ev.snapTargetBlock === document && ev.snapTargetInline === document \
                 && ev.type === 'scrollsnapchange' && ev.bubbles === false \
                 && (ev instanceof SnapEvent) \
                 && window.onscrollsnapchange === null \
                 && window.onscrollsnapchanging === null;",
            )
            .unwrap();
        assert_eq!(ok, Value::Bool(true));
        drop(guard);
    }

