    #[test]
    fn wheel_event_delta_mode_u32_round_trip() {
        let (mut vm, _doc, ctx) = production_vm();
        // WebIDL unsigned long: ToUint32(-1) is 4294967295, which must
        // survive the trip out as an exactly-representable float, not a
        // wrapped i32.
        let m = eval_log(
            &mut vm,
            "var w = new WheelEvent('wheel', {deltaMode: -1}); [w.deltaMode].join(',');",
        );
        assert_eq!(m, "4294967295");
        let v = vm
            .eval("new WheelEvent('wheel', {deltaMode: -1}).deltaMode")
            .unwrap();
        assert!(matches!(v, Value::Float(f) if f == 4294967295.0));
        // Small modes are unaffected.
        let z = eval_log(
            &mut vm,
            "[new WheelEvent('wheel', {deltaMode: 2}).deltaMode].join(',');",
        );
        assert_eq!(z, "2");
        remove_context(ctx);
    }

    #[test]
    fn event_init_non_object_throws_type_error() {
        let (mut vm, _doc, ctx) = production_vm();
        // WebIDL dictionary: only undefined/null (or an absent argument)
        // mean "empty dictionary"; any other non-object throws TypeError.
        for src in [
            "new Event('x', 42)",
            "new Event('x', 'bubbles')",
            "new Event('x', true)",
            "new WheelEvent('x', 42)",
            "new WheelEvent('x', 'mode')",
        ] {
            let err = vm.eval(src).unwrap_err().to_string();
            assert!(
                err.contains("TypeError"),
                "{src} threw {err}, want TypeError"
            );
        }
        // undefined/null/absent still mean defaults.
        vm.eval(
            "new Event('x', undefined); new Event('x', null); new Event('x'); \
             new WheelEvent('x', undefined); new WheelEvent('x', null); new WheelEvent('x');",
        )
        .unwrap();
        remove_context(ctx);
    }

