    #[test]
    fn dispatch_pointer_mouse_delivers_fields_bubbles_and_prevented() {
        let (mut vm, doc, ctx) = production_vm();
        vm.eval(
            "globalThis.seen = []; \
             function fmt(tag) { \
                 return function(e) { \
                     seen.push(tag + ':' + e.type \
                         + ',' + e.clientX + ',' + e.clientY \
                         + ',' + e.button + ',' + e.buttons \
                         + ',' + e.pointerId + ',' + e.pointerType + ',' + e.isPrimary \
                         + ',' + e.pressure + ',' + (e instanceof PointerEvent) \
                         + ',' + (e instanceof MouseEvent) + ',' + (e instanceof Event) \
                         + ',' + e.bubbles + ',' + e.cancelable + ',' + e.isTrusted); \
                     if (e.type === 'pointerdown') e.preventDefault(); \
                 }; \
             } \
             var innerEl = document.getElementById('inner'); \
             var outerEl = document.getElementById('outer'); \
             innerEl.addEventListener('pointerdown', fmt('inner')); \
             outerEl.addEventListener('pointerdown', fmt('outer')); \
             innerEl.addEventListener('mousedown', fmt('inner')); \
             outerEl.addEventListener('mousedown', fmt('outer')); \
             innerEl.addEventListener('pointerenter', fmt('inner')); \
             outerEl.addEventListener('pointerenter', fmt('outer'));",
        )
        .unwrap();
        let inner = doc.borrow().get_element_by_id("inner").unwrap();
        let mut data = dom::PointerData::mouse_at(30.0, 40.0);
        data.button = 0;
        data.buttons = 1;
        data.pointer_id = 5;
        data.pointer_type = dom::PointerType::Pen;
        data.pressure = 0.5;
        // A prevented pointerdown reports true.
        assert!(vm.dispatch_pointer_mouse(inner, "pointerdown", PointerMouseKind::Pointer, data));
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "inner:pointerdown,30,40,0,1,5,pen,true,0.5,true,true,true,true,true,true;\
             outer:pointerdown,30,40,0,1,5,pen,true,0.5,true,true,true,true,true,true"
        );
        // The paired legacy mousedown: a MouseEvent wrapper this time
        // (pointer accessors stay off its prototype chain), unprevented.
        vm.eval("globalThis.seen = [];").unwrap();
        assert!(!vm.dispatch_pointer_mouse(inner, "mousedown", PointerMouseKind::Mouse, data));
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "inner:mousedown,30,40,0,1,undefined,undefined,undefined,undefined,false,true,true,true,true,true;\
             outer:mousedown,30,40,0,1,undefined,undefined,undefined,undefined,false,true,true,true,true,true"
        );
        // pointerenter does not bubble: only the target's listener runs.
        vm.eval("globalThis.seen = [];").unwrap();
        assert!(!vm.dispatch_pointer_mouse(inner, "pointerenter", PointerMouseKind::Pointer, data));
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "inner:pointerenter,30,40,0,1,5,pen,true,0.5,true,true,true,false,false,true"
        );
        remove_context(ctx);
    }

    #[test]
    fn pointer_mouse_bubbles_cancelable_table_matches_spec() {
        // Full audit against the Pointer Events and UI Events tables.
        let cases: &[(&str, bool, bool)] = &[
            ("pointerover", true, true),
            ("pointerenter", false, false),
            ("pointerdown", true, true),
            ("pointermove", true, true),
            ("pointerrawupdate", true, false),
            ("pointerup", true, true),
            ("pointercancel", true, false),
            ("pointerout", true, true),
            ("pointerleave", false, false),
            ("gotpointercapture", true, false),
            ("lostpointercapture", true, false),
            ("mousedown", true, true),
            ("mouseenter", false, false),
            ("mouseleave", false, false),
            ("mousemove", true, true),
            ("mouseout", true, true),
            ("mouseover", true, true),
            ("mouseup", true, true),
            ("click", true, true),
            ("dblclick", true, true),
            ("auxclick", true, true),
            ("contextmenu", true, true),
        ];
        for (ty, bubbles, cancelable) in cases {
            assert_eq!(
                pointer_mouse_bubbles_cancelable(ty),
                (*bubbles, *cancelable),
                "{ty}"
            );
        }
    }

    #[test]
    fn dispatch_pointer_mouse_cancelable_matches_spec_and_mousemove_prevents() {
        let (mut vm, doc, ctx) = production_vm();
        vm.eval(
            "globalThis.seen = []; \
             var innerEl = document.getElementById('inner'); \
             ['mousemove','pointercancel','pointerrawupdate','pointermove','mousedown'].forEach(function(t){ \
               innerEl.addEventListener(t, function(e){ \
                 seen.push(t + ':' + e.bubbles + ',' + e.cancelable); \
                 e.preventDefault(); \
               }); \
             });",
        )
        .unwrap();
        let inner = doc.borrow().get_element_by_id("inner").unwrap();
        let data = dom::PointerData::mouse_at(10.0, 10.0);
        // mousemove is cancelable: preventDefault actually prevents.
        assert!(vm.dispatch_pointer_mouse(inner, "mousemove", PointerMouseKind::Mouse, data));
        // pointermove is cancelable too.
        assert!(vm.dispatch_pointer_mouse(inner, "pointermove", PointerMouseKind::Pointer, data));
        // mousedown is cancelable.
        assert!(vm.dispatch_pointer_mouse(inner, "mousedown", PointerMouseKind::Mouse, data));
        // pointercancel / pointerrawupdate bubble but are not
        // cancelable: per the DOM Standard `preventDefault()` on a
        // non-cancelable event is a no-op, so their dispatches report
        // not-prevented even though the listener called it.
        assert!(!vm.dispatch_pointer_mouse(
            inner,
            "pointercancel",
            PointerMouseKind::Pointer,
            data
        ));
        assert!(!vm.dispatch_pointer_mouse(
            inner,
            "pointerrawupdate",
            PointerMouseKind::Pointer,
            data
        ));
        assert_eq!(
            eval_log(&mut vm, "seen.join(';');"),
            "mousemove:true,true;pointermove:true,true;mousedown:true,true;\
             pointercancel:true,false;pointerrawupdate:true,false"
        );
        remove_context(ctx);
    }

