    #[test]
    fn forged_hidden_wheel_dispatch_native_does_not_crash() {
        let (mut vm, _doc, ctx) = production_vm();
        // The hidden stash-dispatch native is script-reachable; a forged
        // direct call with an empty stash must return false, not crash.
        let v = vm.eval("window[\"\\0bowser:dispatchWheel\"]()").unwrap();
        assert_eq!(v, Value::Bool(false));
        // A forged full stash (script-planted target + event wrapper)
        // dispatches through the temp-rooted path: the values survive the
        // allocating dispatch and the listener fires.
        vm.eval(
            "globalThis.forged = []; \
             document.getElementById('inner').addEventListener('wheel', function(e) { \
                 forged.push(e.type + ':' + e.deltaX); \
             }); \
             window[\"\\0bowser:wheelTarget\"] = document.getElementById('inner'); \
             window[\"\\0bowser:wheelEvent\"] = new WheelEvent('wheel', {deltaX: 7}); \
             if (window[\"\\0bowser:dispatchWheel\"]() !== false) throw new Error('want false');",
        )
        .unwrap();
        assert_eq!(eval_log(&mut vm, "forged.join(';');"), "wheel:7");
        // The stash was unstashed: a second forged call finds nothing.
        let v2 = vm.eval("window[\"\\0bowser:dispatchWheel\"]()").unwrap();
        assert_eq!(v2, Value::Bool(false));
        remove_context(ctx);
    }

    #[test]
    fn listener_event_types_interned_to_ids() {
        let mut fx = setup("<html><body><div id=\"a\"></div></body></html>");
        let a = call_get_element_by_id(&mut fx, "a");
        let l = probe_listener(&mut fx.heap);
        add_listener(&mut fx, a, "click", l, false);
        // Interned once, at add-listener time.
        assert_eq!(
            fx.apis
                .borrow()
                .gc_roots
                .borrow()
                .event_type_ids
                .get("click")
                .map(|t| t.id),
            Some(0)
        );
        // removeEventListener resolves the bucket through the interned id;
        // the emptied bucket is dropped (never left empty), and the intern
        // entry is evicted with its last bucket (no unbounded growth).
        let t = str_val(&mut fx, "click");
        n_remove_event_listener(&mut fx.heap, a, &[t, l, Value::Bool(false)]).unwrap();
        assert!(
            fx.apis
                .borrow()
                .gc_roots
                .borrow()
                .listeners
                .values()
                .all(|v| !v.is_empty())
        );
        assert!(
            !fx.apis
                .borrow()
                .gc_roots
                .borrow()
                .event_type_ids
                .contains_key("click")
        );
        // Re-adding after eviction re-interns with a fresh (never reused)
        // id.
        add_listener(&mut fx, a, "click", l, false);
        assert_eq!(
            fx.apis
                .borrow()
                .gc_roots
                .borrow()
                .event_type_ids
                .get("click")
                .map(|t| t.id),
            Some(1)
        );
        // Dispatching a type nobody registered interns nothing.
        let before = fx.apis.borrow().gc_roots.borrow().event_type_ids.len();
        let ev = plain_event(&mut fx, "nope", false);
        n_dispatch_event(&mut fx.heap, a, &[ev]).unwrap();
        assert_eq!(
            fx.apis.borrow().gc_roots.borrow().event_type_ids.len(),
            before
        );
    }

    #[test]
    fn text_content_retired_and_recomputed_lazily() {
        let mut fx = setup("<html><body><div id=\"a\">x</div></body></html>");
        let doc_val = global_prop(&fx, "document");
        let html_w = prop_val(&fx, obj_of(doc_val), "documentElement");
        let html_o = obj_of(html_w);
        assert!(
            fx.heap
                .get_property(html_o, Wtf8::from_str("textContent"))
                .is_some()
        );
        // Mutate deep: append text to the div. `html` is a higher ancestor
        // (grandparent of the touch), so its `textContent` snapshot retires
        // to the lazy accessor instead of rebuilding eagerly...
        let a = call_get_element_by_id(&mut fx, "a");
        let data = str_val(&mut fx, "yz");
        let text = call_method(&mut fx, doc_val, n_create_text_node, &[data]);
        call_method(&mut fx, a, n_append_child, &[text]);
        assert!(
            fx.heap
                .get_property(html_o, Wtf8::from_str("textContent"))
                .is_none()
        );
        assert!(
            fx.heap
                .get_accessor(html_o, Wtf8::from_str("textContent"))
                .is_some()
        );
        // ...while `children` (provably unchanged above the parents) stays
        // a fresh data property.
        let kids = obj_of(prop_val(&fx, html_o, "children"));
        assert_eq!(prop_val(&fx, kids, "length"), Value::Int(2)); // head, body
        // A read recomputes from the DOM and self-heals to a data property.
        let got = n_text_content_get(&mut fx.heap, html_w, &[]).unwrap();
        assert_eq!(str_contents(&fx, got), "xyz");
        assert_eq!(prop_str(&fx, html_o, "textContent"), "xyz");
    }

    #[test]
    fn text_content_assignment_shadows_retired_snapshot() {
        let mut fx = setup("<html><body><div id=\"a\">x</div></body></html>");
        let doc_val = global_prop(&fx, "document");
        let html_w = prop_val(&fx, obj_of(doc_val), "documentElement");
        let html_o = obj_of(html_w);
        let a = call_get_element_by_id(&mut fx, "a");
        let data = str_val(&mut fx, "y");
        let text = call_method(&mut fx, doc_val, n_create_text_node, &[data]);
        call_method(&mut fx, a, n_append_child, &[text]);
        assert!(
            fx.heap
                .get_accessor(html_o, Wtf8::from_str("textContent"))
                .is_some()
        );
        // Assignment shadows the snapshot, exactly like the old writable
        // data property did.
        let shadow = str_val(&mut fx, "shadow");
        n_text_content_set(&mut fx.heap, html_w, &[shadow]).unwrap();
        assert_eq!(prop_str(&fx, html_o, "textContent"), "shadow");
        // A later mutation retires it again (the shadow is dropped, as the
        // old eager re-sync dropped it).
        let data2 = str_val(&mut fx, "z");
        let text2 = call_method(&mut fx, doc_val, n_create_text_node, &[data2]);
        call_method(&mut fx, a, n_append_child, &[text2]);
        assert!(
            fx.heap
                .get_accessor(html_o, Wtf8::from_str("textContent"))
                .is_some()
        );
        let got = n_text_content_get(&mut fx.heap, html_w, &[]).unwrap();
        assert_eq!(str_contents(&fx, got), "xyz");
    }

    #[test]
    fn script_text_content_accessor_survives_mutation_at_all_depths() {
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "Object.defineProperty(document.getElementById('outer'), 'textContent', \
                 {get: function() { return 'script-outer'; }, configurable: true}); \
             Object.defineProperty(document.documentElement, 'textContent', \
                 {get: function() { return 'script-html'; }, configurable: true}); \
             document.getElementById('inner').appendChild(document.createTextNode('y'));",
        )
        .unwrap();
        // `outer` is the mutation's parent (eager re-sync depth): the
        // script accessor must not be clobbered by `sync_props`.
        assert_eq!(
            eval_log(&mut vm, "document.getElementById('outer').textContent;"),
            "script-outer"
        );
        // `html` is a higher ancestor (retired depth): same rule, via
        // `retire_text_content`.
        assert_eq!(
            eval_log(&mut vm, "document.documentElement.textContent;"),
            "script-html"
        );
        // Untouched data snapshots still re-sync eagerly on the touched node.
        assert_eq!(
            eval_log(&mut vm, "document.getElementById('inner').textContent;"),
            "y"
        );
        remove_context(ctx);
    }

