    #[test]
    fn event_accessors_during_and_after_dispatch() {
        let (mut vm, _doc, ctx) = production_vm();
        vm.eval(
            "globalThis.r = []; \
             globalThis.outerEl = document.getElementById('outer'); \
             globalThis.innerEl = document.getElementById('inner'); \
             outerEl.addEventListener('click', function(e) { \
                 r.push(e.eventPhase); r.push(e.target === innerEl); r.push(e.currentTarget === outerEl); \
             }, true); \
             innerEl.addEventListener('click', function(e) { \
                 r.push(e.eventPhase); r.push(e.target === innerEl); r.push(e.currentTarget === innerEl); \
                 r.push(e.isTrusted); r.push(typeof e.timeStamp); globalThis.saved = e; \
             }); \
             outerEl.addEventListener('click', function(e) { r.push(e.eventPhase); });",
        )
        .unwrap();
        vm.eval("innerEl.dispatchEvent({type: 'click', bubbles: true});")
            .unwrap();
        // capture(1) at outer, target(2) at inner, bubble(3) at outer.
        assert_eq!(
            eval_log(&mut vm, "r.join(',');"),
            "1,true,true,2,true,true,false,number,3"
        );
        // After dispatch: `target` retained, `currentTarget` null,
        // `eventPhase` back to NONE.
        assert_eq!(
            eval_log(
                &mut vm,
                "[saved.target === innerEl, saved.currentTarget === null, saved.eventPhase].join(',');"
            ),
            "true,true,0"
        );
        remove_context(ctx);
    }

