    #[test]
    fn shim_trace_root_leaks_at_most_once_per_heap() {
        // The take-then-reinstall path (production install drains the
        // table, a later shim install starts a fresh one) must not leak a
        // second trace root: the one root is re-pointed at the fresh table.
        let mut vm = Vm::new();
        let heap_id = vm.heap_mut().id();
        let count_before = SHIM_TRACE_ROOTS.with(|s| s.borrow().len());
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        guard.uninstall(&mut vm);
        // The production install takes the table, resetting the slot.
        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = ContextId(
            vm.install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
                .expect("production install"),
        );
        remove_context(ctx);
        assert!(vm.pending_shim_listeners.is_none());
        // Reinstall on the same heap: no new leak, root re-pointed.
        let guard2 = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        let count_after = SHIM_TRACE_ROOTS.with(|s| s.borrow().len());
        assert_eq!(
            count_after,
            count_before + 1,
            "a second install on the same heap must reuse the trace root"
        );
        let root_ptr = SHIM_TRACE_ROOTS.with(|s| s.borrow()[&heap_id]);
        let fresh = vm.pending_shim_listeners.clone().expect("fresh table");
        // SAFETY: `root_ptr` came from `Box::leak` and the engine is
        // single-threaded; no collection runs inside this test body.
        let traced = unsafe {
            (*root_ptr)
                .roots
                .upgrade()
                .expect("root must still trace something")
        };
        assert!(
            Rc::ptr_eq(&traced, &fresh),
            "the reused root must trace the fresh table"
        );
        guard2.uninstall(&mut vm);
    }

