    #[test]
    fn w51_rework_nested_install_duplicate_wrapper_is_merged_at_upgrade() {
        // Defect 3: a nested install mints a second wrapper for an
        // element the outer script already wrapped. At upgrade the
        // duplicate (the cache loser) is transformed in place too
        // and its listeners are adopted — it must not stay a dead
        // shim object.
        struct DupProbe {
            vm: Vm,
        }
        impl bowser_html::ScriptExecutor for DupProbe {
            fn execute_script(
                &mut self,
                host: &mut ScriptHost<'_, '_, '_>,
                _el: ScriptElement,
                _attrs: &[(String, String)],
                _script: &str,
            ) {
                #[allow(clippy::unnecessary_cast)]
                let host_ptr = host as *mut ScriptHost<'_, '_, '_>
                    as *mut ScriptHost<'static, 'static, 'static>;
                let guard_a = install_parse_document_shim(&mut self.vm, host_ptr, None)
                    .expect("outer install");
                self.vm
                    .eval(
                        "globalThis.__seen = [];\
                         globalThis.__outer = document.getElementById('cap');\
                         __outer.addEventListener('scrollsnapchange', function(e) { __seen.push('outer'); });",
                    )
                    .expect("outer eval");
                // Nested install while the outer slot is still live.
                let guard_b = install_parse_document_shim(&mut self.vm, host_ptr, None)
                    .expect("nested install");
                self.vm
                    .eval(
                        "globalThis.__inner = document.getElementById('cap');\
                         globalThis.__same = (__inner === __outer);\
                         __inner.addEventListener('scrollsnapchange', function(e) { __seen.push('inner'); });",
                    )
                    .expect("inner eval");
                guard_b.uninstall(&mut self.vm);
                guard_a.uninstall(&mut self.vm);
            }
        }
        let mut probe = DupProbe { vm: Vm::new() };
        let (doc, _) = Document::parse_html_with_executor(
            b"<html><body><div id=\"cap\">x</div><script>1</script></body></html>",
            true,
            &mut probe,
        );
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = probe
            .vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        // The premise: two distinct wrappers were minted.
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__same;"), "false");
        // The first (outer) wrapper is canonical.
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(document.getElementById('cap') === __outer);"
            ),
            "true"
        );
        // The duplicate works post-parse: production prototype and
        // surface, not a dead shim.
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(Object.getPrototypeOf(__inner) === Element.prototype);"
            ),
            "true"
        );
        assert_eq!(
            node_list_str(&mut probe.vm, "__inner.getAttribute('id');"),
            "cap"
        );
        // Both wrappers' listeners were adopted and fire.
        let cap_node = doc.borrow().get_element_by_id("cap").expect("div#cap");
        probe
            .vm
            .dispatch_snap_event(cap_node, "scrollsnapchange", None, None, false);
        assert_eq!(
            node_list_str(&mut probe.vm, "__seen.join(',');"),
            "outer,inner"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn w51_rework_create_element_set_id_append_child_upgrades() {
        // Defect 4: identity snapshotted while detached was
        // `(None, None)` forever; with live maintenance the
        // element acquires its identity as it is id'd and attached.
        let (mut probe, _doc, ctx) = captured_install(
            b"<html><body><script>\
              globalThis.__el = document.createElement('div');\
              __el.id = 'made';\
              document.body.appendChild(__el);\
              </script></body></html>",
        );
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(document.getElementById('made') === __el);"
            ),
            "true"
        );
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(Object.getPrototypeOf(__el) === Element.prototype);"
            ),
            "true"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn w51_rework_define_property_onscrollsnapchange_supersedes_accessor() {
        // Defect 5: a handler planted as an own data property via
        // `Object.defineProperty` supersedes the accessor-recorded
        // handler: the planted one is adopted, the earlier one is
        // not, and the planted value is not destroyed by the strip.
        let (mut probe, doc, ctx) = captured_install(
            b"<html><body><div id=\"cap\"></div><script>\
              globalThis.__seen = [];\
              globalThis.__cap = document.getElementById('cap');\
              globalThis.__earlier = function(e) { __seen.push('earlier'); };\
              globalThis.__planted = function(e) { __seen.push('planted'); };\
              __cap.onscrollsnapchange = __earlier;\
              Object.defineProperty(__cap, 'onscrollsnapchange', { value: __planted, writable: true, configurable: true });\
              </script></body></html>",
        );
        let cap_node = doc.borrow().get_element_by_id("cap").expect("div#cap");
        probe
            .vm
            .dispatch_snap_event(cap_node, "scrollsnapchange", None, None, false);
        assert_eq!(node_list_str(&mut probe.vm, "__seen.join(',');"), "planted");
        // The value survived: the production getter reports it.
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(__cap.onscrollsnapchange === __planted);"
            ),
            "true"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn w51_rework_remove_event_listener_removes_on_handler_mid_parse() {
        // Defect 7: mid-parse `removeEventListener` must remove an
        // `on*` handler registration too, like production.
        let (mut probe, doc, ctx) = captured_install(
            b"<html><body><div id=\"cap\"></div><script>\
              globalThis.__seen = [];\
              globalThis.__cap = document.getElementById('cap');\
              globalThis.__fn = function(e) { __seen.push('handler'); };\
              __cap.onscrollsnapchange = __fn;\
              __cap.removeEventListener('scrollsnapchange', __fn);\
              globalThis.__mid = String(__cap.onscrollsnapchange === null);\
              __cap.addEventListener('scrollsnapchange', function(e) { __seen.push('kept'); });\
              </script></body></html>",
        );
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__mid;"), "true");
        let cap_node = doc.borrow().get_element_by_id("cap").expect("div#cap");
        probe
            .vm
            .dispatch_snap_event(cap_node, "scrollsnapchange", None, None, false);
        assert_eq!(node_list_str(&mut probe.vm, "__seen.join(',');"), "kept");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn w51_rework_bulk_wrap_of_several_hundred_elements_completes() {
        // Defect 6: bulk wrapping must not be O(N²) — a few
        // hundred elements wrapped through `querySelectorAll`
        // complete, and every wrapper upgrades onto its own node.
        let mut html = String::from("<html><body>");
        for i in 0..300 {
            html.push_str(&format!("<div id=\"d{i}\">x</div>"));
        }
        html.push_str(
            "<script>\
               globalThis.__all = document.querySelectorAll('div');\
               globalThis.__n = __all.length;\
               globalThis.__last = document.getElementById('d299');\
             </script></body></html>",
        );
        let (mut probe, _doc, ctx) = captured_install(html.as_bytes());
        assert_eq!(node_list_str(&mut probe.vm, "globalThis.__n;"), "300");
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(document.getElementById('d299') === __last);"
            ),
            "true"
        );
        assert_eq!(
            node_list_str(
                &mut probe.vm,
                "String(__all[150] === document.getElementById('d150'));"
            ),
            "true"
        );
        remove_context(ContextId(ctx));
    }

