    #[test]
    fn fonts_url_load_installs_via_runner() {
        // No test fonts in the cache up front: `check('16px Ahem')`
        // is false until the fake fetch outcome installs the bytes.
        // The face is never `load()`ed through the pool: a real
        // worker completion would overwrite the injected outcome in
        // `pump_page_event_loop`'s poll (the old "unroutable URL
        // blocks the worker" assumption does not hold in this
        // sandbox — the connect fails fast and the test flakes).
        // Instead a synthetic job is registered for the face record
        // directly, exactly as the w76 CORS gate test does.
        let (mut vm, ctx, _) = fonts_vm(false);
        // The fonts_vm cache has no test fonts in this case, so
        // rebuild the Ahem bytes from a fresh cache.
        let mut probe_cache = FontCache::new();
        probe_cache.install_test_fonts();
        let ahem = probe_cache
            .resolve("ahem", 400, FontStyle::Normal)
            .and_then(|k| probe_cache.font_data(k))
            .map(|d| d.bytes().to_vec())
            .expect("Ahem bytes");
        let before = fonts_str(&mut vm, "document.fonts.check('16px Ahem');");
        assert_eq!(before, "false");
        fonts_str(
            &mut vm,
            "globalThis.__face = new FontFace('Ahem', 'url(http://10.255.255.1/Ahem.ttf)'); \
             document.fonts.add(globalThis.__face); \
             globalThis.__face.status;",
        );
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        let job = 0xC0FF_EE01u32;
        {
            let mut g = apis.borrow_mut();
            let face = g
                .gc_roots
                .borrow()
                .font_faces
                .iter()
                .find(|(_, rec)| rec.family == "Ahem")
                .map(|(h, _)| *h)
                .expect("Ahem face record");
            g.font_load_jobs.insert(job, face);
        }
        // w76 CORS gate: the final URL must be same-origin (or carry
        // ACAO) or `complete_font_load` now rejects the install. The
        // face is never `load()`ed, so no pool worker exists at all
        // (the old "unroutable URL blocks the worker" assumption does
        // not hold — a connect failure completes fast); the final
        // URL is same-origin, as after a redirect to the document's
        // origin.
        let url = bowser_url::parse("http://example.com/Ahem.ttf", None).unwrap();
        let outcome: FetchOutcome = Ok(bowser_net::fetch::Response {
            status: 200,
            headers: Vec::new(),
            body: ahem,
            url,
        });
        {
            let mut g = apis.borrow_mut();
            g.font_load_outcomes.insert(job, outcome);
        }
        vm.event_loop().queue_microtask(Task::PromiseJob { job });
        let _errors = pump_page_event_loop(&mut vm, ctx);
        let r = fonts_str(
            &mut vm,
            "[globalThis.__face.status, document.fonts.check('16px Ahem')].join('|');",
        );
        assert_eq!(r, "loaded|true");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_renamed_face_data_url_loads_under_declared_family() {
        // w75f2-1: a data-URL face declared as `Brand` must install
        // under `Brand` (not the file's internal `Ahem` name), so
        // paint resolves `Brand` after load.
        let (mut vm, ctx, ahem) = fonts_vm(true);
        let ahem = ahem.expect("Ahem installed");
        let b64 = b64_encode(&ahem);
        let r = fonts_str(
            &mut vm,
            &format!(
                "var out = []; \
                 var f = new FontFace('Brand', 'url(data:font/ttf;base64,{b64})', {{weight: '700'}}); \
                 document.fonts.add(f); \
                 var stat = []; \
                 f.loaded.then(function() {{ stat.push('ok'); }}, function() {{ stat.push('err'); }}); \
                 f.load(); \
                 var g = new FontFace('Brand2', 'url(data:font/ttf;base64,{b64})'); \
                 document.fonts.add(g); \
                 g.load(); \
                 out.push(f.status); \
                 out.push(stat.join(',')); \
                 out.push(document.fonts.check('16px Brand')); \
                 out.push(document.fonts.check('bold 16px Brand')); \
                 out.push(document.fonts.check('16px Brand2')); \
                 out.join('|');"
            ),
        );
        // `16px Brand` is false under the exact weight predicate
        // (the Brand face is declared 700, not 400); the bold check
        // and the default-weight Brand2 check are true through the
        // set path, and the Rust assertion below proves paint
        // resolves the declared family at all.
        assert_eq!(r, "loaded|ok|false|true|true", "{r}");
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        let cache = apis.borrow().fonts_cache.clone().expect("cache shared");
        assert!(
            cache.resolve("Brand", 400, FontStyle::Normal).is_some(),
            "paint must resolve the declared family after a renamed load"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_name_table_returns_typographic_and_legacy() {
        // w75f2-5 (name half): the JS name reader must return the
        // same name set paint indexes (typographic ID 16 plus legacy
        // ID 1), not ID 16 alone. Synthetic SFNT with one record of
        // each kind.
        fn utf16be(s: &str) -> Vec<u8> {
            let mut out = Vec::new();
            for u in s.encode_utf16() {
                out.extend_from_slice(&u.to_be_bytes());
            }
            out
        }
        let typo = utf16be("TypoFam");
        let legacy = utf16be("LegacyFam");
        let name_len = 6 + 24 + typo.len() + legacy.len();
        let mut bytes = Vec::new();
        bytes.extend_from_slice(&0x00010000u32.to_be_bytes());
        bytes.extend_from_slice(&1u16.to_be_bytes());
        bytes.extend_from_slice(&16u16.to_be_bytes());
        bytes.extend_from_slice(&0u16.to_be_bytes());
        bytes.extend_from_slice(&0u16.to_be_bytes());
        bytes.extend_from_slice(b"name");
        bytes.extend_from_slice(&0u32.to_be_bytes());
        bytes.extend_from_slice(&28u32.to_be_bytes());
        bytes.extend_from_slice(&(name_len as u32).to_be_bytes());
        bytes.extend_from_slice(&0u16.to_be_bytes());
        bytes.extend_from_slice(&2u16.to_be_bytes());
        bytes.extend_from_slice(&30u16.to_be_bytes());
        for (name_id, text, off) in [(16u16, &typo, 0usize), (1u16, &legacy, typo.len())] {
            bytes.extend_from_slice(&3u16.to_be_bytes());
            bytes.extend_from_slice(&1u16.to_be_bytes());
            bytes.extend_from_slice(&0x0409u16.to_be_bytes());
            bytes.extend_from_slice(&name_id.to_be_bytes());
            bytes.extend_from_slice(&(text.len() as u16).to_be_bytes());
            bytes.extend_from_slice(&(off as u16).to_be_bytes());
        }
        bytes.extend_from_slice(&typo);
        bytes.extend_from_slice(&legacy);
        assert_eq!(
            font_name_families(&bytes, 0),
            vec!["TypoFam".to_string(), "LegacyFam".to_string()]
        );
    }

    #[test]
    fn fonts_w75_set_load_invalid_font_rejects_not_throws() {
        // w75f2-3: only a missing argument throws; an unparseable
        // font string rejects the returned promise.
        let (mut vm, ctx, _) = fonts_vm(false);
        let r = fonts_str(
            &mut vm,
            "var out = []; \
             function attempt(fn) { try { fn(); return 'no-throw'; } catch (e) { return 'threw'; } } \
             var rej = null; var p = null; \
             out.push(attempt(function() { p = document.fonts.load('bogus-no-size'); })); \
             out.push(typeof (p && p.then)); \
             if (p) { p.then(function() { rej = 'ok'; }, function() { rej = 'rejected'; }); } \
             out.push(rej); \
             out.push(attempt(function() { document.fonts.load(); })); \
             out.join('|');",
        );
        assert_eq!(r, "no-throw|function|rejected|threw", "{r}");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_constructor_case_insensitive_and_range_and_syntax() {
        // w75f2-4: case-insensitive keywords, weight ranges, and
        // SyntaxError validation of stretch / unicodeRange / source.
        let (mut vm, ctx, _) = fonts_vm(false);
        let r = fonts_str(
            &mut vm,
            "var out = []; \
             function ok(fn) { try { fn(); return 'ok'; } catch (e) { return 'throw:' + e.name; } } \
             var f; \
             out.push(ok(function() { f = new FontFace('A', 'url(a)', {style: 'Italic'}); })); \
             out.push(f ? f.style : 'none'); \
             out.push(ok(function() { f = new FontFace('B', 'url(b)', {weight: 'BOLD'}); })); \
             out.push(f ? f.weight : 'none'); \
             out.push(ok(function() { f = new FontFace('C', 'url(c)', {weight: '100 900'}); })); \
             out.push(f ? f.weight : 'none'); \
             out.push(ok(function() { new FontFace('D', 'url(d)', {stretch: 'bogus'}); })); \
             out.push(ok(function() { new FontFace('E', 'url(e)', {stretch: '50% 200%'}); })); \
             out.push(ok(function() { new FontFace('F', 'url(f)', {unicodeRange: 'banana'}); })); \
             out.push(ok(function() { new FontFace('G', 'url(g)', {unicodeRange: 'U+41-5A, U+61'}); })); \
             out.push(ok(function() { new FontFace('H', 'garbage'); })); \
             out.push(ok(function() { new FontFace('I', 'LOCAL(\"Ahem\")'); })); \
             out.push(ok(function() { new FontFace('J', 'url(j)', {display: 'SWAP'}); })); \
             out.join('|');",
        );
        assert_eq!(
            r,
            "ok|italic|ok|bold|ok|100 900|throw:SyntaxError|ok|throw:SyntaxError|ok|throw:SyntaxError|ok|ok",
            "{r}"
        );
        remove_context(ContextId(ctx));
    }

