    #[test]
    fn fonts_w75_rejoining_loading_face_blocks_ready() {
        // w75f2-6: a face that starts loading standalone, is added
        // to the set, and is then set-loaded while still Loading
        // must count against `ready` (status `loading`, ready
        // unsettled) instead of letting `ready` settle early.
        let (mut vm, ctx, _) = fonts_vm(false);
        let r = fonts_str(
            &mut vm,
            "var f = new FontFace('RejoinFam', 'url(http://10.255.255.1/rejoin.ttf)'); \
             f.load(); \
             document.fonts.add(f); \
             document.fonts.load('16px RejoinFam'); \
             var readyFired = false; \
             document.fonts.ready.then(function() { readyFired = true; }); \
             [document.fonts.status, readyFired].join('|');",
        );
        assert_eq!(r, "loading|false", "{r}");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_set_load_cache_fallback_matches_members() {
        // w75f2-7: the empty-members cache fallback uses the same
        // exact weight/style predicate as member matching (bold
        // Ahem with only regular cached rejects), and a range member
        // matches a weight inside its range.
        let (mut vm, ctx, _) = fonts_vm(true);
        let r = fonts_str(
            &mut vm,
            "var out = []; \
             var rej = null; \
             document.fonts.load('bold 16px Ahem').then(function() { rej = 'ok'; }, function() { rej = 'rejected'; }); \
             out.push(rej); \
             var ok = null; \
             document.fonts.load('16px Ahem').then(function(a) { ok = a.length; }, function() { ok = 'rejected'; }); \
             out.push(ok); \
             var f = new FontFace('Ahem', 'local(\"Ahem\")', {weight: '100 900'}); \
             document.fonts.add(f); \
             var got = null; \
             document.fonts.load('400 16px Ahem').then(function(a) { got = a.length + ':' + (a[0] === f); }, function() { got = 'rejected'; }); \
             out.push(got); \
             out.join('|');",
        );
        assert_eq!(r, "rejected|0|1:true", "{r}");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_clear_prunes_ready_and_joins() {
        // w75f2-9: clear() drops the loading face's ready pending
        // entry (status returns to `loaded`, `ready` settles) and
        // settles the set-load join with the surviving faces (none),
        // so it never later settles for the cleared face.
        let (mut vm, ctx, _) = fonts_vm(false);
        let r = fonts_str(
            &mut vm,
            "var f = new FontFace('ClearFam', 'url(http://10.255.255.1/clear.ttf)'); \
             document.fonts.add(f); \
             f.load(); \
             var readyFired = false; \
             document.fonts.ready.then(function() { readyFired = true; }); \
             var joinRes = null; \
             document.fonts.load('16px ClearFam').then(function(a) { joinRes = 'ok:' + a.length; }, function() { joinRes = 'rejected'; }); \
             document.fonts.clear(); \
             [document.fonts.size, document.fonts.status, readyFired, joinRes].join('|');",
        );
        assert_eq!(r, "0|loaded|true|ok:0", "{r}");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_delete_prunes_ready() {
        // w75f2-9 (delete half): deleting the one loading member
        // drains `ready` the same way clear() does.
        let (mut vm, ctx, _) = fonts_vm(false);
        let r = fonts_str(
            &mut vm,
            "var f = new FontFace('DelFam', 'url(http://10.255.255.1/del.ttf)'); \
             document.fonts.add(f); \
             f.load(); \
             var readyFired = false; \
             document.fonts.ready.then(function() { readyFired = true; }); \
             document.fonts.delete(f); \
             [document.fonts.size, document.fonts.status, readyFired].join('|');",
        );
        assert_eq!(r, "0|loaded|true", "{r}");
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_complete_font_load_missing_record_settles() {
        // w75f2-10, w76fix M8: when the face record is gone by
        // completion time, the fetch completion must still drain
        // `ready` and reject the set-load join instead of returning
        // unsettled. Synthetic-job pattern (as in the runner and CORS
        // tests): the face is never `load()`ed through the pool, so
        // no pool worker exists to overwrite the injected outcome in
        // `poll_fetch_completions` — the old version called the real
        // `load()` and injected an outcome for the same job, so a
        // fast worker failure masked the injected path entirely (both
        // outcomes rejected, and the test could catch no regression).
        // The Loading state + `ready` pending are established by
        // hand, then `fonts.load` registers the join and rejoins the
        // Loading face without spawning a worker, then the record is
        // removed and a synthetic same-origin success completes.
        let (mut vm, ctx, _) = fonts_vm(false);
        let mut probe_cache = FontCache::new();
        probe_cache.install_test_fonts();
        let ahem = probe_cache
            .resolve("ahem", 400, FontStyle::Normal)
            .and_then(|k| probe_cache.font_data(k))
            .map(|d| d.bytes().to_vec())
            .expect("Ahem bytes");
        fonts_str(
            &mut vm,
            "globalThis.__face = new FontFace('GoneFam', 'url(http://example.com/gone.ttf)'); \
             document.fonts.add(globalThis.__face); \
             'setup';",
        );
        let apis = web_apis(ContextId(ctx)).expect("context registered");
        let face = {
            let g = apis.borrow();
            g.gc_roots
                .borrow()
                .font_faces
                .iter()
                .find(|(_, rec)| rec.family == "GoneFam")
                .map(|(h, _)| *h)
                .expect("GoneFam face record")
        };
        // What `start_font_load` would have established, minus the
        // pool worker — before `ready.then` attaches, so the ready
        // promise observed is the pending one.
        {
            let g = apis.borrow_mut();
            let mut roots = g.gc_roots.borrow_mut();
            roots.font_faces.get_mut(&face).expect("face record").status = FontFaceStatus::Loading;
            roots.fonts_ready_pending.insert(face);
        }
        fonts_str(
            &mut vm,
            "globalThis.__readyFired = false; \
             globalThis.__joinRes = null; \
             document.fonts.ready.then(function() { globalThis.__readyFired = true; }); \
             document.fonts.load('16px GoneFam').then(function() { globalThis.__joinRes = 'ok'; }, function() { globalThis.__joinRes = 'rejected'; }); \
             'joined';",
        );
        // The join now waits on `face`; remove the record and inject
        // the completion. The install runs with no record, so
        // settlement rejects — but must still drain `ready` and the
        // join through the record-absent path of `settle_font_load`.
        let job = 0xC0FF_EE02u32;
        let url = bowser_url::parse("http://example.com/gone.ttf", None).unwrap();
        let outcome: FetchOutcome = Ok(bowser_net::fetch::Response {
            status: 200,
            headers: Vec::new(),
            body: ahem,
            url,
        });
        {
            let mut g = apis.borrow_mut();
            g.font_load_jobs.insert(job, face);
            g.font_load_outcomes.insert(job, outcome);
            g.gc_roots.borrow_mut().font_faces.remove(&face);
        }
        vm.event_loop().queue_microtask(Task::PromiseJob { job });
        let _errors = pump_page_event_loop(&mut vm, ctx);
        let r = fonts_str(
            &mut vm,
            "[globalThis.__readyFired, globalThis.__joinRes].join('|');",
        );
        assert_eq!(r, "true|rejected", "{r}");
        let g = apis.borrow();
        let roots = g.gc_roots.borrow();
        assert!(
            roots.fonts_ready_pending.is_empty(),
            "ready pending drained"
        );
        assert!(roots.font_load_joins.is_empty(), "joins drained");
        drop(roots);
        drop(g);
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_data_url_cap_rejects_oversize() {
        // w75f2-11: a data URL decoding to more than the loader's
        // 32 MiB cap fails with the cap reason, before any decode
        // or install of the oversized bytes.
        let (mut vm, ctx, _) = fonts_vm(false);
        let r = fonts_str(
            &mut vm,
            "var s = 'AAAA'.repeat(12000000); \
             var f = new FontFace('BigFam', 'url(data:font/ttf;base64,' + s + ')'); \
             var reason = null; \
             f.loaded.then(function() { reason = 'ok'; }, function(e) { reason = e; }); \
             f.load(); \
             [f.status, reason].join('|');",
        );
        assert!(
            r.starts_with("error|") && r.contains("32 MiB"),
            "oversize data URL must fail with the cap reason, got: {r}"
        );
        remove_context(ContextId(ctx));
    }

    #[test]
    fn fonts_w75_shim_fonts_same_object_after_production_install() {
        // w75f2-12: a mid-parse script's captured `document.fonts`
        // must BE the production FontFaceSet after install (identity
        // migration of the shim stub), not a stale `{ ready }` stub.
        let mut vm = Vm::new();
        let guard = install_parse_document_shim(&mut vm, std::ptr::null_mut(), None).unwrap();
        vm.eval(
            "globalThis.__capturedFonts = document.fonts; \
             globalThis.__capturedReady = document.fonts.ready;",
        )
        .unwrap();
        guard.uninstall(&mut vm);
        let (doc, _) = Document::parse_html(b"<html><head></head><body></body></html>");
        let doc = Rc::new(RefCell::new(doc));
        let base = bowser_url::parse("http://example.com/", None).unwrap();
        let ctx = vm
            .install_page_web_apis(doc.clone(), base, "BowserTest/1.0")
            .expect("production install");
        let r = match vm
            .eval(
                "[globalThis.__capturedFonts === document.fonts, \
                  globalThis.__capturedFonts instanceof FontFaceSet, \
                  typeof globalThis.__capturedFonts.add, \
                  globalThis.__capturedFonts.status, \
                  typeof globalThis.__capturedFonts.ready.then].join('|');",
            )
            .unwrap()
        {
            Value::Str(s) => s.as_wtf8().to_string(),
            v => panic!("unexpected probe value: {v:?}"),
        };
        assert_eq!(r, "true|true|function|loaded|function", "{r}");
        remove_context(ContextId(ctx));
    }

